(window.FREALLY_I18N = window.FREALLY_I18N || {})["vi"] = {"hero.headline":"<span class=\"hl-muted\">Một phiên.</span> <span class=\"hl-bright\">Bốn nhà sản xuất.</span> <span class=\"cycle\" data-cycle=\"hero.cycle\">Không máy chủ.</span>","hero.cycle":"Không máy chủ.|Không tài khoản.|Không AI.","hero.tagline":"Một DAW nơi bốn nhà sản xuất cùng làm việc trong một phiên.","what.title":"Đây là gì","what.p1":"Mọi DAW đều là phần mềm một người. Làm một bản thu cùng ai đó ở nước khác vẫn có nghĩa là xuất stem, tải lên, chờ, nhập lại và đánh mất mạch — và sáu tháng sau chẳng ai nhớ ai đã viết dòng bass.","what.p2":"Oscillate là một DAW đầy đủ được dựng trên giả định ngược lại. Bạn dán một mã phòng vào khung chat và tối đa ba nhà sản xuất khác bước vào phiên của bạn: bạn thấy camera của họ, nghe thấy họ, con trỏ của họ di chuyển trên dòng thời gian của bạn — và khi xong, nó in ra một bảng chia phần ghi rõ ai viết gì.","what.p3":"Hiện tại nó miễn phí, và phía sau không có máy chủ nào. Mã phòng chính là lời mời kết nối: người đầu tiên dán một mã, sau đó phòng tự chuyển tiếp cho tất cả những người còn lại. Không có gì phải duy trì, không có gì phải trả, không có gì ai đó có thể tắt đi.","features.title":"Bên trong có gì","features.room.title":"Phòng","features.room.body":"Tối đa bốn nhà sản xuất, nối thẳng máy với máy, không tài khoản và không máy chủ. Con trỏ trực tiếp, trò chuyện, giọng nói, ô camera và chia sẻ màn hình. Lệnh hoàn tác của bạn lấy lại thay đổi của bạn và không bao giờ của người khác.","features.arrangement.title":"Bản phối","features.arrangement.body":"Không giới hạn track âm thanh và MIDI, các clip được vẽ từ chính nội dung của chúng, làn tự động hoá, ghép take, nhóm, đánh dấu, cùng bản đồ nhịp độ và loại nhịp. Mỗi lần chỉnh sửa chỉ cần một lần hoàn tác, dù nó chạm vào bao nhiêu clip.","features.pianoRoll.title":"Piano roll","features.pianoRoll.body":"Khoảng chín mươi thang âm có tô sáng, bám lưới và gập, nốt bóng mờ lấy từ bất kỳ clip nào khác, một làn velocity với tay cầm trên từng nốt, và một bàn phím chơi được nơi một phím vang lên cả hợp âm.","features.plugins.title":"Chạy plugin","features.plugins.body":"VST3 và CLAP, mỗi cái trong một tiến trình riêng, nên một plugin sập chỉ làm xám một thiết bị thay vì kéo cả phiên đi theo. Bù trễ trên toàn đồ thị, được chứng minh bằng phép thử triệt tiêu chứ không phải bằng lời tuyên bố.","features.devices.title":"Nhạc cụ của riêng nó","features.devices.body":"Tám mươi lăm nhạc cụ và hiệu ứng, với bảng điều khiển vẽ ra từ chính mô tả của thiết bị — nên con số trên núm vặn đúng là con số mà âm thanh đang dùng, đo tới một phần mười decibel — và các mặt thiết bị vẽ trực tiếp âm thanh đi qua chúng.","features.lessons.title":"Bài học","features.lessons.body":"Mười lăm khóa học, học từng ngày, từ piano và guitar đến sáng tác và trộn âm. Mỗi bước được chơi mẫu trên sân khấu trước, rồi bài học lắng nghe khi bạn chơi, chỉ trên máy tính này và không ghi âm gì, và chỉ ra ô nhịp, phách và cách sửa.","features.finalCheck.title":"Kiểm tra cuối","features.finalCheck.body":"Một bản master cho mỗi nơi phát hành, được xuất cùng lúc và đo từ tệp của nó. Nghe bản mix như điện thoại hay ô tô sẽ phát, kiểm tra độ to của từng đoạn, và đối chiếu một tệp với một quy chuẩn giao nộp.","features.suggest.title":"Gợi ý, và Mix giúp tôi","features.suggest.body":"Mỗi thẻ hiệu ứng đo những gì đến với nó và gợi ý một thiết lập, kèm lý do. Một phím thiết lập toàn bộ bản mix và đưa bản master về đúng mục tiêu, trong một bước hoàn tác. Số học, không phải mô hình.","features.pitch.title":"Dời cao độ và kéo giãn","features.pitch.body":"Dời một khoảng của bản thu lên hoặc xuống mà vẫn giữ formant, và khớp một clip với nhịp độ mà không đổi cao độ. Tệp của bạn không bao giờ bị động tới.","features.phone.title":"Bản mix trên điện thoại của bạn","features.phone.body":"Gửi bản mix và từng phần đến một điện thoại trong mạng Wi-Fi của bạn qua một mã QR, mix chúng ngay tại đó và lưu chúng thành tệp. Không cần cài gì, và không gì rời khỏi mạng của bạn.","features.retro.title":"Oscillate Retro Record","features.retro.body":"Vài phút gần nhất của những gì bạn đã chơi, được giữ trong bộ nhớ, để take mà bạn chưa hề bấm ghi vẫn có thể được lưu. Nó hỏi trước, và không ghi gì cho đến khi bạn lưu.","features.cut.title":"Nhát cắt","features.cut.body":"Kéo một nhát lưỡi dao ngang bản phối và nó cắt mọi clip mà nhát ấy đi qua; góc của nét vẽ đặt độ dốc của crossfade. Đó là ngôn ngữ chuyển động mà toàn bộ giao diện được dựng trên.","features.kumite.title":"Kumite và bảng chia phần","features.kumite.body":"Một chế độ đấu beat trong đó mỗi lượt sở hữu các ô nhịp của riêng mình, và một sổ ghi tác quyền rút ra từ nhật ký chỉnh sửa, đã trừ đi phần việc ai đó đã hoàn tác.","features.free.title":"Miễn phí, và không AI","features.free.body":"Không có gói, không có bản dùng thử, không tài khoản, không khoá bản quyền. Không mô hình, không suy luận, không có thứ gì «thông minh» — và đó không phải lời hứa: một cổng kiểm tra khi biên dịch sẽ thất bại ngay khi bất kỳ runtime học máy nào lọt vào đồ thị phụ thuộc.","ladder.title":"Đường tới 1.0","ladder.intro":"Mỗi bậc một dòng. Đây chính là chiếc thang mà kế hoạch nội bộ đi theo — một bên nhích thì cả hai nhích, và một cổng kiểm tra đối chiếu chúng.","ladder.rung.v0.0.1":"Nền móng, xương sống CI, giấy phép và EULA — cùng một cửa sổ trống đã cài được trên ba hệ điều hành.","ladder.rung.v0.1.0":"Lớp vỏ và engine âm thanh. Trông giống Oscillate và phát ra tiếng.","ladder.rung.v0.2.0":"Dự án và khung nhìn bản phối. Đây là một DAW.","ladder.rung.v0.2.5":"Các trình chỉnh sửa — piano roll, lưới trống, tự động hoá, ghép take, Nhát cắt, Kata, Tua lại phiên.","ladder.rung.v0.3.0":"Chạy plugin và các thiết bị đi kèm — VST3 và CLAP ngoài tiến trình, cùng sáu mươi chín thiết bị của riêng nó.","ladder.rung.v0.4.0":"Công cụ sáng tác — Trình duyệt tệp, Stem thành Bộ sinh và đường xuất.","ladder.rung.v0.4.5":"Quyết định làm hay không làm bản web, thả lên dòng thời gian, mặt hiển thị riêng cho từng thiết bị và âm thanh độc quyền.","ladder.rung.v0.5.0":"Phòng, phần lõi — kết nối không máy chủ, trạng thái hiện diện, đồng bộ và trò chuyện.","ladder.rung.v0.5.5":"Phòng, trực tiếp — giọng nói, video, chia sẻ màn hình, Bàn giao, Kumite và bảng chia phần.","ladder.rung.v0.6.0":"Bản sắc — làn lời bài hát, Bản tua nhanh phiên, thẻ phiên và trang ghi công.","ladder.rung.v0.6.5":"Diện mạo chung của cả gia đình, giống nhau trong mọi ứng dụng Freally — núm xoay, fader và nút bấm được dựng bằng Blender, chế độ sáng và tối với màu xanh Freally, âm thanh giao diện và thanh tiêu đề tối — cùng một thư viện nhạc cụ dùng chung với Freally MIDI Master.","ladder.rung.v0.7.0":"Một engine — các crate âm thanh và nhạc cụ dùng chung được ghim vào một tag, nền móng cho các bậc tiếp theo được đưa vào, cùng con trỏ và các nút bật/tắt của gia đình Freally.","ladder.rung.v0.8.0":"Freally MIDI Master, Flipcopy và Takelight có sẵn bên trong — plugin đi kèm trong trình duyệt cùng một bài hướng dẫn, các bài hát của MIDI Master kéo thẳng vào bản phối, và các bản xuất mang theo cả plugin đang chạy.","ladder.rung.v0.9.0":"Sân khấu — đôi tay 3D chơi bất kỳ track MIDI nào, âm sắc mới, một bộ khuếch đại và một máy trống, cùng trình duyệt nhạc cụ.","ladder.rung.v0.10.0":"Bản nhạc — ký âm được khắc chuẩn, TAB guitar, trình đọc bản nhạc, lời bài hát dưới khuông nhạc, và PDF.","ladder.rung.v0.11.0":"Bài học — mười lăm khoá học, “Chỉ cho tôi”, và nghe trực tiếp qua đầu vào của chính bạn, có chấm điểm.","ladder.rung.v0.12.0":"Của riêng studio — dịch cao độ, kéo giãn thời gian, phân tích trực tiếp, một bộ doubler và một bộ ducker, một bản master cho từng nơi phát hành, và các bước kiểm tra cuối.","ladder.rung.v0.13.0":"MixSir — bản mix trên điện thoại của bạn, ghép nối bằng mã QR.","ladder.rung.v0.14.0":"Thiết bị mới, đợt một — dải trầm và groove.","ladder.rung.v0.15.0":"Thiết bị mới, đợt hai — nhạc cụ cho nhà thiết kế âm thanh.","ladder.rung.v0.16.0":"Thiết bị mới, đợt ba — một nút ghi âm vươn ngược về quá khứ, và tìm âm thanh tương tự trong mọi âm thanh của bạn.","ladder.rung.v0.17.0":"Chuẩn hàng đầu và cặp dải trầm — Oscillate Sub và Oscillate Width, liên kết với nhau.","ladder.rung.v0.18.0":"EQ và dynamics hàng đầu — mọi EQ, compressor, limiter, de-esser và gate được nâng lên mức tốt nhất trong loại của nó, cùng Oscillate Resonance.","ladder.rung.v0.19.0":"Màu âm, không gian và chuyển động hàng đầu — saturation, echo, reverb, điều biến và bộ lọc được nâng cấp; Oscillate Shaper, Voice Changer và Echo Reverb.","ladder.rung.v0.20.0":"Oscillate Wavetable — một synth wavetable kiêm hybrid hàng đầu.","ladder.rung.v0.21.0":"Oscillate Analog, cùng synth nhiều lớp, sampler, bộ trống và trình phát được nâng cấp.","ladder.rung.v0.22.0":"Oscillate Retake — trình sửa nốt và giọng hát của Freally Retake, tích hợp sẵn.","ladder.rung.v0.23.0":"Oscillate Master, bộ công cụ sửa chữa và trình chỉnh sửa phổ, cùng các mô hình được huấn luyện ngay tại đây.","ladder.rung.v0.24.0":"Mọi thiết bị đi kèm và mọi preset gốc đạt chuẩn hàng đầu.","ladder.rung.v1.0.0-beta":"Bản beta — một đợt đóng băng tính năng mới, cả ứng dụng chung một diện mạo và 18 ngôn ngữ, và trang này được viết lại. Lặp lại cho đến khi kiểm thử xong. Trang này không có bản tải xuống nào.","ladder.rung.v1.0.0-rc":"Bản ứng viên phát hành — gia cố, đợt rà soát toàn diện, và mọi tính năng được kiểm thử trên ứng dụng bản phát hành, trong engine của Windows lẫn engine của macOS và Linux. Lặp lại cho đến khi có một bản vượt qua sạch sẽ.","ladder.rung.v1.0.0":"Ổn định và miễn phí, có sẵn Freally MIDI Master, Flipcopy và Takelight bên trong. Bản tải xuống sẽ mở sau.","ladder.note":"Một bậc đã xong là đã được dựng và nằm trên nhánh phát triển. Đó không phải bản tải về: hiện không có bản nào, và sẽ không có cho tới 1.0.0.","honest.title":"Những điều phần lớn trang web đẩy xuống cuối","honest.peers.title":"Bốn nhà sản xuất, không phải năm","honest.peers.body":"Một phòng chứa bốn người. Không có máy chủ chuyển tiếp âm thanh, nên mỗi người gửi tới tất cả những người còn lại, và kết nối thứ năm là chỗ đường tải lên gia đình thông thường cạn kiệt. Bốn là con số chạy được, không phải con số nghe hay.","honest.failure.title":"Khoảng một trong mười kết nối sẽ không hình thành","honest.failure.body":"Một số mạng cấp cho mỗi kết nối đi ra một địa chỉ khác nhau, và hai bên như thế không tìm thấy nhau nếu không có một relay ở giữa. Relay tốn băng thông mãi mãi, và đó là một hoá đơn kéo dài mà một ứng dụng miễn phí không gánh nổi — nên Oscillate không kèm relay nào và để bạn đặt relay của riêng bạn trong phần cài đặt. Khi kết nối thất bại, nó gọi tên đúng một trong chín nguyên nhân.","honest.code.title":"Mã phòng thực sự chứa gì","honest.code.body":"Nó chính là lời mời kết nối, và mang theo địa chỉ công khai của máy bạn. Hãy coi nó như một mật khẩu: chỉ gửi cho những người bạn đang làm việc cùng. Ứng dụng nói điều đó ngay lúc bạn sao chép một mã.","honest.downloads.title":"Không có bản tải về trước 1.0.0","honest.downloads.body":"Trang này không có beta, không có bản xem trước, không có truy cập sớm. Một DAW chạy được một nửa còn tệ hơn một DAW chưa có mặt.","honest.ai.title":"Không AI, và điều đó được bảo đảm thế nào","honest.ai.body":"Một cổng kiểm tra đi khắp đồ thị phụ thuộc và thất bại trước bất kỳ runtime suy luận nào, bất kỳ tệp mô hình nào, và bất kỳ thư viện phân tích hay báo lỗi nào. Đó là tính chất của bản dựng chứ không phải một câu trên website.","honest.updater.title":"Kết nối duy nhất mà ứng dụng tạo ra","honest.updater.body":"Một lần kiểm tra cập nhật, và chỉ khi bạn nhấn nút hoặc bật kiểm tra lúc khởi động — mặc định là tắt. Nó xin một tệp tĩnh và không gửi bất cứ điều gì về bạn hay máy của bạn; mọi bản cập nhật đều có chữ ký, và không bản nào được cài nếu bạn không chọn.","site.tagline":"Một DAW nơi bốn nhà sản xuất cùng làm việc trong một phiên.","footer.licence":"Phần mềm độc quyền — Bảo lưu mọi quyền. © Mike Weaver. Hiện miễn phí sử dụng; các phiên bản sau này có thể được bán. Không phải mã nguồn mở.","footer.yours":"Những gì bạn làm ra bằng nó là của bạn. Tác giả Oscillate không đòi quyền sở hữu với các dự án, MIDI, âm thanh hay bản kết xuất mà bạn tạo bằng nó.","features.7ffdfbe91dc1":"Một DAW đầy đủ có sẵn một phòng bên trong: tối đa bốn nhà sản xuất trong một phiên, trực tiếp, không tài khoản và không máy chủ.","features.02a7818a6ee0":"Trang này mô tả Freally Oscillate như nó sẽ là ở phiên bản 1.0 — bậc mà chiếc thang dừng lại — và không nói gì về những điều dự định sau đó.","features.b4a6bff8b8c9":"Mỗi con số là số đếm những gì phiên bản 1.0 mang theo. Không có gì được ước lượng và không có gì được làm tròn lên. Freally Secretarium chơi cùng thư viện nhạc cụ với Freally MIDI Master: một thư viện duy nhất, được cả hai ghim cùng một phiên bản, thay vì hai bản sao dần dần lệch nhau.","features.7ec427c672a2":"nhà sản xuất trong một phòng","features.d6f79cef6f38":"nhạc cụ và hiệu ứng của riêng nó","features.3a6743460cf9":"nhạc cụ trong Freally Secretarium","features.18c9c4777852":"âm giai trong piano roll","features.7241e8c55883":"bộ trống","features.23131443a715":"giao diện, sáng và tối, với màu xanh Freally","features.9bb4817f8251":"ngôn ngữ, kể cả viết từ phải sang trái","features.09b3154dfa60":"tài khoản phải tạo","features.35b8cb8439d7":"mô hình AI","features.38055402e560":"giá hiện tại","features.da9afac0d7b7":"Hiện tại nó miễn phí. Tất cả mọi thứ.","features.f997324cb19b":"Mọi tính năng, cho mọi người. Không có gói trả phí, không có bản dùng thử hết hạn, không khoá bản quyền, không tài khoản và không mua hàng trong ứng dụng.","features.22f1bb054323":"Những gì bạn làm ra bằng nó là của bạn. Tác giả Oscillate không đòi quyền sở hữu với các dự án, MIDI, âm thanh hay bản kết xuất mà bạn tạo bằng nó, và không đòi tiền bản quyền hay ghi công.","features.c74ea9dc9cd2":"Nó làm gì","features.45a1b4ecfbf5":"Một phòng không có máy chủ phía sau","features.c3ea64baf32c":"Gửi một mã phòng cho người bạn đang làm cùng, và tối đa ba nhà sản xuất khác có thể vào phiên của bạn: con trỏ của họ trên dòng thời gian của bạn, trò chuyện, giọng nói, ô camera và chia sẻ màn hình. Ngang hàng, không tài khoản và không có máy chủ nào ở giữa.","features.225507990407":"Lệnh hoàn tác của bạn là của bạn","features.cb2c6359ccf6":"<kbd>Ctrl</kbd>+<kbd>Z</kbd> lấy lại thay đổi gần nhất của bạn và không bao giờ của người khác, kể cả khi các chỉnh sửa của họ đang đổ về. Nhật ký chỉnh sửa đứng sau nó cũng chính là cơ chế đồng bộ của phòng, Tua lại phiên và bảng chia phần.","features.056c3540052c":"Bàn giao","features.be31856f2db7":"Trao một track cho một cộng sự và lấy lại bằng một phím. Khi họ đang giữ nó, họ là người duy nhất được ghi lên track đó — kể cả bạn cũng không — và điều đó được thực thi ở nơi các chỉnh sửa được kiểm tra, chứ không chỉ trong giao diện.","features.f4d5f7765113":"Kumite","features.d3a91a73c5cc":"Một chế độ đấu beat trong đó mỗi lượt sở hữu các ô nhịp của riêng mình. Đồng hồ đếm ngược chỉ là đồng hồ đếm ngược; các ô nhịp mới là luật, nên hai máy tính không bao giờ có thể bất đồng về việc chỉnh sửa của ai là hợp lệ.","features.6ed23a3037fc":"Bảng chia phần","features.68481398e863":"Ai viết gì, rút ra từ nhật ký chỉnh sửa, đã trừ đi phần việc mà ai đó đã hoàn tác. Một điểm khởi đầu cho cuộc trò chuyện về ghi công, không phải văn bản pháp lý — và nó nói rõ như vậy.","features.6ffb37f5c47d":"Take được gửi đi; sample thì không bao giờ","features.2dc43d70f9ea":"Một take được thu trong phòng sẽ nằm trên dòng thời gian của mọi người. Một sample bạn đã mua thì không bao giờ được gửi: phòng gửi tham chiếu, và cộng sự nào không có gói đó sẽ được cho biết họ cần những sample nào.","features.c3e61cb4f392":"MixSir — bản mix trên điện thoại của bạn","features.e0dafbc1f74f":"Gửi bản mix và từng phần đến một điện thoại trong mạng Wi-Fi của bạn qua một mã QR. Nó mở trong trình duyệt của điện thoại mà không cần cài gì, mix ngay tại đó với gain, pan, tắt tiếng và solo, và lưu bất kỳ phần nào vào điện thoại thành một tệp. Nó chỉ đi qua mạng của chính bạn, sau một khóa chỉ tạo cho riêng lần ghép nối đó. Mới trong v0.16.0.","features.2e5511855cbc":"Bản phối","features.b9277cfd1dc1":"Không giới hạn track âm thanh và MIDI, các clip được vẽ từ đúng nội dung của chúng, tự động hoá trên mọi fader, pan và nút điều khiển thiết bị, ghép take, nhóm, đánh dấu, cùng các bản đồ nhịp độ và loại nhịp. Một pattern đặt mười lần vẫn là một pattern: sửa một lần thì mọi chỗ đặt đều thay đổi, cho tới khi bạn tách một chỗ thành bản riêng.","features.3a0225628776":"Bộ phát clip và nhiều bản phối","features.09461b13e994":"Phát clip và cả cảnh đúng vào ô nhịp, để cảnh này nối tiếp cảnh kia, và ghi những gì bạn đã phát trở lại bản phối trong một bước hoàn tác. Một dự án chứa nhiều bản phối của một bài hát, mỗi bản có clip và điểm đánh dấu riêng trên cùng các track và bàn trộn. Pattern được vẽ lặp dọc theo một làn, một thanh thu phóng nằm phía trên dòng thời gian, và mỗi công cụ có phím riêng. Mới trong v0.16.0.","features.3933d56d65a8":"Nhát cắt và Tua lại phiên","features.7e57d69f84a4":"Kéo một nhát lưỡi dao ngang bản phối và nó cắt mọi clip mà nhát ấy đi qua, góc của nét quyết định crossfade. Tua tới tua lui lịch sử của phiên như một đoạn video, và rẽ nhánh từ bất kỳ điểm nào trong đó.","features.dac11b27d868":"Piano roll","features.8b5fc8a25fa8":"Khoảng chín mươi âm giai có tô sáng, bám lưới và gập, nốt bóng mờ từ bất kỳ clip nào khác, một làn velocity với một tay cầm cho mỗi nốt, các làn cho biết mỗi nốt phát thường xuyên tới đâu và velocity của nó dao động xa tới đâu, cùng một bàn phím nơi một phím có thể chơi cả một hợp âm.","features.a40e410cd4b9":"Giá pattern","features.6c8a2c880e29":"Dựng một phần từng hàng một phía trên bản phối, nhấp chọn bước ngay trong giá: mỗi hàng trên một dòng với đèn, pan, âm lượng và solo của chính track, cùng một đồ thị velocity, pan, cao độ tinh chỉnh và xác suất của từng bước. Chế độ Pattern lặp pattern đang mở bằng chính âm thanh của các track trong đó mà không đụng tới bài hát, và Đặt pattern đưa nó vào bài hát, có liên kết. Mới trong v0.9.0, được trau chuốt trong v0.10.0.","features.510ceece9d3b":"Drum Machine và lưới trống","features.e81deb2b9e8b":"Mười sáu pad trên bốn bộ trống tích hợp, mỗi nhát đánh được chọn theo độ mạnh bạn đánh, với tối đa bốn lớp cho mỗi pad, nhóm chặn tiếng, đảo ngược và chuẩn hoá. Lưới trống là một bộ trình tự bước có swing và velocity, Bản đồ trống chơi phần trống được viết cho bộ trống khác trên bộ của bạn, và chính bộ điều khiển pad của bạn có thể học các pad. Mới trong v0.9.0.","features.87200be7fce5":"Sân khấu","features.c40c7b78e163":"Đôi tay trên một cây piano, guitar, bass, bộ điều khiển pad hay bộ trống 3D chơi bất kỳ track MIDI nào, khớp nhịp với transport. Chọn camera, chất lượng và màu da, rồi tự mình chơi trên track đã bật sẵn sàng thu. Mới trong v0.9.0.","features.578fae09a667":"Bản nhạc, TAB và PDF","features.ca873a2c8b0a":"Bất kỳ track MIDI nào cũng được ghi thành bản nhạc trong một bảng riêng: khuông khóa Sol, khóa Fa hoặc khuông kép, TAB guitar và bass kèm sơ đồ hợp âm, bản nhạc trống ghi rõ tay hay chân nào đánh mỗi nhát, và lời dưới các nốt. Các trang lật theo bài hát và làm sáng những nốt đang vang, và cả bài hát xuất ra thành PDF A4 có trang bìa và phần ghi công, hoặc in ra. Mới trong v0.10.0.","features.cb4ad503e340":"Bài học","features.60f0879d73b2":"Mười lăm khóa học, học từng ngày: piano, guitar, bass và trống, đọc nhạc và tiết tấu, luyện tai và nhạc lý, sáng tác, viết lời, rap, phối khí và trộn âm. Cho xem chơi trước từng bước trên sân khấu, Đọc to đọc nó bằng giọng có sẵn trên máy tính của bạn, và bài học lắng nghe nhạc cụ của bạn qua giao diện âm thanh, chỉ trên máy tính này và không ghi âm gì, rồi chỉ ra ô nhịp, phách và cách sửa. Dự án của bạn chờ, nguyên vẹn, trong lúc bạn học. Mới trong v0.12.0.","features.50f00c2a81bc":"Trình duyệt nhạc cụ","features.72db395b279f":"Toàn bộ 1.648 nhạc cụ trong các thư mục theo họ nhạc cụ, dấu sao cho những cái bạn hay quay lại, âm thanh của riêng bạn, và phần nghe thử phát chính các nốt của track đang chọn qua từng nhạc cụ. PACK gom tối đa 25 one-shot và xuất chúng thành tệp WAV. Mới trong v0.9.0.","features.e840a6b2c21b":"Tìm âm tương tự cùng Ghép kick và bass","features.4db0c395341e":"Tìm âm tương tự xếp hạng các tệp giống một âm thanh hoặc một vòng MIDI trong các thư mục của bạn, mỗi tệp kèm lý do: một bản lưu lại, đổi mức âm lượng, cắt bớt, đổi cao độ hoặc kéo giãn, cùng nhịp điệu. Ghép kick và bass xếp hạng mọi tiếng bass trong một thư mục so với một tiếng kick, kèm mức chỉnh tông để hai tiếng khớp cao độ với nhau. Đo đạc, không phải mô hình. Mới trong v0.16.0.","features.2f4a9c0d9ce6":"Chơi trực tiếp","features.ea63c07ebd35":"Một bàn phím MIDI chơi track đã bật sẵn sàng thu với dịch giọng, phạm vi bend, đường cong lực nhấn và hợp âm trong âm giai của dự án. Bánh xe cao độ, bánh xe điều biến và lực nhấn đi tới các nhạc cụ trong thư viện và plugin của bạn. Mới trong v0.9.0.","features.a4592301df0c":"Thu âm và ghép take","features.3b56c85ac1f3":"Thu âm và bàn phím MIDI phần cứng trên Windows, macOS và Linux. Các take xếp chồng bên dưới nhau, bạn chọn những phần mình muốn, và những take bạn không chọn không bao giờ bị xoá. Âm thanh được ghi xuống đĩa ngay khi tới, nên một lần sập chỉ làm mất khối cuối cùng chứ không mất cả take.","features.724e8a91b5e7":"Oscillate Retro Record","features.d2c74ab7b9ea":"Vài phút gần nhất của đầu vào âm thanh và bàn phím MIDI của bạn, được giữ trong bộ nhớ của máy tính này, để take bạn đã chơi trước khi bấm ghi vẫn có thể được lưu: thành một clip trên track tại ô nhịp bạn đã chơi, hoặc thành một tệp WAV mang ngày và giờ của nó. Nó hỏi trước, hiện một đèn trong lúc đang giữ bất cứ thứ gì, và không ghi gì cho đến khi bạn lưu. Mới trong v0.16.0.","features.7784d462ad95":"Dời cao độ và kéo giãn","features.835c8aaec6ac":"Dời một khoảng của bản thu lên hoặc xuống tối đa một quãng tám mà vẫn giữ formant, để một giọng hát vẫn là chính nó, và khớp một clip với nhịp độ mà không đổi cao độ. Tệp của bạn không bao giờ bị động tới, và mọi bản xuất cũng như mọi cộng tác viên đều nghe như nhau. Mới trong v0.12.0.","features.0baacdf5d6c4":"Plugin của bạn, mỗi cái trong một tiến trình riêng","features.5fab46c33502":"VST3 và CLAP. Plugin nào sập thì chỉ thiết bị của nó bị làm xám, còn phiên vẫn chạy. Bù trễ được áp dụng trên toàn đồ thị và được chứng minh bằng phép thử triệt tiêu, và plugin nào máy này không có sẽ thành một ô giữ chỗ có tên, nên dự án mở ở máy khác vẫn khớp thời gian.","features.74ed3ebdb3f9":"Nhạc cụ và hiệu ứng của riêng nó","features.71af57e5f2e7":"Tám mươi lăm thiết bị, trong đó có Freally Secretarium cùng 1.648 nhạc cụ của nó, một bộ nhân đôi lần nào cũng ra giống hệt nhau, một bộ ducker được kích bởi một track khác, một bộ khoét dải trầm nhường chỗ cho kick, một tiếng reese có sub luôn giữ mono, bốn mươi feel viết tay, một còi hú, một delay zap laser, một cột đá granular và một cơn bão, và, mới trong v0.17.0, cặp dải trầm: Oscillate Sub, một sub-bass bám theo những gì bạn chơi, và Oscillate Width, mở rộng phần phía trên nó mà không bao giờ làm mỏng tổng mono, hai thiết bị dùng chung một crossover khi được liên kết. Mỗi bảng điều khiển được vẽ từ chính mô tả của thiết bị, nên con số trên một núm vặn là con số mà âm thanh đang dùng; mỗi mặt thiết bị vẽ trực tiếp âm thanh đi qua nó; và thiết lập của một thiết bị được sao chép thành một dòng bạn có thể dán vào khung chat.","features.afc35db2da83":"Thiết bị đọc được bản phối","features.8d6419ade018":"Sáu thiết bị làm được điều mà plugin không làm được, vì plugin không nhìn thấy bài hát mà nó nằm bên trong: một compressor đã sẵn sàng đè đoạn điệp khúc ngay khi nó tới, một gate mở ra cho một nhát đánh trước khi nó xảy ra, một delay xả hết vào vạch ô nhịp. Không thiết bị nào trong sáu cái thêm độ trễ.","features.bdb597b1232d":"Bàn trộn","features.6b2a31033aa1":"Mỗi track một dải kênh với fader, pan, tắt tiếng, solo, giá thiết bị, một đồng hồ đo được vẽ từ âm thanh mà engine thật sự tạo ra, và các núm Trầm, Trung, Cao, Phòng, Vọng, Nhiệt, Điều biến cao độ và Hạt bên cạnh một bộ nén của riêng nó. Ra-đa che lấp gọi tên hai track đang tranh nhau cùng một dải tần và tần số đó; bảng độ lớn hiển thị LUFS tích hợp và ngắn hạn, dải độ lớn và đỉnh thực, đối chiếu với mức mà mỗi dịch vụ phát trực tuyến nhắm tới.","features.cf29337c35e2":"Kiểm tra cuối","features.6acd50767d2a":"Một bản master cho mỗi nơi phát hành, từ Spotify và Apple Music đến đĩa CD, câu lạc bộ và phát sóng, được xuất cùng lúc từ một bản mix và mỗi bản được đo từ tệp của nó so với mục tiêu của nó. Nghe bản mix như điện thoại, ô tô, máy tính xách tay, loa nhỏ hay tai nghe nhét tai sẽ phát, đã được cân mức và không bao giờ in vào bản xuất; Bậc thang độ to kiểm tra độ to của từng đoạn, và Kiểm tra quy chuẩn đối chiếu một tệp với một quy chuẩn giao nộp rồi viết báo cáo. Mới trong v0.12.0.","features.5b8f86b084dc":"Gợi ý, và Mix giúp tôi","features.b8fee5c42dca":"Mỗi thẻ hiệu ứng đo những gì đến với nó và gợi ý một thiết lập kèm lý do, áp dụng trong một bước hoàn tác. Mix giúp tôi thiết lập mọi phần và đưa bản master về đúng nơi phát hành bạn đã đánh dấu, cũng trong một bước hoàn tác. Đó là phép tính số học trên kết quả đo, không phải một mô hình, nên cùng một bản mix sẽ nhận cùng một câu trả lời. Mới trong v0.12.0.","features.787726eabc9d":"Làn lời bài hát","features.1c110149d613":"Lời bài hát thành một làn trên dòng thời gian, khoá theo đầu phát, nhập từ <code>.txt</code> hoặc <code>.lrc</code> và sao chép vào dự án, với cỡ chữ để hát từ bên kia căn phòng. Một từ điển 327.000 từ hoàn tất và sửa từ khi bạn gõ, mỗi âm tiết rơi đúng nốt của nó, và dấu trọng âm, vần cùng sơ đồ vần và lưới flow giúp bạn viết. Mới trong v0.10.0.","features.c01fa2f5481f":"Thẻ phiên và Bản tua nhanh phiên","features.ef0a07e0d7a5":"Một phím tắt kết xuất một bức ảnh 1200×630 của phiên để đăng lên. Bản tua nhanh phiên dựng lại toàn bộ phiên từ nhật ký chỉnh sửa thành một ảnh động chia theo chương — kể cả một phiên mà không ai nghĩ tới việc ghi lại.","features.8b8dc99cf84d":"Phiên của bạn mở được mà không cần Oscillate","features.3ab5583a8c27":"Thư mục đi kèm ghi ra stem và MIDI mà bất kỳ DAW nào khác cũng mở được, thẳng hàng ở ô nhịp 1, theo định dạng, tần số lấy mẫu và độ sâu bit bạn chọn.","features.d91ad4caafa2":"Diện mạo chung của gia đình","features.cc88394d86d7":"Núm xoay, fader và nút bấm được kết xuất bằng Blender, chế độ sáng và tối với màu xanh Freally, những âm thanh giao diện ngắn mà bạn có thể tắt, và mười tám ngôn ngữ với bố cục phải-sang-trái thật sự — cùng một diện mạo trong mọi ứng dụng Freally.","features.c87ebc921598":"Không có gì lặng lẽ gửi dữ liệu về","features.587fbb00c1bb":"Không tài khoản và không dữ liệu đo từ xa. Nó chỉ dùng mạng trong bốn trường hợp: một phòng bạn đã mở hoặc tham gia, việc tra cứu địa chỉ trong lúc lập phòng đó, một lần kiểm tra cập nhật vốn tắt cho tới khi bạn bật lên, và MixSir, vốn phục vụ bản mix của bạn cho một điện thoại trong mạng của chính bạn chỉ trong lúc bạn đang gửi. Báo cáo sự cố nằm yên trên đĩa của bạn trừ khi bạn chọn gửi đi.","features.ae2bbaa95738":"Không AI, được bản dựng bảo đảm","features.db3a0428cdec":"Không mô hình, không suy luận, không có gì mang tính tạo sinh. Một cổng kiểm tra đi khắp đồ thị phụ thuộc và thất bại trước bất kỳ runtime suy luận hay tệp mô hình nào, nên đó là tính chất của bản dựng chứ không phải một câu trên website.","features.389cb06662bc":"Đặt cạnh các DAW hàng đầu","features.1b20c8037295":"Freally Oscillate như nó sẽ là ở phiên bản 1.0, đặt cạnh bảy sản phẩm thương mại như chúng được bán vào ngày 1 tháng 10 năm 2026 — lấy từ chính trang sản phẩm, cửa hàng, sách hướng dẫn và bài viết hỗ trợ của từng sản phẩm. Giá là giá niêm yết bằng đô la Mỹ.","features.dbdcc26cbc1a":"Freally Oscillate 1.0 và bảy DAW thương mại, so từng tính năng","features.0c4e9f0c201a":"Freally Oscillate 1.0","features.2088ae055e42":"FL Studio 2026","features.c2373bf58922":"Ableton Live 12","features.89d4cb070d7f":"Logic Pro","features.dec97310271f":"Bitwig Studio 6","features.41e8da85de51":"Cubase Pro 15","features.9a8405135cab":"Pro Tools","features.4da4dbb45aea":"Soundtrap","features.a6a1efe40897":"Giá vào ngày 1 tháng 10 năm 2026, bằng đô la Mỹ","features.4ade5154bd22":"Hiện tại miễn phí","features.20f8fb981865":"$99–$449, trả một lần","features.566c95f474af":"$99–$749, trả một lần","features.19be45f9b5eb":"$199.99 trả một lần, hoặc $12.99 mỗi tháng","features.5e5b2a65eaea":"$99–$399, trả một lần","features.7113d664c5d8":"$579.99, trả một lần","features.9a1ba45b0bfd":"Intro miễn phí; $99–$599 mỗi năm","features.385bc90ff4a3":"Gói miễn phí; $11.99–$20.99 mỗi tháng","features.40cbef707220":"Chạy trên Windows, macOS và Linux","features.85a39ab345d6":"Có","features.deb0147a950c":"Một phần","features.1abbc130b8d9":"Windows, macOS","features.1ea442a134b2":"Không","features.3f2f41cd023d":"chỉ macOS","features.d48bbcde1043":"ứng dụng cho Windows và macOS; Linux qua trình duyệt","features.3cb6a5ed0829":"Chạy plugin VST3","features.6bba86a6bb28":"chỉ Audio Units","features.7d13d66c4393":"chỉ AAX","features.0c8436827b99":"chỉ hiệu ứng, ở gói cao nhất","features.dcbac1a42d75":"Chạy plugin CLAP","features.3592cc9add20":"Plugin sập mà phiên vẫn chạy","features.b37c33f4180d":"mọi plugin, luôn luôn","features.4c8d11154068":"tuỳ chọn, chỉ VST","features.2089380a1ba9":"trên Apple silicon","features.151339072593":"Chưa xác minh được","features.fc8d60587699":"Dùng được mà không cần tài khoản nào","features.b7d5af4a8c98":"Nhiều nhà sản xuất cùng làm việc trong một phiên","features.7e6677e2efad":"tối đa bốn, trực tiếp","features.ba260ef541c6":"thu một người biểu diễn từ xa","features.c7514e6ebfe8":"từng track một, qua đám mây","features.36bd8f7a0c2d":"trực tiếp, trên đám mây của nó","features.956234fe74b6":"Giọng nói và camera với cộng sự, có sẵn","features.62f1fa1162e0":"với người biểu diễn đó","features.c870c00fa541":"chỉ trò chuyện bằng chữ","features.9f3893904d3d":"Cộng tác không có máy chủ và không có tài khoản ở giữa","features.b5db35f851fe":"ngang hàng","features.4c5f872abb2f":"Trao một track cho cộng sự, rồi lấy lại","features.f28162be8d9f":"quyền sở hữu track, theo yêu cầu","features.c3b01984557c":"Chế độ đấu beat","features.1d662dd62590":"Bảng chia phần rút ra từ việc ai sửa gì","features.e6195e7cff54":"Không có tính năng AI hay học máy","features.f0774f2a34b1":"được một cổng kiểm tra bảo đảm","features.7a210d79eda9":"không liệt kê tính năng nào","features.e5498b8a441d":"<strong>Nói ngắn gọn:</strong> mọi sản phẩm khác trong bảng đó đều đòi tài khoản, và sản phẩm nào cũng thu tiền cho bộ tính năng đầy đủ của mình. Hai trong số đó cho nhiều người cùng sửa một dự án — Pro Tools từng track một qua đám mây của nó, Soundtrap trực tiếp trên đám mây riêng của nó. Oscillate đặt bốn nhà sản xuất vào một bản phối, trực tiếp, ngang hàng, không tài khoản, và hiện tại nó miễn phí.","features.52242b315ce6":"Tổng hợp vào ngày 1 tháng 10 năm 2026. Chữ “Không” ở một tính năng nghĩa là tính năng đó không có trong danh sách tính năng, ghi chú phát hành hay sách hướng dẫn của chính sản phẩm đó vào ngày ấy. Sản phẩm thay đổi, và bảng này mô tả chúng như chúng đã là vào lúc đó. Tên sản phẩm là nhãn hiệu của chủ sở hữu tương ứng.","features.6977b748edc2":"Vì sao nó được xây dựng như vậy","features.662d60837a2d":"Không máy chủ, nên chẳng có gì để tắt","features.85567c225aa3":"Mã phòng chính là lời mời kết nối. Không có máy chủ thì không có gì phải duy trì, không có gì phải trả và không có gì ai đó có thể tắt đi — đó cũng là lý do một phòng chứa bốn nhà sản xuất chứ không phải bốn mươi: mỗi người gửi tới tất cả những người còn lại.","features.16275f3a5af9":"Một nhật ký, bốn công dụng","features.d2a4cd186952":"Mỗi chỉnh sửa là một thao tác trong một nhật ký duy nhất. Hoàn tác, đồng bộ của phòng, Tua lại phiên và bảng chia phần là bốn cách đọc nhật ký đó, vì thế lệnh hoàn tác của bạn có thể chỉ là của riêng bạn và ghi công có thể được rút ra thay vì phải gõ tay.","features.af0df7623348":"Sập là chuyện của một thiết bị, không phải cả phiên","features.600105cd00bc":"Mỗi plugin được chạy đều nằm trong một tiến trình riêng, và bản thân ứng dụng thậm chí không thể nạp một plugin nào. Plugin nào gục ngã thì thiết bị của nó bị làm xám, còn thanh điều khiển phát vẫn tiếp tục chạy.","features.908ec1ae94d2":"Con số bạn thấy là con số trong âm thanh","features.b6fc9acbd76d":"Đồng hồ đo được vẽ từ những gì engine tạo ra, số hiển thị trên núm vặn từ giá trị mà DSP đang dùng, và một phép đo bị tụt lại sẽ nói ra. Không có gì trên màn hình là phỏng đoán.","features.944f018d9f74":"Mọi thứ ở lại trên máy của bạn","features.70a55e97f377":"Dự án, âm thanh và MIDI của bạn chỉ rời máy tính của bạn khi bạn đang ở trong một phòng với ai đó — và khi ấy chúng đi thẳng tới những người trong phòng, không qua đám mây của bất kỳ ai.","features.bd873b549bc7":"Những gì vẫn đang tới","features.735112899b1c":"Nói thẳng ra, vì một danh sách tính năng giấu đi chỗ còn thiếu thì chẳng đáng đọc. Mọi thứ ở trên là những gì phiên bản 1.0 dự kiến có, và đây là những gì vẫn còn nằm giữa hiện tại và đích đến ấy.","features.d9d391384838":"Những điều 1.0 sẽ không làm","features.7d48e18b39c1":"<strong>Chạy plugin AU hay VST2.</strong> Nó chạy VST3 và CLAP.","features.a1eea7d00cdd":"<strong>Dùng ASIO.</strong> Trên Windows, đường độ trễ thấp là WASAPI độc quyền, và Oscillate cho bạn biết bạn thực sự nhận được chế độ nào.","features.1bcf2a5c1071":"<strong>Chứa hơn bốn nhà sản xuất trong một phòng.</strong> Kết nối thứ năm là chỗ đường tải lên gia đình thông thường cạn kiệt.","features.37e6fd7fe6f5":"<strong>Chuyển tiếp một kết nối không hình thành được.</strong> Khoảng một trong mười kết nối sẽ không hình thành nếu không có relay ở giữa; Oscillate gọi tên nguyên nhân, và phần Cài đặt nhận relay của riêng bạn.","features.d32646eadd7e":"<strong>Chia sẻ màn hình từ macOS.</strong> Chia sẻ màn hình có trên Windows và Linux; trên macOS nút đó vắng mặt và nói lý do.","features.3b50036d04c0":"Trang này không có beta, không có bản xem trước, không có truy cập sớm. Cho tới 1.0.0, câu trả lời thật lòng cho câu hỏi “tải nó ở đâu” là <em>chưa có</em>.","docs.lede":"Sách hướng dẫn: mọi bảng điều khiển, mọi trình chỉnh sửa, phòng, plugin và các giới hạn.","docs.831d0f72d242":"Bắt đầu","docs.365101815fb2":"Cửa sổ và các bảng","docs.2e5511855cbc":"Bản phối","docs.dac11b27d868":"Piano roll","docs.a232ac37bd92":"Lưới trống","docs.1a3a9fb87365":"Trình chỉnh sửa dạng sóng","docs.a40e410cd4b9":"Giá pattern","docs.d909750b1bbb":"Tự động hoá","docs.a4592301df0c":"Thu âm và ghép take","docs.724e8a91b5e7":"Oscillate Retro Record","docs.2f4a9c0d9ce6":"Chơi trực tiếp","docs.bdb597b1232d":"Bàn trộn","docs.529d3ce4c95e":"Sân khấu","docs.10e78b267d72":"Bản nhạc","docs.cb4ad503e340":"Bài học","docs.9514b7ff4860":"Plugin","docs.c80fbc216c04":"Thiết bị đi kèm","docs.4854ad4c206c":"Trình duyệt tệp","docs.542aa51c9ff9":"Phòng","docs.c3e61cb4f392":"MixSir — bản mix trên điện thoại của bạn","docs.ba5e0c669f84":"Kumite và bảng chia phần","docs.787726eabc9d":"Làn lời bài hát","docs.3664895579f0":"Xuất","docs.b04b9b7961b7":"Kiểm tra cuối","docs.74a883a037bc":"Cài đặt","docs.22e2bada8f1c":"Cập nhật","docs.46e978d0c193":"Phím tắt","docs.69bd78234ffb":"Riêng tư và mạng","docs.8e388ee7590d":"Các giới hạn, nói thẳng","docs.c3af076f92c5":"Xử lý sự cố","docs.05df7711cd6c":"Oscillate được cài như mọi ứng dụng máy tính khác và chạy ngoại tuyến. Lần đầu mở, bạn sẽ thấy bản thoả thuận; bạn phải chấp nhận nó thì ứng dụng mới mở, và bạn có thể mở lại nó bất cứ lúc nào từ <strong>Cài đặt ▸ Giới thiệu ▸ Xem thoả thuận</strong>.","docs.fb63caf27515":"Sau đó bạn ở trong một phiên tên là <em>Dự án mới</em>. Không có gì được lưu ở đâu cả cho tới khi bạn lưu, ngoại trừ nhật ký sự cố — nó ghi lại mọi thay đổi ngay khi bạn thực hiện, để một lần sập không làm bạn mất gì thay vì mất cả buổi chiều.","docs.shot.start":"Cửa sổ Oscillate trong lần chạy đầu tiên, với các phím điều khiển phát Phát, Dừng và Thu âm được đóng khung đỏ ở góc trên bên trái, Giá pattern bên dưới và bố cục ở dưới nữa.","docs.81a2f5639f44":"Cửa sổ trong lần chạy đầu tiên. Các phím được đóng khung là thanh điều khiển phát: phát, dừng và thu, ở góc trên bên trái.","docs.a8522c985343":"Nhấn <kbd>Space</kbd> để bắt đầu và dừng. Kéo một âm thanh từ Trình duyệt tệp vào một track, hoặc nhấp đúp vào một chỗ trống của track MIDI để tạo clip và bắt đầu viết.","docs.ebd61574858f":"Cửa sổ không có viền và Oscillate tự vẽ các nút thu nhỏ, phóng to và đóng. Nó mở ra gọn gàng: thanh điều khiển phát, Giá pattern gắn phía trên bản phối, và bản phối. Mỗi bảng được hiện và ẩn bằng phím của nó trên thanh tiêu đề, bằng mục của nó trong trình đơn <strong>Xem</strong>, hoặc bằng phím tắt:","docs.99a52df3ff3d":"Phím","docs.d0d91173008b":"Bảng","docs.1f36becc3aa7":"Nó là gì","docs.d6f6a04891cc":"Trình duyệt tệp","docs.495763c88db7":"Âm thanh của bạn, plugin của bạn và các thiết bị riêng của Oscillate, kèm nghe thử.","docs.30330bf56a43":"Giá pattern","docs.6d2af2be1078":"Các pattern bạn dựng từng hàng một, gắn phía trên bản phối với một thanh chia ở giữa.","docs.936a161c3931":"Trình chỉnh sửa","docs.05db484cdeb8":"Piano roll, lưới trống, tự động hoá và trình chỉnh sửa dạng sóng.","docs.8ae012d51747":"Bàn trộn","docs.f1972360c8eb":"Fader, đồng hồ đo, Ra-đa che lấp và bảng độ lớn.","docs.911ea89c43d9":"Phòng","docs.b0ab31730a7d":"Mã phòng, danh sách thành viên, trò chuyện, giọng nói, camera và chia sẻ màn hình, cùng bản mix của bạn gửi đến điện thoại.","docs.de838855e4a6":"Sân khấu","docs.5b84a6db221d":"Đôi tay chơi các track MIDI của bạn trên một nhạc cụ 3D, khớp nhịp với transport.","docs.b696ffb49270":"Bất kỳ track MIDI nào dưới dạng bản nhạc, chạy theo đầu phát.","docs.7a7b5b9b8db5":"Mười lăm khóa học, học từng ngày: mỗi bài cho bạn thấy cách làm, rồi lắng nghe khi bạn chơi.","docs.48e75eca2fe2":"Một bản master cho mỗi nơi phát hành, được kiểm tra như điện thoại và ô tô phát, từng đoạn một và theo một quy chuẩn giao nộp.","docs.f58d0e706b34":"Trên macOS, mọi phím <kbd>Ctrl</kbd> dưới đây là <kbd>Cmd</kbd>.","docs.c06b71382c0f":"Các bảng trong cửa sổ riêng","docs.80fe13adbb5b":"<strong>Bàn trộn</strong>, <strong>Trình duyệt tệp</strong>, <strong>Trình chỉnh sửa</strong>, <strong>Phòng</strong> và <strong>Kiểm tra cuối</strong> nằm trong các cửa sổ riêng, ẩn cho tới khi bạn mở chúng. Nút <strong>✕</strong> của cửa sổ một bảng sẽ ẩn nó; nút <strong>⇲</strong> gắn bảng vào cửa sổ chính, ở trạng thái hiện; và nút <strong>⇱</strong> của một bảng đã gắn sẽ tách nó ra cửa sổ riêng lần nữa. Giá pattern được gắn vào và tách ra theo cùng cách đó. Chỗ của mỗi bảng được ghi nhớ trên máy tính này, và cửa sổ bảng vẫn hoạt động trên màn hình thứ hai. Sân khấu, Bản nhạc và Bài học luôn ở trong cửa sổ chính.","docs.966384c2cfde":"Cửa sổ bảng lần đầu mở bên cạnh cửa sổ chính, xếp so le, và sau đó ở chỗ bạn đã để nó, hoặc lại bên cạnh cửa sổ chính nếu màn hình đó không còn. Cửa sổ Trình chỉnh sửa lần đầu mở ở kích thước 1360 × 928, đủ chỗ cho thanh công cụ của piano roll, hai quãng tám, làn tự động hoá và các làn take của nó; khi được gắn vào, trình chỉnh sửa giữ 260 pixel và cuộn.","docs.7b1c22e704ec":"Một cửa sổ bảng đang mở khi Oscillate đóng sẽ mở lại ở lần khởi động sau, đúng chỗ bạn để nó, một khi cửa sổ chính đã hiện và bản thoả thuận đã được chấp nhận; cửa sổ nào có màn hình đã không còn thì sẽ trở lại bên cạnh cửa sổ chính. Một cửa sổ bạn đã đóng thì vẫn đóng. Những gì đang mở được ghi lại ngay khi bạn mở và đóng cửa sổ, không chỉ lúc bạn thoát, nên một lần sập cũng giữ được điều đó.","docs.771bc108d512":"Một bản cài đặt từ trước 0.10.0 chuyển sang bố cục này một lần, ở lần khởi động đầu tiên, và giữ nguyên kích thước các bảng. Trong lúc phần hướng dẫn (<strong>Trợ giúp ▸ Hướng dẫn</strong>) chạy, Trình duyệt tệp và Trình chỉnh sửa vào cửa sổ chính để nó có thể chỉ vào chúng, rồi trở về cửa sổ của chúng khi kết thúc.","docs.2ae2bf6b8884":"Kéo thanh chia giữa hai bảng để đổi kích thước. Khi cửa sổ hẹp hơn 1280 pixel, các bảng bên sẽ tự thu gọn, vì bản phối hết dùng được trước khi chúng hết dùng được.","docs.226516acde25":"Một dòng thời gian với thước ô nhịp và phách, một lưới đi theo mức thu phóng, các đầu track dọc bên cạnh, và các clip được vẽ từ đúng nội dung của chúng — dạng sóng thật cho âm thanh, nốt thật cho một pattern.","docs.78d11d4d5db9":"Chỉnh sửa clip","docs.0bfc00f5a7ca":"Kéo một clip để di chuyển nó; giữ <kbd>Alt</kbd> trong khi kéo để sao chép.","docs.bb5fc5708305":"Kéo một trong hai đầu để cắt gọt; kéo góc trên để fade.","docs.c379e75c7075":"Kéo tay cầm lặp ở mép phải để lặp lại clip.","docs.196e45387bc2":"<kbd>Ctrl</kbd>+<kbd>Z</kbd> lấy lại toàn bộ thao tác — dù nó chạm vào bao nhiêu clip, chỉ một lần nhấn.","docs.65ca08c3ec91":"Nhát cắt","docs.51e37ec2c2d8":"Nhấn <kbd>C</kbd> để lấy lưỡi dao và kéo một nét ngang bản phối. Mọi clip mà nét đi qua đều bị tách tại chỗ nó đi qua, và góc của nét quyết định crossfade dài bao nhiêu: nét thẳng đứng là một nhát cắt gọn, nét thoai thoải là một lần hoà dài. Nhấn <kbd>V</kbd> để quay lại con trỏ.","docs.102bcc2b6fcb":"Biến một clip thành loại kia","docs.e6513c30872c":"Nhấp chuột phải vào một clip MIDI và chọn <strong>Kết xuất thành âm thanh</strong>; nhấp chuột phải vào một clip âm thanh và chọn <strong>Chuyển thành MIDI</strong>. Cách nào thì kết quả cũng nằm <em>bên cạnh</em> bản gốc chứ không đè lên nó, và một lần nhấn hoàn tác sẽ đưa mọi thứ về như cũ.","docs.04d699e071c9":"Một pattern được kết xuất qua bất cứ thứ gì có trên track đó: nhạc cụ trong khe của nó rồi đến mọi hiệu ứng âm thanh phía sau. Thiết bị bạn đã tắt không có trong bản kết xuất. Fader và pan của chính track cũng cố ý không có — clip mới phát qua chúng, nên in chúng vào sẽ áp dụng chúng hai lần.","docs.8d98a4cb90a8":"Chuyển âm thanh sang MIDI là việc không hoàn hảo và nó nói rõ điều đó: nó cho bạn biết có bao nhiêu nhát đánh mà nó không đọc ra được cao độ. Một vòng lặp trống chuyển ra chẳng được gì cả, và đó là câu trả lời thành thật.","docs.b64ff2ff46f9":"Khóa một track","docs.3badbc0f4fad":"Ổ khóa trên đầu track của một track âm thanh hoặc MIDI, trên dải kênh của nó trong bàn trộn và trên chip của nó trong khay của bảng Bản nhạc sẽ khóa track. Khi đang khóa, mọi thay đổi với nốt và clip của nó đều bị từ chối bằng một câu nêu tên track và bảo bạn mở khóa, dù thay đổi đến từ đâu: piano roll, lưới trống, Giá pattern, bản phối, một tệp được thả vào, Thu âm hay hoàn tác. Track cũng không thể bị xoá khi đang khóa. Một take đã đang thu khi khóa được bật vẫn được đặt vào khi bạn dừng. Trong phòng, khóa đến được với mọi người, và từ đó mọi thay đổi của chính mỗi người với track đều bị từ chối.","docs.364d70c63c7b":"Phần mix của nó vẫn tự do: tên, màu, fader, pan, tắt tiếng, solo, thiết bị và định tuyến đều vẫn đổi được. Khóa được lưu cùng dự án, chỉ cần một lần nhấn hoàn tác, và đến được với mọi người trong phòng.","docs.a707a40e3f2b":"Các công cụ và phím của chúng","docs.4696ab63ac11":"Thanh công cụ của bản phối chứa các công cụ của nó, và mỗi công cụ có một phím. Các phím này chỉ có tác dụng khi bản phối đang có tiêu điểm, nên ở chỗ khác bàn phím máy tính vẫn giữ các nốt của nó và Trình chỉnh sửa vẫn giữ các phím riêng. Phím nào cũng đổi được trong <strong>Cài đặt ▸ Phím tắt</strong>.","docs.c74ea9dc9cd2":"Nó làm gì","docs.27a3afb9e655":"Chọn: nhấn vào một clip, kéo một khung, <kbd>Shift</kbd> để thêm vào","docs.926996af2b7c":"Vẽ: một clip âm thanh mới để thu vào","docs.d268870bb66a":"Vẽ lặp: pattern hoặc clip đã chọn, được vẽ dọc theo một làn","docs.cae171a2c418":"Xóa: mọi clip mà một cú nhấp hoặc một lần kéo chạm tới","docs.c6ff289d9370":"Tắt tiếng: mọi clip mà một nét đi qua đều bị tắt hoặc bật lại tiếng","docs.b750b8649775":"Trượt nội dung: phần phát bên trong clip trượt đi; ở một mép, mép di chuyển và phần phát bên trong trượt theo","docs.36c14f300243":"Cắt: lưỡi dao, như ở mục Nhát cắt phía trên","docs.e8cff43cb178":"Nghe thử: một clip được nhấn sẽ phát riêng cho đến khi bạn thả ra","docs.2d9590dbdef9":"Với công cụ vẽ lặp hoặc công cụ xóa, nhấp chuột phải hay kéo chuột phải sẽ gỡ clip; <kbd>Shift</kbd> kèm nhấp chuột phải vẫn mở menu clip. Trượt nội dung ở một mép chỉ dời clip đó; các clip xung quanh vẫn ở nguyên chỗ. Nghe thử phát qua bộ nghe thử, không bao giờ qua transport: một clip âm thanh phát từ chỗ nó bắt đầu trong tệp, một pattern phát qua nhạc cụ trên track của nó. Nó được nghe mà không có các hiệu ứng của track, và một clip đã kéo giãn được nghe ở tốc độ gốc của tệp.","docs.3dd9a67f3b93":"Vẽ lặp pattern","docs.b1f731cac156":"Bộ chọn bên cạnh các track liệt kê những gì có thể vẽ lặp: các pattern của Giá pattern, các pattern MIDI và các clip âm thanh, mục hiện tại được làm sáng. Nhấn vào một mục để chọn nó, và công cụ vẽ lặp sẽ được chọn. Một cú nhấp vào một làn trống thả nó xuống theo lưới, và một lần kéo vẽ các bản sao nối đuôi nhau dọc theo làn, vòng qua các clip đã có ở đó; mỗi nét vẽ là một lần nhấn hoàn tác. Các bản sao liên kết với pattern của chúng, như mọi pattern đã đặt: sửa pattern thì mọi bản sao đều thay đổi, cho tới khi bạn tách một bản thành bản riêng.","docs.9848f51e01bf":"Nhấn vào một clip bằng con trỏ, công cụ vẽ hoặc công cụ vẽ lặp sẽ biến pattern của nó thành pattern hiện tại. <strong>Hiển thị</strong> của bộ chọn lọc theo loại, <strong>Chỉ cái chưa dùng</strong> chỉ giữ những pattern chưa bản phối nào phát, <strong>Thứ tự</strong> sắp xếp theo thứ tự tạo, theo tên, theo độ dài hoặc theo số lần dùng, và <strong>Nghe thử</strong> phát mục mà các phím mũi tên đang đứng.","docs.cae463c6e49a":"Thanh thu phóng","docs.25f57d4fd0f6":"Thanh phía trên thước thể hiện phần bài hát đang hiện trên màn hình. Kéo phần giữa của nó để cuộn, kéo một trong hai đầu để phóng to hoặc thu nhỏ quanh đầu còn lại, và nhấp đúp vào nó để vừa toàn bộ bài hát. Khi thanh đang có tiêu điểm, các phím mũi tên, <kbd>Page Up</kbd>, <kbd>Page Down</kbd>, <kbd>Home</kbd> và <kbd>End</kbd> cuộn nó, còn <kbd>Ctrl</kbd> kèm một phím mũi tên để thu phóng; các phím thu phóng và <kbd>Ctrl</kbd>+con lăn chuột cũng di chuyển nó. Bên dưới nó là một hình nhỏ của cả bài hát, clip của mỗi track mang màu của track đó. Trên thanh, con lăn chuột phóng to và thu nhỏ mà đầu trái của thanh vẫn giữ nguyên, còn <kbd>Shift</kbd>+con lăn chuột thì cuộn nó.","docs.d01650cb106c":"Làm thêm với clip","docs.b69a3372dea1":"Giữ <kbd>Alt</kbd> và kéo mép của một clip âm thanh sẽ kéo giãn nó tới độ dài mới mà vẫn giữ cao độ, từ một phần tư tới gấp bốn lần độ dài. Một clip bị đảo ngược hoặc đang lặp lại thì không kéo giãn được, và nó sẽ nói rõ điều đó.","docs.67a47eb07dd6":"<strong>Tên và màu…</strong> trên menu clip đổi tên một clip và gán cho nó một trong các màu của đầu track, hoặc màu riêng của track.","docs.722bad976090":"<kbd>Ctrl</kbd>+<kbd>C</kbd> sao chép các clip đã chọn và <kbd>Ctrl</kbd>+<kbd>V</kbd> dán chúng tại đầu phát, giữ nguyên khoảng cách giữa chúng.","docs.0e0083d2f7c1":"Menu Sắp xếp","docs.d052ab0af057":"Menu <strong>Sắp xếp</strong> trên thanh công cụ của bản phối làm việc trên các clip đã chọn hoặc track đã chọn. Mỗi mục làm thay đổi bài hát là một lần nhấn hoàn tác; chọn clip, sao chép và thu phóng thì không.","docs.cdea6d45b927":"<strong>Cắt ở mỗi vạch lưới</strong>, <strong>tại các điểm tấn công</strong> (trên âm thanh, bằng bộ dò riêng của trình chỉnh sửa âm thanh), hoặc <strong>tại các vùng trong tệp</strong> (các điểm cue và vùng mà một tệp WAV mang theo).","docs.a81713b16dde":"<strong>Gộp các mẫu đã chọn thành một</strong>: các clip pattern của một track trở thành một pattern mới phát mọi nốt mà chúng đã phát.","docs.423bba8b62c0":"<strong>Nhóm các clip đã chọn</strong>: nhấn vào một clip sẽ chọn cả nhóm, nên nhóm di chuyển, tắt tiếng và bị xóa như một khối, cho đến khi bạn bỏ nhóm.","docs.0b4bedb80285":"<strong>Chọn mọi bản sao</strong> của một clip, chọn <strong>các clip đã tắt tiếng</strong>, <strong>các clip chồng lên nhau</strong> hoặc <strong>các clip xếp chồng</strong>, hoặc <strong>Đảo vùng chọn</strong>.","docs.ed8f4699971e":"<strong>Tắt tiếng</strong> và <strong>Bật tiếng vùng chọn</strong>, cùng <strong>Căn điểm bắt đầu theo lưới</strong>.","docs.09a71aaece1b":"<strong>Chèn thời gian dài bằng vòng lặp</strong> dời mọi clip và điểm đánh dấu nằm sau điểm bắt đầu của vòng lặp đi một đoạn bằng độ dài của vòng lặp; <strong>Xóa đoạn của vòng lặp</strong> bỏ đi những gì nằm trong đoạn đó và khép khoảng trống lại. Một clip vắt qua mép của đoạn đó vẫn ở nguyên chỗ cũ.","docs.81acc44d9e0f":"<strong>Mọi track cỡ nhỏ</strong>, <strong>cỡ vừa</strong> hoặc <strong>cỡ lớn</strong>.","docs.4d5b9e912dcc":"<strong>Nhân bản track đã chọn</strong>, cùng các thiết bị, tự động hoá và clip của nó, ngay bên dưới nó; <strong>Đặt tên track đã chọn theo clip đầu tiên</strong>; <strong>Đưa track đã chọn lên</strong> hoặc <strong>xuống</strong>.","docs.77c05e6e69ab":"<strong>Thu phóng vào vùng chọn</strong>, cùng <strong>Dấu mốc trước</strong> và <strong>Dấu mốc sau</strong> (<kbd>Alt</kbd>+<kbd>←</kbd> và <kbd>Alt</kbd>+<kbd>→</kbd>).","docs.7ba68fe8ebf8":"<strong>Bám lưới</strong> còn có nốt móc ba, một phần sáu bước, và <strong>Mép clip</strong>, đặt một clip khít sát vào mép của clip khác khi nó ở gần, và bám theo lưới ở những chỗ khác.","docs.87453fed8996":"Điểm đánh dấu có tác dụng","docs.262f0a5ac20a":"Nhấp chuột phải vào một điểm đánh dấu trên thước để chọn việc nó làm: không làm gì, <strong>bài hát bắt đầu từ đây</strong> (khi bạn phát từ đầu; điểm đánh dấu như vậy nằm sớm nhất sẽ được dùng), <strong>quay lại đây từ dấu mốc sau</strong>, <strong>nhảy tới dấu mốc sau</strong>, hoặc <strong>dừng ở đây</strong>. Cũng cú nhấp chuột phải đó đổi số chỉ nhịp tính từ ô nhịp dưới con trỏ, hoặc bỏ một thay đổi nhịp tại chỗ nó bắt đầu.","docs.6feff1f9ed51":"Nhiều bản phối","docs.36f67f42cacb":"Một dự án có thể chứa nhiều bản phối của cùng một bài hát. Danh sách thả xuống <strong>Bản phối</strong> trên thanh công cụ của bản phối chuyển qua lại giữa chúng; menu <strong>Các bản phối</strong> bên cạnh có <strong>Bản phối mới</strong>, <strong>Sao chép bản phối này</strong>, <strong>Đổi tên bản phối này</strong>, <strong>Xóa bản phối này</strong> (trừ khi đó là bản duy nhất), và một mục <strong>Gộp … vào bản này</strong> cho mỗi bản còn lại. Mỗi bản phối giữ clip, điểm đánh dấu và các bước hoàn tác riêng, trên các track, pattern và bàn trộn mà chúng dùng chung, và phát, bounce và xuất luôn phát bản đang hiện trên màn hình. Chuyển, tạo và sao chép một bản phối không bao giờ là bước hoàn tác. Một dự án tạo từ trước khi có tính năng này sẽ mở ra thành một bản phối, đúng như cũ.","docs.4b2647bad0e5":"Trong một phòng, thao tác bản phối nào phải gửi hơn 1.024 thay đổi cùng lúc, tức khoảng 500 clip, sẽ bị từ chối kèm một câu nói rõ điều đó: chuyển, gộp, tạo mới, sao chép hay xóa một bản phối. Hãy đóng phòng để thay đổi một bản phối lớn đến thế.","docs.2f4a35fdf295":"Bộ phát clip","docs.047aa27c23ee":"<strong>Hiện bộ phát clip</strong>, trên thanh công cụ của bản phối, mở một lưới phía trên dòng thời gian: mỗi track âm thanh và MIDI một cột, mỗi cảnh một hàng. Nhấn vào một ô để phát clip của ô đó trên track của nó, lặp lại, thay cho thứ track đó đang phát; một ô trống sẽ dừng track. Mũi tên của một cảnh phát cả hàng của cảnh đó. <strong>Phát vào</strong> chọn thời điểm một lần phát bắt đầu: <em>Ô nhịp kế tiếp</em>, <em>Phách kế tiếp</em> hoặc <em>Ngay lập tức</em> (khi bài hát đang phát thì vào sau một phách). Phát một ô khi bài hát đang dừng sẽ cho bài hát chạy.","docs.81be37a5a73c":"Một ô hiện <em>Đang phát</em> khi clip của nó đang phát và <em>Đang chờ</em> khi nó đang chờ. Mỗi cột có <strong>Dừng</strong> cho track của nó, <strong>Dừng mọi track</strong> dừng tất cả, và <strong>Quay về bản phối</strong> đưa mọi track trở về bản phối. Các phím mũi tên di chuyển giữa các ô, và <kbd>Enter</kbd> hoặc <kbd>Space</kbd> nhấn một ô.","docs.c2c7a824e62c":"<strong>Cảnh mới từ các clip dưới đầu phát</strong> tạo một hàng gồm những gì đang phát ở đó, và <strong>Cảnh trống mới</strong> tạo một hàng trống; menu của một ô đặt clip đang chọn vào ô đó — clip âm thanh dưới track âm thanh và clip MIDI dưới track MIDI — hoặc làm trống ô. Sau 1 đến 64 ô nhịp, một cảnh có thể tự chuyển tiếp: <em>Cảnh kế tiếp</em>, <em>Cảnh trước</em>, <em>Cảnh đầu tiên</em>, <em>Cảnh bất kỳ</em> (một cảnh khác, ngẫu nhiên), <em>Dừng tất cả</em>, hoặc <em>Không chuyển</em>.","docs.d0302eb0b177":"Một lần phát không bao giờ là một bước hoàn tác. Khi bật <strong>Ghi lại màn trình diễn</strong>, những gì bạn đã phát được ghi vào bản phối ở đúng chỗ nó đã phát, thay cho những gì các track đó có ở đó, gói trong một lần nhấn hoàn tác; một track bị khóa được giữ nguyên, và báo rõ điều đó.","docs.2b18129f93b9":"Nhấp đúp vào một clip MIDI để mở nó. Một cú nhấp vào chỗ trống trên lưới sẽ vẽ một nốt, và <kbd>P</kbd> chọn Vẽ, công cụ lúc nào cũng vẽ; xem <a href=\"#roll-tools\">Các công cụ</a> bên dưới. Bàn phím dọc bên trái chơi nhạc cụ trên track, và có thể đặt để một phím chơi cả một hợp âm.","docs.42a0052bf1b6":"Âm giai","docs.ddbef0217d41":"Khoảng chín mươi âm giai. Chọn một âm giai sẽ tô sáng các nốt của nó, và <kbd>Ctrl</kbd>+<kbd>K</kbd> đưa những gì đang chọn về âm giai đó. Gập sẽ ẩn mọi hàng không thuộc âm giai, biến một lưới bán cung thành một lưới bạn đọc được.","docs.2cafc9e7c3b3":"Các thao tác với nốt","docs.0baf2bf51650":"Lượng tử hoá — bám các nốt đã chọn vào lưới","docs.ea07e2f557fe":"Nhân tính hoá — đẩy chúng lệch khỏi lưới một chút","docs.0ab966bf90ea":"Legato — kéo dài mỗi nốt cho chạm tới nốt kế tiếp","docs.6a31f294ca42":"Đảo ngược thứ tự các nốt đã chọn","docs.4cde53316a6e":"Đưa chúng về âm giai của clip","docs.16aac93d1c5b":"Nhân bản tại chỗ","docs.6e14c1f152dd":"Nhân bản ra phía sau — cách thường dùng để dựng một đoạn","docs.3acb04d66cdb":"Xê dịch một ô lưới","docs.22667e7b7cca":"Dịch một nửa cung; với <kbd>Shift</kbd>, một quãng tám","docs.af2e3ba89e9f":"Làn velocity dưới lưới có một tay cầm cho mỗi nốt. Nốt bóng mờ từ bất kỳ clip nào khác có thể được vẽ phía sau clip bạn đang sửa — đó là cách viết một dòng bass theo phần hợp âm mà không phải chuyển qua chuyển lại.","docs.1d72dc650e42":"Các công cụ","docs.b6bd035c8802":"<strong>Công cụ</strong> của piano roll là <em>Chọn</em>, <em>Vẽ</em>, <em>Tô</em>, <em>Xoá</em>, <em>Tắt tiếng</em> hoặc <em>Cắt lát</em>, và <kbd>P</kbd> chuyển qua lại giữa Vẽ và Chọn. Dù đang dùng công cụ nào, nhấp chuột phải hay kéo chuột phải cũng xóa các nốt mà nó đi qua, và <kbd>Ctrl</kbd>+kéo vẽ một khung để chọn nốt, <kbd>Shift</kbd> để thêm vào khung chọn. Một cú nhấp vào chỗ trống trên lưới vẽ một nốt dài bằng bước bắt dính, trừ khi đang có nốt được chọn, khi đó nó bỏ chọn; với Vẽ thì nó luôn vẽ. Kéo một nốt sẽ di chuyển nó, còn các mép của nốt, nơi con trỏ hiện [ và ], kéo dài và rút ngắn nó. Trong lúc kéo một nốt, các thanh của nó trong các làn bên dưới cũng di chuyển theo.","docs.7f660c0fd5ab":"Công cụ quyết định một lần kéo thường trên chỗ trống của lưới sẽ làm gì. <em>Tô</em> đặt một nốt vào mỗi bước bắt dính mà lần kéo đi qua nếu ở đó chưa có nốt; <em>Xoá</em> gỡ những gì nó đi qua; <em>Tắt tiếng</em> tắt hoặc bật tiếng các nốt, và nốt bị tắt tiếng được vẽ rỗng; <em>Cắt lát</em> cắt mọi nốt nó đi qua. Với Xoá, Tắt tiếng và Cắt lát, nhấn vào một nốt cũng làm việc của công cụ đó, trừ khi giữ <kbd>Ctrl</kbd>.","docs.41b4d9d1f165":"Lưới vẽ một vạch ở mỗi bước bắt dính đủ xa nhau để đọc được, chùm ba được vẽ thành chùm ba, các ô nhịp xen kẽ được tô bóng, hoặc các phách xen kẽ khi phóng to, và các ô nhịp của lưới theo đúng số chỉ nhịp của bài hát. <strong>Bắt dính</strong> còn có 1/32, chùm ba móc kép, một phần sáu bước, <em>Mép nốt</em> và <em>Dấu</em>. Một clip mở ra với bắt dính nốt móc kép, công cụ Chọn đang được chọn và các hàng cao 18 px.","docs.083fa2e74b39":"Hợp âm và màu","docs.87929e0f6173":"<strong>Con dấu</strong> vẽ một hợp âm với mỗi cú nhấp thay vì một nốt: <em>Trưởng</em>, <em>Thứ</em>, <em>Giảm</em>, <em>Tăng</em>, <em>Sus4</em>, <em>Bảy át</em>, <em>Bảy thứ</em> hoặc <em>Quãng tám</em>, và <em>Một nốt</em> để trở lại như cũ. Mười sáu màu đánh dấu các nốt: <strong>Tô màu này cho các nốt đã chọn</strong>, hoặc <strong>Chọn các nốt màu này</strong>. Tên mỗi nốt được ghi ngay trên nốt ở chỗ đủ vừa, và một phím của bàn phím dọc bên trái chọn mọi nốt cùng cao độ với nó.","docs.8f42006d363d":"Các menu Sửa, Công cụ khác và Thu phóng","docs.3070984d94ad":"<strong>Sửa</strong>: <strong>Cắt</strong>, <strong>Sao chép</strong> và <strong>Dán vào ô nhịp đầu tiên trên màn hình</strong> (<kbd>Ctrl</kbd>+<kbd>X</kbd>, <kbd>Ctrl</kbd>+<kbd>C</kbd>, <kbd>Ctrl</kbd>+<kbd>V</kbd>); tắt hoặc bật tiếng các nốt đã chọn; xoay chúng một bước sang trái hoặc phải; chọn mọi nốt, đảo lựa chọn, hoặc chọn các nốt đã tắt tiếng hay các nốt lệch phách; <strong>Thuộc tính nốt…</strong>; nhóm và bỏ nhóm các nốt đã chọn, để một nhóm di chuyển và bị xóa như một khối; và biến chúng thành nốt trượt hoặc cho lướt vào, hoặc tắt những điều đó.","docs.26835f506821":"<strong>Công cụ khác</strong>: <strong>Lượng tử hóa một nửa</strong> hoặc <strong>có swing</strong>; độ dài về 25, 50, 75 hoặc 150 %; <strong>Điểm kết về lưới</strong>; <strong>Mỗi nốt dài một bước</strong>; lực nhấn về 50, 80, 125 hoặc 150 %; và <strong>Giới hạn</strong> các nốt trong hai quãng tám, từ C1–B2 đến C5–B6.","docs.e1551223f247":"<strong>Thu phóng</strong>: phóng to, thu nhỏ, <strong>Vừa mọi nốt</strong> hoặc <strong>Vừa các nốt đã chọn</strong>.","docs.fe1be326be6b":"Thuộc tính nốt, trượt và lướt","docs.28b425b7cc4f":"Nhấp đúp vào một nốt, hoặc nhấn <strong>Thuộc tính nốt</strong>, để xem mọi con số của các nốt đã chọn: điểm bắt đầu, độ dài, cao độ, lực nhấn, lực nhả, xác suất, biên độ lực nhấn, cân bằng, cao độ tinh, Mod X, Mod Y và màu, số nào cũng gõ vào được, với <em>Khác nhau</em> ở chỗ các nốt đã chọn khác nhau. <strong>Nốt trượt</strong> làm một nốt không đánh tiếng nào mà uốn track tới cao độ của chính nó. <strong>Lướt vào (portamento)</strong> đánh một nốt từ nốt trước nó rồi lướt về đích trong một nốt móc kép, hoặc trong độ dài của chính nó nếu độ dài đó ngắn hơn.","docs.dbcb2e907348":"Một nốt trượt di chuyển bánh xe cao độ của track, nên mọi nốt đang vang trên track đó đều bị uốn theo, và một plugin chỉ theo được chính xác trong tầm uốn của riêng nó.","docs.3d8c81644dbb":"Nhiều làn hơn","docs.189f039326bf":"Các làn dưới lưới dùng chung một thanh chia mà bạn kéo, được ghi nhớ trên máy tính này, và <strong>Thêm làn</strong> cũng có <strong>Cân bằng</strong>, <strong>Cao độ tinh</strong>, <strong>Lực nhả</strong>, <strong>Mod X</strong> (bánh xe điều biến) và <strong>Mod Y</strong> (áp lực). Lực nhả là tốc độ mỗi nốt được thả ra: One-Shot Sampler, Multisampler, Drum Machine, Oscillate Grain Layers và Oscillate Siren ngân dài hơn khi nhả chậm và ngắn hơn khi nhả nhanh, và các plugin của bạn cũng được báo giá trị này.","docs.599e5055f4d0":"Pan và cao độ tinh chỉ được các nhạc cụ phát sample của chính Oscillate nhận, plugin thì không. Oscillate Grain Layers nhận Mod X và Mod Y theo từng nốt, còn Oscillate Siren nhận Mod Y; mọi nhạc cụ khác, và các plugin của bạn, nhận chúng cho cả track vào lúc mỗi nốt được đánh.","docs.db4c8113ce8e":"Một làn CC có thể ghi một LFO: chọn <strong>Dạng sóng LFO</strong> (sin, tam giác, vuông hoặc răng cưa), <strong>Tốc độ LFO</strong> (từ một ô nhịp đến một nốt móc kép) và <strong>Độ sâu LFO</strong> (25 đến 100 %), rồi <strong>Ghi LFO trên toàn mẫu</strong>, hoặc trong khoảng thời gian đã chọn, gói trong một lần nhấn hoàn tác. Làn CC vẫn được vẽ và lưu nhưng không được phát: chưa có nhạc cụ nào đọc nó.","docs.caf0b843d7e7":"Thước của piano roll","docs.2b2fc69a8046":"Piano roll có thước riêng. Kéo trên thước để nghe các nốt, và nhấp đúp vào nó để đặt một điểm đánh dấu; các điểm đánh dấu của bài hát hiện trong piano roll, và đầu phát chạy qua đó. <kbd>Alt</kbd>+kéo chọn một khoảng thời gian và <kbd>Alt</kbd>+nhấp bỏ chọn nó. Khi đó menu <strong>Sửa</strong> chèn khoảng trống theo khoảng đó, làm pattern dài ra; cắt các nốt rồi chèn khoảng trống; xóa khoảng thời gian đã chọn, làm pattern ngắn lại nhưng không bao giờ ngắn quá nốt cuối cùng của nó; cắt theo khoảng đó; bỏ chọn nó; hoặc đặt một điểm đánh dấu tại đó. <strong>Theo đầu phát</strong> dùng chung thiết lập với bản phối: bật ở bên này thì cả hai bên đều bật.","docs.e7b1751c9fce":"Vẫn clip đó nhưng nhìn theo mỗi hàng một trống thay vì mỗi hàng một cao độ, bày ra như một bộ trình tự bước. Khi bật <strong>Chỉ các tiếng đang dùng</strong>, chỉ những trống mà clip chơi mới có hàng. Mọi thứ trong bảng của piano roll ở trên cũng dùng được ở đây — bên dưới vẫn là cùng những nốt ấy — và <strong>Dạng piano roll</strong> đưa bạn trở lại piano roll.","docs.1de3df70ddf4":"Các bước","docs.b94b8809bf80":"Nhấp vào một bước để đặt hoặc xoá một nhát đánh. Kéo dọc một hàng để lấp đầy các bước, hoặc để xoá chúng nếu bước đầu tiên bạn nhấn đã được đặt. Kéo chuột phải thành một khung để bỏ các nhát đánh bên trong nó, và kéo ngược lại để đưa chúng trở về; chỉ nhấp chuột phải thôi sẽ bỏ nhát đánh nằm bên dưới. Mỗi lần kéo là một lần nhấn hoàn tác.","docs.0203ffa34c13":"Mỗi nhát đánh được vẽ thành một cột cao bằng velocity của nó, và nhát đánh nào chơi sớm hay muộn so với bước của nó sẽ được đánh dấu như vậy. Nhấp vào tên một hàng và các velocity của nó hiện ra trong một làn bên dưới lưới: kéo ngang qua các cột để vẽ lại chúng.","docs.5e9d430d1cc7":"<strong>Độ swing</strong>, từ 50 đến 75%, đẩy các nốt móc kép nghịch phách lùi về sau. Một nhát đánh chơi lệch khỏi lưới vẫn nằm đúng chỗ nó được chơi.","docs.c4f07fe24936":"Mỗi hàng có <strong>M</strong> để tắt tiếng nó và <strong>S</strong> để solo nó trong khi phần còn lại của bộ trống vẫn chơi, cùng một <strong>Nhóm chặn tiếng</strong>: một trống làm im mọi trống khác trong nhóm của nó, như hi-hat đóng cắt tiếng hi-hat mở. Trên một track Drum Machine, các hàng được đặt tên theo các pad của nó, và nhóm chặn tiếng của một hàng chính là của pad đó.","docs.e890f4ead6fc":"Bản đồ trống","docs.041ee2a55b4c":"Phần trống được viết cho cách sắp xếp của một bộ trống khác có thể chơi đúng các món trống trong bộ của bạn. Nhấn <strong>Bản đồ trống</strong> và chọn phần đó được <strong>Đọc theo</strong> kiểu nào: General MIDI, Ableton Drum Rack, FL Studio FPC, Logic Drummer, EZdrummer / Superior Drummer hoặc Addictive Drums. Mỗi nốt mà phần đó chứa có một hàng với các nhát đánh của nó và nó <strong>Chơi</strong> gì: một món trong bộ trống của bạn, 808 / bè trầm, hoặc <em>Không có trong bộ trống</em>. Hàng nào bạn đổi sẽ được đánh dấu, và <strong>Đặt lại</strong> đưa nó về như cũ.","docs.82482887ca62":"Bản thân các nốt không bao giờ thay đổi. Tắt bản đồ đi thì phần đó phát đúng y như lúc nó đến; khi bản đồ đang bật, việc phát lại, xuất, một clip được kéo ra ngoài và sân khấu đều làm theo nó.","docs.2b9c9a02b3e1":"Bộ điều khiển pad của bạn","docs.706ed9a82528":"Trong <strong>Cài đặt ▸ MIDI ▸ Bộ điều khiển pad</strong>, nhấn <strong>Học</strong> rồi đánh lần lượt từng pad trong 16 pad khi được yêu cầu, đếm từ góc dưới bên trái; <kbd>Esc</kbd> để huỷ. Từ đó trở đi, khi track đã bật sẵn sàng thu đang chơi một Drum Machine, các pad trên bộ điều khiển của bạn sẽ chơi các pad của nó. Cho tới khi bạn dạy nó, cách sắp xếp thông dụng được dùng: các nốt 36–51 tính từ góc dưới bên trái, và <strong>Quên</strong> sẽ đưa về cách đó.","docs.ad0418c17aab":"<strong>Bố cục</strong> chọn mỗi pad chơi trống nào, theo bố cục mặc định hoặc bố cục <em>Biểu diễn</em> đối xứng gương, và <strong>Ngón tay</strong> chọn những ngón mà sân khấu dùng để chơi một phần pad, từ một ngón trỏ tới tất cả các ngón.","docs.59321ef7fc8a":"Nhấp đúp vào một clip âm thanh để mở nó trong Trình chỉnh sửa: dạng sóng của nó, và bên dưới là những gì có thể làm với âm thanh. Không thao tác nào trong số đó thay đổi tệp của bạn.","docs.887110a8f108":"Dời cao độ","docs.d97419fdaf8a":"Kéo ngang qua dạng sóng để chọn một khoảng, đặt <strong>Nửa cung</strong> (−12 đến +12) và <strong>Cent</strong> (−50 đến +50), rồi nhấn <strong>Dời cao độ</strong>. Khoảng đó được dời mà vẫn giữ formant, nên một giọng hát được nâng lên một cung vẫn nghe như cùng một giọng. Các lần dời được vẽ thành một thanh bên dưới dạng sóng, và <strong>Xóa các lần dời cao độ</strong> gỡ bỏ tất cả chỉ trong một lần nhấn. Mỗi lần dời là một bước hoàn tác.","docs.18c66cec3729":"Oscillate tính toán âm thanh đã dời bên ngoài luồng âm thanh, có thanh tiến trình, và giữ nó trong thư mục dữ liệu của mình; cho tới khi xong, clip phát như cũ. Một lần cắt tỉa không bao giờ làm trượt một lần dời, mọi bản xuất đều mang theo nó, và trong một phòng những người khác tạo ra cùng một âm thanh từ cùng những con số.","docs.c0a913f88834":"Khớp clip với nhịp độ","docs.4e3b3aca2bff":"<strong>Khớp với nhịp độ</strong> làm một clip chạy theo nhịp độ của dự án, một khi <strong>Chất liệu dài bấy nhiêu ô nhịp</strong> cho biết nó dài bao nhiêu. <strong>Repitch</strong> phát nó nhanh hơn hoặc chậm hơn, như băng từ, nên cao độ của nó thay đổi theo nhịp độ; <strong>Stretch (giữ cao độ)</strong> thay đổi độ dài của nó và giữ nguyên cao độ, với trống và hợp âm cũng như với một giọng đơn. Âm thanh được kéo giãn được tạo theo cùng cách như một lần dời cao độ. Một clip bị đảo ngược hoặc lặp lại chưa thể theo nhịp độ, và sẽ nói rõ điều đó.","docs.a904c7da9d0d":"Một clip đã dời cao độ hoặc đã kéo giãn vẫn được vẽ theo tệp của nó: dạng sóng cho thấy bản thu, không phải âm thanh đang phát.","docs.5cc9827d169c":"Giá được gắn phía trên bản phối, với một thanh chia ở giữa, ngay từ lần đầu Oscillate mở ra. <kbd>Ctrl</kbd>+<kbd>2</kbd>, phím của nó trên thanh tiêu đề hoặc <strong>Xem ▸ Giá pattern</strong> hiện và ẩn nó. Nó hoạt động như trong FL Studio: dựng một phần ở đây, nghe riêng nó, và đặt nó vào bài hát khi đã sẵn sàng.","docs.d6b550dc23cd":"Pattern và hàng","docs.70d3e456e7e3":"Nhấn <strong>Pattern mới</strong> để tạo một pattern. Nút <strong>+</strong> ở góc dưới bên trái thêm một hàng: chọn một nhạc cụ từ các kệ của trình duyệt, tìm theo tên, và nó tạo một track MIDI mới với nhạc cụ đó rồi cho track một hàng, tất cả trong một bước hoàn tác. Cùng danh sách đó cũng thêm được một track đã có trong bài hát.","docs.0d6fa14f3070":"Một hàng là một track: tên và <strong>Thiết bị</strong> của hàng là của track đó, nên hàng phát qua nhạc cụ và hiệu ứng của track ấy. Mỗi hàng MIDI có một phần riêng ngay từ đầu; danh sách bên cạnh sẽ liên kết nó với một phần khác thay vào đó, hoặc bắt đầu một <strong>Phần trống mới</strong>.","docs.4c079b8f8d6a":"Một hàng trên một dòng","docs.453ea9f5b586":"Mỗi hàng đọc ngang trên một dòng, giống một kênh trong giá của FL Studio: đèn của nó, sáng khi track đang phát và tối khi bị tắt tiếng; các núm pan và âm lượng; nơi nó phát vào, master hoặc một nhóm; tên của nó; và <strong>S</strong>, nút solo (<kbd>Ctrl</kbd>-nhấp để solo nó cùng các track khác). Các núm chính là pan và fader trên bàn trộn của track, nên vặn một núm sẽ dời dải kênh trên bàn trộn, và bàn trộn cũng dời núm. <strong>Sửa</strong>, <strong>Đặt</strong>, <strong>Đưa lên</strong> và <strong>Bỏ</strong> là các phím nhỏ ở cuối hàng.","docs.34700af9e0c1":"<strong>Sửa</strong> mở phần của một hàng trong piano roll, hoặc trong lưới trống nếu là track trống. <strong>Đặt</strong> đưa nó lên track của nó tại đầu phát. <strong>Đặt pattern</strong> đưa mọi hàng lên track riêng của chúng tại đầu phát trong một bước hoàn tác, và mọi chỗ đặt vẫn liên kết với phần của nó: sửa pattern thì từng chỗ đặt cũng đổi theo.","docs.770d88831365":"Các bước trong giá","docs.26de49bf873c":"Các bước của một hàng nằm ngay trong giá, theo từng nhóm bốn được tô bóng xen kẽ, mỗi bước đang bật sáng tương ứng với velocity của nó. Một hàng giai điệu là một dãy bước trên một nốt bạn chọn bên cạnh nó. Một hàng trống mở ra thành một dãy bước cho mỗi âm thanh của nó, và <strong>Âm thanh</strong> gập nó lại. Nhấp vào một bước để bật nó, kéo để tô một chuỗi, và kéo chuột phải để xoá; mỗi lần kéo là một bước hoàn tác, và <kbd>Enter</kbd> hoặc <kbd>Space</kbd> bật bước đang có tiêu điểm. Một bước bạn bật lên sẽ phát âm thanh của nó khi đang dừng phát.","docs.09f96634c283":"Một giai điệu được viết trong piano roll lệch khỏi lưới bước sẽ hiện trong hàng của nó như một piano roll nhỏ trải ngang qua các bước. Nhấp đúp vào nó, hoặc nhấn <kbd>Enter</kbd> trên nó, để mở nó trong trình chỉnh sửa.","docs.fa59df488bcb":"Đồ thị","docs.7b51047c96dc":"Nhấp vào tên một hàng để mở đồ thị của nó bên dưới: các giá trị mà mỗi bước mang — <strong>Lực nhấn</strong>, <strong>Cân bằng</strong>, <strong>Cao độ tinh chỉnh</strong>, <strong>Xác suất</strong> và <strong>Biên độ velocity</strong>. Vẽ ngang qua các cột hoặc gõ một giá trị; mỗi lần quét là một bước hoàn tác.","docs.21a5f2258e03":"Pan và cao độ tinh chỉnh của từng bước được nghe thấy trên Drum Machine, One-Shot Sampler, Multisampler và Percussion Sampler, khi bài hát phát và trong các bản xuất. Modelled Synth, vốn chơi các nhạc cụ của thư viện, Section Player và Layer Rack chưa chơi chúng, và plugin nghe mọi bước ở chính giữa và đúng cao độ.","docs.3a6bb00d5a4c":"Độ dài, bước và swing","docs.037d8fb8ba6f":"Mỗi pattern có độ dài riêng tối đa 16 <strong>Ô nhịp</strong>, <strong>Bước</strong> riêng từ 1/4 đến 1/32, và <strong>Độ swing</strong> riêng. Đổi độ dài hoặc bước thì mọi phần trong pattern cũng đổi theo, và lựa chọn nào cần hơn 256 bước trong một hàng sẽ bị làm xám.","docs.95cea773b379":"Các bước nằm sau điểm kết thúc của pattern được vẽ mờ. Nhấn hoặc kéo ngang qua chúng, hoặc kéo tay nắm ở bước cuối, để pattern dài tới đó hoặc ngắn hơn; hoặc đặt số bước bằng <strong>−</strong>, con số và <strong>+</strong> cạnh <strong>Số bước</strong>.","docs.af43070008b9":"Pattern và Bài hát","docs.2bbc3c96888d":"Bên cạnh thanh điều khiển phát có một công tắc: <strong>Pattern</strong> hoặc <strong>Bài hát</strong>. Ở chế độ <em>Pattern</em>, Phát sẽ lặp pattern đang mở bằng chính nhạc cụ, hiệu ứng và thiết lập bàn trộn của các track trong đó, theo nhịp độ của bài hát, mà không đụng tới bản phối. Một bước bạn bật lên trong lúc nó đang phát sẽ được nghe ở vòng tiếp theo, và giá hiển thị bước đang phát. Mở một pattern khác thì pattern đó sẽ được lặp thay thế. <em>Bài hát</em> đưa đầu phát về lại chỗ cũ trong bài hát.","docs.9bb80d88f81b":"Chế độ Pattern là một cách nghe, không phải một chỉnh sửa: hoàn tác, phòng và xuất không bao giờ thấy nó. Các track không có trong pattern sẽ im lặng, tự động hoá của bài hát không chạy, và bạn có thể thu lại sau khi chuyển về <em>Bài hát</em>.","docs.2195edf6dd56":"Mọi fader, pan và nút điều khiển thiết bị đều có thể tự động hoá. Mở làn tự động hoá của một track, chọn mục tiêu, rồi vẽ. Các điểm bám theo lưới; giữ <kbd>Alt</kbd> để đặt một điểm tự do. Đường cong giữa hai điểm có thể uốn bằng cách kéo phần giữa của nó.","docs.f82da0230788":"<strong>Kata</strong> là những hình tự động hoá bạn vẽ một lần và đóng dấu ở bất cứ đâu — một lần dâng, một lần quét bộ lọc, một lần ducking dạng sidechain — để một thao tác bạn thích được dùng lại thay vì vẽ lại.","docs.1a01d11683c6":"Bật sẵn sàng thu cho một track, nhấn thu, rồi chơi. Âm thanh được ghi xuống đĩa ngay khi tới thay vì giữ trong bộ nhớ, nên một lần sập chỉ làm bạn mất khối cuối cùng chứ không mất cả take.","docs.91afc456637e":"Thu lại đè lên cùng những ô nhịp đó và bạn có take thứ hai xếp dưới take đầu. Chọn những phần bạn muốn từ mỗi take và Oscillate ghép thành bản comp. <strong>Những take bạn không chọn không bao giờ bị xoá</strong> — đó là ý nghĩa của bản thu ẩn (Shadow Takes), và vì thế đổi ý một tuần sau cũng chẳng tốn gì.","docs.cebcc1706c05":"Phần đếm vào được đặt trong <strong>Cài đặt ▸ Ghi âm</strong>. Mặc định nó tắt.","docs.9409997795f7":"<strong>Transport ▸ Oscillate Retro Record…</strong> mở Retro Record. Nó giữ vài phút gần nhất của đầu vào âm thanh và bàn phím MIDI của bạn trong bộ nhớ của máy tính này, để một take bạn đã chơi trước khi bấm ghi vẫn có thể được lưu.","docs.c9791d9964aa":"Lần đầu tiên, nó hỏi <strong>Giữ lại vài phút cuối của đầu vào?</strong>, và không giữ gì cho đến khi bạn nhấn <strong>Cho phép và bắt đầu</strong>. Sau đó nó chỉ giữ đầu vào của bạn khi <strong>Thu giữ</strong> đang bật, và nó không bao giờ tự bắt đầu thu giữ, kể cả lúc khởi động. Khi tắt, những gì nó đang giữ vẫn còn cho đến khi <strong>Xóa tất cả</strong> xóa chúng khỏi bộ nhớ ngay lập tức. Trong lúc nó đang thu giữ hoặc đang giữ bất cứ thứ gì, một đèn kèm trạng thái của nó (<em>Đang thu giữ</em>, <em>Đang chờ</em> hoặc <em>Đang giữ</em>), thời lượng đang giữ và lượng bộ nhớ nó chiếm luôn nằm trên cùng trong mọi cửa sổ Oscillate, và không thiết lập nào ẩn được nó.","docs.d959459cef30":"Những gì nó lưu giữ","docs.1e04e7f44341":"<strong>Đầu vào</strong> là một đầu vào hoặc một cặp stereo của thiết bị âm thanh đã chọn trong <strong>Cài đặt ▸ Âm thanh</strong>, hoặc <em>Chỉ MIDI</em>; bàn phím MIDI của bạn vẫn được giữ dù chọn thế nào. <strong>Giữ</strong> là giữ bao lâu, từ 30 giây đến một giờ, năm phút nếu bạn không chọn, và lượng bộ nhớ mỗi độ dài chiếm được hiện ra trước khi bạn chọn. <strong>Giữ dưới dạng</strong> là <em>24 bit</em>, <em>16 bit</em> hoặc <em>Dấu phẩy động 32 bit</em>, còn <strong>Khi nào</strong> là <em>Luôn luôn</em>, <em>Khi đang phát</em> hoặc <em>Khi track sẵn sàng ghi</em>. Đổi độ dài, định dạng hay đầu vào sẽ xóa những gì nó đang giữ và bắt đầu lại từ trống, và bảng sẽ cảnh báo bạn trước.","docs.a342ade123d1":"Dạng sóng hiện những gì đang giữ, mới nhất ở bên phải. Kéo ngang qua nó để chọn phần cần lưu; các phím mũi tên dịch vùng chọn, <kbd>Shift</kbd> kèm một phím mũi tên mở rộng nó, và <kbd>Esc</kbd> bỏ chọn. Nếu không có gì vào trong một giây rưỡi khi đang thu giữ, nó sẽ cho biết Windows, macOS hay Linux có thể đang chặn micrô ở chỗ nào.","docs.096b73624b09":"Lưu lại","docs.82e23335c315":"<strong>Lưu</strong>, hoặc <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>R</kbd> trong bất kỳ cửa sổ Oscillate nào, lưu những gì đang giữ; khi đã chọn một đoạn trên dạng sóng, <strong>Lưu vùng chọn</strong> chỉ lưu đoạn đó. Khi chưa giữ gì, phím tắt này sẽ mở Retro Record thay vì lưu.<strong>Một lần bấm lưu</strong> <em>Mọi thứ đang giữ</em> hoặc chỉ đoạn cuối cùng mà bạn chọn.","docs.705171c008eb":"<strong>Lưu thành</strong> cho biết bản thu đi đâu. <em>Clip trên một track</em> đặt phần âm thanh lên track âm thanh đã bật sẵn sàng thu và các nốt lên track MIDI đã bật sẵn sàng thu, hoặc lên một track mới, tại ô nhịp bạn đã chơi chúng, hoặc tại đầu phát nếu bài hát đang dừng. <em>Tệp WAV</em> ghi một tệp WAV đặt tên theo ngày và giờ, kèm một tệp MIDI bên cạnh khi bạn có chơi nốt.","docs.8460d5410f82":"<strong>Bỏ qua khoảng lặng</strong> rút ngắn các đoạn lặng dài khi lưu, có fade để chỗ nối không bao giờ kêu tách. <strong>Đo căn phòng</strong> nghe ba giây yên lặng rồi đặt ngưỡng cao hơn mức đó 9 dB. Một lần lưu mà không chứa gì cả — mọi âm thanh đều bị bỏ qua vì quá nhỏ và không có nốt nào được chơi — sẽ bị từ chối, và nói rõ điều đó.","docs.6b7cc94c730b":"Lưu từ bất cứ đâu","docs.2f7eea744072":"Một công tắc chân MIDI cũng lưu được. <strong>Công tắc chân</strong> ở <em>Tắt</em> cho tới khi bạn chọn <em>Pedal sustain (CC 64)</em>, hoặc nhấn <strong>Học công tắc chân</strong> rồi nhấn pedal hay công tắc bạn muốn. Một lần nhấn là một lần lưu, dù pedal có nảy bao nhiêu đi nữa.","docs.f5a0c0a1e073":"Trong <strong>Cài đặt ▸ Ghi âm</strong>, <strong>Phím tắt toàn cục của Retro Record</strong> cho cùng phím đó lưu từ bất kỳ chương trình nào, khi Oscillate chạy nền, và <strong>Retro Record trong khay hệ thống</strong> đặt một biểu tượng vào khay hệ thống, có menu gồm <strong>Lưu Retro Record</strong> và <strong>Hiện Oscillate</strong>. Cả hai đều tắt cho đến khi bạn bật.","docs.df507f038d45":"Retro Record chỉ nghe đầu vào trực tiếp: bản bounce hay bản xuất không bao giờ đi vào nó. Những gì nó lưu giữ, và nơi một lần lưu được ghi ra, có trong <a href=\"#privacy\">Riêng tư và mạng</a>.","docs.17b03b206557":"Cắm một bàn phím MIDI và chọn nó ở <strong>Đầu vào MIDI</strong> trong <strong>Cài đặt ▸ MIDI</strong>. Nó chơi track đã bật sẵn sàng thu, như bàn phím trên màn hình của piano roll, và nếu bị rút ra, nó tự kết nối lại khi được cắm vào lại. <strong>Hoạt động nốt</strong> sáng lên khi nốt tới, và khi không có track nào bật sẵn sàng thu, mục này sẽ cho bạn biết.","docs.6d35ffc10fcb":"Cách chơi","docs.3a26213a86f3":"<strong>Dịch giọng</strong> dời mọi phím trên bàn phím phần cứng, tối đa bốn quãng tám theo mỗi chiều. <strong>Phạm vi pitch bend</strong> là mức bánh xe cao độ uốn được: hai nửa cung mỗi chiều trừ khi bạn đổi, tối đa bốn quãng tám; plugin uốn theo phạm vi riêng của nó. <strong>Đường cong lực nhấn</strong> là <em>Tuyến tính</em>, <em>Mềm</em>, khi chạm nhẹ cũng chơi to hơn, hoặc <em>Cứng</em>, khi phải nhấn dứt khoát mới chơi to.","docs.b0013f90aea7":"<strong>Hợp âm</strong> biến mỗi phím thành một hợp âm trong âm giai của dự án: hợp âm ba, hợp âm bảy hoặc hợp âm chín, theo <strong>Cỡ hợp âm</strong>. Nó áp dụng cho mọi phím đi tới track đã bật sẵn sàng thu — bàn phím phần cứng, bàn phím trên màn hình, và các phím máy tính bạn gõ vào đó.","docs.b308d15ed7fd":"Các bánh xe","docs.c7e25b23a89c":"Bánh xe cao độ uốn các nốt bạn đang giữ, và một nốt được nhấn khi bánh xe chưa về vị trí nghỉ sẽ bắt đầu ở trạng thái đã uốn. Bánh xe điều biến và channel pressure thêm vibrato cho các nhạc cụ trong thư viện. Plugin VST3 và CLAP được chạy nhận cả ba, như trong bất kỳ DAW nào khác.","docs.81cdc8394f11":"Trên sân khấu, và trên các pad","docs.0d942d8f36fb":"Khi sân khấu theo dõi track đã bật sẵn sàng thu, những gì bạn chơi trên bàn phím MIDI hoặc gõ vào bàn phím của piano roll sẽ hiện trên nhạc cụ của nó; xem <a href=\"#stage\">Sân khấu</a>. Bộ điều khiển pad có thể chơi các pad của Drum Machine sau khi nó đã học chúng; xem <a href=\"#drum-grid\">Lưới trống</a>.","docs.fceb67e7d5a2":"<kbd>Ctrl</kbd>+<kbd>4</kbd>. Mỗi track một dải kênh với fader, pan, tắt tiếng, solo, giá thiết bị và một đồng hồ đo được vẽ từ âm thanh mà engine thật sự tạo ra — không bao giờ từ một phỏng đoán.","docs.fc9ca9fe7259":"Các núm của dải kênh","docs.ab21191b71d4":"Dải kênh của mỗi track có <strong>Trầm</strong>, <strong>Trung</strong>, <strong>Cao</strong>, <strong>Phòng</strong>, <strong>Vọng</strong>, <strong>Nhiệt</strong>, <strong>Điều biến cao độ</strong> và <strong>Hạt</strong>, và bên dưới là một bộ nén của riêng nó: công tắc của nó, một đèn sáng lên khi nó đang giảm bớt âm, và <strong>Ngưỡng</strong>, <strong>Tỉ lệ</strong>, <strong>Khởi</strong>, <strong>Nhả</strong> và <strong>Bù</strong>. Bộ nén tắt cho tới khi bạn bật nó, và Hạt ở 0% thì nằm ngoài đường tín hiệu. Mọi núm đều được lưu cùng dự án, có thể tự động hoá và mỗi lần chỉnh là một bước hoàn tác. Núm duy nhất của kênh master là Hạt.","docs.4e127e233a98":"Các núm được gập lại cho tới khi bạn nhấn <strong>Núm xoay</strong>; khi gập, bàn trộn chỉ gồm fader và đồng hồ đo, và các hiệu ứng vẫn tiếp tục hoạt động.","docs.8eaced166021":"Ra-đa che lấp","docs.bea60461bd8b":"Nhấn <strong>Ra-đa</strong> và Oscillate sẽ canh những cặp track đang tranh nhau cùng một dải tần — bass và kick, giọng hát và pad — rồi gọi tên cặp đó và tần số. Nó tốn CPU trong lúc bật và chú giải công cụ nói rõ điều đó.","docs.6f550e9b860d":"Một cặp chưa được nghe tới sẽ hiện <strong>Chưa nghe thấy</strong>, chứ không phải \"sạch\". Nếu phiên có nhiều track hơn số ra-đa theo dõi, nó cũng nói cho bạn biết thay vì lặng lẽ chỉ hiện một phần.","docs.e0b651a4ea3c":"Độ lớn và đỉnh thực","docs.5a27169c5088":"Nhấn <strong>Độ lớn</strong> để xem LUFS tích hợp, ngắn hạn, dải độ lớn và đỉnh thực, cùng một bảng cho biết mỗi dịch vụ phát trực tuyến nhắm tới mức nào và nó sẽ làm gì với bản master của bạn. Mỗi mục tiêu kèm ngày nó được kiểm tra lần cuối.","docs.bfc4dfe30bdc":"Nếu đồng hồ đo từng bị tụt lại khi tải nặng, nó sẽ nói ra — <em>\"đồng hồ đo đã bị tụt lại, nên một phần âm thanh chưa bao giờ được đo\"</em>. Một con số không kèm cảnh báo nào nghĩa là một phép đo trọn vẹn.","docs.fcbd76890ab6":"Tỉ lệ Âm thanh ↔ MIDI","docs.5395f9abcc77":"Thanh trượt trong khay của bảng Bản nhạc pha các track âm thanh của dự án với các track MIDI: kéo hết sang trái chỉ phát âm thanh, hết sang phải chỉ phát MIDI, và ở giữa cả hai đều tối đa. Thay đổi được nghe ngay và chuyển mượt không có tiếng lách cách, được lưu cùng dự án, và không bao giờ dời fader. Bản xuất, stem và bản đóng băng bỏ qua nó. Nhấp đúp vào nó để đưa về chính giữa.","docs.eadb0d7c2b3a":"Mỗi dải kênh cũng có ổ khóa của track; xem <a href=\"#lock\">Khóa một track</a>.","docs.bb68efe46235":"<kbd>Ctrl</kbd>+<kbd>6</kbd>, hoặc <strong>Xem ▸ Sân khấu</strong>, mở sân khấu: một nhạc cụ 3D và đôi tay chơi các track MIDI của bạn trên đó, khớp nhịp với transport — qua các lần đổi nhịp độ, vòng qua vòng lặp và tới bất cứ đâu bạn tua tới. Nó chỉ tải vào lần đầu bạn mở, nên Oscillate không khởi động chậm hơn vì có nó.","docs.b2c1bf6636d4":"<strong>Theo dõi</strong> là một danh sách thả xuống các track MIDI của dự án, mỗi track một ô đánh dấu, ban đầu <em>Tất cả</em> được đánh dấu, và track bạn chọn trong bản phối hoặc bàn trộn sẽ dẫn dắt. Trên đàn piano, tối đa bốn phần chơi cùng nhau, mỗi phần được nhận ra qua tên track của nó — giai điệu, hợp âm, bass, giai điệu đối — hoặc nếu không thì qua vị trí của nó: bass và hợp âm nghiêng về tay trái, giai điệu và giai điệu đối về tay phải, và hai tay chỉ bắt chéo ở chỗ không còn cách nào khác để chơi đoạn nhạc. Một cây guitar chơi một phần duy nhất đặt ở <strong>Chơi</strong> và một cây bass chơi phần bass, còn track trống không bao giờ tham gia cùng. Những gì được đánh dấu chỉ kéo dài trong phiên làm việc. Khi sân khấu đang mở, để con trỏ dừng trên thước sẽ hiện một hình nhỏ của sân khấu tại thời điểm đó.","docs.b854e3db884e":"Những gì đứng trên sân khấu","docs.fc50699f9956":"Piano, guitar, bass và trống đều được chơi bởi đôi tay riêng của chúng. Các Grand, Acoustic, Upright và Honky-Tonk Pianos có sẵn, Guitar, Nylon, Electric và Muted Guitars, cùng Pluck, Slap và Upright Basses đều hiện lên đúng là chính chúng, và một Electric Guitar đi vào Guitar Amp sẽ hiện lên thành một cây guitar rock. Mọi nhạc cụ khác đều chơi trên cây grand piano.","docs.b13f8d00411c":"Một track Drum Machine hiện lên thành một bộ điều khiển 16 pad do đôi tay đánh trống bằng ngón chơi, các pad sáng lên khi được đánh. Mọi track trống khác hiện lên thành một bộ trống phòng thu được chơi bằng dùi và chân.","docs.501f27b7d77e":"<strong>Nhạc cụ</strong> đưa một cây piano, guitar hay bass khác lên sân khấu cho một track, hoặc bộ điều khiển pad hay bộ trống cho một track trống. Nó chỉ đổi vẻ ngoài và đôi tay: âm thanh vẫn là của chính nhạc cụ trên track.","docs.81c02d3967f8":"Nút điều khiển của từng nhạc cụ","docs.727825c6add3":"<strong>Piano:</strong> <strong>Tên phím</strong> trên mọi phím, chỉ phím trắng hoặc không phím nào, và <strong>Số ngón tay</strong>, từ 1 đến 5.","docs.772ca78133a2":"<strong>Guitar:</strong> nó <strong>Chơi</strong> gì — hợp âm, giai điệu hay giai điệu đối — với tay quạt dây và tay gảy, các kỹ thuật slide, hammer-on và pull-off.","docs.8f7c1096c8f0":"<strong>Bass:</strong> <strong>Số dây</strong> là bốn hoặc năm trên Pluck Bass và Slap Bass. Với bốn dây, các nốt thấp hơn nốt E trầm được chơi cao lên một quãng tám.","docs.72dd5a83030f":"<strong>Guitar hoặc bass:</strong> <strong>Đệm</strong> — tắt thì track được solo và chỉ nghe riêng nó; bật thì các track khác cùng chơi — người chơi <strong>Thuận tay trái</strong>, <strong>Số ngón tay</strong> trên tay bấm phím và, với guitar điện, guitar rock và Pluck Bass, hình dạng và kim loại của <strong>Thanh phím đàn</strong>, vốn thay đổi vẻ ngoài chứ không thay đổi âm thanh.","docs.f7034c6b7a2d":"<strong>Bộ trống:</strong> tay trống <strong>Thuận tay trái</strong>.","docs.a9b675db7c20":"Camera","docs.4c038fd542ad":"<strong>Góc nhìn</strong> nhìn từ phía <em>Trước</em>, phía <em>Trên</em> hoặc phía <em>Bên</em>, hoặc cận cảnh một bàn tay: tay trái hoặc tay phải trên piano, tay bấm phím đàn hoặc tay gảy trên guitar, đôi tay trên các pad, đôi tay hoặc đôi chân ở bộ trống. Nhấp vào sân khấu để nó nhận tiêu điểm, rồi <kbd>V</kbd> lướt sang góc nhìn kế tiếp và <kbd>Shift</kbd>+<kbd>V</kbd> lùi lại. Ở mọi nơi khác, các phím đó vẫn làm việc thường lệ của chúng.","docs.faf2ae9b7dc0":"Khi sân khấu đang hiện, <kbd>Alt</kbd>+<kbd>V</kbd> và <kbd>Alt</kbd>+<kbd>Shift</kbd>+<kbd>V</kbd> chuyển góc nhìn theo cùng cách đó từ bất kỳ đâu, dù tiêu điểm đang ở chỗ nào.","docs.2dfb06bbe520":"Chất lượng và màu da","docs.1c4f1647ab9b":"<strong>Chất lượng</strong> là <em>Tự động</em>, hoặc cố định ở <em>Cao</em>, <em>Trung bình</em> hoặc <em>Thấp</em>. Tự động đánh giá một mức chất lượng theo những khung hình chậm nhất thay vì mức trung bình, nên nó chỉ hạ mức chi tiết ở những chỗ máy thật sự bị giật, và báo cho bạn khi làm vậy. <strong>Màu da</strong> cho đôi tay một trong sáu tông màu. Cả hai được lưu trên máy tính này.","docs.944860301e3b":"Chơi trên sân khấu","docs.e84f7ce0faa7":"Khi sân khấu theo dõi track đã bật sẵn sàng thu, bạn có thể chơi nó: nhấp vào các phím piano, dây guitar hoặc các pad, và những gì bạn chơi trên bàn phím MIDI hoặc gõ vào bàn phím của piano roll sẽ hiện trên nhạc cụ. Khi bánh xe cao độ, bánh xe điều biến hoặc lực nhấn của bàn phím MIDI chưa về vị trí nghỉ, một ô hiển thị nhỏ cho biết giá trị đó. Khi theo dõi bất kỳ track nào khác, phần đầu bảng sẽ nhắc bạn bật sẵn sàng thu cho nó.","docs.32f7674d29c2":"Giá nhạc","docs.2f8af7ba544e":"Các bản nhạc trên giá nhạc của sân khấu là những bản mà bảng Bản nhạc ghi cho track mà sân khấu đang theo dõi; xem <a href=\"#sheets\">Bản nhạc</a>. Các trang tự lật theo tốc độ đặt trong <strong>Cài đặt ▸ Giao diện</strong> — nhanh gấp đôi ở <em>Nhanh</em>, chuyển thẳng ở <em>Giảm</em> — và nốt mà đôi tay đang chơi được làm sáng.","docs.3df54afb81cf":"Cho mọi người","docs.78c6a91c0856":"Mọi nút điều khiển trên sân khấu đều có thể truy cập từ bàn phím và được đặt tên cho trình đọc màn hình, và chính sân khấu cũng được đặt tên theo thứ đang đứng trên đó và track mà nó theo dõi — <em>Sân khấu: Grand Piano, theo dõi Keys</em>. Khi bật giảm chuyển động, trong <strong>Cài đặt ▸ Giao diện</strong> hoặc theo thiết lập của hệ thống, camera chuyển thẳng từ góc nhìn này sang góc nhìn kế tiếp thay vì lướt, và đôi tay vẫn tiếp tục chơi.","docs.e4c4c4cc66eb":"Trên macOS và Linux","docs.a38e5531ae92":"Trên macOS sân khấu chơi theo bài hát, như trên Windows: máy Mac vẽ 3D bằng card đồ họa thật. Linux vẽ cửa sổ của Oscillate bằng WebKit, vốn có thể đang vẽ 3D bằng bộ xử lý mà không báo ra, nên ở đó sân khấu đứng yên để ứng dụng luôn mượt, và nói rõ lý do: nó vẽ một khung hình cho mỗi thay đổi — khi bạn dừng, dời đầu phát hoặc đổi góc nhìn — thay vì chơi theo, và camera chuyển cảnh tức thì thay vì lướt. Một máy Mac hoàn toàn không có card đồ họa, như một máy ảo, cũng đứng yên theo cùng cách đó.","docs.05ec58676b0b":"Khi không làm được","docs.7652f24d0166":"Cửa sổ nào không vẽ được WebGL 2 sẽ hiện <em>Không thể hiển thị 3D</em> kèm lý do, không bao giờ là một sân khấu trống trơn. Track nào có nhiều nốt hơn mức sân khấu chơi được sẽ được gọi tên, kèm số nốt nó có và số nốt sân khấu nhận được: hãy tách nó thành các track ngắn hơn, hoặc theo dõi một track khác.","docs.bfcae0954b62":"<kbd>Ctrl</kbd>+<kbd>7</kbd>, <strong>Xem ▸ Bản nhạc</strong>, hoặc phím Bản nhạc trên thanh tiêu đề sẽ hiện bảng Bản nhạc: bất kỳ track MIDI nào dưới dạng bản nhạc, chạy theo đầu phát. Bảng được gắn bên dưới sân khấu, phía trên trình chỉnh sửa, và ẩn cho tới khi bạn mở. Nó luôn ở trong cửa sổ chính, vì các trang của nó lật theo đồng hồ của cửa sổ chính. Không phần nào của nó được tải cho tới khi một bản nhạc hiện lần đầu, nên Oscillate không khởi động chậm hơn vì có nó.","docs.dbc863f4a58d":"Một bản nhạc có gì","docs.e2e4a9222290":"Mỗi track MIDI có chứa nốt được ghi trên khuông khóa Sol, khóa Fa hoặc khuông kép, chọn theo các nốt mà nó chơi. Số chỉ nhịp và giọng thay đổi ở đúng những chỗ chúng đổi trong dự án, mỗi điểm đánh dấu đoạn có một dấu mốc tập, các ô nhịp im lặng trở thành dấu lặng nhiều ô nhịp, và các trang trông như giấy thật, có tên dự án và <em>Trang n/N</em>. Các khuông được giãn cách theo nội dung, nên vạch nối nốt của trống, các nốt trầm của guitar phía trên TAB và lời bài hát không bao giờ đè lên nhau. Hai trăm ô nhịp được ghi trong khoảng một phần tư giây.","docs.53fe7e8fa768":"<strong>Bản nhạc chỉ để đọc.</strong> Nó là một khung nhìn của track: sửa nốt trong piano roll và bản nhạc đi theo.","docs.be2f58fbb4f7":"TAB và bản nhạc trống","docs.5cf1a74f1eaf":"Track của guitar được ghi ở khóa Sol thấp một quãng tám (8vb) trên TAB sáu dòng, kèm sơ đồ hợp âm và mũi tên quạt chả. Bass được ghi trên TAB bốn dòng, hoặc năm dòng với bass 5 dây. Các phím bấm chính là những phím mà đôi tay trên sân khấu chơi. Track trống ghi bên dưới mỗi nhát đánh là tay hay chân nào đánh: <em>R</em>, <em>L</em>, <em>RF</em> hoặc <em>LF</em>.","docs.99a1f9b6751d":"Lời dưới nốt nhạc","docs.803b68dc26c8":"Lời trong Làn lời bài hát của một track được ghi dưới các nốt của nó, và một âm tiết được ngân bằng <code>_</code> sẽ vẽ đường kéo dài của nó; xem <a href=\"#lyrics\">Làn lời bài hát</a>.","docs.b956e8e07a54":"Khay","docs.c763ac7681d9":"Dải ngang dọc theo cạnh trên của bảng. Chip của tổng phổ đứng đầu, rồi đến một chip cho mỗi track MIDI có chứa nốt, theo thứ tự của bản phối; khi chúng vượt quá chiều dài của dải, dải sẽ cuộn ngang. Chip của mỗi track có:","docs.51870c937279":"số phím và tên của nó: nhấp vào tên để đọc bản nhạc, nhấp lần nữa để quay lại;","docs.b0bbcf140652":"<strong>M</strong> và <strong>S</strong>: tắt tiếng và solo của chính track, giống hai nút trên đầu track và trên dải kênh của nó trong bàn trộn (<kbd>Ctrl</kbd>-nhấp <strong>S</strong> để solo nó cùng các track khác);","docs.ffbfdce6aedb":"<strong>Khóa</strong>: khóa của track; xem <a href=\"#lock\">Khóa một track</a>;","docs.e1403ae0c46a":"trên Windows và macOS, một tay nắm để kéo MIDI của track ra khỏi Oscillate, lên màn hình nền hoặc vào chương trình khác. Nhấp vào các tay nắm để chọn nhiều track và kéo chúng cùng lúc. Tay nắm của tổng phổ, <strong>Kéo tất cả</strong>, kéo track của mọi bản nhạc.","docs.79d6deab7900":"Sau các chip là thanh trượt Âm thanh ↔ MIDI (xem <a href=\"#mixer\">Tỉ lệ Âm thanh ↔ MIDI</a>) và các phím <strong>PDF</strong> và <strong>In</strong>, bị làm xám trong lúc đang tạo PDF hoặc đang in.","docs.28288fa30f54":"Mặt bàn","docs.6787febdf396":"Bên dưới khay, mặt bàn bày trang đầu của mọi bản nhạc thành từng thẻ, theo thứ tự của khay. Nhấp vào một thẻ, hoặc nhấn <kbd>Enter</kbd> trên nó, để đọc. Các thẻ được vẽ khi bài hát dừng; mở mặt bàn giữa lúc bài hát đang phát thì nó hiện tên các bản nhạc cho tới khi bài hát dừng.","docs.70729b5d0c2d":"Trình đọc bản nhạc","docs.ae0ea2772a41":"Bản nhạc bạn mở trải rộng hết chiều ngang bảng, các trang nối tiếp nhau từ trên xuống. Khi bảng Bản nhạc đang hiện, <kbd>1</kbd> đến <kbd>9</kbd> mở chín bản nhạc đầu tiên theo thứ tự của khay, <kbd>1</kbd> là tổng phổ; nhấn lại cùng phím đó, hoặc <kbd>Esc</kbd>, sẽ quay về mặt bàn. Ô văn bản bạn đang gõ vẫn nhận các chữ số của nó. Mọi phím này đều có thể đổi trong <strong>Cài đặt ▸ Phím tắt</strong>.","docs.eb8223ab78ba":"Khi bài hát phát, các trang tự lật, giữ dòng đang phát trong tầm nhìn với dòng tiếp theo ở bên dưới. Các nốt sáng luôn là những nốt đang vang: track bị tắt tiếng không sáng gì cả, khi có track được solo thì chỉ các track solo mới sáng, và trên tổng phổ mỗi nốt sáng trên khuông của chính track của nó. Danh sách đoạn dời đầu phát tới một đoạn, và mọi bản nhạc lật theo. <em>Trang n/N</em> cho biết bạn đang ở đâu.","docs.d1edfe59d41d":"Khi không có track MIDI nào chứa nốt, bảng sẽ nói ra điều đó. Track nào có nhiều nốt hơn mức một bản nhạc ghi được vẫn giữ chip của nó, và bản nhạc của nó nêu số nốt nó chơi và số nốt một bản nhạc chứa được: hãy tách nó thành các track ngắn hơn để đọc như bản nhạc.","docs.b91c8440ec46":"<kbd>Ctrl</kbd>+<kbd>8</kbd>, <strong>Xem ▸ Bài học</strong>, hoặc phím Bài học trên thanh tiêu đề sẽ hiện bảng Bài học: mười lăm khóa học, học từng ngày. Nó mở thành một cột bên cạnh bản phối và luôn ở trong cửa sổ chính. Không phần nào của nó được tải cho tới khi bạn mở nó lần đầu, nên Oscillate không khởi động chậm hơn vì có nó.","docs.24c8b6c0abca":"Phần chữ của chính các bài học, lời của từng bước, hiện vẫn bằng tiếng Anh; mọi phím, nhãn và thông báo xung quanh đều bằng ngôn ngữ của bạn.","docs.2ef08f855c58":"Các khóa học","docs.e8a6f7aa2805":"Tab <strong>Khóa học</strong> chứa đủ mười lăm khóa, trong một danh sách thả xuống và một dải: Đàn piano, Đọc nhạc, Tiết tấu, Luyện tai, Nhạc lý cho nhà sản xuất, Sáng tác bài hát, Viết lời, Rap và flow, Phối khí bài hát, Trộn âm, Đánh trống bằng ngón tay, Bộ trống, Đàn guitar, Guitar cổ điển và Đàn bass. Mỗi khóa hiện một đèn tiến độ gồm mười đoạn và số ngày bạn đã đạt, còn khóa bạn chưa bắt đầu thì cho biết nó bắt đầu sau mốc nào. Bên dưới, các ngày của khóa đang mở chạy dọc trên một đường, nhóm theo tuần dưới các phần của khóa, mỗi ngày được phân biệt bằng hình dạng lẫn màu sắc: đã qua, nơi bạn đang ở, ôn tập, điểm kiểm tra, hoặc chưa tới; các phím mũi tên di chuyển dọc theo đường đó. Các đồng hồ hiện bài học này, tất cả bài học và số ngày luyện tập. <strong>Tiếp tục</strong>, phím duy nhất của bảng, mở đúng ngày và bước nơi bạn đã dừng. Một ngày bạn chưa tới vẫn mở ra, và nói rõ điều đó.","docs.2b065c7c9ce4":"Hôm nay","docs.a94682304567":"<strong>Hôm nay</strong> chơi ngày mà bạn đã mở, từng bước một: <em>Xem</em>, <em>Thử</em>, <em>Theo nhịp</em>, <em>Chơi trọn bài</em>, một câu hỏi luyện tai cần trả lời (<em>Nghe</em>), một bài hát cần <em>Sáng tạo</em>, và những bước khác. Một bước có phát nhạc sẽ đặt phần nhạc của nó lên các track thật bằng nhạc cụ của khóa học, với một ô nhịp đếm vào, và chính transport của Oscillate phát nó; sân khấu làm sáng các phím, cần đàn hoặc các pad mà bước đó yêu cầu. Nhấn <strong>Bắt đầu</strong> và chơi theo trên bàn phím MIDI, hoặc trên nhạc cụ của bạn nếu khóa học có lắng nghe. Một bước đạt khi bạn làm đúng ba lần liên tiếp.","docs.a669864312ff":"Bên cạnh là các công cụ luyện tập: một tay trong khi sân khấu chơi tay còn lại, một vòng lặp các ô nhịp bạn chọn, và nhịp độ, tăng dần về nhịp độ của chính bước đó khi bạn chơi đúng. Một ngày bạn đã thành thạo sẽ quay lại sau để ôn tập.","docs.aeffaf06d287":"Sau một take, phần chấm điểm cho biết điều gì làm tốt và điều gì cần sửa, nêu rõ ô nhịp, phách và cách sửa, tối đa ba điều, điều ảnh hưởng nặng nhất trước. Một take được nghe qua đầu vào của bạn sẽ nói rõ nó được chấm bằng tai. Trong một bước sáng tạo, một mục tiêu bạn cố ý không đạt có thể được đánh dấu bằng <strong>Đánh dấu cố ý</strong>, và nó không còn được tính.","docs.b76c42cb4bf3":"Cho xem","docs.ce107014268a":"<strong>Cho xem</strong> chơi bước đó cho bạn xem trước, cận cảnh đôi tay trên sân khấu, ở nửa tốc độ, ba phần tư hoặc đủ tốc độ, và có thể lặp lại một đoạn của nó. Không có gì được lắng nghe và không có gì được chấm điểm. <strong>Quay lại bước</strong> đưa bạn trở về bước đó.","docs.38e07b2a0ca5":"Đọc to","docs.57b7c4396a9e":"Khi bật, <strong>Đọc to</strong> đọc phần chữ của bước bằng một trong các giọng có sẵn trên máy tính của bạn, làm sáng từng từ khi nó được đọc và giữ dòng của nó trong tầm nhìn. Oscillate không kèm giọng đọc nào: nếu chưa cài giọng nào, nó sẽ nói rõ, và có thể thêm một giọng trong cài đặt hệ thống. Thanh của nó có <strong>Tua lại</strong>, <strong>Đọc</strong> và <strong>Tạm dừng</strong>, <strong>Dừng</strong>, <strong>Tua nhanh</strong>, tốc độ từ nửa tốc độ tới gấp đôi, <strong>Giọng đọc</strong> và một đồng hồ đọc. Khi tiêu điểm ở trong bảng Bài học, <kbd>Space</kbd> đọc hoặc tạm dừng, còn <kbd>Shift</kbd>+<kbd>←</kbd> và <kbd>Shift</kbd>+<kbd>→</kbd> lùi lại hoặc tiến tới một câu.","docs.0a4a6d09bcdb":"Lắng nghe bạn","docs.41d09f811435":"Trong một khóa học có thể nghe bạn, công tắc <strong>Lắng nghe</strong> trên thanh bài học cho bài học nghe nhạc cụ hoặc giọng của bạn thay cho các phím MIDI. Nó nghe đầu vào của thiết bị âm thanh được chọn trong <strong>Cài đặt ▸ Âm thanh</strong>: các nốt và thời điểm của chúng, hợp âm, các cú đánh của bộ trống và các âm tiết của một đoạn rap. <strong>Đầu vào…</strong> chọn kênh nào của nó, hoặc mọi kênh trộn lại, và hiện mức tín hiệu cùng hợp âm mà nó nghe thấy.","docs.758985129d60":"<strong>Bộ chỉnh âm</strong> cho biết một nốt cao hay thấp bao nhiêu cent, theo kiểu chromatic hoặc từng dây một cho guitar hay bass, với A4 ở bất kỳ đâu từ 415 đến 466 Hz. <strong>Hiệu chỉnh</strong> đo thời gian một âm thanh cần để rời Oscillate rồi quay trở vào, để những gì bạn chơi rơi đúng nhịp: <strong>Nối vòng</strong> gửi tám tiếng click qua một sợi cáp từ đầu ra về đầu vào, hoặc từ loa của bạn vào micro; <strong>Chơi theo</strong> để bạn vỗ tay hoặc chơi theo mỗi tiếng click. <strong>Giữ</strong> giữ lại phép đo cho đầu vào đó. Cho tới khi một đầu vào được hiệu chỉnh, Oscillate dùng ước lượng của riêng nó và ghi rõ đó là ước lượng. Trong lúc một bài học đang lắng nghe, bộ chỉnh âm và việc hiệu chỉnh sẽ chờ.","docs.420e5b8d6f43":"Đèn <strong>Đang lắng nghe</strong> sáng đúng trong lúc đầu vào đang mở, và chỉ khi đó mới có thứ gì được nghe. Những gì được nghe được phân tích trên máy tính này ngay khi đến rồi bỏ đi: không có gì được ghi âm, lưu giữ hay gửi đi. Xem <a href=\"#privacy\">Riêng tư và mạng</a>.","docs.72eecb4a3785":"<strong>Nghe lại</strong>, trên thanh bài học, phát đầu vào của bạn qua chính track của bài học để bạn nghe được mình, guitar hay bass thì qua ampli. Mặc định nó tắt, vì micro sẽ hú khi đi qua loa: hãy đeo tai nghe. Nó được ghi nhớ cho từng khóa học, và nó cũng không ghi âm gì cả.","docs.fb7ef24de47f":"Các bước sáng tạo","docs.c85be82fcfea":"Một bước sáng tạo mở chính các công cụ của Oscillate trong dự án của bài học: bản phối với bài hát khởi đầu của bước và các đoạn của nó dưới dạng điểm đánh dấu, Làn lời bài hát và lưới flow của nó, hoặc bàn trộn với vòng lặp của bước. <strong>Kiểm tra</strong> đo những gì bạn đã làm so với các mục tiêu của bước, một mục tiêu trộn âm thì đo trên chính bản mix, được kết xuất rồi đo, và cho biết nó tìm thấy gì. <strong>Tải bài mẫu</strong> đưa vào một bài mẫu, trước tiên giữ bài hát của bạn ở trạng thái hiện tại thành một phiên bản. Trong Rap và flow, <strong>Đọc rap</strong> nghe một take qua đầu vào của bạn và canh thời gian từng âm tiết so với chỗ nó được đặt; take đó không bao giờ được ghi âm. Mỗi bước sáng tạo giữ một trang sổ tay.","docs.e715e082f478":"Dự án của bạn, đã cất sang một bên","docs.1670ea12541a":"Một bài học làm việc trong một dự án của riêng nó. Dự án của bạn được cất sang một bên trong bộ nhớ, nguyên vẹn, cùng các thay đổi chưa lưu và lịch sử hoàn tác của nó, và một dải ở phía trên bảng nói rõ điều đó trong lúc một bài học đang mở. <strong>Quay lại dự án của tôi</strong> đưa nó trở lại đúng như cũ, và Dự án mới, Mở, một phòng hay việc thoát ứng dụng cũng vậy. Không thể mở một bài học trong lúc đang chia sẻ một phòng.","docs.1f37b96dbaaf":"Lịch sử và hồ sơ tác phẩm","docs.c762307fbf0f":"<strong>Lịch sử</strong> cho thấy tiến độ của bạn trong từng khóa học và các đồng hồ; mọi trang sổ tay, mỗi trang mở ngày của nó ở đúng bước của nó; các phiên bản có tên của bài hát của bạn, mỗi phiên bản được so với bài hát hiện tại và có thể đưa trở lại trong một bước hoàn tác; và bản lead sheet, mở trong bảng Bản nhạc. <strong>PDF hồ sơ tác phẩm</strong> tạo một tệp PDF về bài hát của bạn. Tất cả được lưu trong thư mục dữ liệu của Oscillate trên máy tính này.","docs.e3d7060ad727":"Nếu Freally Handscore đã từng được dùng trên máy tính này, tiến độ các bài học của nó, hồ sơ tác phẩm của nó và những từ bạn đã bảo nó giữ nguyên như đã gõ sẽ được chuyển sang vào lần đầu tiên các bài học cần đến chúng, chỉ một lần, và các tệp riêng của Handscore không bao giờ bị thay đổi.","docs.c3c5f9066bd3":"Các bài kinh điển","docs.7e15cf2f46f6":"<strong>Bài kinh điển</strong> chứa 62 bài hát thuộc phạm vi công cộng, tìm được theo tên, cùng các đoạn luyện: một âm giai, một hợp âm rải, một đoạn bắt chéo tay và nhiều hơn nữa. Mở một bài <strong>dưới dạng bài học</strong>, vào dự án riêng của bài học, hoặc <strong>dưới dạng dự án</strong>, được thêm vào sau những gì đã có trong dự án của bạn trong một bước hoàn tác.","docs.9812a95cbb66":"Chỉ có hợp âm của một bài kinh điển mới được kéo ra khỏi Oscillate. Mọi track mà một bài kinh điển thêm vào cho giai điệu của nó vẫn được đánh dấu là của bài kinh điển đó, qua việc đổi tên, hoàn tác và lưu, và một thao tác kéo có thể đưa một track như vậy ra ngoài, dù từ track của nó, bản phối, khay của bảng Bản nhạc hay <strong>Kéo tất cả</strong>, sẽ bị từ chối và nói rõ lý do.","docs.24653cacd405":"Oscillate chạy <strong>VST3 và CLAP</strong>, và mỗi plugin chạy trong một tiến trình riêng. Plugin nào sập thì chỉ thiết bị đó bị làm xám, còn phiên của bạn vẫn chạy.","docs.4c2bf768921f":"Plugin của bạn xuất hiện trong Trình duyệt tệp, mục <em>Plugin</em>. Kéo một plugin vào một track, hoặc chọn track rồi nhấp vào plugin. Mở trình chỉnh sửa riêng của nó từ giá thiết bị — đúng giao diện thật bạn đã mua, không phải một danh sách thanh trượt — và đóng rồi mở lại sẽ đưa nó về đúng kích thước cũ.","docs.657f210c6f73":"Bù trễ được áp dụng trên toàn đồ thị và được chứng minh bằng phép thử triệt tiêu: cùng một tín hiệu đi qua một thiết bị có báo độ trễ và đi vòng qua nó, triệt tiêu nhau thành im lặng. Plugin nào máy này không có sẽ thành một ô giữ chỗ có tên, vẫn tính đủ số mẫu của nó, nên dự án mở ở máy khác vẫn khớp thời gian.","docs.e8fa69bd1ae0":"Biểu cảm riêng của mỗi nốt đến với plugin chỉ trên riêng nốt đó: pressure và âm sắc của nó (Mod Y và Mod X theo từng nốt của piano roll), bend riêng của nó, cùng cao độ tinh chỉnh và pan của một bước. Một plugin CLAP nhận chúng dưới dạng note expression, còn một VST 3 dưới dạng sự kiện note expression, với pressure là polyphonic pressure. Một plugin không nhận cái nào thì vẫn nghe như trước giờ, và một CLAP chỉ đọc MIDI sẽ nhận pressure của nốt dưới dạng polyphonic aftertouch.","docs.dbc9556fe13a":"Tám mươi lăm nhạc cụ và hiệu ứng đi kèm bên trong Oscillate, trong đó có <strong>Freally Secretarium</strong>. Mọi bảng điều khiển đều được vẽ từ chính mô tả của thiết bị, nên con số trên một núm vặn là con số mà DSP đang dùng chứ không phải một con số thứ hai hầu như lúc nào cũng khớp.","docs.57ba00ce7687":"Mặt hiển thị","docs.b1223c1040cb":"Một thiết bị cho thấy nó đang làm gì với âm thanh đi qua nó, trực tiếp, trong lúc thẻ của nó đang hiện. Một equaliser hoặc một ampli vẽ đường cong của nó lên trên phổ âm đi vào và đi ra; một compressor, bộ limiter hoặc một gate vẽ đường cong mức của nó với âm thanh chạy trên đó, mức giảm cuộn qua so với ngưỡng, và kim đồng hồ của nó; bộ de-esser vẽ dải tần của nó lên trên phổ âm; một bộ saturator vẽ đường cong truyền đạt với âm thanh là một chấm trên đó; một thiết bị stereo vẽ trường âm của nó và mức độ hai bên khớp nhau; các delay, reverb và hiệu ứng điều biến vẽ mức âm suốt ô nhịp, còn một reverb vẽ đuôi của nó tắt nhanh thế nào. Khi bật giảm chuyển động, các số đo vẫn cập nhật và không có gì cuộn.","docs.be3ae6fa5bfb":"Mỗi mặt thiết bị được đo từ chính âm thanh của thiết bị, không bao giờ vẽ ra từ thiết lập của nó, và việc vẽ chúng không làm âm thanh tốn thêm chút nào đo được. Tối đa mười sáu mặt hiện trực tiếp cùng lúc; quá số đó, một thẻ được vẽ ở trạng thái nghỉ và nói rõ điều đó. Bản xuất, bản bounce hay bản đóng băng không bao giờ vẽ vào thẻ.","docs.6a4181898f49":"Chuỗi công thức","docs.3c86c1f5f519":"Thiết lập của một thiết bị được sao chép thành một dòng bạn có thể dán vào khung chat. Cả một giá thiết bị — thiết bị đi kèm lẫn plugin cùng nhau — được lưu thành một tệp và gọi lại lên bất kỳ track nào chỉ trong một bước hoàn tác, kể cả trên một máy thiếu một trong các plugin của nó.","docs.4effad823b04":"Gợi ý","docs.a17ac75033a7":"Mỗi thẻ hiệu ứng của chính Oscillate đều có <strong>Gợi ý</strong>. Nó phát riêng track đó cho tới thẻ ấy, ngoại tuyến, trong tối đa 90 giây kể từ chỗ phần đó bắt đầu có tiếng; xác định phần đó là gì từ tên của track; và gợi ý một thiết lập, kèm lý do bằng những câu văn: một equaliser san phẳng chỗ cộng hưởng tệ nhất, một compressor lấy mức giảm hợp với phần đó, bộ de-esser đặt đúng vào tiếng xì mà nó đo được, một delay rơi đúng lưới của nhịp độ. Không có gì thay đổi cho đến khi bạn nhấn <strong>Áp dụng</strong>, nút này đặt mọi nút điều khiển mà nó nêu tên trong một bước hoàn tác. Một thiết bị mà việc của nó thuộc về gu thẩm mỹ sẽ nói rõ và không gợi ý gì, còn một plugin được host thì không có Gợi ý.","docs.d41fd773be92":"<strong>Gợi ý cho các núm của kênh</strong>, ở trên cùng giá thiết bị của track đang chọn, làm điều tương tự cho Trầm, Cao và bộ nén của dải kênh. Đó là phép tính số học trên những gì đo được, không phải một mô hình, nên cùng một bản mix lần nào cũng nhận được cùng một gợi ý. Để thiết lập toàn bộ bản mix cùng lúc, xem <a href=\"#final-check\">Mix giúp tôi</a>.","docs.30b64302573c":"Oscillate Doubler","docs.956a79b573ac":"Nhân đôi một phần như thể nó được hát hoặc chơi thêm một lần nữa: tối đa bốn giọng (<strong>Số giọng</strong>), mỗi giọng lệch tông tối đa 30 cent (<strong>Lệch tông</strong>), trễ từ 5 đến 40 ms (<strong>Delay</strong>) và trải rộng trên trường stereo (<strong>Độ trải</strong>), được pha trộn bằng <strong>Mix</strong>. Các giọng trôi lệch theo hạt giống của dự án và <strong>Hạt giống</strong> riêng của thiết bị, nên một bản xuất lần nào cũng ra giống hệt nhau, còn hai bộ nhân đôi trong cùng một bài sẽ trôi lệch khác nhau. Các preset của nó là Tape Double, Wide Double, Stack và Subtle.","docs.5841824db95a":"Oscillate Ducker","docs.a5d084563a9d":"Hạ nhỏ một track trong lúc một track khác đang phát, như bass nhường chỗ cho kick. Chọn track kia ở mục <strong>Sidechain từ</strong> của thẻ: nó được nghe sau các thiết bị của track đó và trước fader của track đó, nên một kick đã tắt tiếng vẫn kích được nó, và hai track luôn được giữ khớp thời gian dù thiết bị của track nào thêm độ trễ bao nhiêu. <strong>Độ sâu</strong>, <strong>Threshold</strong>, <strong>Attack</strong>, <strong>Release</strong>, <strong>Hold</strong> và <strong>HPF sidechain</strong> định hình nó, và mặt thiết bị vẽ ra lượng nó lấy đi. Các preset của nó là Kick Pump, Gentle Duck và Voice Over.","docs.cf62c3a32ff8":"Track khóa được giữ nguyên qua việc đổi tên, lưu và một phòng. Nếu track khóa bị xóa, thẻ sẽ nói rõ điều đó và âm thanh đi qua nguyên vẹn; một lần hoàn tác sẽ đưa track khóa trở lại.","docs.233e3485af27":"Oscillate Kick Carve","docs.75b2088ada20":"Hạ bass xuống chỉ trong lát dải trầm mà kick đang vang, và chỉ trong lúc kick còn ngân ở đó, nên các họa âm của bass phía trên không bao giờ bị động tới. Chọn kick ở mục <strong>Sidechain từ</strong> của thẻ. <strong>Chế độ</strong> là <em>Spectrum</em>, 24 dải trải khắp vùng trầm, hoặc <em>Bell</em>, một nhát cắt bám theo chính cao độ của kick, và chuyển sang các dải khi kick không có cao độ. <strong>Độ sâu</strong> (tới 24 dB), <strong>Tinh chỉnh</strong>, <strong>Bám theo</strong>, <strong>Hold</strong>, <strong>Độ rộng Q</strong>, <strong>Dải thấp</strong> và <strong>Dải cao</strong> (20 đến 400 Hz), <strong>Chỉ kênh giữa</strong> và tối đa 5 ms <strong>Lookahead</strong> định hình nó, và phần còn lại của bản mix được giữ khớp thời gian với lookahead. Ở Độ sâu bằng không, bass đi qua nguyên vẹn từng bit. Tám preset, từ Sub Pocket đến Wide Bass Safe.","docs.7932b1559e62":"Oscillate Bass Unison","docs.a56a284bec6e":"Biến một tiếng saw hoặc một tiếng 808 thành một tiếng reese chuyển động: hai đến tám giọng, lệch tông tối đa 35 cent và xoay qua 4 đến 12 tầng all-pass (<strong>Số tầng</strong>) ở <strong>Tốc độ</strong> 0.02 đến 10 Hz hoặc đồng bộ theo nhịp, trải rộng, trong khi mọi thứ dưới <strong>Crossover</strong> (40 đến 300 Hz) vẫn mono và không bị động tới, nên loa sub mono của câu lạc bộ và chiếc loa duy nhất của điện thoại đều nghe được trọn vẹn. <strong>Độ rộng</strong> lên tới 150 %, và <strong>Bảo vệ mono</strong>, bật sẵn từ đầu, giữ cho khi gộp về mono không mất quá 3 dB. Nó báo độ trễ xử lý khoảng 15 ms. Tám preset, từ Classic Reese đến Extreme Phase.","docs.2b8b78b8fed7":"Oscillate Groove và bốn mươi feel của nó","docs.ec707d526419":"Một thiết bị nốt đưa tiếng trống được chơi vào nó theo một feel có tên. <strong>Groove A</strong> là một trong bốn mươi feel, từ <em>Grid Tight</em> và <em>Laid-Back Backbeat</em> đến <em>Loose Drummer</em>, và có thể pha với một feel thứ hai; <strong>Độ sâu</strong> lên tới 200 %, và mỗi làn trong mười hai làn của nó, từ kick đến bộ gõ, có độ lệch và độ sâu riêng, nội suy hoặc bám nấc. Khi đứng đầu một track, nó đọc trước các nốt của clip, nên một nốt được đưa sớm không cần thêm độ trễ; một phím chơi trực tiếp, hoặc một Groove đứng sau trong chuỗi, phải chờ theo <strong>Lookahead</strong> của nó, tối đa 80 ms.","docs.d5fdbcc59e0f":"<strong>Thư viện</strong> nạp một feel, <strong>Lưu thành feel</strong> giữ lại feel của riêng bạn, và <strong>In clip đang mở theo feel này</strong> ghi clip đang mở trong Trình chỉnh sửa, đã được căn lại thời gian, thành một clip MIDI mới ngay sau nó. Bốn mươi feel được viết tay cho Oscillate; không feel nào được lấy từ một bản thu hay một sản phẩm khác.","docs.0fa45a3c7e03":"<strong>Oscillate Groove Kit</strong> là bạn đồng hành của nó: mười hai tiếng trống tổng hợp trên các nốt General MIDI, một hi-hat đóng chặn tiếng hi-hat mở, và một <strong>Mẫu</strong> (<em>Backbeat</em>, <em>Half-Time</em>, <em>Four on the Floor</em>, <em>Boom Bap</em>, <em>Shuffle</em>, <em>Two-Step</em> hoặc <em>Sixteenths</em>) để chơi theo một feel.","docs.ba87b5cbd2e5":"Oscillate Chord Trigger","docs.e034e184c3ec":"Một phím chơi cả một hợp âm kèm bass của nó, được dẫn giọng để di chuyển ít nhất có thể. Bàn phím được chia làm ba: bass bên dưới <strong>Điểm chia bass</strong>, các phím điều khiển từ <strong>Điểm chia điều khiển</strong> trở lên (năm phím đầu chọn thể đảo, phím thứ sáu bật hoặc tắt Latch, phím thứ bảy thả tất cả), và các hợp âm ở giữa, được bố trí theo <strong>Bản đồ hợp âm</strong>: <em>Chromatic</em>, <em>Major Key</em> hoặc <em>Minor Key</em>. Hai mươi bảy hình hợp âm và tám hình của riêng bạn, dựng trên một lưới ba quãng tám; quạt hợp âm tới 60 ms; mười hai preset.","docs.9184c71643db":"Các pad của nó cỡ 64 px, hoặc 96 px với <strong>Mục tiêu lớn hơn</strong>, và hàng phím số chơi chúng. <strong>Quét bằng công tắc</strong> cho phép chơi nó bằng <em>Một công tắc</em>, tự bước tới sau mỗi 0.5 đến 5 giây, hoặc <em>Hai công tắc</em>, mỗi công tắc là một phím, một nốt MIDI hoặc một bộ điều khiển mà bạn dạy cho nó. Các pad chơi track đã bật sẵn sàng thu, và thiết lập quét chỉ kéo dài trong phiên làm việc.","docs.6e6483d51004":"Oscillate Glide","docs.841c74d1890b":"Nốt trượt cho các dòng 808. <strong>Trượt khi</strong> chọn những nốt nào trượt sang nốt kế tiếp: <em>Every Note</em>, <em>Every Offbeat Note</em>, <em>Every Nth Note</em>, <em>Notes Shorter Than</em>, <em>Leaps Of</em>, <em>Marked In The Lane</em> hoặc <em>Never</em>, trong một <strong>Thời gian trượt</strong> từ 5 ms đến 2 s hoặc đồng bộ theo nhịp, theo một trong sáu đường cong. Mặt thiết bị có một làn gồm các bước Trượt, Giữ và Bỏ qua dài tới bốn ô nhịp, làn này quyết định khi Trượt khi đặt ở <em>Marked In The Lane</em>. Nó uốn theo bước 14 bit, báo cho các plugin của bạn <strong>Tầm uốn</strong> của nó (1 đến 48 nửa cung; các nhạc cụ của chính Oscillate không cần), và kẹp lại hoặc tách một lần trượt vượt quá tầm đó. Phần bass của Chord Trigger có thể cấp nốt cho nó. Mười hai preset.","docs.be0210423b57":"Oscillate Siren","docs.d8547fe03218":"Một nhạc cụ cho tiếng còi hú cảnh sát, còi báo động phòng không, còi hai tông và còi dub, trên một rô-to quay, với <strong>Quay chậm dần</strong> từ 0.2 đến 12 giây tạo nên tiếng lên và tiếng xuống. Mười hai mẫu <strong>Rô-to</strong>, một đường bao cao độ, glide, một LFO từ 0.01 đến 40 Hz, và <em>Mono</em>, <em>Legato</em>, <em>Poly 8</em> và <em>Latch</em>. Mặt thiết bị có <strong>Âm thanh</strong> (còi hú, dub, stab rave, zap và lò xo: sáu mươi hai preset), một <strong>Mẫu báo động</strong> từ 16 đến 32 bước chơi trong lúc giữ phím, một chuỗi điều biến 16 bước và một ma trận điều biến mười hai ô, cùng hai đường bao và ba LFO. Các bộ dao động của nó mặc định chạy ở 4×, ở đó aliasing thấp hơn −80 dB.","docs.f2c72a5ac00c":"Oscillate Dispersion Delay","docs.7c0d75bc2840":"Tối đa 512 tầng all-pass (<strong>Số tầng</strong>) làm nhòe một tiếng đánh trải khắp các tần số của nó thành một tiếng zap laser: độ trễ chạy theo một đường thẳng, theo từng quãng tám hoặc theo hình chuông giữa <strong>Tần số thấp</strong> và <strong>Tần số cao</strong>, tần thấp đến muộn hoặc tần cao đến muộn, với feedback được giới hạn bên trong vòng lặp và bên phải được đặt lệch so với bên trái bằng <strong>Lệch stereo</strong>. Sau đó là một tiếng vọng băng từ từ 1 ms đến 2 s, với <strong>Feedback tiếng vọng</strong>, wow và flutter, <strong>Suy hao tần cao</strong>, <strong>Bão hòa</strong> và <strong>Head bump</strong>. Mặt thiết bị vẽ độ trễ mà các tầng thực sự tạo ra, theo từng tần số (nét liền cho bên trái, nét đứt cho bên phải, càng cao càng muộn), và trường stereo. Nó không thêm độ trễ xử lý nào.","docs.046ff4ef99fb":"Oscillate Grain Layers","docs.5c26c1dc2d28":"Tối đa tám sample của bạn xếp chồng thành các lớp đá, được đọc bởi một mũi khoan mà độ sâu của nó quyết định thứ gì cất tiếng. Mặt thiết bị gom thành các nhóm <strong>Cột</strong>, <strong>Địa chất</strong> (Xói mòn bào mòn cột, Nếp uốn uốn cong nó, Đứt gãy làm nó nứt vỡ), <strong>Grain</strong>, <strong>Biểu diễn</strong> và <strong>Biểu cảm</strong>, rồi bốn LFO, hai đường bao và một ma trận điều biến mười sáu ô, với mười sáu giọng, có gieo hạt giống để mỗi lần kết xuất đều ra giống hệt nhau. Mod X của một nốt di chuyển mũi khoan, còn Mod Y của nó đi tới nơi mà <strong>Áp lực cho</strong> chỉ định. Mười hai preset gốc, các lớp của chúng được tạo bằng mã.","docs.a8acd4c1d4ce":"Đặt một tệp lên một lớp, hoặc tệp đang được nghe thử trong Trình duyệt tệp. <strong>Giữ âm thanh của lớp này bên trong dự án</strong> mang nó theo trong tệp dự án, và <strong>Tìm lại tệp này trong các thư mục của bạn</strong> tìm một tệp đã bị di chuyển. Lượng bộ nhớ các lớp của nó chiếm được hiển thị, tối đa 1 GiB. Chất lượng là <em>Draft</em>, <em>Normal</em> hoặc <em>High</em>, và <strong>Giới hạn grain</strong> là 16 đến 64 grain, mặc định 48. Mặt cắt của nó được vẽ trực tiếp trên Windows; khi bật giảm chuyển động, và trên macOS và Linux, nó đứng yên.","docs.de620d7ae16d":"Oscillate Storm","docs.874e219ea058":"Mưa, sấm và gió được tạo từ chính vật lý của chúng, nên không có gì lặp lại và không dùng sample nào. Mưa rơi trên tám bề mặt, từ mái tôn và cửa sổ tới vũng nước và ao, và tiếng sấm tới muộn tùy theo tia sét ở xa đến đâu. Bản đồ cơn bão hiện <strong>Vùng mưa</strong>, tính bằng mét, nơi bạn đặt người nghe và tối đa tám vùng, hoặc <strong>Tia sét</strong>, tính bằng ki-lô-mét, nơi <strong>Vẽ một tia sét</strong> nhận một cú nhấp cho mỗi điểm rồi <kbd>Enter</kbd>, tối đa bốn tia sét, và <strong>Nhánh mới</strong> vẽ lại các nhánh của chúng. Hai macro, Mưa và Bão.","docs.6ca928351fc7":"Một phím ở tại hoặc trên <strong>Chia tách</strong> điều khiển thời tiết và thả một giọt mưa ở cao độ của phím đó, bám theo <strong>Nốt gốc</strong>, <strong>Âm giai</strong> và <strong>Bám theo giọng</strong>; một phím thấp hơn đánh xuống một tia sét, nốt của phím quyết định tia nào trong bốn tia. Bánh xe điều biến mang cơn bão tới, CC 11 mang mưa và CC 74 mang gió, còn bánh xe cao độ đưa người nghe lại gần hoặc ra xa. <strong>Đầu ra</strong> là cả cơn bão, mưa, sấm hoặc gió; sáu mươi hai preset mưa, sấm và cả cơn bão; chất lượng <em>Draft</em>, <em>Normal</em> hoặc <em>Ultra</em>. <strong>Kết xuất ba lớp</strong> ghi mưa, sấm và gió thành ba tệp WAV cộng lại bằng đúng track, mỗi tệp đặt tên theo track và lớp của nó, vào thư mục mà <strong>Cài đặt ▸ Xuất</strong> chỉ định (hoặc một thư mục bạn chọn, nếu ở đó chưa chỉ định thư mục nào), thay thế mọi tệp trùng tên. Nó chỉ có stereo.","docs.ee618caedce6":"Oscillate Sub","docs.035d8010d670":"Đặt một lớp sub-bass bên dưới những gì bạn chơi. <strong>Sub 1</strong> bám theo cao độ của âm thanh đi vào và phát một sóng sine bên dưới nó, cao độ hiển thị bằng hertz hoặc thành tên nốt, với <strong>Attack</strong>, <strong>Decay</strong> và glide riêng; <strong>Căn pha</strong> giữ nó cùng pha với nguồn, nên hai âm không bao giờ triệt tiêu nhau, và khi không có cao độ nào để bám theo thì nó im lặng. <strong>Chế độ Sub 1</strong> ở <em>Fixed</em> thì thay vào đó phát một cao độ do bạn đặt. <strong>Sub 2</strong> lấy dải của nguồn quanh <strong>Tần số Sub 2</strong> (<strong>Độ rộng Sub 2</strong> là độ rộng mà nó lắng nghe) rồi hạ xuống một hoặc hai quãng tám, hoặc dịch theo nửa cung bằng <strong>Dịch chuyển</strong>; <strong>Làm mượt</strong> ở 0 giữ lại attack của kick, và nó phát ở mono hoặc ở <strong>Âm thanh nổi</strong>.","docs.77fea442e4ad":"<strong>Chất lượng</strong> là <em>Best</em>, <em>Balanced</em> hoặc <em>Light</em>: Best và Balanced báo độ trễ của chúng, còn Light thì không có độ trễ. <strong>Âm sắc</strong> thêm họa âm để dải trầm vẫn nghe ra trên điện thoại, với <strong>Tính chất</strong> là <em>Tube</em>, <em>Tape</em>, <em>Transistor</em> hoặc <em>Rectifier</em>, được oversample gấp bốn lần khi bật <strong>Oversample</strong>. <strong>Ổn định</strong> san đều một đường bass có mức nhảy lên xuống, theo từng dải dưới 150 Hz, và <strong>Tắt âm trầm</strong> loại bỏ dải trầm của chính nguồn bên dưới <strong>Crossover</strong>. Mặt thiết bị hiển thị cao độ mà nó nghe được, mức của từng sub và một bộ phân tích dải trầm ở ba độ phân giải. Năm mươi preset.","docs.dd33436797ff":"Oscillate Width","docs.89b76ea18568":"Mở rộng những gì bạn chơi mà không bao giờ làm nó mỏng đi khi nghe mono: thêm bao nhiêu vào một bên thì bớt bấy nhiêu ở bên kia, nên tổng mono đúng y như những gì đi vào. Ba dải, chia tại <strong>Crossover 1</strong> và <strong>Crossover 2</strong> (ban đầu là 400 Hz và 4 kHz), mỗi dải được mở rộng từ 0 đến 200 % bằng <strong>Độ rộng dải trầm</strong>, <strong>Độ rộng dải trung</strong> và <strong>Độ rộng dải cao</strong>; <strong>Cường độ</strong> quyết định hai bên bị kéo xa nhau đến đâu. Solo một dải để nghe riêng nó. <strong>Giám sát</strong> phát kết quả <em>Stereo</em>, chỉ phần được thêm vào (<em>Side</em>), hoặc phần giữa, để chứng minh nó không hề dịch chuyển (<em>Mid</em>). <strong>Khớp mức</strong> giữ một nguồn mono đã mở rộng to đúng như trước, <strong>Đang bật</strong> đưa nó vào và ra mà không có tiếng click, và một đồng hồ tương quan cùng một goniometer hiển thị trường âm. Nó không có độ trễ. Năm mươi preset.","docs.b5736b2402bd":"Cặp dải trầm","docs.1232bc16caa2":"Trong Trình duyệt tệp, <strong>Chèn cặp</strong> bên cạnh một trong hai thiết bị sẽ đặt Oscillate Sub rồi Oscillate Width lên track đang chọn, đã liên kết với nhau. Một Width cũng có thể liên kết với một Sub trên track khác, từ danh sách <strong>Sub đã liên kết</strong> trên mặt thiết bị của nó. Khi đã liên kết, hai thiết bị dùng chung một crossover: di chuyển nó trên mặt nào thì cả hai cùng di chuyển. Width không bao giờ mở rộng phần bên dưới nó, nên sub vẫn giữ mono; mặt của Width tô bóng dải mà Sub tạo ra, còn mặt của Sub đánh dấu crossover của Width. Mười hai preset của cặp đặt cả hai thiết bị cùng lúc. Chọn <em>Chưa liên kết</em> để chúng đi đường riêng.","docs.afc35db2da83":"Thiết bị đọc được bản phối","docs.6a537022e329":"Sáu thiết bị trong số đó làm được điều mà không plugin nào làm được, vì plugin không nhìn thấy bản phối mà nó nằm bên trong. Một compressor đã sẵn sàng đè đoạn điệp khúc ngay khi nó tới; một gate mở ra cho một nhát đánh hai ô nhịp trước khi nó xảy ra; một delay xả hết <em>vào</em> vạch ô nhịp để phần đuôi tự tắt thay vì bị cắt. Đọc trước hai ô nhịp âm thanh là độ trễ và ai cũng phải trả giá; đọc cấu trúc thì không tốn gì, và tất cả chúng đều khai báo độ trễ bằng không.","docs.70640caedc3c":"Drum Machine","docs.eb1ebac609ad":"Mười sáu pad, sắp xếp như một bộ điều khiển pad với pad 1 ở góc dưới bên trái, chơi một trong bốn bộ trống tích hợp: <em>Sub</em>, <em>Floor</em>, <em>Neon</em> và <em>Wire</em>. Mỗi nhát đánh được chọn từ ba lớp tuỳ theo bạn đánh mạnh tới đâu và luân phiên giữa hai take, nên một hồi vê trống không bao giờ lặp lại y hệt. Các dự án từng dùng Pad Grid sẽ mở trên Drum Machine với mức âm lượng và các nhóm chặn tiếng được giữ nguyên.","docs.a713154a6b75":"Chọn một pad để tạo hình âm thanh của nó: chỉnh cao độ, một đường quét cao độ, một đường bao, pan, một bộ lọc và một nhóm chặn tiếng, cùng <strong>Các lớp</strong>, tối đa bốn lớp, mỗi lớp bạn có thể <strong>Đảo ngược</strong> hoặc <strong>Chuẩn hóa</strong>. Các lớp thay phiên nhau <em>Theo lực nhấn</em> hoặc <em>Lần lượt</em>, kiểu round robin. <strong>Đặt lại về âm thanh của bộ</strong> đưa pad về như cũ.","docs.2d67d5bec326":"Bên cạnh các pad, <strong>Mẫu đơn</strong> liệt kê các âm thanh riêng của bộ trống và mười một <strong>Gói trống</strong>, theo loại. Nhấp vào một mục để nghe thử, rồi đặt nó lên pad đang chọn hoặc thêm vào đó như một lớp. <strong>Thêm mẫu âm…</strong> đặt các tệp của riêng bạn lên các pad.","docs.b36ebe696a5d":"Guitar Amp và các cây guitar rock","docs.a86f689c0403":"<strong>Guitar Amp</strong> là một bộ khuếch đại và một thùng loa 4×12 với hai kiểu tiếng, <em>Crunch</em> và <em>High Gain</em>, cùng các nút tinh chỉnh <strong>Đầu vào</strong> và <strong>Đầu ra</strong> tới 24 dB theo mỗi chiều. Nó đặt được trên mọi track.","docs.187394fb7629":"Kệ <strong>Chuỗi</strong> trong Trình duyệt tệp có sẵn hai cây guitar rock để chơi ngay, <em>Overdriven Guitar</em> và <em>Distortion Guitar</em>: Electric Guitar đi vào Guitar Amp, rồi một tiếng vọng và một phòng nhỏ, được chỉnh mức để ngang bằng tiếng guitar khô. <strong>Nạp</strong> đặt một trong hai lên track MIDI đang chọn thay cho các thiết bị của nó, trong một bước hoàn tác.","docs.d9cbf26377f3":"Granular Wash","docs.6f3189efd73f":"Một núm vặn, <strong>Lượng</strong>, biến một âm thanh thành một đám mây hạt giữ nguyên nốt và thêm các quãng tám phía trên và phía dưới nó, với một tiếng vọng kéo dài nó thêm nhiều giây. Nó bắt đầu ở 50%; ở 100% bạn chỉ nghe thấy lớp wash.","docs.4af1f7550444":"Đường bao trên mọi nhạc cụ","docs.c6f6907e5d27":"Mỗi nhạc cụ trong thư viện có bốn đường bao bạn có thể bật: <strong>Âm lượng</strong>, <strong>Bộ lọc</strong>, <strong>Cao độ</strong> và <strong>Vị trí</strong>. Mỗi đường bao bắt đầu từ một hình — <em>Init</em>, <em>Gảy</em>, <em>Nền</em>, <em>Dâng</em>, <em>Cổng</em> hoặc <em>Nảy</em> — hoặc bạn tự vẽ hình của mình trên đường cong của nó: kéo một điểm, hoặc nhấp đúp để thêm một điểm hay bỏ một điểm, tối đa 16 điểm của riêng bạn.","docs.8acbbdd5d1ca":"Một đường bao có thể giữ ở một điểm trong lúc phím còn được nhấn và lặp lại từ điểm đó, khoá theo nhịp độ, đi theo velocity và phím được nhấn, bắt đầu lại mỗi ô nhịp, và chuyển dần giữa hai hình A và B của nó. Một hình vẽ tay được lưu trong dự án và trong các tệp giá thiết bị, nhưng không nằm trong một dòng thiết lập được dán. Khi mọi đường bao đều tắt, nhạc cụ phát ra đúng như trước đây.","docs.0d2dfd82f8ee":"<kbd>Ctrl</kbd>+<kbd>1</kbd>. Một màn hình chính gồm các địa điểm — <em>Nhạc cụ</em>, <em>Hiệu ứng âm thanh</em>, <em>Hiệu ứng MIDI</em>, <em>Plugin</em> — để bạn nhấp vào, một nút <strong>Chọn thư mục</strong>, và các thư mục bạn đã thêm, liệt kê theo tên.","docs.0f220b622119":"Bộ lọc tìm theo việc một thiết bị <em>là gì</em> lẫn tên gọi của nó, nên gõ <code>valve</code> sẽ tìm ra <code>Tube Saturator</code> và <code>Amp Head</code>.","docs.00254cbab0ed":"Nghe thử","docs.04348aea2702":"Nhấp vào một thiết bị và bạn nghe phần trình diễn riêng của nó — một nốt được chọn và một độ dài được đo cho từng nhạc cụ — kèm dạng sóng, đầu phát, vòng lặp, và <kbd>←</kbd>/<kbd>→</kbd> để chạy lùi hoặc chạy tới. Trỏ nó vào một thư mục của riêng bạn và nó cũng nghe thử sample của bạn theo cùng cách. Năm trong số các nhạc cụ là sampler và nói rõ điều đó thay vì phát ra im lặng: chúng chờ một tệp của bạn, đưa vào bằng <strong>Thêm mẫu âm…</strong> trên thiết bị hoặc, với Oscillate Grain Layers, bằng <strong>Chọn một tệp cho lớp này…</strong>.","docs.008365bb240d":"Các nhạc cụ","docs.3e31f02db58e":"Toàn bộ 1.648 nhạc cụ nằm trên các kệ <em>Nhạc cụ</em> và <em>Factory Expansion</em>, trong các thư mục theo họ nhạc cụ, và danh sách cuộn mượt dù dài đến đâu. Nhấp vào một hàng, hoặc di chuyển trong danh sách bằng các phím mũi tên, để nghe nó; để con trỏ dừng trên một hàng cũng phát nó. Khi một track MIDI đang được chọn, thứ bạn nghe là chính các nốt của track đó tính từ đầu phát, chơi qua nhạc cụ ở hàng bạn đang đứng. <strong>Thêm</strong> đặt nhạc cụ đó lên track đang chọn.","docs.018dc52d1917":"Trong danh sách nhạc cụ và trong <strong>Âm thanh của tôi</strong>, <kbd>↑</kbd> và <kbd>↓</kbd> đi qua từng hàng và phát từng hàng, còn <kbd>←</kbd> và <kbd>→</kbd> di chuyển giữa các phím của một hàng; trên tên của một nhạc cụ, chúng vẫn phát nhạc cụ đó ngược và xuôi. <kbd>Home</kbd>, <kbd>End</kbd>, <kbd>Ctrl</kbd>+<kbd>Home</kbd> và <kbd>Ctrl</kbd>+<kbd>End</kbd> để nhảy nhanh, và mỗi danh sách chỉ là một điểm dừng của <kbd>Tab</kbd>. Bộ lọc họ nhạc cụ và bộ lọc phần là các danh sách thả xuống, mỗi mục có một ô đánh dấu.","docs.c45ed4856c9f":"Ngôi sao trên một hàng đưa nhạc cụ vào <strong>Đã gắn sao</strong>. Trong <strong>Âm thanh của tôi</strong>, <strong>Lưu âm thanh</strong> giữ lại nhạc cụ trên track MIDI đang chọn, với thiết lập như hiện tại, dưới một cái tên và một thư mục của riêng bạn, sẵn sàng để <strong>Thêm</strong> vào bất kỳ track nào.","docs.0a1f4adb6f56":"PACK","docs.c6b2b316b1be":"Mỗi hàng nhạc cụ có một nút PACK, thêm một one-shot của nhạc cụ đó vào <strong>Gói one-shot</strong> bên dưới trình duyệt, tối đa 25. Phát thử từng cái, đổi nó lấy một take khác của cùng nhạc cụ, hoặc bỏ nó ra. <strong>Xuất</strong> ghi mọi one-shot trong gói thành tệp WAV vào một thư mục bạn chọn, và không bao giờ ghi đè lên tệp đã có sẵn.","docs.5a8b10fcbead":"Kéo một tệp vào","docs.b40583c5f830":"Kéo một tệp <code>.wav</code> hoặc <code>.mid</code> thẳng từ Windows Explorer hoặc Finder vào một ô nhịp trong bản phối và nó nằm <strong>đúng chỗ bạn thả</strong>. MIDI vào track MIDI, âm thanh vào track âm thanh, và loại sai sẽ bị từ chối kèm lý do thay vì được cấp một làn riêng.","docs.5d740606fafb":"Một tệp được thả vào sẽ được <strong>đưa vào dự án</strong>, không phải tham chiếu. Thả một thứ từ thư mục tạm rồi xoá bản gốc, clip vẫn phát.","docs.b7ba15ad34d4":"Tìm âm tương tự","docs.6086461c1507":"<strong>Hiện Tìm âm tương tự</strong> mở nó trong trình duyệt tệp. Chọn một <strong>Tham chiếu</strong>, là một âm thanh hoặc một vòng MIDI trong thư mục bạn đang ở, rồi nhấn <strong>Tìm tương tự</strong>: mọi tệp giống nó trong các thư mục của trình duyệt tệp và các gói trống đi kèm được chấm điểm trên 100, tối đa 200 tệp, mỗi tệp được xếp là <em>Bản sao y hệt</em>, <em>Cùng âm thanh</em>, <em>Âm thanh tương tự</em>, <em>Đổi cao độ hoặc kéo giãn</em> hoặc <em>Cùng nhịp điệu</em>, kèm lý do bằng lời: cùng âm thanh trong một tệp khác, đổi mức âm lượng, cắt bớt, bản sao mono, tần số lấy mẫu khác, đổi cao độ hoặc kéo giãn, âm sắc đã thay đổi, cùng nhịp điệu nhưng bị dịch vòng hoặc ở nhịp gấp đôi. <strong>Nghe</strong> phát <em>A: tham chiếu</em>, <em>B: tệp giống</em>, hoặc <em>A+B cùng lúc</em>, đã căn khớp với nhau.","docs.d601313e7e44":"Lần đầu mở trong một phiên, nó đọc các thư mục ở chế độ nền, và sau đó chỉ đọc những gì mới hoặc đã thay đổi; <strong>Đọc lại các thư mục</strong> đọc chúng ngay bây giờ, và <strong>Dừng đọc</strong> dừng việc đọc. Nó chỉ đọc tệp WAV và MIDI. Đây là phép đo, không có mô hình: độ dịch cao độ tới ba nửa cung và độ kéo giãn tới 12 % sẽ được tìm ra, còn vượt quá mức đó thì nó không hứa gì. Những gì chỉ mục của nó lưu giữ có trong <a href=\"#privacy\">Riêng tư và mạng</a>.","docs.903a1771c064":"Ghép kick và bass","docs.385e4ddb76c4":"Trong một thư mục có từ hai âm thanh trở lên, <strong>Ghép kick và bass</strong> hiện ra trong trình duyệt tệp. Chọn <strong>Trống kick</strong> rồi nhấn <strong>Xếp hạng các tiếng bass</strong>: mọi tệp WAV khác trong thư mục được đọc như một tiếng bass và được chấm <strong>Điểm</strong> trên 100, dựa trên <strong>Quãng</strong>, tức cao độ của kick khớp với nốt gốc, quãng năm hay quãng tám của bass đến đâu; <strong>Độ gồ ghề</strong>, tức hai tiếng tạo phách với nhau nhiều đến mức nào; <strong>Độ chồng lấn</strong>, tức phần dải trầm mà chúng dùng chung; và <strong>Độ khớp tắt dần</strong>, tức đuôi của kick đã tắt hẳn trước khi bass ổn định hay chưa.","docs.f58b0fef366e":"<strong>Chỉnh tông</strong> cho số cent cần chỉnh để kick nằm trên nốt gốc, quãng năm hoặc quãng tám của bass, và <strong>Nghe</strong> phát một ô nhịp gồm bốn tiếng kick đã chỉnh tông, đè lên bass ở 120 BPM. Một tiếng kick không có thân âm cao độ sẽ nói rõ điều đó và không đề xuất chỉnh tông, còn tệp không đọc được sẽ được liệt kê cuối cùng. Nó đọc bốn giây đầu của mỗi tệp, tối đa 2.000 tiếng bass, và không giữ lại gì. Đây là phép đo, không có mô hình.","docs.b24ba56ae294":"<kbd>Ctrl</kbd>+<kbd>5</kbd>. Nhấn <strong>Tạo mã phòng</strong>, chờ mã hiện ra, rồi gửi nó cho người bạn đang làm cùng. Họ dán nó vào, gửi lại mã của họ, bạn dán mã đó vào <strong>Cho họ vào</strong>, và các bạn đã ở trong cùng một phiên.","docs.shot.room":"Bảng Phòng với nút Tạo mã phòng được đóng khung đỏ và đánh số 1, và nút Cho họ vào — nơi bạn dán mã ai đó gửi cho bạn — được đóng khung và đánh số 2.","docs.0548c5c7cd35":"1 tạo mã của bạn. 2 là chỗ dán mã của họ. ⚠ Khi đã có mã, câu nằm bên cạnh nó mới là câu quan trọng: hãy coi nó như một mật khẩu, vì nó chứa địa chỉ công khai của máy bạn.","docs.41a1acbef296":"Bạn có gì","docs.4e795a73e99f":"Một danh sách thành viên, mỗi người một màu, và con trỏ của họ di chuyển trên bản phối của bạn.","docs.e2168f0fe102":"Trò chuyện. Nó tồn tại chừng nào phòng còn và không có gì được ghi xuống đĩa.","docs.83623938eb6f":"Giọng nói, ô camera và chia sẻ màn hình — tất cả đều tắt cho tới khi bạn nhấn nút.","docs.5161add1f5a4":"<strong>Lệnh hoàn tác của bạn là của bạn.</strong> <kbd>Ctrl</kbd>+<kbd>Z</kbd> lấy lại thay đổi gần nhất của bạn và không bao giờ của người khác, kể cả khi các chỉnh sửa của họ đang đổ về.","docs.ab67452f2acf":"<strong>Bàn giao</strong> — trao một track cho ai đó và lấy lại bằng một phím. Khi họ đang giữ nó, họ là người duy nhất được ghi lên track đó, kể cả bạn cũng không.","docs.6a62a97df77a":"Những gì không bao giờ được gửi đi","docs.c61d0ae17869":"<strong>Một take bạn đã thu thì được gửi đi. Một sample bạn đã mua thì không bao giờ.</strong> Khi ai đó vào một phiên dùng một gói sample mà họ không có, họ nhận được một danh sách tên là <em>Sample bạn cần</em> kèm lý do: Oscillate không bao giờ gửi sample giữa các máy tính. Giống hệt từng byte là thứ mà vi phạm bản quyền tạo ra, và sản phẩm này sẽ không trở thành con đường dẫn tới điều đó.","docs.0cce48095d62":"Khi kết nối không thành","docs.7a85d27236d6":"Khoảng một trong mười kết nối sẽ không hình thành, và Oscillate gọi tên đó là nguyên nhân nào trong chín nguyên nhân — từ <em>không tìm thấy mạng nào</em> tới <em>mạng của bạn cấp cho mỗi máy chủ một địa chỉ khác nhau</em>. Trường hợp cuối cần một relay ở giữa; có một ô để điền relay của riêng bạn trong <strong>Cài đặt ▸ Cộng tác</strong>.","docs.17644a30eafc":"MixSir đưa bài hát lên một chiếc điện thoại trong mạng Wi-Fi của bạn, để nghe và mix khi rời khỏi bàn làm việc, mà không cần cài gì lên điện thoại. Trong bảng <strong>Phòng</strong> (<kbd>Ctrl</kbd>+<kbd>5</kbd>), ở mục <strong>Điện thoại</strong>, nhấn <strong>Gửi đến điện thoại của tôi</strong>. Oscillate kết xuất bản mix và một phần cho mỗi track có clip, kể cả các plugin của bạn, rồi liệt kê chúng dưới <strong>Những gì điện thoại sẽ thấy</strong>. Khi nó báo <strong>Sẵn sàng trên mạng của bạn</strong>, mã QR sẽ hiện ra.","docs.c1e2f9c2bdf0":"Quét mã bằng camera của điện thoại, trên cùng mạng Wi-Fi với máy tính, và bản mix sẽ mở trong trình duyệt của điện thoại. Mọi phần được tải lên điện thoại ngay khi trang mở ra; khi trang báo đã sẵn sàng, các phần vẫn tiếp tục phát dù tắt mạng, chừng nào trang còn mở.","docs.9126b986fc96":"Trên điện thoại","docs.592290a5fa7c":"<strong>Bàn trộn.</strong> Một dải kênh cho bản mix và một dải cho mỗi phần, với gain, pan, tắt tiếng và solo. Nhấn Phát sẽ phát bản mix đúng như lúc được gửi. Chạm vào một phần — gain, pan, tắt tiếng hay solo của nó — và các phần sẽ phát thay vào đó, theo cách bạn cân chỉnh chúng; tắt tiếng bản mix để nghe các phần, hoặc solo nó để chỉ nghe bản mix. Bản mix và các phần không bao giờ phát chồng lên nhau.","docs.27a679645074":"<strong>Lưu một phần.</strong> Mỗi dải kênh lưu phần của nó vào điện thoại: dưới dạng WAV với gain và pan của dải kênh đó, được tạo ngay trên điện thoại, hoặc dưới dạng MP3 192 kbps, tải về từ máy tính, nên cần có mạng.","docs.fb7ea2c82263":"<strong>Nghe tại bàn làm việc</strong> phát bản mix từ máy tính, ở định dạng Opus, và không lưu gì.","docs.69571d7ebce2":"<strong>Tạo.</strong> Khi MIDI Master mà bạn chạy trong host có cổng lệnh (một bản dựng MIDI Master sắp ra), trang sẽ hiện một phím <strong>Tạo</strong>: nhấn nó và MIDI Master tạo một take mới trên máy tính, cửa sổ của nó mở ra, và take đó có thể hoàn tác trong lịch sử của chính MIDI Master như mọi take khác. Cho đến lúc đó, trang không nói gì về việc tạo.","docs.803617a467e8":"Điện thoại nghe bài hát đúng như lúc bạn nhấn <strong>Gửi đến điện thoại của tôi</strong>: một chỉnh sửa sau đó cần gửi lại lần nữa. Một bài hát có thể dài tối đa mười phút, với tối đa 127 track có nội dung; bài hát dài hơn, hoặc một bản phối trống, sẽ bị từ chối kèm một câu nói rõ điều đó.","docs.96495dd1cb07":"Mã chính là khóa","docs.34a09397f380":"Mã này mang một khóa chỉ tạo cho lần ghép nối này, và địa chỉ bên dưới cũng mang đúng khóa đó: bất kỳ ai quét mã, hoặc có địa chỉ, đều nghe được bài hát cho đến khi bạn dừng hoặc ghép nối lại. Hãy đối xử với nó như một mã phòng. <strong>Sao chép địa chỉ</strong> đưa địa chỉ vào bộ nhớ tạm.","docs.8490e9d3c2a9":"<strong>Ngừng gửi đến điện thoại</strong>, biểu tượng dừng, kết thúc việc chia sẻ; ghép nối lại (tạo một khóa mới và chấm dứt khóa cũ) hay đóng Oscillate cũng vậy. Năm yêu cầu với khóa sai, hoặc không có khóa, sẽ tự kết thúc lần ghép nối, và bảng hiện <strong>Đã dừng</strong>.","docs.f9a0489529f8":"Điện thoại được phục vụ qua HTTP thường trên cổng 7434, trong mạng của chính bạn. Kết nối không được mã hóa, nên hãy gửi đến điện thoại trên một mạng bạn tin cậy. Nếu một chương trình khác đang giữ cổng 7434, hoặc máy tính không ở trong mạng nào mà điện thoại có thể dùng chung, bảng sẽ báo điều đó. Khi dùng VPN, địa chỉ có thể là một địa chỉ mà điện thoại không tới được.","docs.3dddae9cbb86":"<strong>Kumite</strong> là chế độ đấu beat trong đó mỗi lượt sở hữu các ô nhịp của riêng mình. Đồng hồ đếm ngược chỉ là đồng hồ đếm ngược, còn các ô nhịp mới là luật — nên hai máy tính không bao giờ có thể bất đồng về việc chỉnh sửa của ai là hợp lệ.","docs.aa8f79385db8":"<strong>Bảng chia phần</strong> cho biết ai viết gì, rút ra từ nhật ký chỉnh sửa, đã trừ đi phần việc mà ai đó đã hoàn tác. Nó là điểm khởi đầu cho một cuộc trò chuyện về ghi công, không phải văn bản pháp lý, và nó nói rõ như vậy.","docs.9129cdbc7eff":"Chọn một track giọng hát và nhấn <strong>Lời bài hát</strong>. Một làn chữ hiện ra, khoá theo đầu phát. Thêm dòng, dời một dòng sớm hơn hoặc muộn hơn một ô nhịp, tách một dòng thành các âm tiết, và trỏ một take đã thu vào những chữ mà nó thuộc về.","docs.64413b5bc744":"Nhập một tệp <code>.txt</code> hoặc <code>.lrc</code> và chữ được <strong>sao chép vào dự án</strong> — dời tệp đi sau đó thì chữ vẫn còn đó.","docs.f935e3c9c7fe":"Cỡ chữ được làm để hát từ bên kia căn phòng, không phải để chồm người tới đọc. Mỗi chỉnh sửa lời bài hát là một thao tác, nên <kbd>Ctrl</kbd>+<kbd>Z</kbd> lấy lại nó như mọi thứ khác.","docs.30c821abae69":"Gõ chữ với từ điển","docs.7cbdc2099480":"Trình sửa dòng hoàn tất từ bạn đang gõ dựa trên một từ điển tiếng Anh 327.000 từ: phần còn lại của từ khả dĩ nhất hiện sau con trỏ, và <kbd>Tab</kbd> nhận nó. Một dải dưới dòng hiện từ đúng như bạn đã gõ và các gợi ý cho nó. <kbd>Shift</kbd>+<kbd>Tab</kbd>, hoặc dấu <strong>✓</strong> bên cạnh từ, giữ nguyên nó như đã gõ: từ bạn giữ sẽ không bao giờ bị sửa nữa và từ đó trở đi sẽ được gợi ý. Các từ bạn đã giữ nằm lại trên máy tính này.","docs.a5c2d92c7274":"Công tắc <strong>Chính tả</strong> trong làn sửa một từ viết sai ngay khi từ đó kết thúc. Mặc định nó bật khi Oscillate dùng tiếng Anh và tắt ở các ngôn ngữ khác, vì từ điển là tiếng Anh, và lựa chọn của bạn được ghi nhớ trên máy tính này. <kbd>Backspace</kbd> ngay sau một lần sửa sẽ trả lại từ của bạn. Tính năng tự hoàn tất và các công cụ dưới đây hoạt động như nhau dù công tắc bật hay tắt.","docs.33802db20e24":"Âm tiết trên nốt của chúng","docs.df726c0bd8c5":"Gõ <code>-</code> giữa các âm tiết của một từ, và <code>_</code> để ngân một âm tiết sang nốt tiếp theo. Trên một track có chơi nốt, <strong>Tách</strong> đặt mỗi âm tiết lên nốt của nó, và mỗi dòng cho thấy nó khớp với các nốt bên dưới ra sao: <em>4/4</em> khi khớp, <em>+2</em> khi thừa hai âm tiết, <em>−1</em> khi dư một nốt. Một dòng dài hơn số nốt của nó thì không tách được, và nói rõ lý do; từ nào bị một dấu lặng cắt làm đôi sẽ được nêu tên.","docs.edd3ba06a90f":"Trọng âm, vần và flow","docs.0a571dae45e8":"<strong>Dấu trọng âm</strong> đánh dấu âm tiết nhấn của mỗi từ trong làn, và máy nhắc chữ in đậm âm tiết đó.","docs.f545becb9d77":"<strong>Vần</strong> tô màu từ cuối của mỗi dòng theo vần, đặt chữ cái của dòng trong sơ đồ vần của đoạn ở trước dòng và cả sơ đồ của đoạn — <em>AABB</em>, <em>ABAB</em>… — ở dòng đầu tiên của đoạn, và gắn cờ một cụm từ sáo rỗng là <em>quen thuộc</em>.","docs.1d1d44de93c4":"<strong>Lưới flow</strong> xếp các âm tiết của mỗi ô nhịp lên lưới móc kép, kèm số đếm, một dấu ở chỗ âm tiết cuối của ô nhịp rơi vào phách thứ tư, độ pocket và ngữ điệu: tỉ lệ âm tiết nhấn rơi vào một phách mạnh, một nốt dài hoặc một đỉnh của giai điệu.","docs.dbb2a72d9b7f":"<strong>Đọc rap</strong>, trong lưới flow, đo thời điểm của một take đã thu mà bạn chọn trên track so với các âm tiết đã đặt, và đánh dấu từng âm tiết là sớm hay muộn. Nó đọc một take, không bao giờ đọc micrô, và không tạo ra gì cả.","docs.cebc83e88cfb":"Bản nhạc chính","docs.17bc21413b45":"Phím <strong>Bản nhạc chính</strong> trong làn mở giai điệu của track, lời và các ký hiệu hợp âm trong trình đọc bản nhạc của bảng Bản nhạc. Hợp âm là của chính track, hoặc của track khác đầu tiên có chơi hợp âm.","docs.b3307da67465":"<strong>Tệp ▸ Xuất thư mục đi kèm…</strong> ghi ra stem và MIDI mà bất kỳ DAW nào khác cũng mở được. Các stem thẳng hàng ở ô nhịp 1, nên nhập chúng vào chỗ khác không có nghĩa là phải xê dịch ba mươi tệp vào đúng vị trí.","docs.271287d739a7":"Định dạng, tần số lấy mẫu, độ sâu bit, dither và nơi lưu nằm trong <strong>Cài đặt ▸ Xuất</strong>.","docs.d20207c90bc7":"Một bài hát có thể dài bao nhiêu cũng được: thư mục đi kèm và các bản master được ghi ra đĩa ngay trong lúc kết xuất chứ không giữ trong bộ nhớ. Một tệp WAV hoặc AIFF không thể vượt quá 4 GB, và bản xuất nào sẽ vượt mức đó thì bị từ chối và không để lại gì. Một track được kéo ra dưới dạng âm thanh vẫn bị giới hạn ở mười phút.","docs.1419f63cf3ba":"<strong>Thẻ phiên.</strong> <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>C</kbd>, hoặc <strong>Tệp ▸ Thẻ phiên…</strong>, kết xuất một bức ảnh 1200×630 của phiên — nhịp độ, giọng, số track và số clip, độ dài và hình dáng của bản phối — để đăng lên. Mã phòng không thể nằm trên đó: nó dài hàng kilobyte và chứa địa chỉ công khai của bạn, nên tuỳ chọn ấy có mặt, bị vô hiệu hoá, và nói lý do.","docs.a684e2a13540":"Bản nhạc dưới dạng PDF","docs.5c5543df78a1":"<strong>Tệp ▸ Xuất bản nhạc ra PDF…</strong>, hoặc phím <strong>PDF</strong> trong khay của bảng Bản nhạc, tạo một tệp PDF A4: trang bìa, phần ghi công, bản nhạc của mọi track và tổng phổ, được lưu ở chỗ bạn chọn trong chính hộp thoại lưu của hệ thống, vốn gợi ý tên dự án. Một dòng đếm số trang khi chúng được tạo, rồi cho biết PDF đã được lưu, rằng không có gì để đưa vào, rằng nó sẽ quá lớn, hoặc vì sao nó thất bại. Huỷ hộp thoại thì không có thông báo gì.","docs.f28c2866474a":"<strong>Trang bìa</strong> cho biết giọng, nhịp độ và số chỉ nhịp, mỗi lần đổi kèm ô nhịp nơi nó xảy ra, số ô nhịp, và số nốt tổng cộng và theo từng track. <strong>Phần ghi công</strong> nêu tên những người viết, có nốt vẫn còn trong bài, và những nhà sản xuất, có clip hoặc thiết bị vẫn còn trong bài, lấy từ chính lịch sử của dự án: theo tên đặt trong <strong>Cài đặt ▸ Cộng tác ▸ Tên của bạn trong phòng</strong>, hoặc theo biệt danh của cộng tác viên. Ai chưa từng đặt tên thì vẫn được đếm, không bao giờ bị in ra dưới dạng một ID. Ca sĩ, mẫu âm và hãng đĩa được bỏ ra, vì lịch sử không thể biết về chúng.","docs.d8a5cfa121d2":"In bản nhạc","docs.43a69487c481":"<strong>Tệp ▸ In bản nhạc…</strong>, hoặc phím <strong>In</strong> trong khay, gửi đúng những trang đó tới hộp thoại in của hệ thống: không có gì khác của cửa sổ, trên giấy A4 trắng ở cả hai giao diện. Trong tiếng Ả Rập, trang bìa và phần ghi công đọc từ phải sang trái.","docs.a5d84ebf2f4a":"<kbd>Ctrl</kbd>+<kbd>9</kbd>, <strong>Xem ▸ Kiểm tra cuối</strong>, hoặc phím của nó trên thanh tiêu đề sẽ mở Kiểm tra cuối: một bản master cho mỗi nơi bài hát sẽ đến, mỗi bản được kiểm tra trước khi rời đi. Nó là một cửa sổ riêng, giống Bàn trộn, và nút <strong>⇲</strong> của nó gắn nó vào bên dưới Bàn trộn trong cửa sổ chính. Các tab của nó là <strong>Bản master</strong>, <strong>Loa</strong>, <strong>Bậc thang độ to</strong> và <strong>Kiểm tra quy chuẩn</strong>.","docs.eaa4d72d14bf":"Một bản master cho mỗi nơi phát hành","docs.515031535d57":"Trên tab <strong>Bản master</strong>, đánh dấu nơi bài hát sẽ đến trong danh sách thả xuống các nơi phát hành, mỗi nơi một ô đánh dấu, hoặc <em>Tất cả</em>: Spotify, Apple Music, YouTube, Amazon Music, Tidal, Deezer, SoundCloud, một đĩa CD, một câu lạc bộ, hoặc phát sóng theo EBU R 128 hay ATSC A/85. Mỗi nơi hiện mục tiêu độ to và trần đỉnh thực ngay bên cạnh, và bảng bên dưới đưa ra từng hàng đã đánh dấu cùng loại tệp mà nơi đó muốn. Một hàng cho biết con số là của chính dịch vụ hay là mặc định của Oscillate khi dịch vụ không công bố, kèm nguồn gốc của nó và ngày nó được đọc. Một mục tiêu chỉ là hướng dẫn, không bao giờ là lời hứa rằng một dịch vụ sẽ chấp nhận một tệp. Những gì bạn đánh dấu được ghi nhớ trên máy tính này.","docs.4455f6266bc0":"<strong>Xuất các bản master</strong> tạo một bản master cho mỗi hàng được đánh dấu, cùng lúc, từ cùng một bản mix: mỗi bản được giới hạn ở trần của nó, đưa về độ to của nó và ghi theo định dạng của nó, rồi được đo từ tệp trên đĩa, và bảng cho biết nó có đạt yêu cầu của hàng đó hay không. Chúng được lưu chung trong một thư mục, đặt theo tên dự án, ở nơi mà <strong>Cài đặt ▸ Xuất</strong> gửi các bản xuất của bạn tới.","docs.a7ab3056096a":"Nghe như","docs.9dda3184a093":"Trên tab <strong>Loa</strong>, <strong>Nghe như</strong> phát những gì bạn đang nghe đúng như nó vốn có, <strong>Phẳng</strong>, hoặc như một chiếc <strong>Điện thoại</strong>, một chiếc <strong>Ô tô</strong>, một chiếc <strong>Máy tính xách tay</strong>, một chiếc <strong>Loa nhỏ</strong> hay một bộ <strong>Tai nghe nhét tai</strong> sẽ phát. Mỗi loa đã được cân mức, nên đổi loa chỉ đổi màu âm chứ không đổi độ to, và việc chuyển được chuyển mờ không có tiếng lách cách; <strong>So sánh với phẳng (A)</strong> chuyển qua lại giữa loa đó và Phẳng để so sánh A/B. Nó chỉ để nghe kiểm: những gì bạn nghe ở đây không bao giờ đi vào bản xuất, bản bounce hay bản master, và mỗi lần khởi động đều bắt đầu ở chế độ phẳng. Mỗi loa là một mô phỏng gần đúng của một loại loa, không bao giờ là phép đo của sản phẩm nào.","docs.cdc6504729ef":"Mỗi bản master được xuất cũng được kiểm tra như cách loa của điện thoại và khoang xe ô tô sẽ phát nó: điện thoại còn giữ được bao nhiêu phần bass, những gì bị mất khi nghe mono, dải trầm rộng đến đâu, và nó có bị dồn lại ở 80–150 Hz hay 200–400 Hz trong ô tô hay không, kèm theo cách xử lý cho từng điều.","docs.85148526c29c":"Bậc thang độ to","docs.2472106bcd5c":"<strong>Bậc thang độ to</strong> đo riêng từng đoạn của bài hát, từ một điểm đánh dấu tới điểm kế tiếp, so với một bậc ứng với loại của nó (Mở đầu, Đoạn phiên khúc, Tiền điệp khúc, Điệp khúc, Đoạn chuyển hoặc Kết bài) trong một dung sai, và kiểm tra rằng mỗi điệp khúc vượt lên trên đoạn phiên khúc trước nó theo mức chênh trong <strong>Điệp khúc vượt phiên khúc</strong>. Hãy đặt tên các điểm đánh dấu bằng tiếng Anh (Intro, Verse, Pre-chorus, Chorus, Bridge, Outro) để loại của chúng được nhận ra. <strong>Đo bản phối</strong> vẽ các bậc lên trên độ to của bài hát, với mọi con số trong một bảng. Các mục tiêu được lưu trên máy tính này, không lưu trong dự án.","docs.e4f52faad73b":"Kiểm tra quy chuẩn","docs.966ff4263e47":"<strong>Kiểm tra quy chuẩn</strong> kiểm tra một tệp đã xuất, một trong các bản master hoặc bất kỳ tệp nào qua <strong>Kiểm tra một tệp…</strong>, so với một mục tiêu giao nộp: phát trực tuyến, to hoặc nhỏ; phát sóng, EBU R 128 hoặc Mỹ (ATSC A/85); bản master cho CD; WAV cho nhà phân phối; hoặc mục tiêu của riêng bạn. Mười ba quy tắc của nó bao gồm độ to, 3 giây và 400 ms to nhất, dải độ to, đỉnh thực và đỉnh mẫu, tần số lấy mẫu, độ sâu bit, số kênh, độ dài, khoảng lặng ở mỗi đầu và các mẫu bị cắt đỉnh liên tiếp; mỗi quy tắc cho biết giá trị đo được, khoảng dư và cách sửa đơn giản nhất. Khi chỉ một lần thay đổi gain đáp ứng được mọi quy tắc về mức, nó cho biết cần bao nhiêu, còn khi không lần nào làm được, nó nói điều đó.","docs.565f3cb18dc4":"Một mục tiêu có thể được sửa và đóng dấu bằng <strong>Đánh dấu đã kiểm tra hôm nay</strong>; mục tiêu nào 180 ngày chưa được kiểm tra sẽ hiện là chưa kiểm tra. Bản báo cáo được lưu dưới dạng HTML, JSON hoặc PDF. Đạt nghĩa là tệp đáp ứng các quy tắc của mục tiêu bạn đã chọn, không bao giờ có nghĩa là một dịch vụ sẽ chấp nhận nó.","docs.4d70c96652da":"Mix giúp tôi","docs.80cd4454f137":"<strong>Mix giúp tôi</strong>, bên cạnh <strong>Xuất các bản master</strong>, thiết lập toàn bộ bản mix cho nơi phát hành đầu tiên được đánh dấu: các thẻ hiệu ứng của mọi phần chưa khóa và chưa tắt tiếng được đặt theo gợi ý của chúng (xem <a href=\"#devices\">Gợi ý</a>), mức của mỗi phần theo đúng loại của nó, và trên kênh master là một True-Peak Limiter đưa bản mix về đúng độ to của hàng đó, dưới trần của nó. Các track bị khóa và bị tắt tiếng được giữ nguyên, một fader có tự động hoá âm lượng cũng vậy; nếu Hạt của kênh master đang bật thì nó sẽ bị tắt, vì nó phát sau limiter. Bản báo cáo cho biết nó đã làm gì.","docs.8df50e56ff44":"Đó là một bước hoàn tác: hoàn tác sẽ đưa toàn bộ bản mix trở lại. Nó kết xuất từng phần ngoại tuyến để đo, nên với một phiên lớn sẽ mất một lúc.","docs.5371ad5444f6":"<kbd>Ctrl</kbd>+<kbd>,</kbd>. Mọi thay đổi có hiệu lực ngay và được lưu riêng cho từng máy. Không có nút <em>Áp dụng</em>, vì một hộp thoại cài đặt có nút đó là một hộp thoại cài đặt có thể sai về những gì đang có hiệu lực.","docs.d7af9297a0b1":"Mười ba mục của nó xếp dọc theo cạnh bên. <strong>Ghi âm</strong> chứa phần đếm vào, cùng phím tắt toàn cục và biểu tượng khay của Oscillate Retro Record, cả hai đều tắt cho đến khi bạn bật; xem <a href=\"#retro-record\">Oscillate Retro Record</a>.","docs.bc1b88907d3b":"Âm thanh","docs.40710b1c4ea7":"Chọn đầu ra của bạn và chiếm bao nhiêu thiết bị. Trên Windows bạn có thể yêu cầu <strong>Độc quyền</strong>, cho bạn độ trễ thấp nhất mà phần cứng làm được và làm im mọi ứng dụng khác. Oscillate cho bạn biết <strong>bạn thực sự nhận được chế độ nào và vì sao</strong> — hoặc <em>luồng đã mở ở chế độ độc quyền</em>, hoặc <em>máy này không mở được luồng độc quyền, nên thiết bị vẫn dùng chung</em>. Không bao giờ lặng lẽ hạ cấp.","docs.dfe87d5e5bba":"Giao diện và ngôn ngữ","docs.ca2a0f41ebc8":"Cả hai giao diện sáng tối, mười tám ngôn ngữ, và lựa chọn của bạn thắng lựa chọn của máy ở lần khởi động sau. Bố cục phải-sang-trái là thật, không chỉ là căn lề chữ. Bên cạnh là <strong>Tốc độ</strong> và <strong>Giảm chuyển động</strong>: <em>Nhanh</em> xoay tiêu đề nhanh gấp đôi, còn <em>Giảm</em> dừng mọi hiệu ứng chuyển động, bất kể hệ thống nói gì.","docs.56205fc54fb3":"<strong>Cài đặt ▸ Cập nhật.</strong> Oscillate tìm bản cập nhật <strong>chỉ</strong> khi bạn nhấn <em>Kiểm tra cập nhật</em>, hoặc lúc khởi động nếu bạn bật tuỳ chọn đó — và nó <strong>mặc định là tắt</strong>.","docs.shot.updates":"Cài đặt với mục Cập nhật được chọn, nút Kiểm tra cập nhật được đóng khung đỏ và đánh số 1, và công tắc Kiểm tra khi Oscillate khởi động được đóng khung, đánh số 2 và đang ở vị trí tắt.","docs.983c1169fe58":"1 kiểm tra một lần, ngay bây giờ. 2 là kiểm tra lúc khởi động, và nó tắt cho tới khi bạn bật lên. Bảng in ra chính xác địa chỉ sẽ được liên hệ và lần cuối cùng địa chỉ đó thực sự được liên hệ.","docs.3ce9192c8c94":"Lần kiểm tra xin một tệp tĩnh và không gửi gì về bạn, máy này hay các dự án của bạn. Khi tìm thấy bản cập nhật, bạn được xem phiên bản, ngày, nhật ký thay đổi và dung lượng, rồi bạn quyết định. Mọi tệp phát hành đều có chữ ký; tệp nào chữ ký không xác minh được sẽ bị từ chối kèm thông báo lỗi thay vì được cài.","docs.eb0eedb56328":"Khi tắt kiểm tra lúc khởi động, không có gì được liên hệ và bảng không hiện kết quả nào — <em>Kiểm tra lần cuối</em> vẫn là <em>Chưa bao giờ</em>. Nó không bao giờ hiện \"bạn đang dùng bản mới nhất\" cho một lần kiểm tra chưa hề diễn ra, vì đó là hai sự thật khác nhau và chỉ một trong hai là đúng.","docs.855dbb09047b":"Mọi phím tắt dưới đây đều có thể đổi trong <strong>Cài đặt ▸ Phím tắt</strong>, và một tổ hợp đã có chủ sẽ cho biết hành động nào đang giữ nó. Trên macOS, hãy đọc <kbd>Ctrl</kbd> là <kbd>Cmd</kbd>.","docs.456bb0100878":"Tổ hợp phím","docs.64cff1319d2f":"Hành động","docs.a78afaff2fda":"Phát hoặc tạm dừng","docs.4b627c7915d2":"Lưu Oscillate Retro Record — vài phút cuối của đầu vào, được giữ lại sau đó","docs.a41eb2bf7245":"Dự án mới","docs.c4c61e4f9081":"Mở một dự án","docs.1509f561f241":"Lưu","docs.60af8a30e5e6":"Lưu thành","docs.c0d170d865e7":"Hoàn tác — luôn là của bạn","docs.74273989b096":"Làm lại","docs.26c31b40dc4c":"Thẻ phiên","docs.e91f3b2dc496":"Hiện hoặc ẩn Trình duyệt tệp","docs.3eeec874b1d1":"Hiện hoặc ẩn Giá pattern","docs.56f9e52baa67":"Hiện hoặc ẩn một bảng — Trình chỉnh sửa, Bàn trộn, Phòng","docs.83e175e68d99":"Hiện hoặc ẩn Sân khấu","docs.1d966b73a9ca":"Hiện hoặc ẩn bảng Bản nhạc","docs.ef1800cc8809":"Hiện hoặc ẩn bảng Bài học","docs.30da360ea376":"Hiện hoặc ẩn cửa sổ Kiểm tra cuối","docs.bed27fa10d73":"Mở một trong chín bản nhạc đầu tiên, 1 là tổng phổ, khi bảng Bản nhạc đang hiện; nhấn lại cùng phím đó để quay lại","docs.2f965c221f2d":"Quay lại từ bản nhạc đang mở, trong bảng Bản nhạc","docs.ef86faf16227":"Chuyển góc nhìn của sân khấu, tới hoặc lui, khi sân khấu đang có tiêu điểm","docs.598372c72bff":"Chuyển góc nhìn sân khấu tới hoặc lui, từ bất kỳ đâu khi sân khấu đang hiện","docs.0bb673ee3069":"Lưỡi dao / con trỏ","docs.ce13b797313a":"Công cụ vẽ; trong trình chỉnh sửa, chế độ vẽ (bút chì)","docs.5689a46a3b2a":"Công cụ vẽ lặp — clip đã chọn được vẽ dọc theo một làn","docs.ae568d1cdc7a":"Công cụ xóa","docs.2e45e8cb5822":"Công cụ tắt tiếng","docs.2914595ae6ab":"Công cụ trượt nội dung — nội dung của clip trượt đi; ở một mép, mép đó di chuyển cùng nó","docs.d9e17187d41a":"Công cụ nghe thử — clip được nhấn, nghe riêng","docs.8bda3a715fdf":"Sao chép các clip đã chọn","docs.6a9097f78c98":"Dán các clip tại đầu phát","docs.5d4232ecd8df":"Trong piano roll: sao chép, cắt và dán các nốt đã chọn","docs.c216e4b5e616":"Dấu mốc trước / dấu mốc sau","docs.63195e7ab017":"Ô nhịp 1 / cuối bản phối","docs.308ea67cd57c":"Chọn tất cả","docs.ef8b2814c03b":"Bỏ chọn","docs.3eea5fab03b2":"Xoá những gì đang chọn","docs.324d77bb489d":"Lượng tử hoá","docs.caa2871b6c07":"Nhân tính hoá","docs.c9b32288f886":"Legato","docs.2e5b4c5eaf16":"Đảo ngược các nốt","docs.349dbacd897e":"Đưa các nốt về âm giai","docs.dee3dab5b567":"Nhân bản ra phía sau","docs.a5239b85e5fb":"Xê dịch","docs.f87e04909851":"Một nửa cung; với <kbd>Shift</kbd>, một quãng tám","docs.715210114589":"Gập piano roll theo âm giai","docs.71d26d2e1ebf":"Nốt bóng mờ — phần còn lại của pattern, nằm phía sau những nốt này","docs.c4b80c8b8af1":"Làn velocity","docs.6bea7121b291":"Làn xác suất — mỗi nốt phát thường xuyên tới đâu","docs.12beabce3af4":"Làn biên độ velocity — mỗi nốt dao động xa tới đâu","docs.0c319deafe8d":"Oscillate không cần tài khoản, không thu thập dữ liệu đo từ xa, và không bao giờ gửi dự án, âm thanh của bạn hay bất cứ điều gì về bạn hoặc máy của bạn tới bất cứ đâu mà chính bạn không gửi tới. Thu âm, chỉnh sửa, phát lại, trộn và xuất đều diễn ra hoàn toàn tại máy.","docs.080502306d57":"Có đúng bốn trường hợp nó dùng tới mạng:","docs.7b291aa666a0":"<strong>Một phiên cộng tác mà bạn đã mở hoặc tham gia.</strong> Kết nối thẳng tới những người khác trong đó, ngang hàng, không có máy chủ nào ở giữa.","docs.19e4e946fae3":"<strong>Một lần tra cứu STUN</strong>, chỉ trong lúc đang lập phòng, để tìm ra địa chỉ công khai của bạn. Máy chủ được liên hệ hiện trong Cài đặt và có thể thay bằng máy chủ của riêng bạn — hoặc tắt hẳn, nghĩa là phòng không liên hệ ai cả.","docs.e19cbd5438b8":"<strong>Một lần kiểm tra cập nhật</strong>, chỉ khi bạn nhấn nút hoặc bật kiểm tra lúc khởi động. Mặc định là tắt. Xem <a href=\"#updates\">Cập nhật</a>.","docs.3a3b41351317":"<strong>MixSir, trong lúc bạn gửi đến điện thoại.</strong> Oscillate phục vụ bài hát bạn đã gửi cho các thiết bị trong mạng của chính bạn, qua cổng 7434, cho đến khi bạn dừng; tự nó không liên lạc với bất cứ đâu, và không lấy gì từ điện thoại. Xem <a href=\"#phone\">MixSir</a>.","docs.0d97a43de208":"Điều này được một cổng kiểm tra khi biên dịch bảo đảm chứ không chỉ là lời hứa: không có HTTP client nào truy cập được từ bất kỳ phần nào của Oscillate ngoài các thành phần cộng tác và cập nhật nêu trên, và cổng kiểm tra chứng minh điều đó bằng cách đi khắp đồ thị phụ thuộc chứ không phải bằng cách dò tên. Báo cáo sự cố được ghi xuống đĩa của bạn, cho bạn xem toàn bộ, và chỉ rời khỏi máy nếu bạn chọn gửi.","docs.64a02f31ce7f":"<strong>Nghe trực tiếp.</strong> Khi một bài học lắng nghe bạn, hoặc bạn dùng bộ chỉnh âm hay hiệu chỉnh đầu vào, Oscillate nghe đầu vào của thiết bị âm thanh được chọn trong <strong>Cài đặt ▸ Âm thanh</strong>, và chỉ trong lúc đèn lắng nghe đang sáng. Những gì nó nghe được phân tích trên máy tính của bạn ngay khi đến, thành nốt, hợp âm, cú đánh trống, âm tiết và thời điểm, rồi bỏ đi. Không có bản ghi âm nào được tạo, không có âm thanh nào được ghi ra đĩa, và không có gì được gửi đi đâu cả.","docs.8d1a762df8c1":"Thứ duy nhất mà việc lắng nghe giữ lại là một tệp thiết lập nhỏ, <code>listen.json</code>, trong thư mục dữ liệu của Oscillate trên máy tính này: đầu vào bạn đã chọn, mức chỉnh A4 của bạn, những khóa học nào lắng nghe, công tắc Nghe lại của từng khóa học, và độ trễ đo được của từng đầu vào tính bằng mili giây. Đó là các con số và tên gọi, không bao giờ là âm thanh. Nghe lại, mặc định tắt, phát đầu vào của bạn qua chính track của bài học để bạn nghe được mình; nó cũng không ghi âm gì cả. Một cổng kiểm tra khi build sẽ thất bại nếu mã của phần lắng nghe đụng tới bất kỳ tệp nào ngoài tệp đó, và một bài kiểm thử chạy cả một phiên lắng nghe và không tìm thấy thứ gì khác bị để lại.","docs.caf7b4929a7d":"<strong>Oscillate Retro Record.</strong> Khi <strong>Thu giữ</strong> đang bật, Retro Record giữ đầu vào âm thanh và bàn phím MIDI của bạn trong bộ nhớ của máy tính này, từ 30 giây đến một giờ, phần mới nhất thay thế phần cũ nhất. Không có âm thanh nào được ghi ra ổ đĩa cho đến khi bạn nhấn <strong>Lưu</strong>, và không phần nào của nó bị gửi đi bất cứ đâu. Lưu thành clip sẽ ghi phần âm thanh dưới dạng WAV vào thư mục <code>Takes</code> của Oscillate, như mọi take đã thu; lưu thành tệp WAV sẽ ghi nó, kèm một tệp MIDI khi bạn có chơi nốt, vào thư mục <code>Retro Record</code> trong thư mục dữ liệu của Oscillate. Mỗi tệp được tạo mới dưới một cái tên chưa tệp nào dùng, nên một lần lưu không bao giờ ghi đè lên tệp của bạn, và một lần lưu thất bại giữa chừng không để lại tệp nào của nó.","docs.e5be57430ab7":"<strong>Xóa tất cả</strong> ghi đè bằng số không những gì Retro Record đang giữ, kể cả vài giây vẫn đang trên đường từ luồng âm thanh tới, và trả lại bộ nhớ; đổi độ dài, định dạng hay đầu vào của nó, hoặc rút lại sự đồng ý của bạn, cũng làm như vậy, và thoát ứng dụng sẽ trả bộ nhớ về cho hệ điều hành. Tệp duy nhất khác của nó là <code>retro.json</code>: sự đồng ý của bạn, độ dài, định dạng và đầu vào của nó, công tắc chân và hai công tắc, không bao giờ có âm thanh. Bản bounce hay bản xuất không bao giờ đi vào nó, và một bài kiểm thử giữ cho nó chỉ có một nguồn cấp duy nhất là đầu vào trực tiếp.","docs.5a3b48d48644":"<strong>Tìm âm tương tự</strong> giữ một tệp, <code>find-similar.index</code>, trong thư mục dữ liệu của Oscillate. Với mỗi tệp WAV và MIDI trong các thư mục của trình duyệt tệp và các gói trống đi kèm, nó lưu đường dẫn đầy đủ, kích thước và ngày của tệp, mã băm của các byte và của phần âm thanh hoặc các nốt trong tệp, cùng các số đo thô: độ to và phổ tần của một âm thanh, hoặc nhịp điệu, nhịp độ và nốt thấp nhất của mỗi điểm khởi âm trong một vòng lặp. Không có âm thanh nào được giữ trong đó, và nó không được gửi đi đâu cả; xóa nó chỉ tốn thêm một lần đọc lại các thư mục của bạn. <strong>Ghép kick và bass</strong> không giữ gì cả.","docs.c474edeb7ac4":"<strong>Bốn nhà sản xuất trong một phòng</strong>, vì mỗi người gửi tới tất cả những người còn lại và kết nối thứ năm là chỗ đường tải lên gia đình thông thường cạn kiệt.","docs.d92b90c2dcd3":"<strong>Khoảng một trong mười kết nối sẽ không hình thành</strong> nếu không có relay, và Oscillate không kèm relay nào — relay tốn băng thông mãi mãi, và đó là một hoá đơn kéo dài mà một ứng dụng miễn phí không gánh nổi.","docs.12e311704eeb":"<strong>Sample không bao giờ đi qua đường truyền.</strong> Một take bạn đã thu thì có; một sample bạn đã mua thì không.","docs.311b8222a5fd":"<strong>Sáu thiết bị được gọi tên và làm xám, không có nút điều khiển</strong>, mỗi cái vì một lý do được viết rõ chứ không phải một cái nhún vai.","docs.5aae84a23e5e":"<strong>Phần chữ của các bài học bằng tiếng Anh</strong> cho tới bản beta. Mọi nút điều khiển xung quanh đều bằng ngôn ngữ của bạn.","docs.414bff17d593":"<strong>Một clip âm thanh đã dời cao độ hoặc đã kéo giãn được vẽ theo tệp của nó.</strong> Dạng sóng cho thấy bản thu, không phải âm thanh đang phát.","docs.822c3066dfa6":"<strong>Sampler không có tệp thì không thể kết xuất thành âm thanh.</strong> Chuyển đổi một pattern trên track có sampler đang trống sẽ bị từ chối kèm tên gọi rõ ràng thay vì trả về một khoảng im lặng.","docs.a638c9f1f04c":"<strong>Điện thoại nghe bài hát đúng như lúc được gửi.</strong> Một chỉnh sửa sau <strong>Gửi đến điện thoại của tôi</strong> cần gửi lại lần nữa, và điện thoại được phục vụ qua HTTP thường trong mạng của chính bạn, không được mã hóa.","docs.c446742f8d3c":"<strong>Phòng từ chối một thay đổi bản phối quá lớn.</strong> Việc chuyển, gộp, tạo bản phối mới, sao chép hay xóa mà phải gửi hơn 1.024 thay đổi cùng lúc, khoảng 500 clip, sẽ bị từ chối trong phòng; khi làm một mình, kích thước nào cũng được.","docs.601ee4a78c6d":"<strong>Mod X và Mod Y riêng của từng nốt tới được hai nhạc cụ.</strong> Oscillate Grain Layers nhận cả hai theo từng nốt và Oscillate Siren nhận Mod Y; mọi nhạc cụ khác và các plugin của bạn nhận chúng cho cả track. Plugin không nhận pan hay cao độ tinh của một nốt.","docs.7ddad12c5802":"<strong>Một nốt trượt uốn cả track.</strong> Nó di chuyển bánh xe cao độ của track, nên mọi nốt đang vang ở đó đều bị uốn theo.","docs.687899918ed2":"<strong>Làn CC được vẽ và lưu, nhưng không được phát.</strong> Chưa có nhạc cụ nào đọc nó, kể cả một LFO được ghi vào làn đó.","docs.9596113825be":"<strong>Chia sẻ màn hình có trên Windows và Linux.</strong> macOS không có đường ghi hình màn hình nào ra khỏi một webview nhúng mà không cần API riêng tư trong một tệp nhị phân đã được công chứng, nên nút đó vắng mặt ở đây và nói lý do.","docs.00cc76804476":"<strong>Chưa phát hiện được người bị rớt kết nối.</strong> Nếu mạng của ai đó mất, danh sách thành viên vẫn tiếp tục hiện họ.","docs.c8fe28a31074":"Không có tiếng","docs.90409e8554a3":"Kiểm tra <strong>Cài đặt ▸ Âm thanh</strong> trước: thiết bị, và chế độ bạn thực sự nhận được. Nếu một ứng dụng khác đang giữ giao diện âm thanh ở chế độ độc quyền, Oscillate không mở được nó và sẽ nói ra. Một track im lặng trong khi các track khác thì không thường là do đang có track khác được solo, track bị tắt tiếng, hoặc khe nhạc cụ của nó đang trống.","docs.15d94cccd4a0":"Một plugin không xuất hiện","docs.b2298073a265":"<strong>Cài đặt ▸ Plugin</strong> liệt kê các thư mục đang được quét và những gì tìm thấy. Plugin nào nạp thất bại sẽ được liệt kê là bị chặn kèm lý do, và có thể bỏ chặn để thử lại. Oscillate chạy VST3 và CLAP; nó không chạy VST2 hay AU.","docs.2ac89ed8e9e1":"Phòng không kết nối được","docs.dde8792e71cd":"Đọc lý do nó đưa ra — có chín lý do và chúng là những vấn đề khác nhau. <em>Mạng của bạn cấp cho mỗi máy chủ một địa chỉ khác nhau</em> nghĩa là bạn cần một relay, điền vào <strong>Cài đặt ▸ Cộng tác</strong>. Hãy kiểm tra mã bạn dán có phải là toàn bộ mã không: mã rất dài, và một ứng dụng chat đã ngắt dòng mã sẽ làm hỏng nó.","docs.79993d75b6ac":"Có thứ gì đó bị sập","docs.f6ceafb1fe98":"Một báo cáo được tự động ghi lên máy của bạn. <strong>Cài đặt ▸ Chung</strong> cho biết tên báo cáo gần nhất và mở thư mục chứa nó. Báo cáo gồm phiên bản, hệ điều hành, thiết bị âm thanh và danh sách plugin theo tên — không bao giờ có dự án của bạn, không bao giờ có đường dẫn trên đĩa của bạn, không bao giờ có mã phòng. Nó chỉ rời máy tính của bạn nếu bạn chọn gửi.","docs.9031c748abd6":"Một bảng trắng trơn nhưng nhạc vẫn phát","docs.0f28d0790cf5":"Đó là một kiểu lỗi khác với sập, và là kiểu mà phần lớn mọi người không báo. Luồng âm thanh không chạy chút mã giao diện nào, nên việc phát vẫn tiếp tục và dự án của bạn còn nguyên vẹn. Một báo cáo vẫn được ghi; Cài đặt sẽ cho biết tên của nó.","kit.skip":"Chuyển đến nội dung","kit.nav.site":"Trang web","kit.nav.home":"Trang chủ","kit.nav.features":"Tính năng","kit.nav.documentation":"Tài liệu","kit.nav.changelog":"Nhật ký thay đổi","kit.nav.language":"Ngôn ngữ","kit.nav.allApps":"Tất cả ứng dụng Freally","kit.badge.progress":"v0.17.0 đã xong · tiếp theo là v0.18.0","kit.cta.features":"Xem mọi tính năng","kit.cta.docs":"Đọc tài liệu","kit.price":"Freally Oscillate hiện miễn phí, nhưng có thể không miễn phí mãi mãi: các phiên bản sau này có thể được bán.","kit.noDownloads":"Hiện chưa có bản tải xuống, và mã nguồn là riêng tư.","kit.label.overview":"Tổng quan","kit.label.inside":"Bên trong","kit.label.roadmap":"Lộ trình","kit.ladder.done":"Xong","kit.ladder.planned":"Đã lên kế hoạch","kit.ladder.goal":"Mục tiêu","kit.label.honesty":"Trung thực","kit.family.label":"Gia đình Freally","kit.family.title":"<span class=\"hl-muted\">Một gia đình.</span> <span class=\"hl-bright\">Mười ứng dụng.</span>","kit.cta.label":"Những gì đã thay đổi","kit.cta.title":"<span class=\"hl-muted\">Mỗi phiên bản,</span> <span class=\"hl-bright\">đều được ghi lại.</span>","kit.cta.lede":"Nhật ký thay đổi liệt kê mọi thứ đã thay đổi trong Freally Oscillate, theo từng phiên bản, bằng cả mười tám ngôn ngữ.","kit.cta.changelog":"Đọc nhật ký thay đổi","kit.footer.thisApp":"Ứng dụng này","kit.footer.family":"Gia đình Freally","kit.status.devVersion":"Đang phát triển · v0.17.0","kit.head.features":"<span class=\"hl-muted\">Mọi thứ nó làm được,</span> <span class=\"hl-bright\">đặt cạnh nhau.</span>","kit.label.numbers":"Qua các con số","kit.label.free":"Miễn phí hôm nay","kit.label.compare":"So sánh","kit.label.principles":"Nguyên tắc","kit.label.limits":"Giới hạn","kit.states.title":"Ý nghĩa của các trạng thái","kit.states.done":"đã dựng và gắn thẻ, nhưng không phải bản tải xuống trên trang này","kit.states.planned":"vẫn chưa được xây dựng","kit.states.goal":"phiên bản mà con đường này hướng tới","kit.states.ladder":"Xem mọi nấc trên con đường","kit.head.documentation":"<span class=\"hl-muted\">Cách hoạt động,</span> <span class=\"hl-bright\">từng bước một.</span>","kit.search.placeholder":"Tìm kiếm trong tài liệu","kit.docs.contents":"Mục lục","kit.head.changelog":"<span class=\"hl-muted\">Mọi thay đổi,</span> <span class=\"hl-bright\">theo từng phiên bản.</span>","kit.changelog.lede":"Mới nhất trước: mọi thứ đã thay đổi trong Freally Oscillate, bằng mọi ngôn ngữ của trang này.","kit.changelog.versions":"Phiên bản","kit.search.none":"Không có gì trên trang này khớp với điều đó.","kit.zoom.close":"Đóng","changelog.9fd9a60c9a98":"<span class=\"release__meta\"><span class=\"release__ver\">v0.17.0</span><time class=\"release__date\" datetime=\"2026-11-12\">2026-11-12</time></span>","changelog.c4015d81ec0c":"<strong>Dải trầm, theo cặp — chưa có bản tải xuống.</strong> Hai thiết bị mới được làm để hoạt động cùng nhau: Oscillate Sub đặt một lớp sub-bass bên dưới những gì bạn chơi, còn Oscillate Width mở rộng những gì nằm phía trên nó mà không bao giờ làm mỏng tổng mono. Liên kết chúng, trên một track hoặc trên hai track, và chúng dùng chung một crossover, nên không có gì bên dưới nó bị mở rộng. Bản mix trên điện thoại có thêm phím Tạo cho MIDI Master đi kèm, và một plugin chạy trong host giờ đây nhận được biểu cảm riêng của từng nốt.","changelog.6b02e0d363a4":"Thêm mới","changelog.a86d93475bf6":"<strong>Oscillate Sub: một lớp sub dưới bass.</strong> Sub 1 bám theo cao độ của âm thanh đi vào và phát một sóng sine bên dưới nó, hiển thị bằng hertz hoặc thành tên nốt, với attack, decay và glide riêng; Căn pha giữ nó cùng pha với nguồn, nên hai âm không bao giờ triệt tiêu nhau. Sub 2 hạ một dải của nguồn xuống một hoặc hai quãng tám (hoặc theo nửa cung) ở chất lượng Best, Balanced hoặc Light, ở mono hoặc stereo, và Làm mượt ở 0 giữ lại attack của kick. Âm sắc thêm họa âm để dải trầm vẫn nghe ra trên điện thoại: Tube, Tape, Transistor hoặc Rectifier, oversample gấp bốn lần nếu bạn muốn. Ổn định san đều một đường bass có mức nhảy lên xuống, theo từng dải dưới 150 Hz, và Tắt âm trầm loại bỏ dải trầm của chính nguồn bên dưới crossover. Mặt thiết bị hiển thị cao độ mà nó nghe được, mức của từng sub và một bộ phân tích dải trầm ở ba độ phân giải. Năm mươi preset gốc.","changelog.6dcbf76fb98e":"<strong>Oscillate Width: rộng hơn, không bao giờ mỏng hơn khi nghe mono.</strong> Ba dải, ban đầu chia tại 400 Hz và 4 kHz, mỗi dải được mở rộng từ 0 đến 200 % trong khi tổng mono vẫn y nguyên; Cường độ quyết định hai bên bị kéo xa nhau đến đâu. Solo một dải, chỉ nghe phần được thêm vào (Side) hoặc chứng minh phần giữa không hề dịch chuyển (Mid). Khớp mức giữ một nguồn mono đã mở rộng to đúng như trước, Đang bật đưa nó vào và ra mà không có tiếng click, và một đồng hồ tương quan cùng một goniometer hiển thị trường âm. Không có độ trễ. Năm mươi preset gốc.","changelog.56f07800a4bc":"<strong>Cặp đôi.</strong> Trong trình duyệt, <em>Chèn cặp</em> đặt Sub rồi Width lên một track, đã liên kết với nhau. Khi đã liên kết, trên một track hay trên hai track, chúng dùng chung một crossover: di chuyển nó trên mặt nào thì cả hai cùng di chuyển. Width không bao giờ mở rộng phần bên dưới nó; mặt của Width tô bóng dải mà Sub tạo ra, còn mặt của Sub đánh dấu crossover của Width. Mười hai preset của cặp đặt cả hai cùng lúc. Giờ đây <strong>TÁM MƯƠI LĂM TRONG CHÍN MƯƠI MỐT ĐÃ ĐƯỢC DỰNG</strong>.","changelog.ed4b1f0cb640":"<strong>Tạo từ điện thoại của bạn.</strong> Khi MIDI Master mà bạn chạy trong host có cổng lệnh (một bản dựng MIDI Master sắp ra), trang mix trên điện thoại sẽ hiện một phím Tạo: nhấn nó và MIDI Master tạo một take mới tại bàn làm việc, cửa sổ của nó mở ra và take đó có thể hoàn tác trong lịch sử của chính nó như mọi take khác. Cho đến lúc đó, trang không nói gì về việc tạo.","changelog.c14badf75253":"<strong>Biểu cảm riêng của từng nốt đến được plugin của bạn.</strong> Pressure và âm sắc riêng của một nốt (Mod Y và Mod X theo từng nốt của piano roll), bend riêng của nó, cùng cao độ tinh chỉnh và pan của một bước đến với một plugin CLAP chạy trong host dưới dạng note expression và với một VST 3 dưới dạng sự kiện note expression (pressure là polyphonic pressure), chỉ trên riêng nốt đó. Một plugin không nhận cái nào thì vẫn nghe như trước; một CLAP chỉ đọc MIDI sẽ nhận pressure của nốt dưới dạng polyphonic aftertouch.","changelog.2a6141e43be0":"Thay đổi","changelog.0f032151ad10":"<strong>Nhãn thiết bị bằng tiếng Hà Lan, tiếng Ả Rập, tiếng Ukraina và tiếng Nga</strong> đã được đọc lại đối chiếu với việc mỗi nút điều khiển thực sự làm, và được viết lại ở những chỗ dịch sát chữ, hoặc ở những chỗ hai nút điều khiển dùng chung một từ.","changelog.f016cddec88d":"<strong>Ảnh chụp màn hình phần Bắt đầu</strong> cho thấy bố cục mới.","changelog.8f6fb4eb7f42":"Bảo mật","changelog.32e5a43f5672":"<strong>MixSir có một tuyến gây tác động tại bàn làm việc</strong>: phím Tạo của điện thoại. Nó cần token của lần ghép nối như mọi tuyến khác, và khi MIDI Master chưa có cổng thì nó bị từ chối như một tuyến không tồn tại.","changelog.79508d88a5b7":"<span class=\"release__meta\"><span class=\"release__ver\">v0.16.0</span><time class=\"release__date\" datetime=\"2026-11-09\">2026-11-09</time></span>","changelog.83d578f4962d":"<strong>Bản mix của bạn trên điện thoại, một diện mạo mới, và mười thiết bị mới — chưa có bản tải xuống.</strong> Gửi bản mix và từng phần đến một điện thoại trong mạng Wi-Fi của bạn qua một mã QR, để mix chúng ngay tại đó và lưu chúng vào điện thoại thành tệp. Mọi bảng đều được bố trí lại, mỗi bảng có một phím chính, còn phần còn lại là các biểu tượng nhỏ, danh sách thả xuống và công tắc. Bản phối có thêm tính năng vẽ lặp pattern, một thanh thu phóng phía trên dòng thời gian, một phím cho mỗi công cụ, nhiều bản phối trong một dự án và một bộ phát clip với các cảnh; piano roll có thêm các công cụ tô, tắt tiếng và cắt lát, các nốt trượt và lướt, và một vùng chọn thời gian riêng. Sân khấu chơi nhiều phần cùng lúc, với đôi tay tránh bắt chéo. Mười thiết bị đến trong hai đợt, từ một tiếng kick tự khoét chỗ cho mình trong bass đến một cơn bão vẽ trên bản đồ. Oscillate Retro Record giữ vài phút gần nhất của những gì bạn chơi, để một take bạn chưa hề bấm ghi vẫn có thể được lưu, và Tìm âm tương tự xếp hạng các tệp giống một âm thanh trong các thư mục của bạn. Một bản phát hành này khép lại bốn bậc của chiếc thang, từ 0.13.0 đến 0.16.0, dưới một tag; 0.13.0, 0.14.0 và 0.15.0 không có tag riêng.","changelog.98037fc94f72":"<strong>MixSir: bản mix của bạn trên điện thoại.</strong> Trong bảng Phòng, Điện thoại ▸ <em>Gửi đến điện thoại của tôi</em> kết xuất bản mix và từng track có clip, kể cả các plugin của bạn, rồi hiện một mã QR khi đã <em>Sẵn sàng trên mạng của bạn</em>. Quét mã bằng một điện thoại trong cùng mạng Wi-Fi và bản mix sẽ mở trong trình duyệt của nó, không cần cài gì. Mọi phần được tải lên điện thoại ngay khi trang mở ra, nên nó vẫn phát khi tắt mạng chừng nào trang còn mở. Bàn trộn của điện thoại có một dải kênh cho bản mix và cho từng phần, với gain, pan, tắt tiếng và solo (Phát sẽ phát bản mix; chạm vào một phần, hoặc tắt tiếng bản mix, và các phần sẽ phát thay vào đó, theo cách bạn cân chỉnh chúng, không bao giờ bị bản mix phát chồng lên); bất kỳ phần nào cũng lưu được vào điện thoại dưới dạng WAV với gain và pan của nó, hoặc dưới dạng MP3 192 kbps tải về từ máy tính. <em>Nghe tại bàn làm việc</em> phát bản mix, truyền trực tuyến bằng Opus, và không lưu gì. Điện thoại nghe bài hát đúng như lúc bạn nhấn gửi: một chỉnh sửa sau đó cần gửi lại lần nữa. Bài hát dài tối đa mười phút, với tối đa 127 track có nội dung. <em>Dừng</em>, ghép nối lại, đóng cửa sổ chính hoặc thoát ứng dụng sẽ kết thúc việc chia sẻ.","changelog.0d29b6c8fb39":"<strong>Diện mạo mới trên mọi bảng.</strong> Mọi bảng và cửa sổ đều được bố trí lại theo cùng một phong cách: than chì mờ, các nút điều khiển đặt trong những hốc lõm, nhãn khắc chìm, các chấm sáng và dải hiển thị cho các con số. Mỗi bảng giữ hành động chính duy nhất của nó dưới dạng một phím được render (trình chỉnh sửa không giữ phím nào, để nhường chỗ cho piano roll); mọi thứ khác là một biểu tượng nhỏ có chú giải nêu tên nó và phím tắt của nó, một danh sách thả xuống ở nơi chọn một trong nhiều mục (có ô đánh dấu ở nơi chọn được nhiều mục), một công tắc phân đoạn, hoặc một nút bật tắt màu xám khi tắt, trắng khi con trỏ ở trên và xanh lá khi bật. Núm xoay, fader và các làn tự động hoá vẫn như cũ, và mọi chữ đều có đủ mười tám ngôn ngữ, viết từ phải sang trái trong tiếng Ả Rập.","changelog.5260ed9a395d":"<strong>Kiểm tra cuối, bố trí lại.</strong> Các tab của nó là Bản master, Loa, Bậc thang độ to và Kiểm tra quy chuẩn, Bản master đứng đầu. Các nơi phát hành nằm trong một danh sách thả xuống, mỗi nơi một ô đánh dấu (và <em>Tất cả</em>), mỗi nơi có độ to và mức trần ngay bên cạnh, và bảng chỉ hiện những hàng bạn đã đánh dấu. <em>Nghe như</em> là một danh sách thả xuống với Phẳng đứng đầu, chuyển vẫn không có tiếng lách cách, kèm một nút bật tắt A/B so với phẳng (A). <strong>Xuất các bản master</strong> là phím duy nhất của cửa sổ, và khi chưa đánh dấu gì, nó nhắc bạn đánh dấu một nơi phát hành.","changelog.cf2a1447c43c":"<strong>Piano roll có thêm chỗ.</strong> Thanh công cụ của trình chỉnh sửa giờ là một hàng biểu tượng thay vì ba hàng phím, một clip mở ra với các hàng cao 18 px (trước là 14), và các làn velocity, xác suất, CC, tự động hoá và take nằm dưới một thanh chia mà bạn kéo, được ghi nhớ trên máy tính này. Cửa sổ Trình chỉnh sửa lần đầu mở ở kích thước 1360 × 928. Trình chỉnh sửa của Giá pattern cũng là piano roll đó và cũng có thêm chỗ như vậy.","changelog.4f61c7339338":"<strong>Vẽ, chọn và xóa mà không cần đổi công cụ.</strong> Dù đang dùng công cụ nào, nhấp chuột phải hay kéo chuột phải cũng xóa những gì nó đi qua, và Ctrl+kéo vẽ một khung, Shift để thêm vào. Một cú nhấp vào chỗ trống trên lưới vẽ một nốt dài bằng bước bắt dính (khi đang có nốt được chọn, nó bỏ chọn thay vào đó, trừ khi dùng Vẽ, công cụ luôn vẽ). Kéo một nốt sẽ di chuyển nó, còn các mép của nốt, được đánh dấu <code>[</code> và <code>]</code> dưới con trỏ, kéo dài và rút ngắn nó; với Xoá, Tắt tiếng và Cắt lát, nhấn vào một nốt sẽ làm việc của công cụ đó trừ khi giữ Ctrl. Công cụ, một trong Chọn, Vẽ, Tô, Xoá, Tắt tiếng và Cắt lát, quyết định một lần kéo thường trên chỗ trống của lưới sẽ làm gì. Trong lúc kéo một nốt, các thanh velocity, xác suất và độ lệch của nó cũng di chuyển theo.","changelog.c016b8f11128":"<strong>Lưới hiện bước bắt dính.</strong> Piano roll vẽ một vạch ở mỗi bước bắt dính cách nhau từ 6 px trở lên, chùm ba được vẽ thành chùm ba, các ô nhịp xen kẽ được tô bóng (hoặc các phách xen kẽ, khi phóng to). Các ô nhịp của nó theo đúng số chỉ nhịp của bài hát, nên một ô nhịp 3/4 có ba phách và một ô nhịp 7/8 có bảy nốt móc đơn.","changelog.6de419fe1b5c":"<strong>Bảng Bài học, bố trí lại.</strong> Một danh sách thả xuống các khóa học và một dải gồm mười lăm khóa, mỗi khóa có một đèn tiến độ mười đoạn, số Ngày bạn đã đạt và, với khóa chưa bắt đầu, mốc mà nó bắt đầu sau đó; rồi các Ngày của khóa đang mở dọc theo một đường, nhóm theo tuần dưới các phần của khóa. Mỗi Ngày được phân biệt bằng hình dạng lẫn màu sắc (đã qua, nơi bạn đang ở, ôn tập, điểm kiểm tra, chưa tới), các phím mũi tên di chuyển dọc theo đường đó, và <em>Tiếp tục</em> là phím duy nhất của bảng.","changelog.ad7c3a66767e":"<strong>Cài đặt xếp dọc bên cạnh, và các danh sách của trình duyệt tệp dùng được bằng bàn phím.</strong> Mười ba mục của Cài đặt xếp dọc theo cạnh bên. Trong trình duyệt tệp, danh sách nhạc cụ và Âm thanh của tôi nhận ← và → để đi giữa các thao tác của một hàng, cùng ↑ và ↓ để đi qua và phát (trên tên một nhạc cụ, ← và → vẫn phát nhạc cụ đó ngược và xuôi), cùng Home, End, Ctrl+Home và Ctrl+End; mỗi danh sách là một điểm dừng tab. Bộ lọc họ nhạc cụ và bộ lọc phần là các danh sách thả xuống có ô đánh dấu.","changelog.143667e7f56b":"<strong>Sân khấu chơi nhiều phần cùng lúc.</strong> <em>Theo dõi</em> giờ là một danh sách thả xuống các track MIDI của dự án, mỗi track một ô đánh dấu, mặc định <em>Tất cả</em> được đánh dấu, do track bạn chọn dẫn dắt. Trên đàn piano, tối đa bốn phần chơi cùng nhau, mỗi phần được nhận ra qua tên track của nó (giai điệu, hợp âm, bass, giai điệu đối) hoặc nếu không thì qua vị trí của nó: bass và hợp âm nghiêng về tay trái, giai điệu và giai điệu đối về tay phải. Một cây guitar chơi một phần duy nhất đặt ở <em>Chơi</em> và một cây bass chơi phần bass, còn track trống không bao giờ tham gia ban nhạc. Những gì được đánh dấu chỉ kéo dài trong phiên làm việc.","changelog.eb52194f9ce6":"<strong>Đôi tay không bắt chéo.</strong> Giờ hai tay trên đàn piano chỉ bắt chéo khi không có cách nào không bắt chéo chơi được đoạn nhạc, và một tay không có gì để chơi sẽ nghỉ ở phía của mình so với tay kia.","changelog.02db47470aef":"<strong>Vẽ lặp pattern vào bản phối.</strong> Bộ chọn bên cạnh các track liệt kê các pattern của Giá pattern, các pattern MIDI và các clip âm thanh, mục hiện tại được làm sáng; nhấn vào một mục sẽ chọn nó và chọn luôn công cụ vẽ lặp. Một cú nhấp vào một làn trống thả nó xuống theo lưới, một lần kéo vẽ các bản sao nối đuôi nhau vòng qua các clip đã có ở đó, và nhấp chuột phải hay kéo chuột phải sẽ gỡ chúng; mỗi nét vẽ là một bước hoàn tác. Các bản sao vẫn liên kết với pattern của chúng, như mọi pattern đã đặt xưa nay vẫn vậy. Nhấn vào một clip bằng con trỏ, công cụ vẽ hoặc vẽ lặp sẽ biến pattern của nó thành pattern hiện tại, và bộ chọn lọc theo loại, chỉ hiện những mục chưa dùng, sắp xếp, và phát mục bạn đang đứng bằng <em>Nghe thử</em>.","changelog.e25983ec7ed8":"<strong>Thanh thu phóng phía trên bản phối.</strong> Thanh cuộn chuyển lên phía trên thước: kéo con chạy của nó để cuộn, kéo một trong hai đầu để thu phóng quanh đầu còn lại, và nhấp đúp vào nó để vừa cả bài hát; khi thanh đang có tiêu điểm, các phím mũi tên để cuộn và Ctrl+mũi tên để thu phóng. Dưới con chạy là một hình nhỏ của cả bài hát, clip của mỗi track mang màu của track đó. Các phím thu phóng và Ctrl+con lăn chuột cũng di chuyển nó. Con lăn chuột trên thanh phóng to và thu nhỏ, còn Shift+con lăn chuột thì cuộn nó.","changelog.037c5be5d7bc":"<strong>Một phím cho mỗi công cụ.</strong> Trong bản phối, <strong>P</strong> để vẽ, <strong>B</strong> để vẽ lặp, <strong>D</strong> để xóa, <strong>T</strong> để tắt tiếng, <strong>S</strong> để trượt nội dung, <strong>C</strong> để cắt bằng lưỡi dao, <strong>V</strong> để chọn và <strong>Y</strong> để nghe thử: đúng những chữ cái mà một nhà sản xuất nhạc vẫn quen dùng. Chúng chỉ có tác dụng khi bản phối đang có tiêu điểm, nên ở chỗ khác bàn phím máy tính vẫn giữ các nốt của nó và trình chỉnh sửa vẫn giữ các phím riêng. Ctrl+C và Ctrl+V sao chép các clip đã chọn và dán chúng tại đầu phát, còn Alt+← và Alt+→ đến điểm đánh dấu trước và sau. Phím nào cũng đổi được trong Cài đặt ▸ Phím tắt.","changelog.169c9a143cc7":"<strong>Công cụ mới trên bản phối.</strong> Công cụ tắt tiếng tắt hoặc bật tiếng mọi clip mà một nét đi qua; công cụ trượt nội dung trượt phần phát bên trong một clip, và ở một mép thì dời mép đó trong khi phần phát bên trong trượt theo, các clip khác vẫn ở nguyên chỗ; công cụ nghe thử phát riêng một clip được nhấn qua bộ nghe thử, không bao giờ qua transport. Giữ Alt và kéo mép một clip âm thanh sẽ kéo giãn nó mà vẫn giữ cao độ, từ một phần tư tới gấp bốn lần độ dài (trừ clip bị đảo ngược hoặc đang lặp). <em>Tên và màu…</em> trên menu clip đổi tên và đổi màu một clip. ⚠ Một clip được nghe thử sẽ vang mà không có các hiệu ứng của track, và một clip đã kéo giãn thì vang ở tốc độ gốc của tệp.","changelog.25abbe4e8d33":"<strong>Menu Sắp xếp, đầy đủ hơn.</strong> Cắt ở mỗi vạch lưới, tại các điểm tấn công của âm thanh đã chọn hoặc tại chính các điểm cue và vùng trong tệp của nó; gộp các clip pattern đã chọn của một track thành một pattern; nhóm các clip để chúng di chuyển, tắt tiếng và bị xóa như một khối, hoặc bỏ nhóm; chọn mọi bản sao của một clip, các clip đã tắt tiếng, chồng lên nhau hoặc xếp chồng, hoặc đảo vùng chọn; sao chép và dán; tắt và bật tiếng vùng chọn; căn điểm bắt đầu theo lưới; chèn hoặc xóa khoảng thời gian của vòng lặp; đặt mọi track cỡ nhỏ, vừa hoặc lớn; nhân bản một track cùng các thiết bị, tự động hoá và clip của nó, đặt tên nó theo clip đầu tiên, hoặc đưa nó lên hay xuống; thu phóng vào vùng chọn. Mỗi mục làm thay đổi bài hát là một bước hoàn tác; chọn, sao chép và thu phóng thì không. Bám lưới có thêm 1/32, một phần sáu bước và <em>Mép clip</em>. ⚠ Xóa một khoảng thời gian sẽ để nguyên chỗ cũ một clip vắt qua mép của khoảng đó.","changelog.c27e0439c34e":"<strong>Điểm đánh dấu biết làm việc.</strong> Nhấp chuột phải vào một điểm đánh dấu trên thước và chọn việc nó làm: bài hát bắt đầu từ đó khi bạn phát từ đầu (điểm đánh dấu như vậy nằm sớm nhất sẽ được dùng), quay lại đó từ điểm đánh dấu kế tiếp, nhảy tới điểm đánh dấu kế tiếp, hoặc dừng ở đó. Nhấp chuột phải trên thước cũng đổi số chỉ nhịp từ bất kỳ ô nhịp nào, hoặc bỏ một thay đổi nhịp.","changelog.40f1052de714":"<strong>Nhiều bản phối trong một dự án.</strong> Một danh sách thả xuống trên thanh công cụ của bản phối chuyển qua lại giữa chúng, và menu của nó tạo bản mới, sao chép, đổi tên, xóa, hoặc gộp một bản khác vào bản đang hiện trên màn hình. Mỗi bản giữ clip, điểm đánh dấu và các bước hoàn tác riêng trên các track, pattern và bàn trộn mà chúng dùng chung, và phát, bounce và xuất đều phát bản đang hiện trên màn hình. Chuyển sang một bản, tạo một bản và sao chép một bản không bao giờ là bước hoàn tác. Một dự án từ trước mở ra thành một bản phối, đúng như cũ. ⚠ Trong một phòng, một thay đổi bản phối phải gửi hơn 1,024 thay đổi cùng lúc (chuyển, gộp, tạo mới, sao chép hay xóa, khoảng 500 clip) sẽ bị từ chối, kèm một câu nói rõ điều đó; khi làm một mình, kích thước nào cũng được.","changelog.327140a0572b":"<strong>Bộ phát clip và các cảnh.</strong> Phím của bộ phát trên thanh công cụ của bản phối hiện một lưới phía trên dòng thời gian, mỗi track âm thanh và MIDI một cột và mỗi cảnh một hàng. Một ô phát clip của nó, lặp lại, vào ô nhịp kế tiếp, phách kế tiếp hoặc ngay lập tức (khi bài hát đang phát thì vào sau một phách), mỗi track một clip, và phát khi bài hát đang dừng sẽ cho bài hát chạy; một cảnh phát cả hàng của nó; dừng một track, dừng mọi track, hoặc <em>Quay về bản phối</em>. Ô đang phát hiện <em>Đang phát</em> và ô đang chờ hiện <em>Đang chờ</em>, và các phím mũi tên cùng Enter điều khiển được nó. Một cảnh mới lấy các clip dưới đầu phát, và mỗi cảnh có thể chuyển tiếp sau 1 đến 64 ô nhịp sang cảnh kế tiếp, cảnh trước hoặc cảnh đầu tiên, một cảnh khác ngẫu nhiên, hoặc dừng tất cả. Một lần phát không bao giờ là một bước hoàn tác; <em>Ghi lại màn trình diễn</em> ghi những gì bạn đã phát vào bản phối ở đúng chỗ nó đã phát, thay cho những gì các track đó có ở đó, thành một bước hoàn tác, và giữ nguyên một track bị khóa.","changelog.228b76751682":"<strong>Công cụ mới của piano roll.</strong> <strong>Tô</strong> đặt một nốt vào mỗi bước bắt dính mà lần kéo đi qua nếu ở đó chưa có nốt, <strong>Tắt tiếng</strong> tắt hoặc bật tiếng các nốt (vẽ rỗng), và <strong>Cắt lát</strong> cắt mọi nốt mà lần kéo đi qua. Menu <strong>Con dấu</strong> vẽ một hợp âm với mỗi cú nhấp; mười sáu màu nốt, mỗi nốt được ghi tên ở chỗ đủ vừa, và bàn phím dọc bên trái chọn mọi nốt cùng cao độ. Menu <strong>Sửa</strong> cắt, sao chép và dán (Ctrl+X, C và V trong piano roll), xoay các nốt một bước, đảo lựa chọn và chọn các nốt đã tắt tiếng hoặc lệch phách; <strong>Công cụ khác</strong> đặt độ dài về 25, 50, 75 hoặc 150 %, làm mỗi nốt dài một bước, đưa điểm kết về lưới, lượng tử hóa một nửa hoặc có swing, giới hạn các nốt trong hai quãng tám, và co giãn lực nhấn. Một menu <strong>Thu phóng</strong> vừa mọi nốt hoặc các nốt đã chọn, đầu phát chạy qua piano roll, và <em>Thêm làn</em> có thêm cân bằng và cao độ tinh, những thứ mà các nhạc cụ phát sample của chính Oscillate nhận còn các plugin của bạn thì không.","changelog.699aad0e2319":"<strong>Nốt biết trượt, lướt và buông.</strong> Một làn lực nhả cho mỗi nốt tốc độ nó được thả ra, và One-Shot Sampler, Multisampler, Drum Machine, Grain Layers và Siren ngân dài hơn khi nhả chậm và ngắn hơn khi nhả nhanh; các plugin của bạn cũng được báo giá trị này. Một nốt trượt không đánh tiếng nào mà uốn track tới cao độ của chính nó; một nốt lướt vào được đánh từ nốt trước đó rồi lướt về đích trong một nốt móc kép, hoặc trong độ dài của chính nó nếu độ dài đó ngắn hơn. Các làn Mod X và Mod Y gửi bánh xe điều biến và áp lực riêng của mỗi nốt vào lúc nốt được đánh. Nhấp đúp vào một nốt để xem thuộc tính của nó: mọi con số của các nốt đã chọn, gõ vào được, hiện <em>Khác nhau</em> ở chỗ chúng khác nhau. ⚠ Một nốt trượt di chuyển bánh xe cao độ của track, nên mọi nốt đang vang trên track đó đều bị uốn theo, và một plugin chỉ theo được chính xác trong tầm uốn của riêng nó. Grain Layers nhận Mod X và Mod Y theo từng nốt còn Siren nhận Mod Y; mọi nhạc cụ khác và các plugin của bạn nhận chúng cho cả track. Chỉ năm nhạc cụ đó nhận tốc độ nhả: các nhạc cụ dựng trên engine synth dùng chung chưa nhận.","changelog.9fc979239544":"<strong>Thời gian trong piano roll.</strong> Piano roll có thước riêng: Alt+kéo trên đó chọn một khoảng thời gian, và menu Sửa chèn khoảng trống theo khoảng đó (pattern dài ra), cắt rồi chèn, xóa khoảng đó (pattern ngắn lại, không bao giờ ngắn quá nốt cuối của nó), cắt theo khoảng đó, hoặc bỏ chọn nó. Kéo trên thước để nghe các nốt, bật <em>Theo đầu phát</em>, và xem các điểm đánh dấu của bài hát trong piano roll (nhấp đúp lên thước để đặt một điểm). Các nốt có thể được nhóm để di chuyển và bị xóa như một khối, bắt dính có thêm các bước mịn hơn, mép nốt và điểm đánh dấu, và một làn CC có thể ghi một LFO (sin, tam giác, vuông hoặc răng cưa, từ một ô nhịp đến một nốt móc kép, 25 đến 100 %) thành một bước hoàn tác. ⚠ Làn CC vẫn được vẽ và lưu nhưng không được phát: chưa có nhạc cụ nào đọc nó, nên không nghe thấy LFO.","changelog.5af822d7568e":"<strong>Oscillate Kick Carve:</strong> bass được hạ xuống chỉ trong lát dải trầm mà kick đang vang, và chỉ trong lúc kick còn ngân ở đó; các họa âm của bass phía trên không bao giờ bị động tới. Chọn kick ở <em>Sidechain từ</em>. <em>Spectrum</em> chia dải trầm thành 24 dải, <em>Bell</em> bám theo chính cao độ của kick bằng một nhát cắt; Độ sâu tới 24 dB, Tinh chỉnh, Độ rộng Q, Bám theo, Hold, dải tần, Chỉ kênh giữa, và tối đa 5 ms lookahead, độ trễ của nó được bù trên toàn bản mix. Ở Độ sâu bằng không, bass đi qua nguyên vẹn từng bit, chỉ muộn hơn đúng bằng phần lookahead đó. Tám preset.","changelog.6e9e3eb32420":"<strong>Oscillate Bass Unison:</strong> một tiếng saw hoặc 808 biến thành một tiếng reese chuyển động, hai đến tám giọng lệch tông tới 35 cent và xoay qua các tầng all-pass, trải rộng, trong khi mọi thứ dưới Crossover (40–300 Hz) được giữ mono và để nguyên, nên loa sub mono của câu lạc bộ và chiếc loa duy nhất của điện thoại đều nghe được trọn vẹn. Độ rộng tới 150 %, Độ nặng, Mix; tám preset, từ Classic Reese đến Extreme Phase. Nó báo độ trễ xử lý khoảng 15 ms.","changelog.2f0e26ac5223":"<strong>Ghép kick và bass, trong trình duyệt tệp.</strong> Trong một thư mục âm thanh, chọn một tiếng kick rồi nhấn <em>Xếp hạng các tiếng bass</em>: mọi tệp WAV khác trong thư mục được chấm điểm trên 100 theo quãng, độ gồ ghề, độ chồng lấn dải trầm và độ khớp tắt dần, kèm số cent cần chỉnh tông để kick nằm trên nốt gốc, quãng năm hoặc quãng tám của bass. <em>Nghe</em> phát một ô nhịp gồm bốn tiếng kick đã chỉnh tông, đè lên bass ở 120 BPM. Đây là phép đo, không có mô hình, và không có gì được giữ lại. ⚠ Chỉ tệp WAV, bốn giây đầu của mỗi tệp, và tối đa 2,000 tiếng bass.","changelog.2bbf8a9cbdb7":"<strong>Oscillate Groove, và bốn mươi feel:</strong> một thiết bị nốt đưa tiếng trống được chơi vào nó theo một feel có tên, từ <em>Grid Tight</em> và <em>Laid-Back Backbeat</em> đến <em>Loose Drummer</em>. Pha hai feel, đặt Độ sâu (tới 200 %) và độ lệch cùng độ sâu riêng của từng làn, nội suy hoặc bám nấc. Khi đứng đầu một track, nó đọc trước các nốt của clip, nên một nốt được đưa sớm không cần thêm độ trễ; một phím chơi trực tiếp, hoặc một Groove đứng sau trong chuỗi, phải chờ theo Lookahead của nó. Lưu các feel của riêng bạn và gọi lại chúng, và in clip đang mở trong trình chỉnh sửa theo một feel, thành một clip MIDI mới bên cạnh nó. <strong>Oscillate Groove Kit</strong> là nhạc cụ đồng hành của nó, mười hai tiếng trống tổng hợp chơi các mẫu nhịp của mình theo một feel. Bốn mươi feel được viết ngay tại đây, mọi con số đều bằng tay; không feel nào được lấy từ đâu cả.","changelog.92a1c80a9eba":"<strong>Oscillate Chord Trigger:</strong> một phím chơi cả một hợp âm kèm bass của nó, được dẫn giọng để di chuyển ít nhất có thể. Ba vùng (bass, hợp âm và phím điều khiển), 27 hình hợp âm và tám hình của riêng bạn dựng trên một lưới ba quãng tám, thể đảo, latch, quạt hợp âm tới 60 ms, mười hai preset. Các pad của nó lớn (64 px, hoặc 96 với <em>Mục tiêu lớn hơn</em>), hàng phím số chơi các hợp âm, và có thể chơi nó bằng quét công tắc, với một hoặc hai công tắc (một phím, hoặc một nốt MIDI hay bộ điều khiển mà bạn dạy cho nó). ⚠ Các pad chơi track đã bật sẵn sàng thu, và thiết lập quét chỉ kéo dài trong phiên làm việc.","changelog.53a6da7d9287":"<strong>Oscillate Glide:</strong> nốt trượt cho các dòng 808. Bảy quy tắc chọn những nốt nào trượt (mọi nốt, các nốt lệch phách, cứ vài nốt một lần, các nốt ngắn, các bước nhảy quãng, các nốt được đánh dấu trên làn của nó, hoặc không nốt nào), trong một Thời gian trượt từ 5 ms đến 2 s hoặc đồng bộ theo nhịp, theo một trong sáu đường cong, với một làn Trượt, Giữ và Bỏ qua dài tới bốn ô nhịp vẽ trên mặt thiết bị. Nó uốn theo bước 14 bit, báo cho các plugin của bạn tầm uốn của nó (các nhạc cụ của chính Oscillate không cần), và kẹp lại hoặc tách một lần trượt vượt quá tầm đó. Phần bass của Chord Trigger cấp nốt cho nó. Mười hai preset.","changelog.f839647ae043":"<strong>Oscillate Siren:</strong> còi hú cảnh sát, còi báo động phòng không, còi hai tông và còi dub trên một rô-to quay, với độ quay chậm dần từ 0.2 đến 12 giây tạo nên tiếng lên và tiếng xuống; mười hai mẫu rô-to, một đường bao cao độ, glide, một LFO từ 0.01 đến 40 Hz, Mono, Legato, Poly 8 và Latch, một mẫu báo động từ 16 đến 32 bước, hai đường bao, ba LFO, một chuỗi 16 bước và một ma trận mười hai ô. Sáu mươi hai preset: còi hú, dub, stab rave, zap và lò xo. Các bộ dao động của nó mặc định chạy ở 4×, ở đó aliasing thấp hơn −80 dB. ⚠ Ở 1× thì cao hơn nhiều.","changelog.3a01cdff8bdc":"<strong>Oscillate Dispersion Delay:</strong> tối đa 512 tầng all-pass làm nhòe một tiếng đánh trải khắp các tần số của nó thành một tiếng zap laser (theo một đường thẳng, theo từng quãng tám hoặc hình chuông, tần thấp đến muộn hoặc tần cao đến muộn), với feedback được giới hạn bên trong vòng lặp của nó và bên phải đặt lệch so với bên trái; sau đó là một tiếng vọng băng từ từ 1 ms đến 2 s với wow, flutter, làm tối tiếng, bão hòa và head bump. Mặt thiết bị vẽ độ trễ mà các tầng thực sự tạo ra, theo từng tần số, và trường stereo. Nó không thêm độ trễ xử lý nào.","changelog.ff6ae697f032":"<strong>Oscillate Grain Layers:</strong> tối đa tám sample của bạn xếp chồng thành các lớp đá và được đọc bởi một mũi khoan mà độ sâu của nó quyết định thứ gì cất tiếng; Xói mòn bào mòn cột, Nếp uốn uốn cong nó và Đứt gãy làm nó nứt vỡ. Mười sáu giọng, bốn LFO, hai đường bao và một ma trận mười sáu ô, có gieo hạt giống để mỗi lần kết xuất đều ra giống hệt nhau, và mười hai preset gốc có các lớp được tổng hợp bằng mã. Đặt một tệp, hoặc tệp đang được nghe thử trong trình duyệt tệp, lên một lớp; <em>Giữ âm thanh của lớp này bên trong dự án</em> mang nó theo trong tệp dự án, và <em>Tìm lại tệp này trong các thư mục của bạn</em> tìm một tệp đã bị di chuyển. Lượng bộ nhớ các lớp của nó chiếm được hiển thị, tối đa 1 GiB. Mặt cắt của nó được vẽ trực tiếp trên Windows, và đứng yên khi bật giảm chuyển động, cũng như trên macOS và Linux. Mod X của một nốt di chuyển mũi khoan còn Mod Y của nó đi tới nơi mà <em>Áp lực cho</em> chỉ định. ⚠ Giới hạn grain của nó là 16 đến 64 (mặc định 48), thấp hơn dự kiến ban đầu, để tầng mịn nhất của nó vẫn nằm trong phần được chia cho nó trên luồng âm thanh.","changelog.d13b6a8a420c":"<strong>Oscillate Storm:</strong> mưa, sấm và gió được tạo từ chính vật lý của chúng, nên không có gì lặp lại và không dùng sample nào. Mưa rơi trên tám bề mặt (mái tôn, cửa sổ, ô, sàn gỗ, lá cây, bê tông, vũng nước, ao), và tiếng sấm tới muộn tùy theo tia sét ở xa đến đâu. Trên bản đồ cơn bão, bạn đặt người nghe, tối đa tám vùng mưa và tối đa bốn tia sét do bạn vẽ. Hai macro, Mưa và Bão. Một phím ở tại hoặc trên Chia tách điều khiển thời tiết và thả một giọt mưa ở cao độ của phím đó; một phím thấp hơn đánh xuống một tia sét. Bánh xe điều biến mang cơn bão tới, CC 11 mang mưa, CC 74 mang gió, còn bánh xe cao độ đưa người nghe lại gần hoặc ra xa. Sáu mươi hai preset, ba mức chất lượng (Draft, Normal, Ultra), và <em>Kết xuất ba lớp</em> ghi mưa, sấm và gió thành ba tệp WAV cộng lại bằng đúng track. Chỉ có stereo. Giờ đây <strong>TÁM MƯƠI BA TRONG TÁM MƯƠI CHÍN ĐÃ ĐƯỢC DỰNG</strong>, với ba mươi hai hiệu ứng cốt lõi và toàn bộ mười chín thiết bị nốt.","changelog.d26614725630":"<strong>Oscillate Retro Record: vài phút gần nhất, lúc nào cũng có.</strong> Transport ▸ Oscillate Retro Record… giữ đầu vào âm thanh của bạn (một đầu vào hoặc một cặp stereo) và bàn phím MIDI của bạn trong bộ nhớ: từ 30 giây đến một giờ (mặc định năm phút), ở 24 bit, 16 bit hoặc dấu phẩy động 32 bit, lượng bộ nhớ mỗi độ dài chiếm được hiện ra trước khi bạn chọn; <em>Luôn luôn</em>, <em>Khi đang phát</em> hoặc <em>Khi track sẵn sàng ghi</em>. Một dạng sóng trực tiếp hiện những gì đang giữ, mới nhất ở bên phải; kéo ngang qua nó để chọn. <em>Lưu</em>, hoặc Ctrl+Shift+R trong bất kỳ cửa sổ Oscillate nào, đặt take thành một clip, phần âm thanh lên track âm thanh đã bật sẵn sàng thu và các nốt lên track MIDI đã bật sẵn sàng thu (hoặc một track mới), tại ô nhịp bạn đã chơi, hoặc tại đầu phát nếu bài hát đang dừng; hoặc thành một tệp WAV đóng dấu ngày và giờ, kèm một tệp MIDI bên cạnh. Một lần bấm lưu mọi thứ đang giữ, hoặc chỉ đoạn cuối cùng bạn chọn; <em>Bỏ qua khoảng lặng</em> rút ngắn các đoạn lặng dài, với ngưỡng được <em>Đo căn phòng</em> đặt cao hơn mức nền của căn phòng 9 dB. Một công tắc chân MIDI (pedal sustain hoặc một công tắc mà nó học được, tắt cho đến khi bạn chọn) cũng lưu được, và Cài đặt ▸ Ghi âm có thêm một phím tắt toàn cục và một biểu tượng khay, cả hai đều tắt cho đến khi bạn bật.","changelog.3faf581791d2":"<strong>Retro Record hỏi trước, và luôn cho thấy nó đang chạy.</strong> Nó không giữ gì cho đến khi bạn đồng ý, một lần, và chỉ bắt đầu khi bạn nhấn <em>Thu giữ</em>. Trong lúc nó đang thu giữ hoặc đang giữ bất cứ thứ gì, một đèn kèm chữ trạng thái, thời lượng đang giữ và lượng bộ nhớ nó chiếm luôn nằm trên cùng trong mọi cửa sổ Oscillate, và không gì ẩn được nó. <em>Xóa tất cả</em> xóa ngay những gì nó đang giữ. Bản bounce hay bản xuất không bao giờ đi vào nó, và nếu đầu vào im lặng trong một giây rưỡi, nó sẽ cho biết Windows, macOS hay Linux có thể đang chặn micrô như thế nào.","changelog.5d6f51c7a959":"<strong>Tìm âm tương tự, trong trình duyệt tệp.</strong> Chọn một âm thanh hoặc một vòng MIDI trong thư mục bạn đang ở rồi nhấn <em>Tìm tương tự</em>: mọi tệp giống nó trong các thư mục của trình duyệt tệp và các gói trống đi kèm được chấm điểm trên 100, mỗi tệp kèm lý do bằng lời (cùng tệp, một bản lưu lại, đổi gain, cắt bớt, dịch cao độ, kéo giãn, âm sắc khác, cùng nhịp điệu). <em>Nghe</em> phát tham chiếu, tệp giống, hoặc cả hai cùng lúc đã căn khớp. Các thư mục được đọc ở chế độ nền khi bảng mở lần đầu trong một phiên, và chỉ những gì mới hoặc đã thay đổi mới được đọc lại. Đây là phép đo, không có mô hình. ⚠ Chỉ tệp WAV và MIDI; độ dịch cao độ quá ba nửa cung và độ kéo giãn quá 12 % thì không được hứa hẹn.","changelog.62790887f365":"<strong>Lưỡi dao giờ là C</strong>, thay cho B trước đây, phím giờ dùng để vẽ lặp; công cụ của nó là <em>Cắt</em>. Các chữ cái công cụ của bản phối chỉ có tác dụng khi bản phối đang có tiêu điểm: <strong>V</strong> và <strong>C</strong> không còn tác dụng từ bất kỳ chỗ nào khác, và <strong>P</strong> là bút chì của trình chỉnh sửa ở mọi nơi ngoài bản phối.","changelog.9d2ea7559799":"<strong>Trên macOS, lời nhắc cấp quyền micrô có nêu tên Retro Record</strong> trong số những gì có thể nghe đầu vào của bạn.","changelog.981dec5c13f5":"<strong>Máy chủ của MixSir chỉ chạy trong lúc bạn đang gửi đến điện thoại.</strong> Nó là một tiến trình riêng, <code>oscillate-mixsir</code>, được khởi động bởi <em>Gửi đến điện thoại của tôi</em> và kết thúc bởi <em>Dừng</em>, bởi việc ghép nối lại, hoặc khi đóng Oscillate. Nó lắng nghe trên cổng 7434 cho bất kỳ thiết bị nào kết nối được tới máy tính này. Địa chỉ trong mã QR mang một khóa gồm 32 byte ngẫu nhiên chỉ tạo cho riêng lần ghép nối đó: không có khóa, danh sách các phần, mọi tệp và luồng phát đều bị từ chối bằng cùng một câu trả lời không bao giờ nói lý do, và năm yêu cầu có khóa sai hoặc không có khóa sẽ kết thúc lần ghép nối. Nó không lấy gì từ điện thoại, không đọc tệp nào, và không ghi gì ra ổ đĩa. ⚠ Kết nối là HTTP thường, không được mã hóa: bất kỳ ai nhìn thấy mã, hoặc theo dõi lưu lượng trên mạng Wi-Fi của bạn, đều nghe được bài hát cho đến khi lần ghép nối kết thúc, nên hãy đối xử với nó như một mã phòng và gửi đến điện thoại trên một mạng bạn tin cậy.","changelog.0118b7065892":"<strong>Retro Record giữ những gì nó nghe trong bộ nhớ, không bao giờ trên ổ đĩa, cho đến khi bạn lưu.</strong> Không phần nào của nó bị gửi đi bất cứ đâu. Tệp thiết lập của nó, <code>retro.json</code>, chứa các lựa chọn của bạn và không bao giờ chứa âm thanh. <em>Xóa tất cả</em> ghi đè bằng số không những phút nó đang giữ và trả lại bộ nhớ. Phím tắt toàn cục đăng ký một phím với hệ điều hành của bạn, chỉ khi công tắc của nó đang bật; không phím nào khác bạn gõ bị đọc.","changelog.9f3a2f272e06":"<strong>Chỉ mục của Tìm âm tương tự lưu một âm thanh là gì, không bao giờ lưu chính âm thanh.</strong> Đó là một tệp trong thư mục dữ liệu của Oscillate: với mỗi âm thanh, đường dẫn đầy đủ, kích thước và ngày, mã băm của các byte và phần âm thanh, cùng các số đo thô về độ to và phổ tần; với một vòng lặp, nhịp điệu, nhịp độ và nốt thấp nhất của mỗi điểm khởi âm. Không có âm thanh nào được giữ trong đó, và nó được đọc lại như dữ liệu không đáng tin, mọi độ dài đều được kiểm tra trước khi cấp phát bất cứ thứ gì. Một lần tìm, một lần nghe thử và <em>đặt tệp đã nghe thử trong trình duyệt tệp lên lớp này</em> của Grain Layers chỉ mở những tệp nằm trong các thư mục bạn đã thêm.","changelog.915d977e99d5":"<strong>Giờ một dự án có thể mang theo âm thanh của một lớp, và được kiểm tra kỹ phần đó.</strong> Một lớp của Grain Layers được giữ <em>bên trong dự án</em> sẽ được ghi vào tệp dự án; khi mở một dự án như vậy, âm thanh đó được đọc từ chính tệp đó chứ không từ đâu khác, và một khối dữ liệu khai nhiều hơn những gì nó chứa sẽ bị từ chối trước khi cấp phát bất cứ thứ gì. Các bản phối và cảnh của một dự án tuân theo cùng giới hạn như các clip của nó.","changelog.1246fc93bca0":"Sửa lỗi","changelog.8cbf5609dedb":"<strong>Một nút điều khiển bị vô hiệu hoá không làm gì cả.</strong> Ở 0.12.0, một phím bị làm mờ vẫn có thể nhô lên, lún xuống và sáng lên dưới con trỏ. Giờ đây một nút điều khiển bị vô hiệu hoá không hiện trạng thái di chuột hay nhấn, và không việc nào nó lẽ ra làm được kích hoạt, ở bất cứ đâu trong ứng dụng.","changelog.2263c6fa5d22":"<strong>Cửa sổ bảng mở lại đúng kích thước bạn đã để.</strong> Thỉnh thoảng Bàn trộn trở lại đúng chỗ nhưng cao hơn 100 px; giờ các cửa sổ mở lại lần lượt từng cái, và cửa sổ nào lớn thêm sau khi đã được đặt sẽ được đưa về như cũ.","changelog.04b1306d704e":"<strong>Menu clip không còn bị cắt mất.</strong> Hiệu ứng quét lúc mở của một bảng để lại lớp mặt nạ sau khi bảng đã mở, việc này có thể cắt mất chính menu clip của bản phối.","changelog.29675e838f56":"<strong>Một giá trị hỏng không còn đặt lại mọi thiết lập xuất.</strong> Một thiết lập sai kiểu trong tệp đã lưu của Cài đặt ▸ Xuất từng đưa thư mục, định dạng, độ sâu bit và các thiết lập còn lại về mặc định; giờ chỉ riêng thiết lập đó trở về mặc định.","changelog.3a479cc9ddc2":"<strong>Mở một Ngày khác sẽ chuyển sang Hôm nay.</strong> Khi đã có một Ngày đang mở, mở một Ngày khác từ khóa học trước đây vẫn đứng yên tại chỗ.","changelog.a95437716e5e":"**Trong trình duyệt tệp, <em>Lên</em> không còn là một trong các tệp.** Nó từng nằm bên trong danh sách tệp, nên bàn phím và trình đọc màn hình coi nó là một tệp; giờ nó đứng tách riêng khỏi chúng.","changelog.ea34e6ae8231":"<span class=\"release__meta\"><span class=\"release__ver\">v0.12.0</span><time class=\"release__date\" datetime=\"2026-11-04\">2026-11-04</time></span>","changelog.329cfec3b9c7":"<strong>Bài học và những công cụ của riêng studio — chưa có bản tải xuống.</strong> Giờ mười lăm khóa học dạy ngay trong Oscillate, mỗi ngày một chút, trong một bảng Bài học riêng: sân khấu cho bạn thấy cách làm, rồi bài học lắng nghe khi bạn chơi, trên bàn phím MIDI hoặc qua đầu vào âm thanh của bạn, trong khi dự án của chính bạn chờ an toàn ở một bên. Bên cạnh đó là dời cao độ và kéo giãn giữ cao độ trên clip âm thanh, mọi thẻ hiệu ứng được vẽ trực tiếp, một bộ doubler và một bộ ducker, núm Hạt (granular) và một bộ nén trên mọi dải kênh của bàn trộn, một gợi ý trên mọi thẻ, và một cửa sổ Kiểm tra cuối tạo một bản master cho mỗi nơi phát hành và cho bạn nghe bản mix như điện thoại hay ô tô sẽ phát. Một bản phát hành này khép lại hai bậc của chiếc thang, 0.11.0 và 0.12.0.","changelog.ac2db52dddb9":"<strong>Bảng Bài học, từ Freally Handscore.</strong> Xem ▸ Bài học (Ctrl+8), hoặc phím hình mũ tốt nghiệp trên thanh tiêu đề, mở một cột riêng bên cạnh bản phối với mười lăm khóa học: Đàn piano, Đọc nhạc, Tiết tấu, Luyện tai, Nhạc lý cho nhà sản xuất, Sáng tác bài hát, Viết lời, Rap và flow, Phối khí bài hát, Trộn âm, Đánh trống bằng ngón tay, Bộ trống, Đàn guitar, Guitar cổ điển và Đàn bass. Mỗi khóa học là một bản đồ gồm các phần, các tuần và các Ngày, kèm thời gian bạn đã luyện tập, và <em>Tiếp tục</em> đưa bạn về đúng bước bạn đã dừng. Các tab của bảng là Khóa học, Hôm nay, Lịch sử và Bài kinh điển. Bản thân các bài học hiện được viết bằng tiếng Anh; mọi nút, nhãn và thông báo xung quanh chúng đều có đủ mười tám ngôn ngữ, viết từ phải sang trái trong tiếng Ả Rập.","changelog.37b4f7453a04":"<strong>Dự án của bạn được cất sang một bên khi bạn học.</strong> Một bài học chạy trong dự án riêng của nó, với các track thật trên các nhạc cụ của chính Oscillate, do transport phát và sân khấu theo dõi. Dự án của bạn, các thay đổi chưa lưu và lịch sử hoàn tác của nó được cất sang một bên nguyên vẹn, và một dải băng ngang bảng cho biết điều đó; <em>Quay lại dự án của tôi</em> đưa nó về đúng như cũ, và Mới, Mở, một phòng hay việc thoát ứng dụng cũng vậy. Bài học sẽ chờ trong lúc bạn chia sẻ một phòng.","changelog.953ff1f65d1e":"<strong>Hôm nay, trình phát của Ngày.</strong> Các bước của một Ngày được chơi trên sân khấu: xem đôi tay, rồi chơi các phím mà nó làm sáng trên bàn phím MIDI của bạn trong khi nó chờ bạn; <em>Theo nhịp</em> đếm vào một ô nhịp và chấm take của bạn từng ô nhịp một; <em>Chơi trọn bài</em> yêu cầu cả bản nhạc từ đầu đến cuối; các bài luyện tai và nhạc lý đặt câu hỏi, và bạn trả lời trên phím. Luyện một tay trong khi sân khấu chơi tay kia, lặp bất kỳ ô nhịp nào, và leo thang nhịp độ đến tốc độ của Ngày; ba lần đạt liên tiếp là qua Ngày, và những gì bạn đã học sẽ quay lại khi đến lúc ôn. Sân khấu làm sáng các phím, cần đàn guitar hoặc các pad trống mà bài học yêu cầu.","changelog.316226b27a80":"<strong>Cho xem.</strong> <em>Cho xem</em> chơi một bước trên sân khấu trước khi bạn thử, đôi tay ở gần, ở tốc độ một nửa, ba phần tư hoặc đầy đủ, lặp các ô nhịp bạn chọn, và không lắng nghe gì cả; <em>Quay lại bước</em> đưa bạn trở lại bước đó.","changelog.67a53511787c":"<strong>Đọc to.</strong> Bài học tự đọc cho bạn nghe bằng các giọng có sẵn trên máy tính của bạn, vì Oscillate không kèm giọng đọc nào, và làm sáng từng từ khi đọc tới. Thanh đọc có tua lại, phát và tạm dừng, dừng, tua nhanh, tốc độ từ 0.5× đến 2×, chọn giọng và đồng hồ đọc, và Space cùng Shift+← hoặc Shift+→ hoạt động khi bảng đang có tiêu điểm. Tính năng này tắt cho tới khi bạn bật, và được ghi nhớ; trên máy không cài giọng đọc nào, thanh đọc sẽ báo điều đó.","changelog.2de5fcb18e84":"<strong>Các khóa sáng tác mở công cụ của chính Oscillate.</strong> Sáng tác bài hát, Viết lời, Rap và flow, Phối khí bài hát và Trộn âm làm việc trong dự án của bài học: bài hát nằm trong bản phối với các đoạn là điểm đánh dấu, lời nằm trên Làn lời bài hát và lưới flow của nó, vòng lặp nằm trên bàn trộn của chính Oscillate, và sổ tay là một trang trong bảng Bài học. Các bài hát và vòng lặp khởi đầu đi kèm ứng dụng, được engine của Freally MIDI Master tạo một lần; không có gì được sinh ra trong lúc bạn học. Các mục tiêu của một bước trộn âm (đỉnh, độ to, đỉnh thực, độ to riêng của phần chính) được đo trên bản mix đã render, và <em>Đọc rap</em> của Rap và flow nghe một take rap qua đầu vào của bạn, không thu lại, và đo thời điểm từng âm tiết so với chỗ bạn đã đặt nó.","changelog.e562f651546c":"<strong>Bài học biết lắng nghe.</strong> Bật <em>Lắng nghe</em> của một khóa học và bài học sẽ nghe bạn qua đầu vào mà Oscillate dùng để thu, trên thiết bị âm thanh chọn trong Cài đặt ▸ Âm thanh, một đầu vào hoặc một cặp stereo, và chấm những gì nó nghe: các nốt và thời điểm của chúng, hợp âm, các nhát đánh trên bộ trống và các âm tiết rap, phân biệt với chính tiếng tích tắc của máy đếm nhịp. Một take được nghe theo cách này ghi rằng nó được <em>chấm bằng tai</em>. <em>Đầu vào…</em> trên thanh bài học hiện đầu vào, mức của nó, hợp âm nó nghe thấy, bộ chỉnh âm và phần hiệu chỉnh độ trễ, và một đèn sáng đúng trong lúc có thứ gì đó đang lắng nghe.","changelog.8065bd36868b":"<strong>Bộ chỉnh âm và hiệu chỉnh độ trễ.</strong> Bộ chỉnh âm hiện nốt bạn chơi và nó lệch bao nhiêu cent, so với A4 từ 415 đến 466 Hz, kèm dây buông gần nhất của guitar hoặc bass. Phần hiệu chỉnh phát tám tiếng click và lắng nghe chúng, vòng ngược qua một sợi cáp, từ loa vào micro, hoặc bằng tiếng vỗ tay theo, rồi giữ độ trễ đo được cho riêng đầu vào đó, để những gì bạn chơi rơi đúng chỗ bạn chơi; cho tới lúc đó, bài học dùng ước lượng của chính Oscillate.","changelog.8652ebf2415a":"<strong>Nghe lại.</strong> Công tắc <em>Nghe lại</em> trên thanh bài học cho bạn nghe chính mình trong lúc bài học lắng nghe, guitar hoặc bass qua Guitar Amp. Mặc định nó tắt, để micro không bị hú qua loa của bạn, và được ghi nhớ cho từng khóa học; nó thay đổi dự án của bài học, không bao giờ thay đổi dự án của bạn.","changelog.c89ae4f5ac3a":"<strong>Không gì bạn chơi được giữ lại.</strong> Việc lắng nghe diễn ra trên máy tính này, chỉ trong lúc đèn sáng: không âm thanh nào được thu, lưu hay gửi đi. Thứ duy nhất được giữ là một tệp cài đặt nhỏ: đầu vào bạn chọn, A4 và các dây của bộ chỉnh âm, công tắc <em>Lắng nghe</em> và <em>Nghe lại</em> của từng khóa học và phần hiệu chỉnh của từng đầu vào.","changelog.f735c56f78c4":"<strong>Nhận xét nói rõ cần sửa gì.</strong> Sau một take, bài học nêu tối đa ba điều, điều tốn kém nhất trước, mỗi điều kèm ô nhịp, phách và cách sửa, bằng ngôn ngữ của bạn. Trong các khóa sáng tác, một mục tiêu bạn cố ý bỏ lỡ có thể được đánh dấu <em>cố ý</em> và không còn được tính.","changelog.0a8fd7218c37":"<strong>Lịch sử và hồ sơ tác phẩm.</strong> Lịch sử hiện tiến độ, thời gian luyện tập của bạn và bài hát bạn đang làm xuyên suốt các bài học: các phiên bản có tên của nó cùng những gì thay đổi giữa chúng (đưa một bản trở lại là một bước hoàn tác), mọi trang sổ tay, mỗi trang mở đúng Ngày của nó ở đúng bước, và bản lead sheet của nó, mở trong bảng Bản nhạc, cùng tệp PDF của nó. Tất cả được giữ trong thư mục dữ liệu của chính Oscillate. Nếu máy tính này có Freally Handscore, tiến độ, hồ sơ tác phẩm và những từ bạn đã giữ trong từ điển lời bài hát của nó được chuyển sang ở lần đầu, chỉ một lần, và Oscillate sẽ báo điều đó; các tệp của chính Handscore không bao giờ bị thay đổi.","changelog.68b193b60b2e":"<strong>Bài kinh điển và các đoạn nhạc.</strong> Tab Bài kinh điển chứa 62 bài hát thuộc phạm vi công cộng của Handscore, kèm phần ghi công, và các đoạn nhạc của nó, tìm được dù gõ có dấu hay không dấu. Mở một bài làm tài liệu học trên sân khấu, hoặc thành các track trong dự án của chính bạn trong một bước hoàn tác. Chỉ hợp âm của một bài kinh điển mới được rời khỏi Oscillate: mọi thao tác kéo ra (tay nắm của một track, của bản phối, tay nắm trên khay Bản nhạc và <em>Kéo tất cả</em>) đều từ chối giai điệu, phản giai điệu và bass của nó và nói rõ lý do, và dấu đó đi theo các track ấy qua việc đổi tên, hoàn tác và lưu.","changelog.0f01b6fe1544":"<strong>Dời cao độ trên clip âm thanh.</strong> Trong trình chỉnh sửa âm thanh, kéo ngang qua một đoạn dạng sóng, đặt Nửa cung (−12 đến +12) và Cent (−50 đến +50) rồi nhấn <em>Dời cao độ</em>: một nốt hát được dời một cung mà không biến thành giọng sóc chuột, vì formant của nó được giữ, và một clip stereo giữ nguyên hình ảnh stereo. Lần dời được tính trong nền với một thanh tiến trình, rồi được đặt vào như một bước hoàn tác; nó được vẽ thành một thanh dưới dạng sóng, <em>Xóa các lần dời cao độ</em> bỏ tất cả, và bản thu gốc không bao giờ bị thay đổi. Khi phát, mọi bản xuất và mọi người trong phòng đều nghe thấy nó. Dạng sóng vẫn vẽ clip như lúc được thu.","changelog.0e16fde64d9e":"<strong>Kéo giãn mà giữ cao độ.</strong> <em>Khớp với nhịp độ ▸ Stretch (giữ cao độ)</em>, trước giờ bị làm mờ, nay đã hoạt động: một clip theo nhịp độ của các điểm warp mà cao độ không đổi, với trống và hợp âm cũng như với một giọng đơn. Nó được tạo trong nền ngay khi bạn chọn hoặc đổi số ô nhịp của nó, và được lưu, chia sẻ và nghe thấy trong mọi bản xuất như mọi chỉnh sửa khác; một clip bị đảo ngược hoặc lặp lại sẽ nói rõ vì sao không thể kéo giãn.","changelog.1f1daa435d8e":"<strong>Mọi thẻ hiệu ứng được vẽ trực tiếp.</strong> Khi một thẻ đang hiện trên màn hình, nó vẽ những gì thiết bị của nó đang làm với âm thanh đi qua: đường cong của EQ trên phổ âm đi vào và đi ra; đường cong mức của bộ nén, bộ giới hạn hoặc gate với âm thanh chạy trên đó, mức giảm gain cuộn qua và một kim đo trực tiếp; chấm của bộ saturator trên đường cong của nó; trường stereo của doubler, chorus và lớp âm hạt; các tiếng vọng của delay và đuôi reverb kèm thời gian tắt dần đo được; mức giảm của ducker từ khóa của nó. Bộ phân tích và kim giảm gain, vốn ghi <em>chưa trực tiếp</em>, giờ đã chuyển động. Một thẻ bị ẩn gần như không tốn gì của luồng âm thanh, và không gì bạn xuất ra được vẽ vào thẻ. Khi bật giảm chuyển động, các số đo vẫn cập nhật và không gì cuộn.","changelog.93c41d273176":"<strong>Oscillate Doubler, từ Freally Handscore:</strong> một phần được hát hoặc chơi lại bởi tối đa bốn giọng ngay phía sau, mỗi giọng lệch vài cent và vài mili giây và trôi chậm theo cách riêng, trải khắp trường stereo. Độ trôi được gieo từ dự án, nên một bản xuất luôn là cùng một tệp, và một núm Hạt giống cho hai doubler trong cùng bài hát mỗi cái một độ trôi riêng. Mix bằng không giữ nguyên âm thanh như cũ. Bốn preset: Tape Double, Wide Double, Stack và Subtle.","changelog.3d6134de7c78":"<strong>Oscillate Ducker, từ Freally Handscore:</strong> một track được hạ xuống khi track khác vang, bass nhường chỗ cho kick. Chọn khóa ở <em>Sidechain từ</em> trên thẻ của nó: tín hiệu được lấy sau các thiết bị của track đó và trước fader của nó, nên một kick đã tắt tiếng vẫn kích được nó, và nó đến khớp với bass dù thiết bị của track nào thêm độ trễ bao nhiêu. Độ sâu, ngưỡng, khởi, giữ, nhả và bộ lọc thông cao trên khóa; ba preset: Kick Pump, Gentle Duck và Voice Over. Đổi tên track khóa thì khóa vẫn giữ; xóa nó thì thẻ báo khóa đã mất, và bass phát nguyên vẹn cho tới khi bạn chọn khóa khác. Giờ đây <strong>BẢY MƯƠI BA TRONG BẢY MƯƠI CHÍN ĐÃ ĐƯỢC DỰNG</strong>, với ba mươi hai hiệu ứng cốt lõi.","changelog.00ebccea7a17":"<strong>Hạt và một bộ nén trên mọi dải kênh.</strong> Mỗi dải kênh của bàn trộn có thêm núm Hạt (granular) của Freally Handscore và bộ nén dải kênh của nó, cạnh Trầm, Trung, Cao, Phòng, Vọng, Nhiệt và Điều biến cao độ. Hạt ở 0% giữ nguyên âm thanh như cũ, rải mỗi dải kênh theo một cách riêng và render giống hệt mỗi lần. Bộ nén nằm ngoài đường tín hiệu cho tới khi bạn nhấn <em>C</em> của nó, rồi có ngưỡng, tỉ lệ, khởi, nhả và bù, với một đèn sáng lên khi mức giảm gain đạt nửa decibel. Mọi nút điều khiển đều được lưu, tự động hoá được và là một bước hoàn tác, và phím Núm xoay của bàn trộn gập chúng lại cùng phần còn lại. Núm duy nhất của master là Hạt.","changelog.1750f070ec46":"<strong>Cửa sổ Kiểm tra cuối.</strong> Xem ▸ Kiểm tra cuối (Ctrl+9), hoặc phím của nó trên thanh tiêu đề, mở một cửa sổ riêng, như Bàn trộn; nút ⇲ của nó gắn nó vào bên dưới Bàn trộn. Nó liệt kê các nơi phát hành (Spotify, Apple Music, YouTube, Amazon Music, Tidal, Deezer, SoundCloud, CD, câu lạc bộ, EBU R 128 và ATSC A/85), mỗi nơi kèm độ to, mức trần và tệp của nó, cho biết con số là của chính dịch vụ hay là mặc định của Oscillate khi dịch vụ không công bố, và được đọc ở đâu, khi nào. Đánh dấu những nơi bạn muốn (được ghi nhớ trên máy này) và <em>Xuất các bản master</em> tạo một bản master cho mỗi nơi từ cùng một bản mix, vào một thư mục riêng trong thư mục của Cài đặt ▸ Xuất: mỗi bản nằm trong phạm vi 0.5 LU so với mục tiêu và dưới mức trần nhờ True-Peak Limiter, được đo từ chính tệp của nó. Không có gì hứa rằng một dịch vụ sẽ chấp nhận một tệp.","changelog.dcc02d2a0030":"<strong>Bài kiểm tra ô tô và điện thoại, và Nghe như.</strong> Mọi bản master được kiểm tra như loa điện thoại và khoang ô tô sẽ phát (bass được họa âm mang đi, bản mix ở mono, độ rộng dải trầm, tiếng ù và dồn ứ ở dải trung trầm) và hoặc vẫn ổn, hoặc nói cần đổi gì. Trên tab Loa, <em>Nghe như</em> phát loa kiểm âm của bạn như Điện thoại, Ô tô, Máy tính xách tay, Loa nhỏ hoặc Tai nghe nhét tai sẽ phát, mỗi loại được cân bằng mức và chuyển mượt, với <em>Phẳng</em> để so A/B. Nó chỉ dành cho tai bạn: không gì nghe qua nó đi vào bản xuất, bản bounce hay bản master, và mỗi lần mở ứng dụng đều bắt đầu ở mức phẳng.","changelog.a9218b2ebd52":"<strong>Bậc thang độ to.</strong> Đặt tên các điểm đánh dấu là Intro, Verse, Pre-chorus, Chorus, Bridge hoặc Outro (bằng tiếng Anh), và tab Bậc thang độ to đo từng đoạn, từ một điểm đánh dấu tới điểm tiếp theo, riêng rẽ so với bậc của nó, một mục tiêu và một dung sai, và mỗi điệp khúc so với phiên khúc ngay trước nó theo một khoảng chênh bạn đặt. Nó vẽ các bậc lên độ to ngắn hạn của bài hát với mọi con số trong một bảng; các mục tiêu của nó được lưu trên máy này.","changelog.d4c91aa1d3a3":"<strong>Kiểm tra quy chuẩn.</strong> Tab Kiểm tra quy chuẩn kiểm tra một bản master, hoặc bất kỳ tệp nào bạn chọn, theo một mục tiêu giao nộp (phát trực tuyến to hoặc nhỏ, EBU R 128, phát sóng Mỹ, CD, WAV cho nhà phân phối hoặc của riêng bạn) trên mười ba quy tắc, từ độ to tích hợp và đỉnh thực đến tần số lấy mẫu, khoảng lặng ở mỗi đầu và các mẫu bị clip liên tiếp. Mỗi quy tắc đạt, trượt hoặc cảnh báo kèm khoảng chênh và cách sửa đơn giản nhất, và một thay đổi gain duy nhất đáp ứng mọi quy tắc về mức được đề xuất, hoặc phần kiểm tra nói rằng không có. Các mục tiêu sửa được và có ghi ngày (<em>Đánh dấu đã kiểm tra hôm nay</em>), hiện là chưa kiểm tra sau 180 ngày, và báo cáo được lưu dưới dạng HTML, JSON hoặc PDF.","changelog.ab8c6b35f5a4":"<strong>Gợi ý trên mọi thẻ hiệu ứng.</strong> <em>Gợi ý</em> trên từng thẻ hiệu ứng của chính Oscillate lắng nghe những gì tới thẻ (riêng track đó, tính đến thẻ đó) và gợi ý thiết lập bằng các câu văn, đọc vai trò của phần từ tên track: EQ san phẳng một cộng hưởng hoặc dọn tiếng ù rền hay âm đục, bộ nén lấy mức giảm theo vai trò, De-Esser canh giữa vào âm xuýt đo được, delay hoặc phòng vang khớp nhịp với bài hát, Gain and Width giữ an toàn khi mono. <em>Áp dụng</em> đặt tất cả như một bước hoàn tác. Các thiết bị mà việc của chúng là chuyện gu sẽ nói vậy và không gợi ý gì, và Trầm, Cao cùng bộ nén của dải kênh có <em>Gợi ý</em> riêng ở trên cùng giá thiết bị của track đang chọn; plugin được nạp thì không có. Nó hoạt động bằng đo đạc và các quy tắc viết sẵn, không dùng AI, nên cùng một bản mix luôn nhận cùng một gợi ý.","changelog.0c3173aff29d":"<strong>Mix giúp tôi.</strong> Trong cửa sổ Kiểm tra cuối, <em>Mix giúp tôi</em> đặt các thẻ của mọi phần không bị khóa, không bị tắt tiếng theo gợi ý của chúng và mức của phần đó theo vai trò, rồi đáp master xuống nơi phát hành đầu tiên được đánh dấu với một True-Peak Limiter ở cuối chuỗi của chính master; một lần hoàn tác đưa cả bản mix về. Các track bị khóa và bị tắt tiếng được giữ nguyên, núm Hạt của master được tắt nếu đang bật, và báo cáo nói rõ nó đã làm gì. Chuỗi của master chưa có giá thiết bị riêng: bộ giới hạn của nó hiện trong báo cáo và mất đi khi hoàn tác hoặc khi chạy <em>Mix giúp tôi</em> lần nữa.","changelog.e2c4c3ac3a03":"<strong>Các cửa sổ mở lại như lúc bạn để.</strong> Các cửa sổ Bàn trộn, Trình duyệt tệp, Trình chỉnh sửa, Phòng và Kiểm tra cuối đang mở khi bạn thoát sẽ trở lại ở lần khởi động sau, đúng chỗ bạn để, ngay khi cửa sổ chính hiện lên; một cửa sổ nằm trên màn hình không còn nữa sẽ mở trên màn hình đang có. Bản ghi được lưu mỗi khi một cửa sổ mở và đóng, nên nó vẫn còn sau khi ứng dụng bị sập.","changelog.1b5c3133a037":"<strong>Xuất với độ dài bất kỳ.</strong> Tệp ▸ Xuất thư mục đi kèm… ghi bản mix và các stem của nó, và Kiểm tra cuối ghi mọi bản master, xuống ổ đĩa ngay trong lúc render, nên một bài hát dài hơn mười phút được xuất trọn vẹn. Thao tác kéo ra vẫn giữ giới hạn mười phút, và tệp WAV và AIFF dừng ở 4 GB.","changelog.1a96cd093f4f":"<strong>Mỗi loại một cái, với phần ruột tốt hơn.</strong> Ở những chỗ Oscillate và Freally Handscore đều có một hiệu ứng cùng loại, hai cái được đo cạnh nhau, và mỗi thiết bị giữ tên, mặt hiển thị và các preset của nó, với âm thanh tốt hơn bên trong. Precision EQ và Four-Band EQ vẽ cùng những đường cong, và một núm xoay được vặn trong lúc đang phát giờ lướt trong 30 ms thay vì nhảy cóc, nên một lần quét không còn bị lụp bụp; độ rộng của Gain and Width cũng lướt, và phần giữa của hình ảnh stereo đi qua nguyên vẹn. Đồng hồ đo độ to của bàn trộn, Kiểm tra cuối và các bản master giờ đọc cùng một đồng hồ, sai lệch trong 0.02 LU so với tín hiệu thử của EBU.","changelog.2ca6b9df7119":"<strong>Phiên làm việc dày đặc chạy nhẹ hơn, và xuất xong sớm hơn.</strong> Các bus và kênh return giờ render trên các nhân của bộ xử lý song song với các track, một track có ducker bắt đầu những gì đứng trước nó cùng lúc với khóa của nó, và Digital Delay chỉ làm một phần nhỏ công việc khi thời gian của nó đứng yên. Trên phiên dày đặc nhất mà chúng tôi thử, việc xuất bản mix chạy nhanh gấp hơn bốn lần và các bản master nhanh gấp khoảng sáu lần, cả hai đều trải trên các nhân và giống hệt bản render trên một nhân.","changelog.e1eb319dfd66":"<strong>Các nhạc cụ dùng chung với Freally MIDI Master chuyển sang bản phát hành mới nhất của nó.</strong> Bộ lọc của Bright Reed mở ra một chút, như trong MIDI Master, và một bài hát được kéo vào từ MIDI Master cùng bản phát hành sẽ đặt từng phần lên đúng âm thanh mà nó đã chơi ở đó.","changelog.a086436bf07c":"<strong>Kéo ra trên Linux.</strong> MIDI hoặc âm thanh của một track giờ cũng kéo ra khỏi Oscillate được trên Linux, từ mọi tay nắm, như trên Windows và macOS; những gì được kéo chờ trong một thư mục chỉ mình bạn đọc được.","changelog.4a30a62f9b42":"<strong>Một hợp âm được đánh lại đúng lúc nó kết thúc sẽ vang trọn vẹn.</strong> Khi một hợp âm được nhả và đánh lại ở cùng một tick, một nốt có thể bị đánh trước khi nó được nhả và bị cắt ngay; giờ các lần nhả đi trước, rồi hợp âm vang lên từ nốt thấp nhất trở lên, khi phát, trong chế độ Pattern và trong các bản xuất. Hai nốt cùng một nhóm chặn tiếng được đánh cùng lúc sẽ để nốt cao hơn tiếp tục vang, lần nào cũng vậy.","changelog.a4ae782328a5":"<strong>True-Peak Limiter giữ đúng mức trần.</strong> Khi đặt ở −1 dBTP, nó để lọt các đỉnh tới −0.91 dBTP; giờ nó đọc đỉnh thực bằng chính phần oversampling của đồng hồ đo độ to và nhắm vào trong 0.02 dB, đáp ở −1.02 dBTP với 4× và 8×, và chỉ thêm phần look-ahead của nó làm độ trễ.","changelog.8fb884be103d":"<strong>Chuỗi hiệu ứng riêng của master đã phát.</strong> Mọi dự án vẫn giữ một chuỗi hiệu ứng cho master, nhưng không gì phát nó; giờ nó phát sau phần tổng của master và trước fader của master. Một dự án tạo trước bản phát hành này có chuỗi rỗng và nghe như trước.","changelog.e18d492281be":"<strong>Thoát sẽ đóng mọi cửa sổ.</strong> Một cửa sổ Bàn trộn, Trình duyệt tệp, Trình chỉnh sửa hoặc Phòng đang ẩn có thể khiến Oscillate vẫn chạy ngầm sau khi cửa sổ chính đã đóng, và lần khởi động sau đó không làm gì cả. Giờ việc đóng cửa sổ chính sẽ lưu vị trí của từng cửa sổ và đóng tất cả.","changelog.569c159e4ed3":"<strong>Một dòng lời giữ các từ bạn chưa gửi.</strong> Khi dòng bạn đang sửa bị một người khác trong phòng, một lần hoàn tác hoặc một lần nhập dời đi, trình sửa giờ đi theo nó cùng các từ của bạn; khi dòng đó bị xóa, các từ của bạn được giữ lại, và một lần hoàn tác đưa dòng trở lại sẽ mở lại nó cùng các từ đó. Trước đây, trình sửa đóng lại và các từ biến mất.","changelog.208739ca3b60":"<strong>Auto Gain của Precision EQ chỉ nâng một bộ cắt lên tối đa 24 dB.</strong> Khi bật Auto Gain, bộ cắt cao hoặc cắt thấp bù lại phần đã bỏ đi tới 37 dB (cắt cao ở 100 Hz), đủ lớn để gây hại cho tai; nay phần bù dừng ở 24 dB, và nút Output vẫn chạm tới đúng mức nó ghi.","changelog.043185ecadf0":"<span class=\"release__meta\"><span class=\"release__ver\">v0.10.0</span><time class=\"release__date\" datetime=\"2026-11-02\">2026-11-02</time></span>","changelog.34fbbfb4cefd":"<strong>Bản nhạc — chưa có bản tải xuống.</strong> Giờ bất kỳ track MIDI nào cũng đọc được dưới dạng bản nhạc trong một bảng Bản nhạc riêng, với TAB cho guitar và bass, ký hiệu tay đánh cho trống và lời của Làn lời bài hát dưới các nốt, và cả bài hát xuất ra PDF hoặc in ra. Bên cạnh đó là một trình sửa lời có từ điển, vần, trọng âm và flow, một khóa trên mọi track, tỉ lệ Âm thanh ↔ MIDI, một Giá pattern được trau chuốt như của FL Studio, và một cửa sổ chính mở ra gọn gàng.","changelog.8db786d68913":"<strong>Bảng Bản nhạc.</strong> Xem ▸ Bản nhạc (Ctrl+7), hoặc phím riêng của nó trên thanh tiêu đề, hiện một bảng bên dưới sân khấu ghi bất kỳ track MIDI nào thành bản nhạc: khuông khóa Sol, khóa Fa hoặc khuông kép chọn theo âm vực của track, số chỉ nhịp và giọng thay đổi ở đúng những chỗ chúng đổi trong dự án, một dấu mốc tập ở mỗi điểm đánh dấu đoạn, dấu lặng nhiều ô nhịp cho các ô nhịp im lặng, và các trang như giấy thật có tên dự án và <em>Trang n/N</em>. Bản nhạc là một khung nhìn của track: bạn sửa nốt trong piano roll và bản nhạc đi theo. Hai trăm ô nhịp được ghi trong khoảng một phần tư giây, và không phần nào của bộ ghi bản nhạc được tải cho tới khi một bản nhạc hiện lần đầu.","changelog.c333a04570c9":"<strong>TAB và bản nhạc trống.</strong> Track của guitar được ghi ở khóa Sol thấp một quãng tám trên TAB sáu dòng, kèm sơ đồ hợp âm và mũi tên quạt chả; bass trên TAB bốn dòng, hoặc năm dòng với bass 5 dây. Các phím bấm chính là những phím mà đôi tay trên sân khấu chơi. Track trống ghi R, L, RF hoặc LF dưới mỗi nhát đánh.","changelog.904679c05d35":"<strong>Lời dưới nốt nhạc.</strong> Lời của Làn lời bài hát được ghi dưới các nốt của chúng, và một âm tiết được ngân bằng <code>_</code> sẽ vẽ đường kéo dài của nó.","changelog.81d8f60280bd":"<strong>Khay và mặt bàn.</strong> Dọc cạnh trên của bảng Bản nhạc, chip của tổng phổ đứng đầu, rồi đến một chip cho mỗi track MIDI có chứa nốt, theo thứ tự của bản phối. Mỗi chip mở bản nhạc của nó, tắt tiếng và solo track của nó như bàn trộn, khóa track, và trên Windows và macOS có một tay nắm để kéo MIDI của track ra khỏi Oscillate; tay nắm của tổng phổ, <em>Kéo tất cả</em>, kéo track của mọi bản nhạc. Bên dưới khay, mặt bàn hiện trang đầu của mọi bản nhạc: nhấp vào một trang để đọc.","changelog.8c17b512f72a":"<strong>Trình đọc bản nhạc.</strong> Khi bảng Bản nhạc đang hiện, 1 đến 9 mở chín bản nhạc đầu tiên trải hết chiều ngang, 1 là tổng phổ, và nhấn lại cùng phím đó hoặc Esc sẽ quay lại. Các trang tự lật khi bài hát phát, các nốt sáng luôn là những nốt đang vang (track bị tắt tiếng không sáng gì cả), và một danh sách đoạn nhảy tới từng đoạn. Mọi phím đều có thể đổi trong Cài đặt ▸ Phím tắt.","changelog.fa43705c3059":"<strong>Bản nhạc dưới dạng PDF, hoặc in ra.</strong> Tệp ▸ Xuất bản nhạc ra PDF…, hoặc phím PDF của khay, lưu một tệp PDF A4 vào chỗ bạn chọn: trang bìa, phần ghi công, bản nhạc của mọi track và tổng phổ. Trang bìa cho biết giọng, nhịp độ và số chỉ nhịp (mỗi lần đổi kèm ô nhịp của nó), số ô nhịp và số nốt, tổng cộng và theo từng track. Phần ghi công nêu tên người viết và nhà sản xuất lấy từ chính lịch sử của dự án, theo tên đặt trong Cài đặt ▸ Cộng tác ▸ <em>Tên của bạn trong phòng</em>. Tệp ▸ In bản nhạc…, hoặc phím In, gửi đúng những trang đó tới hộp thoại in của hệ thống, trên giấy A4 trắng ở cả hai giao diện.","changelog.34db14f3968c":"<strong>Giá nhạc của sân khấu hiện bản nhạc</strong> của track mà sân khấu đang theo dõi, tự lật trang và làm sáng nốt mà đôi tay chơi.","changelog.eedc16f5e0ac":"<strong>Lời bài hát với từ điển.</strong> Trình sửa dòng của Làn lời bài hát hoàn tất từ bằng Tab dựa trên một từ điển tiếng Anh 327.000 từ, và Shift+Tab hoặc ✓ giữ một từ đúng như bạn đã gõ, trên máy tính này. Công tắc <strong>Chính tả</strong> sửa một từ viết sai ngay khi từ đó kết thúc, và Backspace ngay sau đó trả lại từ cũ. Mặc định nó bật trong tiếng Anh và tắt ở các ngôn ngữ khác.","changelog.84697cddb821":"<strong>Âm tiết trên nốt của chúng.</strong> <code>-</code> tách một từ thành các âm tiết và <code>_</code> ngân một âm tiết sang nốt tiếp theo, và <em>Tách</em> đặt mỗi âm tiết lên nốt của nó. Mỗi dòng cho thấy nó khớp với các nốt ra sao (4/4, +2, −1), và một dòng dài hơn số nốt của nó sẽ nói rõ điều đó thay vì bị tách.","changelog.1a063c6e681b":"<strong>Trọng âm, vần và flow.</strong> <em>Dấu trọng âm</em> đánh dấu âm tiết nhấn của mỗi từ, và máy nhắc chữ in đậm âm tiết đó. <em>Vần</em> tô màu cuối dòng theo vần, gắn cho mỗi dòng một chữ cái trong sơ đồ vần của đoạn (AABB, ABAB…) và gắn cờ các cụm từ sáo rỗng là quen thuộc. <em>Lưới flow</em> xếp các âm tiết của mỗi ô nhịp lên lưới móc kép kèm số đếm, độ pocket và ngữ điệu, và <em>Đọc rap</em> đo thời điểm của một take đã thu mà bạn chọn so với các âm tiết đã đặt, đánh dấu từng âm tiết là sớm hay muộn.","changelog.0439610e6f48":"<strong>Bản nhạc chính.</strong> Một phím trong Làn lời bài hát mở giai điệu của track, lời và các ký hiệu hợp âm trong trình đọc bản nhạc của bảng Bản nhạc.","changelog.72e16178296c":"<strong>Khóa một track.</strong> Một ổ khóa trên đầu track của mỗi track âm thanh và MIDI, trên dải kênh của nó và trên chip bản nhạc của nó. Khi một track đang khóa, mọi thay đổi với nốt và clip của nó đều bị từ chối bằng một câu nêu tên track, dù thay đổi đến từ đâu: piano roll, lưới trống, giá pattern, bản phối, một tệp được thả vào, Thu âm hay hoàn tác; một take đã đang thu khi khóa được bật vẫn được đặt vào. Phần mix của nó vẫn tự do. Khóa được lưu cùng dự án, là một bước hoàn tác, và trong phòng nó đến được với mọi người, rồi từ đó mọi thay đổi của chính mỗi người với track đều bị từ chối.","changelog.3f6496b8d90e":"<strong>Tỉ lệ Âm thanh ↔ MIDI.</strong> Một thanh trượt trong khay của bảng Bản nhạc pha các track âm thanh của dự án với các track MIDI: bên trái chỉ phát âm thanh, bên phải chỉ MIDI, ở giữa cả hai đều tối đa. Nó chuyển mượt không có tiếng lách cách, được lưu cùng dự án và không bao giờ dời fader; bản xuất, stem và bản đóng băng bỏ qua nó. Nhấp đúp sẽ đưa nó về giữa.","changelog.463a355353fb":"<strong>Pan và cao độ tinh chỉnh của từng bước giờ được nghe thấy</strong> trên Drum Machine, One-Shot Sampler, Multisampler và Percussion Sampler, khi phát và trong các bản xuất. Modelled Synth, vốn chơi các nhạc cụ của thư viện, Section Player và Layer Rack chưa chơi chúng, và plugin nghe mọi bước ở chính giữa và đúng cao độ.","changelog.b8ba10151223":"<strong>Đổi góc nhìn sân khấu từ bất kỳ đâu.</strong> Khi sân khấu đang hiện, Alt+V chuyển sang góc nhìn tiếp theo và Alt+Shift+V quay lại, dù bạn đang làm việc ở đâu.","changelog.51aa144b34b1":"<strong>Tay trống đi giày thật.</strong> Giày cổ cao có dây, vải canvas đen trên đế và mũi giày cao su trắng, dây giày trắng luồn qua khoen kim loại đến nút nơ, bên trên đôi tất trắng, thay cho đôi giày tối màu đơn giản trước đây bị chìm trên tấm thảm.","changelog.a19019b8fb76":"<strong>Cửa sổ chính mở ra gọn gàng:</strong> thanh điều khiển phát, Giá pattern gắn phía trên bản phối với một thanh chia ở giữa, và bản phối. Phím của giá trên thanh tiêu đề, Xem ▸ Giá pattern và Ctrl+2 hiện và ẩn nó; nó không còn thế chỗ bản phối, và phím Bản phối trên thanh tiêu đề đã bị bỏ.","changelog.44f584847313":"<strong>Bàn trộn, Trình duyệt tệp, Trình chỉnh sửa và Phòng nằm trong các cửa sổ riêng,</strong> ẩn cho tới khi phím của chúng trên thanh tiêu đề, mục của chúng trong trình đơn Xem hoặc Ctrl+số mở chúng ra. Nút ✕ của một cửa sổ sẽ ẩn nó, nút ⇲ gắn bảng vào cửa sổ chính, và nút ⇱ của một bảng đã gắn sẽ tách nó ra lần nữa; chỗ của mỗi bảng được ghi nhớ trên máy tính này. Cửa sổ bảng lần đầu mở bên cạnh cửa sổ chính, rồi mở lại ở chỗ bạn đã để nó. Cửa sổ Trình chỉnh sửa lần đầu mở đủ lớn cho thanh công cụ của piano roll, hai quãng tám, làn tự động hoá và hai làn take. Một bản cài đặt từ trước 0.10.0 chuyển sang bố cục này một lần, giữ nguyên kích thước các bảng, và phần hướng dẫn đưa Trình duyệt tệp và Trình chỉnh sửa vào cửa sổ chính trong lúc chỉ vào chúng.","changelog.14ef80e49e29":"<strong>Giá pattern, được trau chuốt như của FL Studio.</strong> Mỗi hàng nằm trên một dòng: đèn (tắt tiếng của track), các núm pan và âm lượng (pan và fader trên bàn trộn của chính track), nơi nó phát vào, tên của nó và S, cùng Sửa, Đặt, Đưa lên và Bỏ là các phím nhỏ ở cuối hàng. Các bước theo từng nhóm bốn, tô bóng xen kẽ, mỗi bước sáng tương ứng với velocity của nó. Các bước sau điểm kết thúc của pattern được làm mờ: nhấn hoặc kéo ngang qua chúng, kéo tay nắm ở bước cuối, hoặc dùng − và + cạnh <em>Số bước</em> để đổi độ dài, tối đa 256 bước và 16 ô nhịp. Một giai điệu được viết trong piano roll lệch khỏi lưới bước hiện trong hàng của nó như một piano roll nhỏ; nhấp đúp để mở. Nhấp vào tên một hàng để có đồ thị velocity, pan, cao độ tinh chỉnh, xác suất và biên độ velocity của từng bước, vẽ hoặc gõ, mỗi lần quét là một bước hoàn tác. Nút <strong>+</strong> ở góc dưới bên trái thêm một hàng nhạc cụ mới: một track MIDI mới với nhạc cụ bạn chọn từ các kệ của trình duyệt, trong một bước hoàn tác.","changelog.a46684dcbb1e":"<strong>Chất lượng Tự động của sân khấu giờ đánh giá theo những khung hình chậm nhất</strong> thay vì mức trung bình, nên nó chỉ hạ mức chi tiết ở những chỗ máy thật sự bị giật, và không còn hạ nó khi máy chạy ổn định 52 khung hình mỗi giây.","changelog.d72c41d7cffa":"<strong>Sân khấu chơi trên macOS.</strong> Máy Mac vẽ 3D bằng card đồ họa thật, nên ở đó sân khấu chơi theo bài hát như trên Windows. Trên Linux nó vẫn đứng yên, vẽ một khung hình cho mỗi thay đổi, và nói rõ lý do.","changelog.18c24a81e339":"<strong>Thao tác kéo cả bài hát của Freally MIDI Master có thể mang theo âm thanh của từng phần.</strong> Giờ Oscillate đọc preset mà mỗi phần mang theo khi một bài hát được kéo vào từ MIDI Master. MIDI Master sẽ bắt đầu ghi nó trong một bản phát hành sắp tới; cho tới lúc đó, các phần của một bài hát được thả vào sẽ chơi âm thanh chính của nhạc cụ, như trước.","changelog.0440f7958ce1":"<strong>Không còn bàn phím trên bộ trống.</strong> Mở sân khấu thẳng trên một rãnh trống thì bộ trống đứng một mình, không còn bàn phím đàn piano trơ trọi lơ lửng trên trống snare.","changelog.1d9fe93e55f4":"<strong>Tay trống cầm dùi.</strong> Mỗi bàn tay nắm lấy dùi bằng mọi ngón, dùi nằm chéo qua lòng bàn tay như tay trống cầm, thay vì kẹp giữa ngón cái và ngón trỏ với các ngón còn lại buông thõng.","changelog.6dbc52a85080":"<strong>Ngón tay không có gì để chơi nằm yên trên phím.</strong> Bên cạnh một hợp âm, các ngón rảnh của bàn tay không còn dựng đứng trên phím, đậu trên phím đen hay bật lên mỗi phách.","changelog.845917250ea2":"<strong>Bẻ cao độ một bộ trống dày không còn làm mất tiếng.</strong> Khi bánh xe pitch bẻ một groove Drum Machine dày hay một hợp âm sampler lớn, các giọng nhỏ nhất vượt quá 32 sẽ mờ dần, như ở một sampler phần cứng, nên âm thanh không bao giờ đứt.","changelog.420f580c3422":"<strong>Sân khấu thấp vẫn hiện cả cây đàn piano.</strong> Thu thấp sân khấu và máy quay lùi lại cho đến khi bàn phím, đôi tay và giá nhạc hiện đủ, ở giữa.","changelog.88dda7027d59":"<strong>Rãnh Drums của dự án mới là rãnh trống:</strong> sân khấu đặt bộ trống cho nó, không phải đàn piano.","changelog.09d0ea47cefd":"<strong>Thanh công cụ của bản phối vẫn hiện trên màn hình</strong> khi sân khấu làm bản phối thấp lại, và biểu tượng của phím lời bài hát nằm giữa phím.","changelog.6de570ed34e4":"<span class=\"release__meta\"><span class=\"release__ver\">v0.9.0</span><time class=\"release__date\" datetime=\"2026-10-31\">2026-10-31</time></span>","changelog.846db83f9221":"<strong>Sân khấu — chưa có bản tải xuống.</strong> Một sân khấu 3D bên dưới bản phối chơi bất kỳ track MIDI nào bằng đôi tay trên piano, guitar, bass và trống. Bên cạnh đó là một drum machine, một bộ amp guitar, trình duyệt nhạc cụ với đủ 1,648 nhạc cụ, một Giá pattern hoạt động như của FL Studio, các bánh xe của bàn phím MIDI trên mọi nhạc cụ, và núm vặn mới.","changelog.f5738fc842ef":"<strong>Sân khấu, từ Freally Handscore.</strong> Xem ▸ Sân khấu (Ctrl+6) mở một sân khấu 3D bên dưới bản phối. Chọn một track MIDI, hoặc để nó theo track đang được chọn, và đôi tay chơi các nốt của track đó trên nhạc cụ của nó, khớp nhịp với transport: qua các lần đổi tempo, vòng qua vòng lặp và tới bất cứ đâu bạn tua. Rê chuột lên thước của dòng thời gian sẽ hiện một bản xem trước nhỏ của sân khấu tại thời điểm đó. Sân khấu chỉ tải vào lần đầu bạn mở nó, nên Oscillate vẫn khởi động nhanh như trước. Trên macOS và Linux, sân khấu chuyển tới từng vị trí mới khi bạn dừng, nhảy tới hoặc đổi góc nhìn, thay vì chơi theo, và có nói rõ điều đó.","changelog.00de69a4fa5a":"<strong>Bốn cây piano trên sân khấu:</strong> các nhạc cụ có sẵn Grand Piano, Acoustic Piano, Upright Piano và Honky-Tonk Piano đều hiện lên đúng là chính chúng, còn mọi nhạc cụ khác chơi trên Grand Piano. Bạn có thể chọn một cây piano khác chỉ để thay vẻ ngoài. Phím có thể được ghi tên (phím trắng, tất cả phím hoặc không phím nào), và các ngón tay được đánh số 1–5.","changelog.29f8c7f4c6b7":"<strong>Guitar và bass trên sân khấu.</strong> Các nhạc cụ có sẵn Guitar, Nylon Guitar, Electric Guitar và Muted Guitar cùng Pluck Bass, Slap Bass và Upright Bass đều hiện lên đúng là chính chúng, với đôi tay quạt chả và gảy dây, kỹ thuật slide, hammer-on và pull-off. Một Electric Guitar cắm vào Guitar Amp hiện lên thành một cây guitar rock. Hãy chọn thứ guitar chơi (hợp âm, giai điệu hoặc giai điệu đối), 4 hay 5 dây cho bass, thanh phím đàn, và người chơi thuận tay trái. Một đường bass chuyển lên hoặc xuống một quãng tám ở những chỗ cần đàn đòi hỏi. <em>Đệm</em> solo track đang được theo hoặc để các track khác cùng chơi. Bạn có thể dựng bất kỳ nhạc cụ nào cho bất kỳ track nào, chỉ để thay vẻ ngoài.","changelog.7a3b1c31c7b1":"<strong>Trống trên sân khấu.</strong> Một track Drum Machine hiện lên thành một bộ điều khiển 16 pad do đôi tay đánh trống bằng ngón chơi, các pad sáng lên khi được đánh. Mọi track trống khác hiện lên thành một bộ trống phòng thu được chơi bằng dùi và chân, thuận tay phải hoặc tay trái. Trên track đang sẵn sàng thu, hãy nhấp vào một pad để chơi nó.","changelog.893ee50f0701":"<strong>Các camera của sân khấu.</strong> Nhìn từ phía trước, từ trên xuống hoặc từ bên cạnh, hoặc lại gần một bàn tay: tay trái hoặc tay phải trên piano, tay bấm phím hoặc tay gảy trên guitar, đôi tay trên các pad, tay và chân của bộ trống. Khi sân khấu đang có tiêu điểm, V chuyển sang góc nhìn tiếp theo và Shift+V lùi lại, lướt giữa các góc nhìn (hoặc cắt thẳng nếu hệ thống của bạn yêu cầu giảm chuyển động). Chất lượng có thể là Tự động, tự hạ xuống để hình ảnh luôn mượt, hoặc Cao, Trung bình hay Thấp, và đôi tay có sáu màu da.","changelog.586b2ef349d2":"<strong>Sân khấu cho mọi người.</strong> Mọi điều khiển trên sân khấu đều dùng được từ bàn phím và có tên cho trình đọc màn hình. Sân khấu nói rõ thứ gì đang hiện lên và nó đang theo track nào, và chế độ giảm chuyển động cắt camera thay vì lướt, trong khi đôi tay vẫn tiếp tục chơi.","changelog.e502dae2a32f":"<strong>Chơi cây piano của sân khấu.</strong> Trên track đang sẵn sàng thu, hãy nhấp vào các phím 3D của nó để chơi, và những gì bạn chơi trên bàn phím máy tính hoặc bàn phím MIDI hiện lên trên các phím đó. Khi bánh xe cao độ, bánh xe điều biến hoặc lực nhấn của bàn phím MIDI rời khỏi vị trí nghỉ, một ô hiển thị nhỏ cho thấy giá trị đó.","changelog.52f0b0e83617":"<strong>Trình duyệt nhạc cụ trưởng thành.</strong> Cả 1,648 nhạc cụ nằm trong các thư mục theo họ trên mỗi kệ, danh sách cuộn mượt dù dài đến đâu, và một ngôi sao trên bất kỳ hàng nào sẽ đưa nó vào một chỗ mới là <strong>Đã gắn sao</strong>. Khi đang chọn một track MIDI, dừng chuột trên một nhạc cụ sẽ chơi chính các nốt của track đó qua nhạc cụ ấy. <strong>Âm thanh của tôi</strong> giữ các nhạc cụ bạn lưu, theo tên và thư mục, sẵn sàng để đặt lên một track.","changelog.ed2da6e473fb":"<strong>PACK:</strong> chọn tối đa 25 one-shot từ bất kỳ nhạc cụ nào, chơi chúng, đổi từng cái sang một bản thu khác của cùng nhạc cụ, và xuất chúng thành tệp WAV vào thư mục bạn chọn. Việc xuất không bao giờ ghi đè lên một tệp đã có sẵn.","changelog.f8948f1e3897":"<strong>Một bộ amp guitar, từ Freally Handscore</strong>, như một thiết bị trên bất kỳ track nào: các chất âm crunch và high-gain mà guitar rock của Handscore từng chơi qua, với mức đầu vào và đầu ra.","changelog.1f5a90f43722":"<strong>Guitar rock, sẵn sàng để chơi:</strong> một kệ <strong>Chuỗi</strong> mới trong trình duyệt chứa <em>Overdriven Guitar</em> và <em>Distortion Guitar</em>. Mỗi cái là Electric Guitar cắm vào Guitar Amp, với một tiếng vọng và hồi âm phòng nhỏ phía sau, được chỉnh mức để nằm đúng chỗ của tiếng guitar khô. Nạp một cái lên track MIDI và nó thay giá thiết bị của track trong một bước hoàn tác. Sân khấu hiện cả hai thành một cây guitar rock.","changelog.2c1bdb1a5144":"<strong>Granular Wash, từ Freally Handscore:</strong> một núm biến âm thanh thành một đám mây hạt, giữ nguyên nốt và thêm các quãng tám phía trên và phía dưới nó, với một tiếng vọng kéo nó dài thêm nhiều giây.","changelog.456b255a9204":"<strong>Đường bao trên mọi nhạc cụ.</strong> Mỗi nhạc cụ trong 1,648 nhạc cụ giờ có bốn đường bao bạn có thể bật: Âm lượng, Bộ lọc, Cao độ và Vị trí. Mỗi đường bao bắt đầu từ một hình dạng (Init, Gảy, Nền, Dâng, Cổng hoặc Nảy), hoặc bạn tự vẽ với tối đa 16 điểm thêm. Mỗi đường bao có thể lặp khi giữ phím, khóa theo tempo, theo velocity và phím, khởi động lại mỗi ô nhịp, và chuyển dần giữa hai hình dạng. Hình dạng tự vẽ được lưu trong dự án và trong tệp giá thiết bị, nhưng không nằm trong dòng thiết lập được dán. Khi mọi đường bao đều tắt, mỗi nhạc cụ vang lên y như trước. Giờ đây <strong>BẢY MƯƠI MỐT TRONG BẢY MƯƠI BẢY ĐÃ ĐƯỢC DỰNG</strong>, với ba mươi hiệu ứng cốt lõi.","changelog.3c490686a380":"<strong>Drum Machine, từ Freally Handscore</strong>, thay thế Pad Grid: 16 pad chơi bốn bộ trống tổng hợp của Handscore (Sub, Floor, Neon và Wire), mỗi nhát đánh được chọn từ ba lớp theo độ mạnh bạn chơi và luân phiên giữa hai bản thu, nên một hồi trống cuộn không bao giờ lặp lại y hệt. Mỗi pad có chỉnh cao độ, quét cao độ, đường bao, pan, bộ lọc và nhóm chặn tiếng, cùng tối đa bốn lớp mà bạn có thể đảo ngược hoặc chuẩn hóa. Các âm thanh của bộ trống và 11 gói trống được liệt kê bên cạnh các pad, để nghe và để đặt lên một pad. Các bài hát từng dùng Pad Grid mở ra trên Drum Machine với mức âm lượng và nhóm chặn tiếng được giữ nguyên.","changelog.a73196fdefd8":"<strong>Giá pattern hoạt động như của FL Studio.</strong> Mỗi hàng có phần riêng ngay từ đầu, nên <em>Sửa</em> mở nó trong piano roll (hoặc lưới trống) và <em>Đặt</em> đưa nó vào bài hát ngay lập tức; không có gì phải tồn tại trong bản phối trước.","changelog.accec80b1ae2":"Nhấp các bước ngay trong giá. Một track trống mở ra thành một hàng bước cho mỗi âm thanh của nó, và các bước của một hàng giai điệu chơi nốt của hàng đó. Một lần kéo tô hoặc xóa cả một dải trong một bước hoàn tác, và một bước bạn bật sẽ phát âm thanh của nó.","changelog.115e9acfd86e":"<strong>Đặt pattern</strong> đặt mỗi hàng lên track riêng của nó tại đầu phát trong một bước hoàn tác, có liên kết, nên sửa pattern sẽ thay đổi mọi vị trí đã đặt.","changelog.75ba3144030f":"Một pattern có chiều dài riêng (tối đa 16 ô nhịp), lưới (1/4 đến 1/32) và swing riêng.","changelog.afc2281ee72b":"<strong>Pattern / Bài hát</strong>, bên cạnh transport: ở chế độ <em>Pattern</em>, Phát lặp pattern đang mở trên chính nhạc cụ, chuỗi và bàn trộn của các track của nó, theo tempo của bài hát, mà không chạm tới bản phối. Một bước bạn bật trong lúc nó đang phát sẽ được nghe ở lượt kế tiếp, và giá hiển thị bước đang phát. <em>Bài hát</em> đưa đầu phát về lại chỗ cũ.","changelog.f7997e06e1f4":"Biểu tượng của phím <em>Pattern mới</em> giờ nằm cạnh tên của nó, và biểu tượng của mọi phím khác cũng vậy.","changelog.2ac99e3c60b4":"<strong>Lưới trống cũng là một bộ trình tự bước:</strong>","changelog.19331c466587":"velocity của mỗi nhát đánh được vẽ thành một thanh, và velocity của một hàng có thể được vẽ trong một làn bên dưới nó;","changelog.0efc86543f52":"Độ swing từ 50 đến 75%;","changelog.e59c0853bb61":"một nhát đánh lệch lưới được đánh dấu là sớm hoặc trễ;","changelog.6a44598b8b11":"kéo chuột phải xóa cả một vùng hình chữ nhật;","changelog.4ba33e04b552":"mỗi hàng có thể được solo cũng như tắt tiếng.","changelog.7946b0544401":"Trên một track Drum Machine, các hàng được đặt tên theo các pad của nó, và nhóm chặn tiếng của một hàng là của pad đó.","changelog.72e1521ec764":"<strong>Bản đồ trống:</strong> trống được nhập từ cách sắp xếp của bộ trống khác (Toontrack, Addictive Drums, Superior và các bộ khác) sẽ chơi đúng thành phần trong bộ trống của bạn. Mỗi hàng có thể được trỏ tới một thành phần, tới đường bass 808 hoặc để ngoài bộ trống, mà không thay đổi một nốt nào: tắt bản đồ đi thì phần đó phát đúng như lúc nó đến. Phát lại, xuất, kéo thả và sân khấu đều làm theo nó.","changelog.a24945cd87a3":"<strong>Cho Oscillate học bộ điều khiển pad của bạn</strong> (Cài đặt ▸ MIDI ▸ Bộ điều khiển pad): đánh từng pad trong 16 pad khi được yêu cầu, và bộ điều khiển của bạn sẽ chơi các pad của Drum Machine theo bố cục và cách đặt ngón bạn chọn.","changelog.d9fbc164eaf0":"<strong>Các bánh xe của bàn phím MIDI tới được mọi nhạc cụ.</strong> Bánh xe cao độ uốn các nốt đang giữ, và các nốt được nhấn trong lúc nó đang bị giữ sẽ bắt đầu ở trạng thái đã uốn. Bánh xe điều biến và channel pressure đưa vibrato của các nhạc cụ vào. Cả ba đều tới được các plugin VST3 và CLAP đang chạy, như trong một DAW khác.","changelog.b74af77e2ad7":"<strong>Cài đặt ▸ MIDI ▸ Cách chơi:</strong> dịch giọng, phạm vi bend (mặc định ±2, tối đa bốn quãng tám), đường cong lực nhấn mềm hoặc cứng, và <strong>Hợp âm</strong>, chơi một hợp âm theo âm giai của dự án từ mỗi phím.","changelog.c6232c384873":"<strong>Các track được kết xuất trên các nhân của máy tính.</strong> Khi một bài hát nặng, các track độc lập của nó được tối đa bảy luồng phụ chơi cùng lúc, nên một phiên bận rộn chỉ mất khoảng một phần năm thời gian như trước. Âm thanh giống nhau đến từng bit cuối cùng. Một phiên nhẹ hoặc transport đang dừng hoàn toàn không đánh thức các luồng phụ.","changelog.862476a841b8":"<strong>Một phần của Section Player sẵn sàng trong chưa tới một giây</strong>, trong khi trước đây mất khoảng hai mươi giây. Các track Modelled Synth và Layer Rack cũng sẵn sàng nhanh hơn.","changelog.0eeb8bf8931a":"<strong>Núm vặn mới.</strong> Mọi núm đều là núm màu than chì tối với viền sáng dịu và một kim chỉ màu xanh lá mảnh, cùng một núm ở giao diện sáng lẫn tối, với vòng cung giá trị mỏng hơn bao quanh.","changelog.b74912e85473":"<strong>One-Shot Sampler, Multisampler, Percussion Sampler và Granular Player chơi các tệp của chính bạn.</strong> Trước đây không có cách nào đưa tệp cho chúng trong ứng dụng, nên chúng không phát ra tiếng. <em>Thêm mẫu âm…</em> trên mỗi cái, và trên các pad của Drum Machine, giờ chọn tệp để chơi. One-shot của một gói lên pad chỉ với một cú nhấp.","changelog.a1d18eba0405":"<strong>Plugin CLAP chỉ nhận bánh xe MIDI trên cổng nói rằng nó hiểu MIDI</strong>, như chuẩn CLAP yêu cầu; một cổng chỉ nói sự kiện nốt riêng của CLAP không còn bị gửi MIDI mà nó không yêu cầu.","changelog.76148bf374f1":"<strong>Một tệp âm thanh có mẫu hỏng (giá trị not-a-number hoặc vô cực) sẽ phát im lặng ở chỗ đó</strong> thay vì đẩy chúng vào bản trộn.","changelog.d14ed914a63c":"<strong>Đường bao của các sampler giữ đúng thời gian.</strong> Một attack 10 ms trước đây mất 18 ms, và một attack 100 ms không bao giờ đạt mức đầy đủ. Việc đọc một mẫu âm cũng rẻ hơn khoảng một trăm lần, nên một bộ trống bận rộn không còn tốn hơn mức máy tính có.","changelog.dcc387d30b9e":"<strong>Amp Head không còn thêm một tiếng rè mờ</strong> vốn không có trong bản nhạc. Phần crossover class AB của nó, khi được đẩy ở Gain mặc định, giờ nằm thấp hơn bản nhạc thêm khoảng 20 dB, và bộ head tốn ít CPU hơn khoảng một phần năm.","changelog.de63c4379a3e":"<strong>Bản phối giữ thước và thanh công cụ trên màn hình.</strong> Lăn chuột trên các track hoặc trên tên của chúng chỉ cuộn các track, một thanh cuộn mảnh hiện ra bên cạnh khi không đủ chỗ cho tất cả, và thanh công cụ xuống dòng thay vì đẩy bản phối sang một bên trong cửa sổ hẹp.","changelog.b00b534eb987":"<strong>Lưới trống dùng được bằng bàn phím.</strong> Enter hoặc Space bật tắt một ô, và mỗi thanh velocity là một thanh trượt mà các phím mũi tên di chuyển. Một lần kéo chuột phải kết thúc bên ngoài lưới không còn mở trình đơn chuột phải riêng của cửa sổ (Quay lại, Làm mới, In), và một lần chạm biến thành cuộn không còn đặt một nhát đánh.","changelog.a95781e19fc6":"<strong>Trong phòng, chỉnh sửa của cộng sự vẫn nhanh trên một phần lớn hoặc một plugin nặng.</strong> Mỗi thay đổi nốt hoặc núm trước đây sao chép toàn bộ phần hoặc track mà nó chạm tới, cả trạng thái plugin và mọi thứ, nên một lần kéo trên track chứa plugin lớn có thể mất vài giây mới tới nơi.","changelog.71e443e94c1d":"<strong>Một plugin mà cộng sự đổi sang plugin khác rồi đổi lại sẽ quay về với âm thanh của chính nó</strong>, thay vì về mặc định.","changelog.f7cfe2b155f7":"<strong>Phòng không còn bị tách đôi</strong> khi một người gỡ một âm thanh mà người khác đang đặt lên các pad trống cùng lúc; mọi máy đều kết thúc với cùng một bài hát.","changelog.6a3c703c203f":"Chính sách nội dung của cửa sổ giờ cho phép trang đọc lại các địa chỉ <code>blob:</code> do chính nó tạo, nên các mô hình của sân khấu hiển thị đúng kết cấu. Không gì từ bên ngoài ứng dụng được phép vào.","changelog.b2ad26c2005b":"<strong>Trạng thái plugin của cộng sự không bao giờ tới một plugin khác.</strong> Khi một cộng sự chuyển một thiết bị sang plugin có tên khác, plugin đó bắt đầu ở mặc định thay vì được trao trạng thái của plugin cũ, và <em>Tải lại</em> trên một thiết bị đã trở thành plugin khác sẽ khởi động đúng plugin.","changelog.37b7bf5a7781":"<strong>Các bước kiểm tra của phòng không còn chậm đi khi bài hát lớn dần.</strong> Việc một cộng sự gỡ nhiều âm thanh, hoặc cả một track được ghi một lần, được kiểm tra trong thời gian tăng theo những gì đã gửi chứ không theo mọi thứ trong bài hát.","changelog.0777d6b7566d":"<strong>Trong phòng, một lần chỉnh sửa có hơn 1,024 thay đổi bị từ chối, kèm lời nhắc hãy làm thành nhiều phần nhỏ hơn.</strong> Máy của các cộng sự từ chối một lần chỉnh sửa lớn như vậy, và trước đây tính nó vào điểm trừ của người gửi. Hoàn tác và Làm lại cũng theo cùng giới hạn.","changelog.f930a12d52df":"<span class=\"release__meta\"><span class=\"release__ver\">v0.8.0</span><time class=\"release__date\" datetime=\"2026-10-30\">2026-10-30</time></span>","changelog.176a21a2f44e":"<strong>MIDI Master, Flipcopy và Takelight có sẵn trong bộ cài — chưa có bản tải xuống.</strong> Trình cài đặt của Oscillate giờ mang theo ba plugin Freally, làm plugin đi kèm của chính nó: Freally MIDI Master để viết các phần và cả bài hát, Freally Flipcopy để sao âm thanh thành MIDI và ngược lại, và Freally Takelight cho giọng hát.","changelog.506992d57adc":"<strong>Ba plugin Freally đi kèm Oscillate</strong>, được liệt kê là đi kèm trong mục Plugin của trình duyệt, không cần quét. Trình cài đặt đặt chúng vào các thư mục VST3 và CLAP của hệ thống, nên mọi DAW trên máy tính cũng tìm thấy chúng, và gỡ cài đặt Oscillate vẫn để chúng ở đó. Nó không bao giờ thay thế một bản mới hơn, hay một bản bạn tự cài.","changelog.f26b74a62345":"<strong>Một hướng dẫn</strong>, trong Trợ giúp, dẫn bạn qua cả ba trong bảy bước, mỗi bước chỉ vào đúng điều khiển thật: thêm MIDI Master vào một track MIDI, kéo một bài hát từ nó vào bản phối, sao chép bằng Flipcopy và đặt Takelight lên một giọng hát. Nó nói được cả 18 ngôn ngữ của Oscillate.","changelog.af2f024f12a2":"<strong>Thả cả một bài hát từ Song Mode của MIDI Master</strong> vào vùng trống, và nó đến thành mỗi phần một track, kèm các thay đổi nhịp độ của bài và một điểm đánh dấu cho mỗi đoạn. Một lần hoàn tác đưa tất cả trở lại.","changelog.352062423c22":"<strong>Nhập thành các phần.</strong> Một tệp âm thanh hoặc một <code>.mid</code> (từ trình duyệt, hộp chọn tệp, hoặc trình đơn riêng của một clip âm thanh) đi vào thành các track MIDI: giai điệu, hợp âm và bè trầm, không có trống.","changelog.3677012c1215":"<strong>Độ sẵn sàng thành hit</strong>, trong Xem: điểm từ A đến F cho bất kỳ bản phối nào, đọc từ các điểm đánh dấu đoạn của nó, kèm lời khuyên nên rút bớt phần nào trước điệp khúc. Các đoạn có thể được đặt tên bằng bất kỳ ngôn ngữ nào trong 18 ngôn ngữ của Oscillate.","changelog.16d08660e013":"<strong>Kéo track ra khỏi Oscillate</strong>, bằng tay cầm trên mỗi đầu track, vào một thư mục hoặc một DAW khác: dưới dạng MIDI (mỗi phần một tệp, hoặc một tệp duy nhất với Ctrl) hoặc dưới dạng âm thanh (mỗi track một stem kèm các plugin của nó, hoặc bản trộn với Ctrl).","changelog.b4fc9a1d1d3f":"<strong>Sidechain vào một plugin.</strong> Plugin có đầu vào sidechain, như Takelight, có thêm lựa chọn <em>Sidechain từ</em> trên thẻ của nó, để nó nghe được một track khác (beat, cho Auto Key của Takelight).","changelog.1b0e0cbf5f82":"<strong>Trình cài đặt giờ cài cho cả máy</strong>: một lời nhắc UAC, Oscillate vào Program Files. Bản <code>0.7.0</code> cài theo từng người dùng được thay thế.","changelog.be6892914a86":"<strong>Bản xuất mang theo mọi plugin bạn dùng.</strong> Bounce, stem và master giờ chạy ngoại tuyến từng plugin được host, nên một phần do plugin chơi không bao giờ im lặng trong tệp. Plugin bị thiếu hoặc gặp lỗi được nêu tên trong ghi chú của bản xuất.","changelog.884818bbcd38":"<strong>Mọi preset có sẵn, không chỉ âm thanh chính của mỗi nhạc cụ</strong>, đều tải được, nên một phần từ MIDI Master đến đúng âm thanh mà nó được viết cùng.","changelog.bc05f9aa575a":"<strong>Preset Wavetable chơi vibrato riêng của chúng</strong>, như trong MIDI Master. Núm Cao độ ở mức không đã tắt nó đi.","changelog.b69c8ebb18bf":"<strong>&quot;Chuyển thành MIDI&quot; trên clip không bắt đầu ở phách đầu</strong> đặt nốt đúng phách; trước đây chúng rơi sớm.","changelog.2633e1dc8bb9":"<strong>Plugin chơi nốt, như MIDI Master, phát ra âm thanh trong Oscillate</strong>, và các phần nó chơi được thu đúng phách thay vì trễ một khối.","changelog.0b2b3be5c0d7":"<strong>Plugin thay đổi độ trễ của nó</strong> (Takelight khi chuyển chuỗi) vẫn khớp thời gian với các track khác.","changelog.da4c4e9ff002":"<strong>Plugin bị thiếu giữ track của nó đúng thời gian.</strong> Một track có plugin bị thiếu từng phát sớm đúng bằng độ trễ của plugin đó.","changelog.274f7feb38d5":"<strong>Chỉnh sửa trong trình chỉnh sửa âm thanh và piano roll vẽ lại dòng thời gian ngay lập tức.</strong>","changelog.6c69e876d1d2":"<strong>Esc trên trình đơn chuột phải đóng trình đơn</strong> và không còn xóa luôn những gì bạn đã chọn trên dòng thời gian.","changelog.eff8a20b3835":"<strong>Xuất MIDI từ một dự án có đoạn chuyển nhịp độ giờ giữ nguyên thời gian của đoạn chuyển</strong>, nên trong DAW khác mọi nốt đều rơi đúng chỗ Oscillate phát nó. Trước đây đoạn chuyển đến dưới dạng một bước nhảy duy nhất, và mọi nốt sau đó đều bị trễ.","changelog.ae7d802659fb":"<strong>Xuất sang FLAC, OGG hoặc MP3 trên ổ đĩa đầy</strong> báo là thất bại, thay vì để lại một tệp bị cắt cụt và báo là đã ghi.","changelog.71eaab782086":"<strong>Trình cài đặt không bao giờ đi theo một liên kết bị cài vào các thư mục plugin của hệ thống.</strong> Ở nơi mọi người dùng đều ghi được vào các thư mục đó, một liên kết bị cài như vậy có thể đã khiến trình cài đặt, vốn chạy với quyền quản trị, ghi hoặc xóa tệp ở nơi khác.","changelog.1d5cbd1d6bbd":"<strong>Tệp MIDI thả lên bản phối sẽ bị từ chối nếu lớn hơn 4 MB</strong>, hoặc ngay khi nó chứa nhiều nốt, điểm đánh dấu hay thay đổi nhịp độ hơn mức một dự án chứa được, trước khi nó kịp làm đầy bộ nhớ của máy tính.","changelog.33ee0c5ec252":"<span class=\"release__meta\"><span class=\"release__ver\">v0.7.0</span><time class=\"release__date\" datetime=\"2026-10-28\">2026-10-28</time></span>","changelog.6380b0daebc4":"<strong>Một engine — chưa có bản tải xuống.</strong> Vẫn là DAW đó, giờ được dựng trên engine dùng chung của gia đình Freally thay vì trên các bản sao của nó. Bản <code>1.0.0</code> bên dưới được dựng để thử nghiệm và đã tạm gác lại: Oscillate đang lớn dần thành một DAW lớn hơn, từng bậc một, và đây là bậc đầu tiên trong các bậc mới.","changelog.f8f3a7bd4b47":"<strong>Các nhạc cụ đến từ thư viện dùng chung của gia đình Freally</strong>, đúng thư viện mà Freally MIDI Master chơi, được ghim ở một phiên bản thay vì sao chép. Mọi âm thanh có sẵn đều kết xuất y hệt như trước: cả 4.983 bản kết xuất thử nghiệm đều giống nhau đến từng byte.","changelog.94126c8f7ee2":"<strong>Con trỏ Freally:</strong> một vòng tròn có một chấm ở tâm. Chấm là nơi bạn nhấp và vòng tròn bám theo nó; nó to ra trên mọi thứ có thể nhấn và thu nhỏ khi bạn nhấn. Những con trỏ mang ý nghĩa, chẳng hạn ở các mép cắt gọt của clip, ở các thanh chia và trên văn bản, vẫn là con trỏ của hệ thống bạn.","changelog.ef160105ff0d":"<strong>Nút bật/tắt nhìn là biết ngay:</strong> xám khi tắt, trắng khi tắt và nằm dưới con trỏ, xanh Freally khi bật.","changelog.ae7560701556":"<strong>&quot;Chuyển thành MIDI&quot; hoạt động bằng chuột.</strong> Chọn nó bằng một cú nhấp trong trình đơn của clip không làm gì cả; chỉ bàn phím là dùng được. Clip đã chuyển đổi cũng được vẽ ngay, thay vì sau lần cuộn tiếp theo.","changelog.a63a6cbcf25f":"<strong>Hoàn tác, Làm lại và mở dự án vẽ lại các clip của chúng ngay lập tức.</strong> Một phản hồi nhanh có thể khiến dòng thời gian hiện các clip ở chỗ cũ của chúng.","changelog.664eefc3eae5":"<strong>Nhấp chuột phải lên một trình đơn clip đang mở</strong> không còn mở trình đơn riêng của trình duyệt đè lên nó.","changelog.336a4fd289a9":"<strong>Khung của ứng dụng và các thư viện đứng sau việc kiểm tra cập nhật đã được cập nhật</strong>, do tám khuyến cáo bảo mật được công bố trong tháng này nhắm vào chúng (<code>rustls</code> và <code>zip</code>).","changelog.77d42d7c2487":"<span class=\"release__meta\"><span class=\"release__ver\">v1.0.0</span><time class=\"release__date\" datetime=\"2026-10-09\">2026-10-09</time></span>","changelog.e0b00ac11c8b":"<strong>Phiên bản 1.0.0, được dựng để thử nghiệm — chưa có bản tải xuống.</strong> Mọi thứ trong bản ứng viên phát hành bên dưới, những lỗi mà đợt rà soát tìm ra, và hai cài đặt mà mọi ứng dụng Freally đều có.","changelog.ab16cb9401f9":"<strong>Tốc độ và Giảm chuyển động</strong> trong Cài đặt ▸ Giao diện, cặp cài đặt giống mọi ứng dụng Freally. <em>Nhanh</em> xoay tiêu đề nhanh gấp đôi; <em>Giảm</em> dừng mọi hiệu ứng chuyển động — cả màn hình khởi động — và giữ tiêu đề phẳng, bất kể hệ thống nói gì.","changelog.ac49a12e1f61":"<strong>Gửi báo cáo qua email.</strong> Khi giao diện gặp sự cố, <em>Gửi qua email</em> mở chương trình email của bạn với báo cáo gửi tới freallyproducts@gmail.com, đồng thời sao chép toàn bộ báo cáo. Nó thay cho một liên kết tới trang không hề tồn tại.","changelog.e088f2f8847a":"<strong>Hiệu ứng của dải kênh tắt dần tự nhiên.</strong> Đưa núm cuối cùng của dải về không không còn cắt phần đuôi Phòng hay Vọng hoặc gây tiếng tách; núm được tăng trong lúc phát sẽ vào mượt mà; các lần lặp sau của Vọng không còn bị mất; một chút Nhiệt không còn làm tối âm cao; và bật Phòng hay Vọng không còn có nguy cơ ngắt quãng ở tần số lấy mẫu cao.","changelog.3c2767adacb5":"<strong>Bản xuất theo đúng tự động hóa của dải</strong> chính xác như khi phát, nên một cú ném Vọng hay Nhiệt ngắn cũng có trong bản bounce.","changelog.4abd4bab9fc5":"<strong>Các bảng chuyển động đúng bằng độ dài âm thanh của chúng</strong>: 320 ms khi vào, 280 ms khi ra.","changelog.3882af1c3146":"<strong>Đồng hồ đo, núm xoay và phím:</strong> đèn đỉnh vẫn sáng khi vượt 0 dBFS; núm hiển thị giá trị khi được xoay bằng bàn phím hoặc con lăn; phím không còn bị giữ ở trạng thái nhấn khi tiêu điểm rời khỏi nó.","changelog.dea443b9c7d5":"<strong>Trình đọc màn hình</strong> lại đọc được cảnh báo mã phòng trên thẻ phiên và lời giải thích của khóa thang âm.","changelog.7ba875906742":"<span class=\"release__meta\"><span class=\"release__ver\">v1.0.0-rc</span><time class=\"release__date\" datetime=\"2026-09-25\">2026-09-25</time></span>","changelog.508d2f7ec832":"<strong>Đợt rà soát bản ứng viên phát hành ngày 24–25 tháng 9 năm 2026</strong> nằm ở trên cùng: một tính năng mới, các lỗi mà đợt rà soát tìm ra, và những gì giờ nghe khác đi trong một dự án đã lưu. Bên dưới là các bản sửa ngày 19 tháng 9, rồi <strong>bộ máy của bản beta</strong> (Giai đoạn 11), rồi <strong>mặt hiển thị, giọng nói, lượt và ghi công</strong> (Giai đoạn 9.5), rồi <strong>phòng</strong> (Giai đoạn 9), rồi <strong>công cụ sáng tác</strong> (Giai đoạn 8), <strong>thiết bị riêng của Oscillate</strong> (Giai đoạn 7), <strong>chạy plugin</strong> (Giai đoạn 6), <strong>các trình chỉnh sửa</strong> (Giai đoạn 5) và <strong>khung nhìn bản phối cùng dự án bên dưới nó</strong> (Giai đoạn 3 và 4, toàn bộ bậc <code>v0.2.0</code>).","changelog.b1f634b002e5":"Đã thay đổi — điều khiển, giao diện và âm thanh của gia đình Freally (2026-10-06)","changelog.cce1ebda3172":"<strong>Bộ phần cứng Blender, một độ rộng phím.</strong> Mọi núm xoay, fader, thanh trượt, công tắc bật/tắt, phím và phím chuyển giờ đều là bản dựng Blender từ sổ tay Freally, cả tối và sáng, đúng những tệp mà Freally Flipcopy dùng. Mọi nút vốn có dáng nút giờ là phím, tất cả cùng một độ rộng vừa mọi nhãn trong cả mười tám ngôn ngữ; các nút vẽ dạng chữ và cụm điều khiển phát vẫn giữ nguyên. Núm xoay là cùng một núm bạc chải xước ở cả hai giao diện.","changelog.be6f318c395c":"<strong>Bộ giao diện Freally.</strong> Bảng màu, các bảng nổi, hộp thoại và trình đơn kính cùng chữ biểu trưng đến từ bộ dùng chung. Màu xanh Freally dùng để tô và phát sáng; chữ và đường kẻ màu xanh dùng mực của nó. &quot;Hệ thống&quot; vẫn theo hệ điều hành.","changelog.00660e46fb29":"<strong>Âm thanh giao diện.</strong> Hộp thoại, bảng và cửa sổ tách rời phát âm thanh của gia đình cho mỗi chuyển động, qua đầu ra âm thanh và không bao giờ vào bản bounce. Cài đặt ▸ Chung ▸ Âm thanh giao diện tắt chúng.","changelog.6fae69200b7e":"<strong>Dải kênh của Freally Flipcopy trong bộ trộn</strong>: lưới núm xoay, một fader dài mảnh cạnh đồng hồ LED, rồi Solo và Mute, với kênh tổng ở tận cùng. Bảy núm của nó là hiệu ứng thật — Low, Mid, High, Room, Echo, Heat và Pitch Mod — được lưu, hoàn tác được, chia sẻ trong phòng và tự động hóa được; ở mức không, chúng không thay đổi gì. Lưới núm xoay được thu gọn cho đến khi phím <strong>Núm xoay</strong> hiện nó, và giá âm thanh phía trên bàn phím của piano roll xoay đúng các núm Phòng, Vọng, Nhiệt và Điều biến cao độ đó.","changelog.0e780ad471b9":"<strong>Mọi nơi khác, và MixSir.</strong> Cài đặt bật/tắt là công tắc được dựng hình, các phím bật/tắt nhỏ là phím chuyển, và bộ trộn trên điện thoại dùng cùng một bộ.","changelog.dc28fa7b5e37":"<strong>Các đàn piano âm học</strong> là bản được Freally MIDI Master làm lại. ⚠ Chúng nhỏ hơn 10–12 dB, và dự án đã lưu giữ cây đàn cũ cho đến khi được chọn lại.","changelog.7a5d4f56ddd0":"Thêm mới — bàn phím MIDI phần cứng chơi và thu được","changelog.e63d48df6d81":"⛔⛔ <strong>Chưa từng có thứ gì trong Oscillate mở một cổng MIDI.</strong> Mã trình điều khiển đã được dựng và kiểm thử nhưng không có gì gọi tới nó, trong khi README, lộ trình và câu chuyện lần chạy đầu đều nói <em>&quot;chơi bàn phím MIDI → ra tiếng&quot;</em> và Cài đặt ▸ MIDI thì nói tính năng này chưa có. Giờ nó đã có.","changelog.dcc8ae17c873":"<strong>Cài đặt ▸ MIDI liệt kê các đầu vào của bạn. Chọn một đầu vào</strong> và nó chơi track đang sẵn sàng thu y như bàn phím trên màn hình, và thu vào take theo cùng cách. Một chấm sáng lên khi có nốt tới, và mục này nói rõ khi không có track nào sẵn sàng thu.","changelog.fdebbbb5e13c":"<strong>Những gì nó truyền:</strong> nốt kèm velocity, pedal ngân, và các thông điệp khẩn (<em>All Notes Off</em> và <em>All Sound Off</em>), nên nút khẩn trên bàn phím sẽ dừng mọi thứ.","changelog.fe2865a6e325":"⚠ <strong>Pedal do Oscillate giữ, không phải nhạc cụ.</strong> Không nhạc cụ nào ở đây đọc pedal, nên Oscillate giữ lại các note-off cho tới khi nhấc pedal. Nó hoạt động như nhau trên mọi nhạc cụ, và một take đã thu giữ mỗi nốt dài đúng bằng lúc nó còn vang, chứ không chỉ bằng lúc phím còn được nhấn.","changelog.c6abb9b19ac3":"⛔ <strong>Chưa được truyền, và không làm giả:</strong> pitch bend, bánh xe mod và các bộ điều khiển khác, channel pressure, polyphonic aftertouch và program change. Các nhạc cụ nhận được bend và pressure; đường trực tiếp từ bàn phím tới chúng thì chưa. Pitch bend, bánh xe mod và pressure sẽ đến sau 1.0.","changelog.f17d5e0822ce":"<strong>Rút dây giữa chừng một nốt thì nốt dừng.</strong> Thư viện MIDI không báo sự kiện cắm hay rút, nên Oscillate kiểm tra mỗi giây một lần khi đã chọn một cổng: bàn phím đã biến mất sẽ nhả mọi nốt nó đang giữ và mục này hiện <em>chưa cắm</em>. Cắm lại thì nó tự kết nối lại theo tên.","changelog.4e160f9c55ef":"<strong>Lựa chọn được ghi nhớ</strong> trong <code>midi.json</code>, cạnh <code>audio.json</code>, và cổng được mở lại lúc khởi động trước khi cửa sổ xuất hiện. Khởi động khi bàn phím chưa cắm, Oscillate vẫn mở bình thường và nói rõ điều đó.","changelog.315f68af9cc8":"<strong>Cổng đang bị một ứng dụng khác giữ sẽ nói rõ</strong>, <em>không mở được</em>, kèm lý do của chính trình điều khiển, và kết nối ngay khi cổng rảnh.","changelog.34f38d764f89":"⚠ <strong>Giới hạn đã biết:</strong> rút ra rồi cắm lại trong cùng một lần kiểm tra một giây có thể để cổng hiện <em>đã kết nối</em> trong khi không có tiếng gì. Chọn lại cổng sẽ khắc phục.","changelog.942c6cb85fad":"<strong>Hai lỗi của bàn phím trên màn hình, được sửa luôn trên đường đi</strong> vì giờ cả hai loại bàn phím dùng chung một đường:","changelog.d2f0b8c7936a":"<strong>Bật sẵn sàng thu cho một track khác trong lúc đang giữ phím đã gửi lệnh nhả tới track mới</strong>, nên nốt trên track cũ cứ vang cho tới khi khởi động lại Oscillate. Giờ một nốt được nhả trên đúng track nó đã được chơi.","changelog.7634f305d478":"***All notes off<em> làm rỗng cả hàng đợi nốt</em>*, vứt luôn các lệnh nhả đang chờ của bàn phím kia.","changelog.19562cee5d4a":"Sửa lỗi — đợt rà soát bản ứng viên phát hành","changelog.9705daf96914":"▶ <strong><code>/simplify</code>, <code>/code-review</code> và <code>/security-review</code> trên toàn bộ cây mã thêm một lần nữa, rồi khoảng một chục lượt sửa.</strong> Hàng trăm lỗi đã được sửa, mỗi lỗi kèm một bài kiểm thử đã được thấy thất bại trước ở bất cứ đâu công cụ cho phép. Những lỗi tệ nhất được nêu trước. Mục <em>Thay đổi</em>, ở phía dưới, liệt kê những gì giờ nghe hoặc hoạt động khác đi trong một dự án bạn đã có.","changelog.9cfb8a7fe85a":"<strong>Tệ nhất</strong>","changelog.c3b3b0310b60":"⛔⛔ <strong>Trong ứng dụng bạn cài đặt, clip bản phối, clip MIDI và tự động hoá chưa bao giờ tới được engine, và đã như vậy từ 27 tháng 8.</strong> <code>main.rs</code> gọi <code>Builder::setup</code> của Tauri hai lần, và lần gọi thứ hai <strong>thay thế</strong> lần đầu chứ không cộng thêm vào. Lần đầu khởi chạy worker phát lại, Ra-đa che lấp và đồng hồ đo độ lớn, nên cả ba đều không chạy. Mọi bài kiểm thử đều đạt, vì không bài nào chạy builder. Giờ chỉ còn một lần setup, và một cổng kiểm tra (<code>the_builder_has_one_setup.rs</code>) từ chối lần thứ hai.","changelog.57f0db8ea734":"⛔⛔ <strong>Mọi bản xuất chỉ phát các nốt ở ngay đầu bài.</strong> Bản kết xuất ngoại tuyến không bao giờ di chuyển transport của chính nó. Một bản xuất thư mục đi kèm mang các nốt ở tick đầu tiên mà không có note-off, tự động hoá âm lượng bị đóng băng và các thiết bị đồng bộ nhịp độ chạy ở 120. Giờ bản xuất phát cả bài với bản đồ nhịp độ và tự động hoá âm lượng của nó, và clip âm thanh không còn cạn tiếng giữa chừng.","changelog.88021b53a47d":"⛔⛔ <strong>Mở lại một dự án khiến mọi plugin VST 3 và CLAP im lặng, và thiết lập riêng của plugin chưa bao giờ được lưu.</strong> Plugin chỉ được nạp khi bạn thêm một plugin hoặc mở cửa sổ của nó. Giờ chúng được nạp sau mỗi lần mở, hoàn tác, làm lại, nạp preset chuỗi và cập nhật từ người cùng phòng. Trạng thái của mỗi plugin được chụp lại trước mỗi lần lưu và khôi phục khi dự án mở.","changelog.cc2f0645818b":"⛔ <strong>Hiệu ứng khởi động lại năm mươi lần mỗi giây khi transport đang chạy.</strong> Worker phát lại dựng lại toàn bộ kế hoạch kết xuất mỗi 20 ms dù có gì thay đổi hay không, và mỗi lần dựng lại đặt lại mọi thiết bị đi kèm. Đuôi reverb bị cắt, compressor bắt đầu lại từ đầu, các giọng đang ngân bị rớt, và mỗi thiết bị trượt về từ thiết lập mặc định. Giờ kế hoạch chỉ được dựng lại khi có gì đó trong nó thay đổi, và lần dựng lại mang các thiết bị đang chạy sang thay vì thay thế chúng.","changelog.b8a809519ca1":"⛔ <strong>Vùng lặp không bao giờ lặp.</strong> Thước vẽ nó và dự án lưu nó, nhưng không có gì báo cho transport. Giờ việc phát quay vòng ở cuối vùng lặp, và âm thanh của clip không còn chạy quá cuối vùng lặp rồi phát trễ.","changelog.8e4359696cb2":"⛔ <strong>Hoàn tác, làm lại, mở dự án và chỉnh sửa của người cùng phòng không vẽ lại các cửa sổ khác.</strong> Piano roll, trình chỉnh sửa âm thanh, một bảng thiết bị đang mở và mọi cửa sổ tách rời vẫn hiện trạng thái cũ, và một lần cắt gọt thứ hai tính từ một khung nhìn cũ có thể ghi đè lần đầu. Giờ mọi thay đổi đều nhích một bộ đếm mà mọi cửa sổ đều lắng nghe.","changelog.991a518ad40a":"⛔ <strong>Sau Tệp ▸ Mở, đề nghị khôi phục sau sự cố không bao giờ xuất hiện, và lần Lưu kế tiếp xoá luôn nhật ký mà lẽ ra nó sẽ đề nghị.</strong> Giờ đề nghị này xuất hiện mỗi khi một dự án mở, và Lưu giữ lại nhật ký cho tới khi bạn trả lời.","changelog.72fcf1110d6e":"⛔ <strong>Các lỗ hổng bảo mật</strong>, tiếp theo.","changelog.bbc74b04e065":"<strong>Bảo mật</strong>","changelog.1b1ab848b297":"<strong>Một chỉnh sửa trực tiếp của người cùng phòng có thể chỉ định một tệp trên máy bạn</strong>, và Oscillate sẽ mở nó. Ảnh chụp từ người cùng phòng được làm sạch khi đi vào; từng chỉnh sửa đơn lẻ thì không. Giờ mọi chỉnh sửa đi vào đều bị gỡ đường dẫn tệp và trạng thái plugin, đúng như các chỉnh sửa đi ra vẫn luôn được xử lý.","changelog.db067cb38cfa":"<strong>Một đường dẫn mạng trong tệp dự án hoặc trong chỉnh sửa của người cùng phòng có thể làm lộ mã băm đăng nhập Windows của bạn</strong> khi bạn làm chủ phòng hoặc đọc một take, vì Windows tự đăng nhập vào thư mục chia sẻ mạng. Giờ mọi trình đọc đều kiểm tra rằng đường dẫn là một tệp trên ổ đĩa cục bộ <strong>trước</strong> mọi lời gọi hệ thống tệp, và từ chối thẳng thư mục chia sẻ mạng lẫn đường dẫn thiết bị.","changelog.a26ae554ba1a":"<strong>Một thành viên trong phòng có thể chiếm danh tính của thành viên khác</strong> bằng cách chuyển tiếp một lời mời kết nối dưới tên họ, và cùng với đó là phần ghi công của họ, các track được giao cho họ và các ô nhịp Kumite của họ. Việc này bị từ chối trong trang và một lần nữa trong tiến trình phòng.","changelog.2819dc6c2317":"<strong>Một dự án được mở, hoặc ảnh chụp từ người cùng phòng, tới luồng âm thanh mà không được kiểm tra.</strong> Một giá trị tự động hoá 1000 thành +60 dB, và gain 1000 dB thành vô cực. Giờ cả hai được kiểm tra hợp lệ khi tới. Hư hỏng không sửa được thì bị từ chối, số ngoài phạm vi bị kẹp lại, và bạn được báo những gì đã bị thay đổi.","changelog.52903827c85e":"<strong>Giờ mỗi người cùng phòng tự giới thiệu trực tiếp</strong> khi một liên kết mở ra, và đó là điều cho phép một trận đấu xếp chỗ cho tất cả mọi người. Lời giới thiệu đó gắn liên kết một lần, không bao giờ đổi tên nó, và không thể nhận là một người mà liên kết khác đã đại diện.","changelog.caedde91f452":"<strong>Pull request từ một bản fork không còn chạy trên máy dựng Windows tự lưu trữ</strong>, nơi giữ khoá ký của trình cập nhật.","changelog.bb6bf121bbd4":"<strong>Phát lại và engine</strong>","changelog.b8040300e667":"<strong>Nốt bị kẹt khi Dừng, khi đầu phát nhảy và khi vòng lặp quay lại.</strong> Giờ mọi nốt được nhả ở từng thời điểm đó, và một làn trống bị tắt tiếng trong lúc một nốt đang vang không còn giữ nốt đó lại.","changelog.60710aea2474":"<strong>Độ trễ riêng của một thiết bị nốt không được bù</strong>, nên một đoạn đi qua Tread phát trễ đúng bằng độ trễ đó.","changelog.af5806634af3":"<strong>Đầu phát trôi lệch khỏi âm thanh qua một đoạn đổi nhịp độ</strong>, vốn được tính trễ một đoạn. Một lần định vị ngắn di chuyển đầu phát nhưng để âm thanh ở nguyên chỗ cũ.","changelog.6c68d7fa128a":"<strong>Clip được đổi cao độ bị lách cách</strong> ở chỗ tệp được đọc theo từng khúc. <strong>Clip đảo ngược bị giật</strong> khi qua cuối tệp. Một lần fade-out bị đo sai qua chỗ đổi nhịp độ. Cắt gọt trước ô nhịp 1, hoặc trên một clip đã đổi cao độ, đọc nhầm phần của tệp, và phần đuôi của một lần tách đọc từ phần đầu của take.","changelog.6187aee593ac":"<strong>Một khe bàn trộn được dùng lại phát ra phần sót lại của track trước.</strong>","changelog.7f42837dfb17":"<strong>Đồng hồ đo và độ lớn chỉ đọc kênh trái.</strong> Một track pan hết sang phải không hiện gì, và các số liệu độ lớn bỏ qua bên phải. Giờ cả hai bên đều được đo.","changelog.75dc4a3bc8cb":"<strong>Giờ các số denormal được xả bỏ</strong> trên các luồng kết xuất, trực tiếp lẫn ngoại tuyến, nên một đoạn decay dài tắt dần về im lặng không còn làm bộ xử lý vọt tải. ⚠ Việc này cần một chỗ <code>unsafe</code> mới, <code>denormal.rs</code>, đã được chủ dự án rà soát và chấp thuận; <code>SECURITY.md</code> liệt kê nó.","changelog.3b1cc767fb75":"<strong>Lần nghe thử thứ hai có thể bắt đầu giữa chừng, hoặc không bắt đầu chút nào.</strong>","changelog.2e44dc9f2c04":"<strong>Xuất</strong>","changelog.aa4e4757d0fd":"<strong>Track bị tắt tiếng lọt vào bản trộn master.</strong>","changelog.dca6958b82dc":"<strong>Sau khi một track bị xoá hoặc đổi thứ tự, các phần được xuất rơi vào sai kênh.</strong>","changelog.0c77d58d7aa5":"<strong>Xuất làm xáo trộn việc phát trực tiếp.</strong> Nó dùng chính các luồng âm thanh của phiên, nên stem có thể mang âm thanh trực tiếp, và sau đó Phát bắt đầu từ sai chỗ. Giờ một bản xuất kết xuất từ các luồng của riêng nó.","changelog.927038d08ab5":"<strong>Tần số lấy mẫu bạn chọn bị bỏ qua.</strong> Mọi thứ đều được kết xuất và ghi ở 48 kHz; giờ nó kết xuất ở tần số đã chọn.","changelog.7a5894bfd40f":"<strong>Tệp AIFF khai gấp đôi tần số lấy mẫu của nó</strong>, nên phần mềm khác phát chúng cao lên một quãng tám. Giờ tệp float AIFF-C mang một header đầy đủ.","changelog.b85e29446f98":"<strong>FLAC 24-bit bị co giãn mức và dither sai.</strong>","changelog.81c39a6550b6":"<strong>Tệp <code>.mid</code> được xuất cắt cụt các nốt lặp lại trong DAW khác.</strong> Điểm bắt đầu của một nốt được ghi trước điểm kết thúc của nốt trước trên cùng một tick.","changelog.f92853678a37":"⚠ <strong>Bản xuất vẫn được kết xuất mà không có plugin VST 3 và CLAP.</strong> Xem <em>Vẫn còn mở</em>.","changelog.cdb5aaa35ee1":"<strong>Thu âm</strong>","changelog.cd64252ce063":"<strong>Một đầu vào 44.1 kHz dưới đầu ra 48 kHz thu ra có khoảng trống</strong>, khoảng 8% của take im lặng. Giờ đầu vào mở ở tần số của đầu ra, hoặc được chuyển đổi.","changelog.0c4683ccfd2e":"<strong>Độ trễ của một take thay đổi</strong> tuỳ theo đầu vào đã mở bao lâu.","changelog.18dc0df95ce2":"<strong>Take có đếm vào và take punch rơi trễ tới một bộ đệm</strong>, và khối ở điểm punch-out bị bỏ mất. Một lần punch MIDI giữ lại các nốt được chơi trước điểm punch-in.","changelog.b39ca3f1ef37":"**Một tệp được thả vào mà sao chép thất bại để lại một tệp dở dang trong <em>Imports</em>.**","changelog.f489fa7c6c3b":"Khoảng cách tối thiểu giữa các nốt của bộ phát hiện onset dài hơn một bước phân tích.","changelog.585177b8005b":"<strong>Plugin</strong>","changelog.9ea91ef0792f":"<strong>Thao tác vặn núm trong cửa sổ riêng của plugin VST 3 không bao giờ tới được âm thanh</strong>, và các thay đổi tham số vượt quá 512 trong một khối bị bỏ mất.","changelog.27e989498bde":"<strong>Hoàn tác việc gỡ một thiết bị sẽ trả lại âm thanh của nó như cũ.</strong>","changelog.27732aa68c31":"<strong>Xoá một track sẽ đóng các tiến trình plugin của nó</strong>, và một dự án mới hoặc vừa mở sẽ giải phóng các tiến trình của dự án trước.","changelog.3db09f2ff76a":"<strong>Một plugin bị sập hoặc treo có thể làm đứng ứng dụng.</strong> Giờ plugin bị lỗi được dừng trước khi Oscillate chờ nó, và không có khoá nào bị giữ khi một plugin khởi động. Lỗi trong kết nối điều khiển của plugin giờ được báo ra.","changelog.d5b5750c16ca":"<strong>Một plugin bạn định vị bằng tay không bao giờ được thêm vào chỉ mục</strong>, và một lần quét lại hoàn tác việc bỏ chặn cũng như các plugin được định vị trong lúc nó chạy.","changelog.8d834fbea6c9":"<strong>Plugin tự thay đổi độ trễ của nó</strong> giờ nhận một kế hoạch mới, có bù trễ.","changelog.750a21151bde":"<strong>Hộp thoại tệp chạy trên luồng chính</strong> (mở, lưu, lưu thành, preset chuỗi, <em>Định vị…</em>, thêm thư mục plugin, chọn thư mục nghe thử, nhập lời bài hát và âm thanh) và có thể làm cửa sổ bị khoá chết. Giờ tất cả đều chạy ngoài luồng chính.","changelog.78ee198e26b6":"<strong>Các trình chỉnh sửa</strong>","changelog.2b57535746ad":"<strong>Kéo mép cuối của một nốt giờ thay đổi độ dài của nó</strong>, và kéo điểm đầu sẽ dời điểm đầu mà giữ nguyên điểm cuối, trong một bước hoàn tác.","changelog.eb080b94fcd5":"<strong>Kéo chéo một nốt, và kéo chéo để sao chép, đều là một bước hoàn tác</strong>, và kéo với <code>Ctrl</code>/<code>Alt</code> sẽ sao chép thay vì di chuyển.","changelog.33cf4310ae9b":"<strong>Làn tự động hoá bên dưới một clip không nằm ở ô nhịp 1 lại vẽ và ghi các điểm của nó ở ô nhịp 1.</strong> Giờ nó làm việc ở đúng vị trí thật của clip. Dưới một bộ trống, nó không còn đi theo thanh cuộn của piano roll bị ẩn, và <em>Lưu thành Kata</em> cùng <em>Đóng dấu</em> bao trọn đúng khoảng của clip.","changelog.a75d2252b98e":"<strong>Làm im một khoảng bên trong một đường bao gain nhỏ lại làm âm thanh xung quanh nó phình lên.</strong> Giờ tách, cắt hoặc cắt gọt bên trái một clip đều giữ đường bao gain của nó ở đúng chỗ âm thanh.","changelog.b4c012d3b380":"<strong>Dấu transient trên một clip đã tách hoặc cắt gọt hiện những nhát đánh mà clip không phát.</strong> Một lần cắt gọt từ trình chỉnh sửa âm thanh giữ nguyên độ lệch của lần cắt gọt trước, kể cả trong cửa sổ trình chỉnh sửa tách rời. Trình chỉnh sửa âm thanh không còn vẽ một khung cũ sau khi thu phóng, hay vẽ xuôi một clip đảo ngược ở mức thu phóng từng mẫu.","changelog.14e60b4dae34":"<strong>Trong bản phối</strong>, một clip đã chọn bị cuộn khuất khỏi tầm nhìn bị thả nhầm chỗ khi di chuyển hoặc sao chép, và một lần cắt gọt bên trái có thể chạy quá đầu âm thanh và kéo nó lên sớm. Một lần cắt gọt hoặc fade xem trước cả vùng chọn trong khi chỉ clip được nắm thay đổi; giờ bản xem trước cho thấy đúng những gì sẽ xảy ra khi thả chuột. Một thao tác bị hệ điều hành huỷ đã được ghi nhận thay vì bị bỏ.","changelog.3e8ed6000a39":"<strong>Thao tác nhấp-và-quét của lưới trống chỉ chạy trong trình duyệt kiểm thử</strong>, và nhấp chuột phải không còn bật tắt một ô.","changelog.c83a3388d770":"<strong>Gõ giá trị vào một núm vặn</strong>: 6 dB giờ nghĩa là 6 dB, không phải hết hành trình, và 50 trong ô pan không còn nghĩa là R100.","changelog.ca7b3b7fb67d":"<strong>Bàn phím trên màn hình và một phím tắt cùng chữ cái đều kích hoạt cùng lúc.</strong> Phím mũi tên trong danh sách trình duyệt và trên thước bị lọt xuống thành xê dịch bản phối.","changelog.4ecad0ceceaa":"<strong>Điều khiển phát ▸ Home, End, Con trỏ và Lưỡi dao không làm gì cả.</strong>","changelog.8872f6e3c7a1":"<strong>Nhấn Tab ra khỏi một dòng lời xoá mất nhịp âm tiết của nó.</strong> Một dòng lời được thả đúng vào điểm bắt đầu của dòng khác không còn bị từ chối.","changelog.c967a14cb0d7":"<strong>Giá pattern</strong> làm mới sau hoàn tác, làm lại và chỉnh sửa của người cùng phòng, và bộ chọn pattern mở ra ở pattern hiện tại.","changelog.9b72ff0fe3e8":"<strong>Tiếng Ả Rập</strong>: thanh cuộn, thanh chia, làn lời bài hát và thẻ phiên bị lật gương sai.","changelog.0af10661d846":"<strong>Mọi câu có chứa số đều có dạng số nhiều</strong> trong cả mười tám ngôn ngữ.","changelog.b58312a40a18":"<strong>Những lỗi nhỏ hơn:</strong> đầu phát khi nghe thử <code>.mid</code> chạy gấp đôi tốc độ; một tệp <code>.mid</code> được thả vào có nốt đầu ở vị trí không thì rơi trễ một tick; một lần quét làn CC đi ngoằn ngoèo; tay cầm fade dài bằng không không nắm được; kéo chiều cao track vẫn lệch sau một lần bị từ chối; WAV số nguyên 32-bit, và âm thanh 24-bit trong vỏ 32-bit, được vẽ và phát ra như nhiễu toàn thang.","changelog.ea7aa3c36986":"<strong>Thiết bị và nhạc cụ</strong>","changelog.d838f5d0cc47":"<strong>Vặn một núm trên nhạc cụ có sẵn (Cello, Sub Bass và các nhạc cụ khác) biến nó thành một synth Wavetable mặc định</strong>, và hoàn tác không đưa nó trở lại. Giờ nhạc cụ có sẵn mở một bảng điều khiển, hiện hàng núm âm sắc của nó, và sao chép ra một công thức có ghi tên nó.","changelog.618828dda056":"<strong>Chamber và Vault mất ổn định ở thiết lập mặc định.</strong> Nút Low Decay của chúng có thể làm reverb phình lên vô hạn. <em>Freeze</em> giờ không tắt dần mà cũng không phình lên.","changelog.96ae9147c9a5":"<strong>De-esser Quench lúc nào cũng làm việc</strong>, không chỉ trên các âm xì.","changelog.a33e5317a331":"<strong>Các lần lặp của Relay trôi trễ dần theo mỗi tiếng vọng</strong>, Sparks lách cách ở thiết lập mặc định, Gild lách cách giữa các khối, và Ceiling đặt một mức gain cho mỗi khối. Bộ oversampling dùng chung bị trục trặc ở ranh giới khối với cỡ bộ đệm mặc định, ảnh hưởng tới mọi drive, amp và saturator.","changelog.0b69c04327da":"<strong>Feedback có thể vượt tầm kiểm soát</strong> trong Shoal và Relay và khoá track vào im lặng.","changelog.c9fc79327515":"<strong>Các nút điều khiển từng không làm gì giờ đã có tác dụng:</strong> Grid Bias của Guard, Diffusion của Vault, Tension của Coil trên toàn dải, Driver Position của Foil, Medium của Wear và Oversample của Ceiling.","changelog.f73ae6f614ed":"<strong>Cũng được sửa:</strong> Halve và Flush của Lantern, Rein ở thời gian vọng bằng không hoặc đang thay đổi, Comb khi đi qua không, ngưỡng của Strand, và tín hiệu khô trong Cleave và Strand, vốn không được làm trễ cho khớp với tín hiệu đã xử lý.","changelog.d3d9ad692654":"<strong>Không còn nốt bị kẹt</strong> từ Scatter, Turn, Hone, Stack, Approach, Hold, Tread, Runner hay Revoice, và các thiết bị nốt giờ chơi như nhau bất kể cỡ bộ đệm âm thanh.","changelog.039ca12ebc31":"<strong>Hammer</strong> phát tiếng ở Hold 0 và không còn tăng gấp đôi mức khi kích lại; <strong>một giọng sampler bị cướp sẽ tắt dần</strong> thay vì lách cách; tiếng vỗ tay của Skin đi theo velocity; Feedback của Sideband hoạt động trên cả tám thuật toán; Armory không còn sập ở trên nốt 127. Mọi lần trượt của mọi nhạc cụ giờ đều mượt bất kể cỡ bộ đệm.","changelog.bf11fb10bbc6":"<strong>Các đường cong trên thẻ thiết bị</strong> được đo khi thiết bị vẫn đang trượt giá trị, nên chúng sai.","changelog.74b1e2eb3733":"<strong>Phòng và phiên</strong>","changelog.a0322da52ba0":"<strong>Một trận Kumite chỉ tồn tại trên máy đã nhấn Bắt đầu.</strong> Clip của người cùng phòng trong các ô nhịp của chính họ bị bỏ đi không một lời, và thứ tự lượt có thể khác nhau giữa các máy. Giờ trận đấu là một phần của dự án, do chủ phòng bắt đầu và dừng, và như nhau trên mọi máy.","changelog.221c7bfd4bd2":"<strong>Take:</strong> một take bạn đã có không còn bị tính vào chủ phòng; các take tới cùng lúc không còn bị mất; một lần truyền không còn gây mất tiếng; tệp take ghi dở được xoá đi.","changelog.ca86740f15d8":"<strong>Mọi thông điệp trên một liên kết do máy này đề nghị đều được xử lý hai lần.</strong>","changelog.97e5f228e6ba":"<strong>Micrô có thể vẫn bật trong khi nút của nó nói là đã tắt</strong>, sau khi một lần ghi khác bị dừng. Nhấn-để-nói cũng kích hoạt trong lúc bạn gõ vào ô văn bản.","changelog.4a064c4a34ce":"<strong>Tua lại phiên</strong> làm đứng ứng dụng trong khi phát lại. <em>Hoàn tác đến đây</em> chỉ hoàn tác một bước và giờ hoàn tác tới đúng điểm đó; <em>Trở về hiện tại</em> khôi phục bản phối đang sống; một nhánh thất bại sẽ nói rõ.","changelog.3d5138762144":"<strong>Bảng chia phần</strong> gọi tên hàng của chính bạn, làm mới khi có người cùng phòng khác tham gia, và không còn ghi công phần khung sườn của mẫu cho bất kỳ ai.","changelog.c893c1638a99":"<strong>Các chỉnh sửa có thể làm hỏng một phiên:</strong> một lần ghi toàn bộ thứ tự track có thể làm rớt track; xoá một track hoặc một clip để lại các hàng pattern trỏ vào hư không, nên mọi thao tác giá về sau trên pattern đó đều bị từ chối; một take vẫn đang được dùng trên track khác có thể bị xoá; hai máy có thể bất đồng vĩnh viễn khi một máy sửa cả một track trong khi máy kia sửa thứ gì đó bên trong nó; một clip được dời sang track mà người khác đang giữ bị kiểm tra theo nhầm track.","changelog.8dfa12545efa":"<strong>Một chỉnh sửa ngay sau khi lưu không đánh dấu dự án là chưa lưu</strong>, và một chỉnh sửa nhanh có thể bị gộp vào một lần hoàn tác hoặc làm lại.","changelog.5fe00713937b":"<strong>Các phần của tệp do một bản Oscillate mới hơn ghi ra giờ được giữ lại sau khi lưu.</strong>","changelog.eb5b0a0ed3af":"<strong>Vào lại một phòng</strong> không còn ghi nối vào nhật ký của phiên trước.","changelog.80a4afa3903d":"Bản tua nhanh của một phiên bắt đầu từ mẫu không còn mở đầu bằng một chương <em>Đã mở phòng</em> giả; bước kiểm tra kết nối không còn báo một NAT đối xứng không hề có; người thứ năm không còn vào được phòng.","changelog.bf9104f16adc":"<strong>Cửa sổ và cài đặt</strong>","changelog.f478b946c3ed":"<strong>Các cửa sổ tách rời ghi đè cài đặt của nhau.</strong> Giờ cài đặt được ghi từng khoá một, dưới một khoá chung, và mọi cửa sổ đọc lại chúng.","changelog.0e7572903a98":"<strong>Thoát khi đang thu nhỏ làm mất vị trí và kích thước cửa sổ.</strong>","changelog.3d17c7fddadd":"<strong>Hai báo cáo sự cố được ghi cùng lúc ghi đè lên nhau.</strong>","changelog.8ad92ece2e49":"<strong>Nhật ký khôi phục được xả xuống đĩa khi Oscillate thoát</strong>, khi bạn dừng, và khi một take được ghi xong.","changelog.09d6b687a5b5":"<em>Có, kiểm tra khi khởi động</em> ở câu hỏi lần chạy đầu bị lặng lẽ từ chối, và một lần cài cập nhật thất bại biến mất không một lời.","changelog.166249aead89":"Gán <code>Space</code> trong Cài đặt ▸ Phím tắt cướp mất Phát; một màn hình lỗi thay chỗ thanh tiêu đề nên không đóng được cửa sổ; một cửa sổ có thể vẫn chưa được co giãn sau một lần kéo bị ngắt giữa chừng.","changelog.42078e2a4ce9":"<strong>Trình cập nhật và công cụ phát hành</strong>","changelog.079af0dc6c83":"<strong>Windows lẽ ra đã không có manifest cập nhật nào cả.</strong> Script phát hành tìm những tên trình cài đặt mà Tauri 2 không tạo ra.","changelog.ec17b741d16a":"<strong><code>1.0.0</code> lẽ ra đã khớp với các trình cài đặt <code>1.0.0-rc</code></strong>, nên manifest của bản phát hành chính thức có thể đã trỏ vào bản ứng viên phát hành mãi mãi.","changelog.12c5a28c6a09":"<strong>Một tag bản ứng viên phát hành không dựng được trình cài đặt</strong>, vì MSI từ chối phiên bản tiền phát hành. Giờ bản tiền phát hành chỉ dựng NSIS.","changelog.df7f1b0ff2d6":"<strong>Ghi chú phát hành bị cắt ra bằng so khớp tiền tố</strong>, nên <code>1.0.0</code> lẽ ra đã lấy ghi chú của bản ứng viên phát hành, và thiếu ghi chú chỉ gây cảnh báo. Giờ nó lấy đúng mục của phiên bản này, và nếu thiếu thì bản phát hành thất bại.","changelog.88312da3637b":"<strong>Những cổng kiểm tra không thể thất bại, hoặc chẳng chạy ở đâu:</strong> bước kiểm tra tương đương của CI thiếu target WebAssembly; bước kiểm tra tải về thất bại với mọi bản phát hành chỉ có Windows; kiểm thử đầu-cuối trong hai tệp không thể thất bại; chạy kiểm thử đầu-cuối ghi đè ảnh chụp màn hình của tài liệu; trang nhật ký thay đổi được công bố mang id mục bị trùng. Một cổng kiểm tra mới từ chối ký tự điều khiển trong nhật ký thay đổi và tài liệu.","changelog.da13fe88f9b4":"<strong>Tìm ra khi rà soát chính các bản sửa</strong>","changelog.d52c1048f2f9":"⚠ Mọi bản sửa ở trên đều được rà soát lại sau khi đưa vào. Các đợt rà soát đó tìm ra những hồi quy thật trong các bản sửa, và vài lỗi cũ hơn mà lượt đầu đã bỏ sót. Tất cả đều được sửa ở đây.","changelog.8f27c8f6a2dc":"⛔⛔ <strong>Sau khi một track bị gỡ hoặc một dự án được mở, bàn phím trên màn hình, bàn phím MIDI và phần nghe thử nốt của piano roll chơi nhầm track hoặc không chơi gì, và thu âm chẳng ghi được gì.</strong> Nốt trực tiếp được gửi theo id của kênh trong khi engine đọc chúng theo vị trí, và hai thứ này chỉ khớp nhau cho tới khi track đầu tiên bị gỡ. Giờ nốt tìm track của mình theo vị trí, được đọc lại sau mỗi thay đổi, và một phím đang giữ khi một track bị gỡ sẽ được nhả trên đúng track của nó.","changelog.0e5001be4975":"⛔ <strong>Khi bật vòng lặp, các nốt MIDI ở đầu vòng lặp bị bỏ mất ở mọi lần lặp sau lần đầu.</strong> Clip âm thanh thì không sao. Giờ việc lên lịch nốt đã biết về vòng lặp.","changelog.4dd4a9484523":"⛔ <strong>Chỉnh sửa trong phòng chạm vào nhiều thứ cùng lúc có thể rơi xuống khác nhau trên các máy khác nhau, vĩnh viễn và lặng lẽ</strong> (dời hai clip trong khi ai đó đổi màu một clip, hoặc xoá một track trong khi ai đó sửa pattern của nó). Giờ mỗi chỉnh sửa bên trong một thao tác được giải quyết riêng, và một cổng kiểm tra mới phát lại ba máy qua mọi thứ tự tới.","changelog.73da74cfe8a0":"⛔ <strong>Một người cùng phòng có thể chiếm <code>Ctrl+Z</code> của bạn</strong> bằng cách dùng lại id của chỉnh sửa gần nhất của bạn. Giờ một id đã thuộc về người khác sẽ bị từ chối, và người dùng lại sẽ phải trả giá.","changelog.3496697e7b5b":"⛔ <strong>Lưu có thể làm sập một plugin có thiết lập lớn hơn khoảng 19 MB, và mỗi lần lưu lại chứa thêm một bản sao đầy đủ của track trong tệp dự án</strong>, nên tệp phình ra vô hạn. Giờ thiết lập plugin được truyền dưới dạng byte và chỉ được giữ một lần trong tệp đã lưu: không bao giờ trong lịch sử hoàn tác, không bao giờ trong phòng.","changelog.f26a96f70549":"<strong>Plugin:</strong>","changelog.6efbe93b609b":"Plugin từ chối thiết lập đã lưu của nó không còn bị lưu đè thiết lập mặc định lên thiết lập của bạn.","changelog.3d2817502593":"Độ trễ do plugin báo không còn đánh dấu dự án là đã thay đổi, thêm một bước hoàn tác, hay xoá thiết lập plugin của cộng sự.","changelog.c4b6e7b8714a":"Một plugin chậm một lần không còn bị coi là đã sập, và một plugin trả lời tức thì không còn bị nhầm là đang đứng và bị nạp lại.","changelog.ae1ae60b6520":"Hoàn tác và làm lại đưa plugin trở lại với đúng thiết lập chúng từng có, kể cả khi một cộng sự đã xoá track rồi hoàn tác, và khi plugin vắng mặt vào lúc đó.","changelog.5dc3a7247bfd":"Thay đổi preset VST 3 di chuyển hơn 128 tham số giờ đều tới được âm thanh, và plugin không còn bị khởi động lại mỗi khối. Một lần khởi động lại VST 3 không còn vứt bỏ các thay đổi khác mà plugin đã thông báo trong lúc đó.","changelog.1396f179afdf":"Plugin đi theo tần số lấy mẫu của thiết bị âm thanh.","changelog.39e285644bd7":"Hộp thoại tệp thuộc về cửa sổ chính và mở từng cái một. Lưu thành sẽ từ chối nếu dự án bị sửa hoặc bị thay thế trong lúc hộp thoại đang mở, và Mở không còn bị từ chối chỉ vì một cộng sự đã chỉnh sửa trong lúc đó.","changelog.ba3a925735d4":"<strong>Phát lại và thu âm:</strong>","changelog.ac75155693e0":"Rút ra rồi tiếp tục thiết bị âm thanh, hoặc đổi nhịp độ khi đang phát, không còn để âm thanh lệch nhịp với đầu phát.","changelog.cfe7e8319c5a":"Track được bù độ trễ của plugin không còn mất tiếng mỗi khi bản trộn được dựng lại hoặc vòng lặp quay lại.","changelog.99bca8f464be":"Phím bạn đang giữ không còn bị cắt khi vòng lặp quay lại hoặc đầu phát di chuyển.","changelog.d98cd614c1dc":"Nốt chơi trong lúc đếm vào không còn dồn đống lên phách đầu tiên của take. Một nốt chơi ngay trước phách mạnh (trong vòng một khối hoặc 30 ms) được giữ lại và rơi đúng vào phách đó.","changelog.e786b3ffa54c":"Một lần gọi lại đầu vào hơi trễ không còn để lại khoảng trống trong bản thu, và việc giám sát đầu vào không còn mất tiếng vài mili giây mỗi khi phần tồn đọng đầu vào bị cắt bớt.","changelog.ee43b80e51fe":"Nốt có thiết lập Xác suất không còn lặp lại đúng mẫu mà lượt vòng lặp kế tiếp lẽ ra sẽ chơi sau khi bạn dời đầu phát.","changelog.ae9faf402cfe":"Giao diện âm thanh nhiều kênh không còn tráo đổi đầu vào sau một lần tràn bộ đệm.","changelog.a28c78da2430":"Đầu vào có tần số lấy mẫu cao không còn bị răng cưa khi vào một phiên có tần số thấp hơn.","changelog.66785b97f53f":"<strong>Xuất:</strong>","changelog.e230adbb4330":"MP3 trên 48 kHz thất bại sau khi cả bài đã kết xuất xong. Giờ MP3 được ghi ở 48 kHz, và Cài đặt ▸ Xuất nói rõ điều đó.","changelog.6e5025c21bdc":"Một bản xuất bị từ chối giờ cho bạn biết lý do bên dưới menu Tệp; trước đây nó thất bại trong im lặng.","changelog.1de1be9b8ded":"Một thiết bị đọc trước không còn làm bản xuất bắt đầu trễ và mất phần cuối.","changelog.69d54e8f37b8":"MIDI trong bản xuất không còn trôi sớm sau một lần đổi nhịp độ hoặc đoạn chuyển nhịp độ.","changelog.a4184301f89d":"<strong>Công tắc Dither bị bỏ qua:</strong> mọi bản xuất 16 và 24-bit đều bị dither kể cả khi tắt. Giờ nó được tôn trọng, và các stem mang dither độc lập.","changelog.01060597d526":"Tệp kéo vào từ thư mục tạm không còn để lại bản sao trong Imports.","changelog.1181bbddc23a":"Bảng Độ lớn không còn gọi mọi số liệu là &quot;chưa đầy đủ&quot; ở 88.2 kHz trở lên.","changelog.0f052d7de643":"<strong>Phòng và phiên:</strong>","changelog.ce576eef99b0":"Ai cũng có thể kết thúc một trận Kumite, kể cả trận mà chủ phòng đã rời đi, và trận đấu không bao giờ được lưu vào tệp dự án; hai lần Bắt đầu cùng lúc được gộp thành một trận.","changelog.9a242815cb22":"Vào một phòng với một dự án bạn cũng có trên đĩa không còn xoá dữ liệu khôi phục sau sự cố của dự án đó.","changelog.e1a82a286154":"&quot;Hoàn tác đến đây&quot; trong phòng gửi mọi lần hoàn tác tới các nhà sản xuất khác, và lấy lại cả những thay đổi bạn đã làm lại sau thời điểm đó.","changelog.152a9fa8944c":"Một take bị cắt ngang vì sự cố sẽ tới nơi ở lần gửi kế tiếp.","changelog.b58ba06bb488":"Khôi phục sau sự cố giữ lại lần kéo fader của cộng sự mà chính chỉnh sửa của bạn đã chen ngang.","changelog.db0e3ba74f7a":"Mở một dự án bên trong phòng không còn để các chỉnh sửa cũ hơn của người cùng phòng ghi đè lên nó; vào lại phòng không còn làm bạn bị tính một lỗi vi phạm.","changelog.121c95328780":"Hai lần vặn riêng biệt trên cùng một núm là hai bước hoàn tác, không phải một.","changelog.731cf5b68562":"Các cửa sổ tách rời không còn hoàn tác kích thước bảng, phím tắt hay thiết lập xuất của nhau.","changelog.19fbc09eb565":"Tệp ▸ Mới không còn đề nghị khôi phục phiên bạn vừa rời.","changelog.9e2773fb1867":"Một núm bạn vặn trên thiết bị mà cộng sự đang kéo sẽ giữ giá trị của nó trên mọi máy, và một fader hoặc núm bị kéo đi rồi kéo về đúng chỗ ban đầu sẽ tới được phòng thay vì làm bạn bị tính một lỗi vi phạm.","changelog.0541b65c1e83":"Một track hoặc take bị xoá trong lúc cộng sự đổi màu hoặc fade một clip của nó sẽ biến mất trên mọi máy, và hoàn tác một lần xoá trong lúc cộng sự thay đổi chính clip đó sẽ đưa nó trở lại trên mọi máy.","changelog.d15a8772edef":"Bounce nhiều clip MIDI thành âm thanh cùng lúc giờ tới được các nhà sản xuất khác, và một pattern từng phát hai clip trong số đó không còn tiếp tục gọi tên một clip.","changelog.622a2b984e68":"Kết thúc một trận đấu do người khác bắt đầu không còn làm <code>Ctrl+Z</code> ngừng hoạt động, và một khách rời phòng không còn kết thúc trận đấu của chủ phòng cho tất cả mọi người.","changelog.0603f0c1588b":"Một nhà sản xuất vào lại phòng giữ được các chỉnh sửa đã làm trong lúc kết nối lại, tên và chỗ ngồi trong trận đấu của họ trở lại ngay khi liên kết cũ của họ mất đi, và người thứ hai tự nhận danh tính của họ không còn chiếm được nó.","changelog.f1a8d7a6d26e":"Một chỉnh sửa bị từ chối của người cùng phòng không còn để máy này dùng lại con dấu của nó, và chấp nhận khôi phục sau sự cố bên trong phòng không còn để các chỉnh sửa cũ hơn của người cùng phòng ghi đè lên phần việc đã khôi phục.","changelog.c8981d80a918":"<strong>Trình chỉnh sửa:</strong>","changelog.e708a20db8e5":"Lần kéo núm đầu tiên trên nhạc cụ của một dự án cũ (ví dụ một Cello có sẵn) là một bước hoàn tác, và trong phòng nó không còn ghi đè chỉnh sửa của cộng sự trên track đó.","changelog.102d708d0039":"Bên dưới lưới trống, làn tự động hoá thẳng hàng với các bước.","changelog.8febd9bab766":"Một dòng lời được thả đúng vào điểm bắt đầu của dòng khác sẽ được đặt sau dòng đó, và không có gì khác bị dời đi.","changelog.1a424e0ded88":"Tệp WAV có header định dạng ghi một thứ khác ngoài PCM thuần hoặc float sẽ bị từ chối kèm thông báo thay vì được phát ra như nhiễu.","changelog.08c29531d3c4":"Một hàng pattern có clip đã bị gỡ sẽ không hiện clip nào, thay vì một clip không tên không mở được.","changelog.3c2daf0d3e7f":"<strong>Đầu vào MIDI:</strong> phím được chơi trong lúc một track không có chỗ phát đang sẵn sàng thu sẽ bị từ chối thay vì bị dồn lại rồi phát ra một lượt sau đó; hai bàn phím giống hệt nhau đều chọn được; Cài đặt ▸ MIDI không còn bị đứng vì một trình điều khiển chậm.","changelog.412206443be0":"Thay đổi — những gì nghe khác đi trong một dự án đã lưu","changelog.6459a83979a9":"⚠ <strong>Một dự án được lưu trước bản dựng này có thể nghe khác đi khi bạn mở nó.</strong> Mỗi mục dưới đây là một bản sửa, và vài mục làm dịch mức âm vài decibel, nên hãy kiểm tra bản mix nào bạn quan tâm.","changelog.d2730738dfc9":"<strong>Thu âm bỏ qua vòng lặp.</strong> Trong khi bạn thu, vòng lặp tắt, cho cả âm thanh lẫn MIDI, và take chạy thẳng qua cuối vòng lặp. Vòng lặp vẫn áp dụng cho việc phát. Trước đây, mỗi lượt của một bản thu có vòng lặp được ghi nối đuôi nhau, và take MIDI không khớp với take âm thanh.","changelog.15f909e8e1c8":"<strong>Một bản xuất có thể dài tới mười phút ở bất kỳ tần số lấy mẫu nào.</strong> Nó bị từ chối ngay từ đầu, kèm lý do, nếu máy không đủ bộ nhớ để chứa. Trước bản dựng này giới hạn là mười phút ở 48 kHz, và bản xuất bỏ qua tần số bạn chọn.","changelog.3d3d8119cb3d":"<strong>Độ trễ của Ceiling là 100 mẫu ở thiết lập mặc định (trước là 72)</strong>, và bộ chọn Oversample giờ thay đổi được nó. Những gì Ceiling khai báo là phần đọc trước của nó cộng với độ trễ riêng của bộ phát hiện, nên bù trễ plugin căn nó thẳng hàng.","changelog.18563098f694":"<strong>Comb:</strong> chế độ qua không bật theo mặc định, và tâm quét thấp hơn một nấc Delay.","changelog.429dc9a41e0f":"<strong>Tension của Coil</strong> giờ ánh xạ 0 thành 1.92 (trước là 1.2) và 1 thành 0.75 (trước là 1.0); 0.5 không đổi.","changelog.42ca15cb09d8":"<strong>Wear, Spool và Oxide:</strong> thành phần 6 Hz giờ đáp theo Flutter thay vì Wow. Các chất liệu Vinyl và Converter của Wear là âm thanh mới; Tape không đổi.","changelog.9605e8d810a8":"<strong>Sparks:</strong> grain giờ là các cửa sổ Hann sạch khi đám mây thưa và ở thiết lập mặc định, nên hình dạng grain thay đổi kể cả khi bạn chưa từng chạm vào nó.","changelog.a2fb1a26818a":"<strong>Guard</strong> chỉ mở trong phạm vi Grid Bias của nó quanh một nốt.","changelog.ee039b997faa":"<strong>Vise, Weld, Parry, Peen và Guard:</strong> sidechain được lọc trước khi đo, nên ngưỡng thực tế dịch đi vài decibel.","changelog.4415b1af6ee9":"<strong>Quench</strong> khử âm xì với mức khác trước.","changelog.2d621f5fc3be":"<strong>Edge:</strong> Attack và Release giờ chậm hơn bốn lần, đúng như nhãn ghi.","changelog.c091d1c40cb7":"<strong>Triode, Rasp, Shear và Fold:</strong> bass và độ sụt thay đổi ở mức oversampling cao. <strong>Furnace:</strong> thời gian sụt thay đổi.","changelog.3875af7ad8a2":"<strong>Chamber, Foil, Coil, Vault và Baffle:</strong> các điểm lấy ra của reverb thay đổi, nên mức âm và hình ảnh stereo dịch chuyển. Trường âm muộn của <strong>Vault</strong> giờ bắt đầu ở pre-delay, và các bộ khuếch tán của nó ngắn hơn.","changelog.0a57881c2b36":"<strong>Shoal</strong> có ít feedback hơn khi Voices lớn hơn 1. Drive của <strong>Rein</strong> giờ tăng dần theo lượng của nó.","changelog.72f7c4662b6e":"Các lần lặp của <strong>Relay</strong> rơi đúng lúc, và chỉ những tiếng vọng quay vòng lại mới đi qua bộ giới hạn feedback mới của nó, nên một đầu vào mạnh không bị bão hoà. Các đầu từ phụ của <strong>Spool</strong> lặp lại đúng ở thời điểm chúng được đặt.","changelog.def90dbc42c4":"<strong>Sideband</strong> giờ oversample bốn lần thật sự và khai báo độ trễ 24 mẫu. <strong>Hammer</strong> không còn tăng gấp đôi mức khi kích lại, và tiếng vỗ tay của <strong>Skin</strong> đi theo velocity.","changelog.5d9cf4f7dd65":"Số đọc <strong>LUFS tích hợp</strong> thay đổi: việc chặn cổng giờ dùng các khối 400 ms chồng nhau 75%, đúng như tiêu chuẩn quy định.","changelog.85271e6ecd8c":"<strong>Bản xuất không còn bị dither trừ khi bật Dither.</strong> Trước đây công tắc này bị bỏ qua, nên một bản xuất 16 hoặc 24-bit làm bằng bản dựng cũ mang dither mà bạn không yêu cầu.","changelog.d82014f95805":"<strong>Thu âm và giám sát đầu vào trễ hơn khoảng 5 ms</strong> ở chu kỳ âm thanh 10 ms. Đầu vào giờ giữ một khoảng dự phòng nhỏ để một lần gọi lại hơi trễ không thể để lại khoảng trống trong take; độ trễ là không đổi.","changelog.ccde2b49c256":"Vẫn còn mở","changelog.2948905e9c03":"⚠ <strong>Bản xuất được kết xuất mà không có plugin VST 3 và CLAP</strong>. README trong mọi thư mục xuất đều nói rõ điều đó. Sửa việc này cần một bản kết xuất ngoại tuyến có phiên bản plugin của riêng nó, và đó là một quyết định thiết kế chứ không phải một lỗi.","changelog.0740065d75e1":"⚠ <strong>Pitch bend, bánh xe mod và pressure của bàn phím MIDI</strong> chưa được truyền. Nốt, velocity và pedal ngân thì có. Một nốt từ phần cứng phát ra ở đầu khối âm thanh nhận nó, và take đã thu chưa được bù độ trễ đầu vào và đầu ra.","changelog.e4f8567eaca5":"⚠ <strong>Thiết lập plugin được lưu trong tệp dự án dưới dạng một danh sách số</strong>, lớn khoảng ba lần rưỡi kích thước của chúng, và khôi phục sau sự cố đưa chúng về như ở lần lưu gần nhất.","changelog.94b3ea8fff75":"⚠ <strong>Bốn tình huống tranh chấp hiếm gặp trong phòng vẫn có thể khiến các máy khác nhau:</strong> một clip được đặt lên một track đúng khoảnh khắc cộng sự xoá track đó; một chỉnh sửa được thực hiện vào lúc một trận Kumite mở ra, trước khi người gửi thấy trận đấu; một núm trên nhạc cụ cũ được một nhà sản xuất vặn mà tới máy thứ ba trước lần vặn núm đầu tiên đã chuẩn bị cho nó; và một clip có lần xoá được hoàn tác trong khi cộng sự đổi màu nó, clip đó trở lại ở mọi nơi nhưng màu mới có thể chỉ còn trên một số máy.","changelog.7f22bd522c65":"Thêm mới — một pattern cuối cùng cũng tới được dòng thời gian","changelog.0cc9d8e73e75":"⛔⛔ **<code>ClipContent::Midi</code> đã là một tham chiếu sống kể từ v0.2.0 — <em>&quot;sửa nguồn sẽ thay đổi mọi vị trí đặt của nó, và đó chính là pattern&quot;</em> — vậy mà không có gì trên trang tạo được vị trí đặt thứ hai cho bất cứ thứ gì.** <code>ArrangementEdit::PlacePattern</code> không mang nguồn nào và trình xử lý của nó gọi <code>MidiSource::empty</code> vô điều kiện, nên mỗi lần đặt là một pattern rỗng hoàn toàn mới. Một nhà sản xuất có thể dựng pattern trong giá nhưng không có cách nào đưa nó vào bài. Mô hình làm được; nhà sản xuất thì không, và đó là sự phân biệt mà dự án này đã từng phải trả giá một lần ở nhật ký thao tác.","changelog.894247c903fd":"<strong><code>PlacePattern</code> nhận một <code>source</code> tuỳ chọn.</strong> Một biến thể, không phải hai: một <code>PlaceExistingPattern</code> song song sẽ là lỗi hai-cửa-mở-vào-một-trường mà <code>ArrangementEdit::SetClipLoop</code> đã bị xoá vì nó vào 2026-09-17. <code>None</code> là đúng hành vi cũ, và nhấp đúp vào dòng thời gian trống giờ nói rõ điều đó.","changelog.a278c0f6d9cf":"<strong>Giá đặt pattern của một hàng tại đầu phát</strong>, lấy đúng độ dài của clip thay vì một ô nhịp phỏng đoán, và clip được đặt tên theo pattern nên hai vị trí đặt của <em>Verse</em> hiện là <em>Verse</em> hai lần thay vì như hai kẻ lạ.","changelog.bad0be6b218c":"⚠ <strong>Một nút bấm, không phải thao tác kéo.</strong> WebView2 của Tauri trao mọi thao tác kéo HTML5 cho trình xử lý thả tệp của hệ điều hành trước khi trang nhìn thấy nó, nên <code>draggable</code> + <code>onDragStart</code> xanh dưới Playwright — Chromium không có lớp Tauri nào bên dưới — nhưng chết trong ứng dụng phát hành. Một nút bấm cũng là thứ mà bàn phím và trình đọc màn hình được hưởng sẵn.","changelog.b2a11a0200e5":"⛔ <strong>Đặt pattern sẽ hiện bản phối ra.</strong> Giá và dòng thời gian dùng chung một khe ở giữa, nên từ trong giá, một lần đặt thành công không thay đổi gì trên màn hình — cùng kiểu &quot;trông như chẳng làm gì&quot; mà bản phát hành này cũng sửa ở <em>Pattern mới</em>, và một lần đặt mà nhà sản xuất không nhìn thấy là lần họ sẽ nhấn lại.","changelog.d996223bdc2c":"⛔⛔ <strong>Cổng kiểm tra chính là tham chiếu sống</strong>: đặt một pattern hai lần, sửa nốt một lần, và khẳng định <strong>cả hai</strong> vị trí đặt đều thay đổi — rồi <em>Tách riêng</em> một vị trí và khẳng định vị trí kia không đổi. ⚠ Bất cứ điều gì ít hơn thế đều đạt với một cách cài đặt sao-chép-khi-đặt, vốn trông y hệt trên màn hình vào ngày phát hành và không thể gỡ ra về sau. Đã được chứng minh bằng cách viết đúng cách cài đặt đó và nhìn bài kiểm thử này, và chỉ bài này, chuyển đỏ.","changelog.4e4c1e91df18":"Sửa lỗi — <em>Pattern mới</em> trông như chẳng làm gì","changelog.bb60005cf453":"⛔ <strong>Chủ dự án, 2026-09-19.</strong> Chỉnh sửa lần nào cũng được ghi nhận. <code>refreshPatternRack</code> giữ pattern đang mở <em>khi nó vẫn còn tồn tại</em>, và sau khi thêm thì pattern trước luôn còn — nên vùng chọn không bao giờ dịch chuyển, phần thân của bảng không bao giờ đổi, và bằng chứng duy nhất của thành công là thêm một mục trong một danh sách thả xuống đang đóng.","changelog.cb9e75e7d0bf":"<strong>Pattern mới giờ là pattern đang mở</strong>, được tìm bằng hiệu tập hợp thay vì theo vị trí: <code>patterns.at(-1)</code> sẽ là một khẳng định thứ hai không được nói ra về thứ tự mô hình trả về các pattern, đúng hôm nay và im lặng khi nó thôi đúng.","changelog.fe911c060ae2":"<strong>Pattern mới không còn lấy một cái tên đã có chủ.</strong> Con số được lấy từ số đếm, nên với <em>Pattern 1 / 2 / 3</em> mà <em>Pattern 2</em> đã bị xoá, pattern kế tiếp là một <em>Pattern 3</em> thứ hai — trong khi lời chú thích ngay bên cạnh khẳng định chính cấu trúc đó ngăn được đúng việc này. Bộ chọn liệt kê pattern theo tên, nên hai pattern trùng tên không phân biệt được ở chỗ duy nhất mà nhà sản xuất chọn giữa chúng.","changelog.37c6b44b957f":"⚠ **Bài kiểm thử có sẵn khẳng định chỉnh sửa đã được <em>gửi</em>.** Đúng là nó đã được gửi. Mọi cổng kiểm tra đều xanh với một nút mà chủ dự án báo là chết — gần như nguyên văn cái bẫy số 8: các bài kiểm thử phủ từng mảnh mà không bao giờ phủ đường nối. Bài mới hỏi xem sau đó nhà sản xuất đang nhìn thấy gì.","changelog.8bc07e14cb41":"Thay đổi — crate synth đã bắt kịp nguồn gốc của nó","changelog.b60fde70b9bf":"▶ <strong><code>synth/</code> được nhập từ <code>Freally MIDI Master</code>, không bao giờ được sửa ở đây</strong>, và <code>tests/the_synth_is_not_forked.rs</code> so sánh hai bản từng byte trên bất kỳ máy nào có cả hai được checkout. Nó đã chuyển đỏ: bản sao này chậm một commit.","changelog.973b9db56f9d":"<strong>Nhập lại ở <code>ff99972c</code></strong>, một bản sửa đổi đã push chứ không phải một cây làm việc, nên thứ được sao chép không thể xê dịch bên dưới bản sao. Cả <code>src</code> được lấy thay vì chỉ ba tệp khác biệt, và đó cũng là điều chứng minh không có gì khác bị trôi lệch — <code>git</code> báo đúng ba tệp đó, cộng với phần header.","changelog.d0edfd8085ba":"<strong>Thứ đi kèm là một tính năng</strong>: bộ chỉnh âm sắc ba dải trên đầu ra của mỗi phần, sau tầng drive. Mặc định phẳng, và <code>is_flat()</code> bỏ qua cả tầng thay vì chạy ba biquad ở mức đơn vị.","changelog.563488a64458":"⚠ <strong>Không âm thanh có sẵn nào bị dịch đi, và điều đó được đo chứ không phải lập luận.</strong> Cả <strong>1,648</strong> one-shot đã nướng sẵn được lấy dấu vân tay trước khi nhập và nướng lại sau đó: tất cả đều giống hệt từng byte. Đường bỏ qua là chính xác.","changelog.719cec9783d3":"⛔ <strong>Header của chính crate đã khẳng định suốt bốn commit rằng nó &quot;giống hệt, ngoại trừ phần ngắt dòng của rustfmt&quot; so với lần nhập ban đầu.</strong> Điều đó thôi đúng từ <code>b6149993</code> và vẫn nằm trên trang cho tới <code>0e36a6ab</code>. Giờ nó gọi tên bốn commit đã làm nó dịch đi. Cổng kiểm tra của sản phẩm này đã neo một khẳng định vào câu đã bị bỏ, nên cổng được chuyển sang câu thay thế — một header không còn nói crate là được nhập vẫn là một lỗi, và trên một máy không có bản checkout anh em thì nó là thứ <em>duy nhất</em> đang kiểm tra.","changelog.69b25eeb0c5b":"<strong>Mười ba cổng kiểm tra mà nguồn gốc không có.</strong> Bộ chỉnh âm sắc ra mắt mà không có bài kiểm thử nào ở cả hai sản phẩm, và <em>&quot;mọi trường ở giá trị mặc định đều đúng là bỏ qua&quot;</em> là điều gánh trọng trách cho 372,600 âm thanh ở bên đó và 1,648 ở đây — vậy mà nó chỉ dựa vào một lời chú thích. Mỗi cổng đã được chứng minh là thất bại với đúng lỗi mà nó gọi tên. Những cổng xứng đáng có mặt:","changelog.b94bccab9f9e":"<strong>Một patch mặc định kết xuất giống hệt từng bit với một patch có tần số dải vô lý và mọi gain bằng không</strong> — nên một EQ phẳng không thể rò tần số trung tâm của nó vào đầu ra.","changelog.5e207e72d810":"<strong>Một dải bị dịch đi thì nghe được.</strong> ⚠ Thiếu điều này, bài kiểm thử bỏ qua ở trên vẫn đạt vui vẻ y như vậy với một EQ chẳng nối vào đâu cả, và đó là lỗi được ghi nhận nhiều nhất của dự án này.","changelog.185db1f5eda0":"<strong>Mỗi dải làm đúng như tên gọi của nó, được đo bằng đáp ứng biên độ tính theo dB.</strong> ⛔ Một bài kiểm thử chỉ khẳng định đầu ra <em>đã thay đổi</em> vẫn đạt với một EQ bị nối ngược. Low shelf nâng 50 Hz lên 12 dB và làm 12 kHz dịch chưa tới nửa dB; đỉnh dải giữa dịch đúng tần số trung tâm của nó và để yên hai đầu; Q thật sự quyết định độ rộng. Và mọi dải ở 0 dB là mức đơn vị — <code>resonator.rs</code> cảnh báo bằng chính lời của nó rằng một shelf và một peak từ hai cách suy ra khác nhau sẽ không cộng lại thành phẳng, và đường bỏ qua của engine chính là thứ sẽ che giấu điều đó.","changelog.561660be824d":"<strong>Một patch mang các trường <code>NaN</code> và vô cực vẫn kết xuất ra âm thanh hữu hạn.</strong> ⛔ Các gain cố ý khác không, nên đường bỏ qua-khi-phẳng không thể cứu nó và phép kẹp phải làm việc. Xoá phép kẹp thì đúng là các mẫu không hữu hạn đi vào bus đầu ra — một patch tới từ tệp dự án, preset hoặc khối dữ liệu phiên, nên những con số đó đến từ đĩa.","changelog.cf7a53067d45":"<strong>Một patch được lưu trước khi trường này tồn tại vẫn nạp được, và nạp ở trạng thái phẳng</strong>, đó là mọi tệp dự án mà nhà sản xuất đã có. ⚠ Nó khẳng định khoá <code>eq</code> đã được tìm thấy trước khi xoá nó, nên một lần đổi tên không thể khiến bài kiểm thử lặng lẽ nạp một tài liệu hiện đại rồi báo thành công.","changelog.5cfdbb31fdb6":"<strong><code>reset</code> xoá bộ nhớ của bộ chỉnh âm sắc</strong>, đó là con đường mà cả 1,648 one-shot nướng sẵn đi qua, nối đuôi nhau, qua cùng một engine.","changelog.8db9ed06330a":"<strong>Các hệ số đi theo khi tần số lấy mẫu thay đổi</strong> — xem bên dưới.","changelog.844ddc7e034e":"⚠ <strong>Bộ chỉnh âm sắc không truy cập được từ Oscillate</strong>, và đó là trạng thái thật chứ không phải một thiếu sót. Không có gì ở đây ghi <code>patch.fx.eq</code> và thiết bị nhạc cụ không có nút điều khiển nào cho nó — đó là tính năng trên mặt máy của <code>Freally MIDI Master</code>, có mặt vì crate được nhập nguyên khối. Nên ở đây nó phẳng mãi mãi, tức là bị bỏ qua mãi mãi. Các cổng kiểm tra ở trên tồn tại để vào ngày Oscillate <em>thật sự</em> đưa nó ra, lời hứa mà nó được nhập kèm đã sẵn được giữ.","changelog.04a45d3f4f5f":"⛔ <strong>Và hai lỗi được tìm ra nhờ viết chúng, cả hai đều được sửa ở nguồn gốc và nhập trở lại.</strong> <code>SynthEngine::set_sample_rate</code> dựng lại các giọng, delay và reverb nhưng không dựng lại bộ chỉnh âm sắc — việc dựng lại được canh theo việc các <em>tham số</em> thay đổi và tần số lấy mẫu không phải một tham số, nên một host chuyển 48 kHz → 96 kHz vẫn giữ các hệ số dựng cho 48 kHz và đặt mọi dải thấp đi một quãng tám, một shelf 6 kHz tác động ở 3 kHz. ▶ <strong>Có thật trong sản phẩm kia, không phải lý thuyết</strong>: plugin của nó gọi <code>set_sample_rate</code> khi khởi tạo, nên một dự án mở ở tần số khác lẽ ra đã phát hành đúng lỗi đó.","changelog.164f095fad5b":"⚠ Nhìn vào điều kiện canh cho bản sửa đó lại lòi ra lỗi thứ hai: nó ghi lại các tham số <strong>đã kẹp</strong> rồi so với patch <strong>chưa kẹp</strong>, nên bất kỳ patch nào mang một số ngoài phạm vi sẽ không bao giờ khớp và bị dựng lại mỗi khối — ba hàm siêu việt cho mỗi dải mỗi kênh, trên luồng âm thanh, suốt đời của nốt. Đó chính là cái giá mà điều kiện canh tồn tại để tránh, bị trả đủ.","changelog.10064bd5014c":"▶ Cả hai đều được sửa trong <code>ff99972c</code> và crate này mang bản sửa đó. ⛔ <strong>Không lỗi nào được vá ở đây</strong> — <code>tests/the_synth_is_not_forked.rs</code> chính là quy tắc đó, và một lỗi trong crate được nhập sẽ được báo về nguồn gốc của nó và quay lại qua một lần nhập lại.","changelog.763976c39a5e":"⚠ <strong>Oscillate không chạm tới được lỗi nào</strong>: <code>prepare</code> dựng lại engine thay vì sửa tần số của nó, không có gì ở đây gọi <code>set_sample_rate</code> trên một synth cả, và không có gì ghi <code>patch.fx.eq</code>, nên tầng đó bị bỏ qua hoàn toàn. Bài kiểm thử vẫn được giữ — vào ngày sản phẩm này đưa nút điều khiển ra, sẽ chẳng ai nhớ rằng crate từng làm sai chỗ này.","changelog.748d76268df9":"Sửa lỗi — một cổng kiểm tra lại đi đo cái máy","changelog.907c2f2fd645":"<strong>Cổng chi phí lưu của <code>the_profile</code> chập chờn, và chính các con số của nó bác bỏ thông báo của nó.</strong> Nó đọc được 1.007 µs/thao tác ở 1 000 mục, <strong>4.399</strong> ở 10 000 và 2.030 ở 40 000, rồi thất bại với câu <em>&quot;chi phí mỗi thao tác đang leo thang theo nhật ký&quot;</em>. ⛔ Một chi phí leo thang thì không tụt xuống lại — mẫu lớn nhất còn chưa bằng nửa mẫu đã thất bại. Số đọc ở giữa là một lần khựng, đo trong lúc <code>cargo-test-parallel</code> cho tệp nhị phân này chia máy với một hàng xóm 265 s và một hàng xóm 198 s.","changelog.f740ca8afb55":"⚠ <strong>Giờ đo ba lần, giữ lần nhỏ nhất, và ngưỡng không hề bị đụng tới.</strong> Nhiễu bộ lập lịch, một lỗi trang và một bộ cấp phát nới rộng vùng nhớ chỉ có thể <em>thêm</em> thời gian, nên giá trị nhỏ nhất là số đọc gần nhất với chi phí thật. ▶ Bằng chứng rằng đây là phép đo tốt hơn chứ không phải lỏng hơn: nó trả về <strong>0.484 µs/thao tác</strong>, đúng con số <em>&quot;khoảng nửa micro giây&quot;</em> mà chính lời chú thích của bài kiểm thử đã ghi từ khi nó được viết. Ngưỡng 2.0 giữ nguyên khoảng dư 4× mà nó được cấp.","changelog.ee0e7470e12b":"⚠ <strong>Nó quan trọng nhất ở chỗ không miễn phí</strong> — cùng tệp nhị phân đó chạy trên job macOS với hệ số tính phí 10×, nơi một lần chập chờn tốn tiền và một lần chạy lại là một con người quyết định chi số tiền đó.","changelog.976e6e97f8a2":"Sửa lỗi — hai đợt rà soát, và ba mươi lỗi chúng tìm ra","changelog.db1222c7163d":"▶ <strong><code>/code-review</code> và <code>/security-review</code> trên toàn bộ cây mã, rồi một đợt rà soát đường nối của mọi nút điều khiển.</strong> Đợt rà soát bảo mật không tìm thấy gì khai thác được. Hai đợt kia tìm ra ba mươi lỗi, và khuôn mẫu chung của chúng là một điều nói theo ba cách: một cơ chế chạy được, và không có gì gọi tới nó.","changelog.7cf2cd2dae19":"<strong>Âm thanh</strong>","changelog.6b2f9047e7fb":"<strong>Tách một clip âm thanh khiến cả hai nửa phát cùng những ô nhịp.</strong> <code>tail_of</code> tăng <code>content_offset_ticks</code> còn engine lại đọc <code>source_start_frame</code>, nên cắt một take tám ô nhịp ở ô nhịp năm sẽ phát lại ô nhịp một tới bốn đè lên năm tới tám và khiến đoạn kết thật của take không thể tới được. ⚠ Cùng đường đó là <em>cắt</em>, thu đè lên một take, và kéo mép trái của clip. Giờ <code>clipwindow.rs</code> là nơi duy nhất cộng hai giá trị đó lại.","changelog.2c8ea832888d":"<strong>Repitch cộng Reverse chạy quá cuối tệp vào im lặng</strong>, và Repitch cộng Repeat là một thao tác im lặng không làm gì. Trình chỉnh sửa luôn vô hiệu hoá chế độ này cho cả hai; engine thì chưa bao giờ kiểm tra.","changelog.776681ae58b6":"<strong>Một tiếng lách cách khoảng 85 ms sau đầu mọi clip đã đổi cao độ</strong> bắt đầu từ đầu tệp của nó — bộ lấy mẫu lại giả định có một đoạn dẫn vào của kernel mà nó không được cấp, rồi nhảy lùi đúng đoạn đó ở ranh giới khúc kế tiếp.","changelog.025480518fc8":"<strong>Nút M của làn trống và nhóm choke của nó được lưu nhưng không bao giờ được phát.</strong> Một hi-hat bị tắt tiếng vẫn kêu; hai hi-hat trong nhóm 1 vẫn ngân cùng nhau. Giờ cả hai do bộ lập lịch xử lý, nên hi-hat đóng sẽ cắt hi-hat mở.","changelog.00a6999c8a9e":"<strong>Những nút điều khiển chẳng tới đâu cả</strong>","changelog.dcf104640213":"<strong>Cả mười mục của Cài đặt ▸ Xuất.</strong> Định dạng, độ sâu, dither, tần số, ba ô <em>Ghi ra</em>, mẫu tên stem, thư mục, chuẩn hoá và phần đuôi được ghi vào <code>preferences.json</code> và <strong>không có gì</strong> đọc chúng: bản xuất duy nhất trong sản phẩm cố định WAV 24-bit và lần nào cũng hỏi thư mục. Nhà sản xuất chọn FLAC nhận được WAV, và không có gì nói ra điều đó. ⚠ <em>Chuẩn hoá</em> và <strong>phần đuôi</strong> reverb được cài đặt mới chứ không chỉ được nối vào, và <em>Ghi ra → master</em> giờ có thể tạo ra bản mix mà nó vẫn luôn mặc định đòi.","changelog.59d90c6cb919":"<strong>Menu clip chỉ có một mục, trên một backend làm được bảy việc.</strong> <em>Tắt tiếng clip này</em> — engine đã tôn trọng <code>Clip::muted</code> từ Giai đoạn 5 mà không nút điều khiển nào đặt được nó, nên kiểu tắt tiếng duy nhất là tắt cả track. <em>Tách riêng</em>, <em>Xoá comp</em>. Giờ nó cũng mở được trên một clip trống.","changelog.e5b3cca1b7df":"<strong>Gain clip và chỉnh sửa trượt</strong>, cả hai trong trình chỉnh sửa âm thanh. Trượt là chỉnh sửa âm thanh phổ biến nhất mà sản phẩm lại không có cách nào làm.","changelog.6d771bdd8e51":"<strong>Một nhóm thiết bị không bao giờ đổi tên được</strong>, nên nhóm nào cũng mãi tên là <em>Nhóm mới</em>. Nhấp đúp vào tên của nó.","changelog.467d149679e8":"<strong>Lưới bám không bao giờ được lưu lại.</strong> Nó quay về <em>Thích ứng</em> mỗi lần khởi động lại và khác nhau giữa cửa sổ chính và mỗi cửa sổ tách rời. ⚠ Giờ nó là một thiết lập của dự án, được lưu dưới dạng <strong>chế độ</strong> thay vì số tick — <em>thích ứng</em> là một quy tắc về thu phóng còn <em>ô nhịp</em> và <em>chùm ba</em> đi theo loại nhịp, nên một con số không bao giờ chứa nổi câu trả lời.","changelog.a5d42a8ae7a9":"<strong>Bộ đếm mất tiếng có thể đặt lại</strong> — nhấn vào nó. Một bộ đếm cộng dồn từ lúc khởi động không thể cho nhà sản xuất biết cỡ bộ đệm vừa đổi có giúp được gì không.","changelog.ba7c289f15f7":"<strong>Cửa sổ của plugin có thể đóng lại</strong>, chứ không chỉ mở ra.","changelog.2cb47acac22e":"<strong><code>Ctrl</code>+<code>2</code> không làm gì cả.</strong> Nó được liệt kê trong Cài đặt, in trong chú giải của nút Pattern, và lật một tuỳ chọn mà khung cửa sổ đã thôi không đọc nữa.","changelog.e50883a683a3":"<strong>Cài đặt ▸ Phím tắt vẽ ra một khoá dịch thô</strong> làm tên hành động của hàng Giá pattern, trong cả mười tám ngôn ngữ.","changelog.b14b86b1382f":"<strong>Những thứ lẽ ra đã thất bại trên máy của người khác</strong>","changelog.66c3c6c5267c":"<strong>Mọi bản dựng macOS đều hỏng.</strong> <code>include_bytes!</code> trỏ vào một PNG màn hình chờ đã bị xoá cùng hoạt ảnh mà nó thuộc về — một lỗi biên dịch cứng trên chính nền tảng mà máy Windows không bao giờ biên dịch.","changelog.0baaabb3b598":"<strong>Quy trình phát hành không bao giờ hoàn thành được một bản nháp.</strong> Nó đã ngừng dựng trên ba runner trong khi manifest của trình cập nhật vẫn đòi cả bốn nền tảng, nên bước đó thoát với mã 1 ở mọi lần chạy. Giờ một bản phát hành khai báo nó bao phủ những nền tảng nào, và nói bằng chữ in hoa những gì nó để lại không cập nhật được.","changelog.8427ce0ef17b":"<strong>Hai cổng kiểm tra CI chẳng chạy ở đâu</strong> — bước kiểm tra loại relay và bước kiểm tra giấy phép của trình cài đặt — trong khi chính header của quy trình khẳng định mọi cổng đều chạy.","changelog.a778bef2ac7c":"<strong>Thành thật về những gì chưa được dựng</strong>","changelog.542fd1169d51":"<strong>Làn CC nói rõ là nó không được phát.</strong> Đường cong được vẽ, ghi nhận, lưu và đọc lại, nhưng không nhạc cụ nào đọc nó: <code>NoteMessage</code> không có biến thể cho bộ điều khiển và không thiết bị nào có nút để ánh xạ vào. Làn này vẫn hoạt động như một trình chỉnh sửa và không còn ngụ ý rằng nó được nghe thấy.","changelog.19d2f3668484":"<strong>Câu hỏi cập nhật lần chạy đầu chặn cả bàn phím lẫn chuột.</strong> Lớp phủ của nó chỉ chặn được cú nhấp chuột chứ không chặn gì khác, nên <code>Space</code> khởi động transport và <code>B</code> chọn lưỡi dao phía sau một hộp thoại lẽ ra phải đang chặn cửa sổ.","changelog.4408a66cf4a7":"<strong>Kéo fader và núm gửi từng lần ghi một.</strong> Mỗi lần trước đây là một tác vụ riêng, 60 tới 120 lần mỗi giây, nhắm vào một lần ghi nhận không nguyên tử, nên một lần kéo đổi hướng có thể áp dụng các giá trị <strong>ngược thứ tự</strong> và để fader hiện một giá trị mà tay đã lướt qua.","changelog.a76424b61990":"<strong>Mặc định của <code>Writes</code> là cả ba.</strong> Trước đây chỉ có master — viết cho một hộp thoại bounce chưa từng được dựng — trong khi bản xuất duy nhất sản phẩm này có là thư mục đi kèm, mà toàn bộ đặc tả của nó là stem và MIDI.","changelog.4118fb4fed0e":"Gỡ bỏ","changelog.15b34653c2d8":"<code>ArrangementEdit::SetClipLoop</code>, cánh cửa đường nối thứ hai mở vào trường mà <em>Repeat</em> của trình chỉnh sửa âm thanh đã sở hữu. Hai cánh cửa mở vào một trường có thể trôi lệch nhau.","changelog.87ab637f8719":"Năm lệnh đã đăng ký mà không có gì gọi tới được, trong đó có cả một đường thu âm thứ hai lặp lại phần sắp thứ tự vốn do <code>transport_toggle_record</code> sở hữu.","changelog.840e2d665a01":"<code>InputRouting::midi_channel</code> — không được ghi cũng không được đọc ở đâu, và một trường trong định dạng tệp ngụ ý rằng có một tính năng tồn tại.","changelog.68ff7b9f2a51":"Một bản sao thứ hai đã chết của phần điều hướng trong trình duyệt tệp, và một bản trùng 1.4 MB của logo thanh trạng thái mà không có gì nhập vào.","changelog.5804894b279c":"Thêm mới — năm cổng kiểm tra, mỗi cổng đã được chứng minh thất bại với đúng lỗi nó được viết ra để bắt","changelog.cbc111af658b":"▶ <strong>Các đợt rà soát tìm ra lỗi; những cổng này là thứ sẽ tìm ra các lỗi tiếp theo.</strong>","changelog.0ced7e4acc29":"<strong>Mọi <code>#[tauri::command]</code> đã đăng ký đều được thứ gì đó gọi tới.</strong> Cổng kiểm tra có sẵn so khai báo↔đăng ký theo cả hai chiều nhưng không nhìn thấy được trường hợp mà đợt rà soát thực sự tìm ra bảy lần.","changelog.bfa23431d44f":"<strong>Mọi đường dẫn <code>include_bytes!</code> trong cây Rust đều phân giải được</strong> — đọc dưới dạng văn bản, nên nó thấy cả những dòng mà bản dựng Windows không bao giờ biên dịch.","changelog.82c650a2453e":"<strong>Mọi cổng kiểm tra mà <code>ci:local</code> định nghĩa đều chạy trên CI, hoặc nói rõ vì sao không.</strong>","changelog.bbe1d90a6900":"<strong>Mọi đường dẫn mà <code>tauri.conf.json</code> nêu ra đều tồn tại</strong>, và ảnh minh hoạ của trình cài đặt đúng là một bitmap.","changelog.35eba3face11":"<strong>Các mặc định xuất là cùng một con số trong Rust và TypeScript.</strong> <code>preferences.ts</code> khẳng định có một cổng kiểm tra giữ chúng đồng bộ. Không có bài kiểm thử nào như vậy, và hai bên đã trôi lệch nhau.","changelog.601f1c69bd48":"Bản dịch phím tắt giờ được <strong>suy ra từ bảng gán phím</strong> thay vì liệt kê bằng tay. Danh sách viết tay đã lạc hậu mười tám id.","changelog.b9d982ea6bd7":"Thêm mới — chín điều piano roll từng không làm được","changelog.1f9c5a34c9d1":"▶ <strong>Khoảng cách giữa piano roll của Oscillate và cái mà nhà sản xuất đã quen.</strong> Có chín điều, và không điều nào là thiết lập: mỗi điều là một thao tác hoặc có hoặc không.","changelog.d5a043ed3427":"<strong>Nốt bóng mờ.</strong> Các pattern khác trên dòng thời gian, được vẽ phía sau pattern bạn đang sửa, để một dòng bass được viết theo các hợp âm mà nó nằm bên dưới. ⚠ <strong>Căn theo DÒNG THỜI GIAN</strong>, không phải tick-không với tick-không: nốt bóng mờ nằm đúng chỗ nó thực sự vang, nên kéo clip của nó sẽ dời thứ bạn nhìn thấy. Chúng được vẽ không kèm id nốt nên không thể nhấp, kéo hay xoá — bạn không thể vô tình sửa nhầm pattern.","changelog.acb285536839":"<strong>Xác suất theo từng nốt.</strong> Một nốt có <code>chance: 60</code> phát sáu lần trong mười. ⚠ Việc gieo là <strong>tất định</strong> — cùng một nốt ở cùng một chỗ trả lời giống nhau ở mọi lần kết xuất, nên bản bounce nghe giống lúc nghe thử — và câu trả lời thay đổi mỗi vòng qua <strong>ngoặc vòng lặp</strong>, đó là cách bạn nghe ra nó.","changelog.91a46043d207":"<strong>Độ lệch velocity theo từng nốt.</strong> Một nửa độ rộng quanh velocity của chính nốt đó, để dòng hi-hat có hơi thở mà không phải vẽ lại. Cả hai trường đều có làn riêng trong piano roll, cạnh làn velocity.","changelog.ae227f69dad4":"<strong>Rải hợp âm, quạt, flam và cắt nhỏ</strong> — bốn công cụ biến một vùng chọn thành nhiều nốt. ⚠ <em>Quạt</em> dời điểm bắt đầu của mỗi nốt mà giữ nguyên mỗi <strong>điểm kết thúc</strong>, nên hợp âm vẫn kết thúc cùng nhau; <em>rải hợp âm</em> dời cả nốt.","changelog.7567510c9217":"<strong>Đóng dấu hợp âm.</strong> Vẽ một nốt, được cả hợp âm. Nốt gốc giữ nguyên danh tính của nó, nên hoàn tác và sửa lại hoạt động đúng; một quãng sẽ rơi ra ngoài bàn phím thì bị bỏ đi thay vì bị gói vào sai quãng tám.","changelog.a5716970627f":"<strong>Dán.</strong> Nối các nốt cùng cao độ thật sự chạm nhau. Theo từng cao độ, không bao giờ vượt qua ranh giới ngoài của vùng chọn.","changelog.6dca58299583":"<strong>Nghe thử khi nhấp.</strong> Nhấn một nốt là nghe nó — ngân trong lúc bạn giữ, và <strong>im ngay khi bạn bắt đầu kéo</strong> nó, nên việc dời một nốt không phải là một chuỗi cao độ. ⚠ Nó phát trên <strong>chính track của clip</strong>, không phải track đang sẵn sàng thu.","changelog.d436aec70d34":"<strong>Chỉnh sửa nhiều clip.</strong> Chọn nhiều clip trong bản phối và một công cụ piano roll sẽ tác động tới tất cả. ⛔ <strong>Theo từng pattern, không bao giờ trên hợp của chúng</strong> — đảo ngược hai clip như một khoảng sẽ tráo nội dung của chúng thay vì đảo ngược từng clip.","changelog.02c466c71f3d":"<strong>Khoá âm giai</strong> <em>(theo yêu cầu của chủ dự án)</em>. Khi bật, không có gì rơi lạc giọng: vẽ, kéo, mọi phép biến đổi, và nốt được chơi vào từ bàn phím MIDI. ⚠ <strong>Track trống được miễn</strong>, vì cao độ của một bộ trống là các khe chứ không phải nốt. Tệp <code>.mid</code> được nhập và chỉnh sửa của người cùng phòng được cố ý để yên — khoá này canh những gì <em>bạn</em> chơi, và không viết lại những gì bạn được trao.","changelog.c0a758a4c2c8":"Thêm mới — ba điều nữa chủ dự án yêu cầu trong lúc những điều trên đang được dựng","changelog.228a32503478":"<strong><code>[</code> và <code>]</code> trên các mép của clip.</strong> Con trỏ cho biết bạn sắp cắt gọt mép nào trước khi bạn nhấn, và trở về con trỏ di chuyển khi ở giữa.","changelog.67dab04fd1a6":"<strong>Bounce vùng chọn thành âm thanh.</strong> Nhiều clip MIDI trở thành tệp âm thanh chỉ với một lần nhấn, và <strong>một lần hoàn tác</strong> đưa tất cả trở lại thành MIDI. ⚠ Bản kết xuất tôn trọng xác suất và độ lệch velocity, nên âm thanh đúng là thứ bạn đã nghe.","changelog.e79c873347d5":"<strong>Trang phím tắt và ứng dụng khớp nhau.</strong> Giờ một bài kiểm thử so sánh các phím gán của ứng dụng với bảng trong tài liệu theo cả hai chiều, nên một phím gán được thêm mà thiếu hàng của nó — hoặc một hàng bị bỏ lại sau khi phím gán đã dời đi — sẽ làm bản dựng thất bại thay vì tới tay người đọc.","changelog.94af29dd35e5":"Thay đổi — mười bốn nhạc cụ nói rõ chúng là gì","changelog.dba1519e23b3":"▶ <strong>Chủ dự án, 2026-09-16:</strong> <em>&quot;đổi tất cả tên plugin hiệu ứng audio/midi của tôi thành tên thông thường, chỉ cần không trùng với Ableton/FL Studio, và cũng vậy với mọi thứ khác trong ứng dụng của tôi có dính tới 'Kiln' hay thứ gì giống thế.&quot;</em>","changelog.da573c0bab5c":"Sáu mươi mốt hiệu ứng đã được đổi tên ở bậc trước; các nhạc cụ vẫn giữ mật danh theo chủ đề lò rèn và câu hỏi còn bỏ ngỏ là có nên đổi theo hay không. Chúng đã được đổi:","changelog.c973dfc231e6":"⚠ <strong>Ba trong số đó vẫn bị làm xám và nói rõ lý do</strong>, và nói dưới tên mới của chúng: <code>Hardware Instrument</code> chơi phần cứng ngoài qua một cổng MIDI trong khi Oscillate chưa có cổng MIDI; <code>Track Replay</code> cần chính đầu ra đã thu của track này; <code>Folder Kit</code> cần thư viện sample của nhà sản xuất, và đó là việc của Trình duyệt tệp.","changelog.759ed41312d0":"⚠ <strong>Một hiệu ứng cũng được đổi tên.</strong> <code>Strum</code> giờ là <strong>Chord Strummer</strong>, vì Live 12 có sẵn một phép biến đổi MIDI tên đúng là <em>Strum</em> và chỉ dẫn đã nói rõ không cái tên nào được trùng với tên của họ.","changelog.5bce801ca6dd":"⛔ <strong>Không có gì mà tệp dự án lưu bị thay đổi.</strong> Chỉ tên hiển thị thay đổi; mọi <code>type_id</code> — <code>crucible</code>, <code>flint</code>, <code>hammer</code> và các id khác — vẫn y như cũ, vì chuỗi đó là khoá mà một tệp <code>.oscillate</code> đã lưu mang theo. Nhà sản xuất mở dự án tuần trước sẽ thấy mọi thiết bị ở đúng chỗ họ để lại, với thiết lập và tự động hoá của nó. ⚠ Vì vậy một mật danh còn sót trong <code>type_id</code> không phải là thiếu sót để dọn sau; dọn nó mới là lỗi, và <code>every_device_name_says_what_it_is.rs</code> ghim cả mười lăm cái.","changelog.a4c30729338f":"⚠ <strong>&quot;Kiln&quot; được cố ý để yên</strong>, và đáng nói rõ nó nằm ở đâu: hoàn toàn không phải một thiết bị, mà là <em>&quot;Kiln Gong&quot;</em>, một preset trong số 1,648 preset của thư viện có sẵn được nhập vào. Thư viện đó được so từng byte với bản của Freally MIDI Master, nên đổi tên bên trong nó là rẽ nhánh một bản nhập và phá vỡ lời hứa rằng một <code>PresetId</code> kết xuất ra cùng một âm thanh ở cả hai sản phẩm.","changelog.388337669577":"Thêm mới — khôi phục sau sự cố tới được cả phiên chưa từng được lưu","changelog.4e88f60bb868":"⛔⛔ <strong>Một nhật ký được đặt tên theo dự án mà nó thuộc về, và một phiên chưa từng được lưu thì không có tệp dự án nào để mở lại</strong> — nên lần khởi động sau tạo ra một dự án mới với id mới và không bao giờ tìm tới nó. Phần việc vẫn nằm trên đĩa suốt thời gian đó mà không có gì đề nghị trả lại, và đó chính là nhà sản xuất đã làm việc từ trưa tới giờ mà chưa lưu lần nào.","changelog.e842b6131eed":"✅ Giờ Oscillate chụp lại điểm khởi đầu của một phiên chưa lưu vào nhật ký ngay ở chỉnh sửa đầu tiên, và một lần khởi động chưa bắt đầu công việc riêng sẽ được đề nghị bản mồ côi mới nhất có thể khôi phục. ⚠ Hộp thoại nói rõ đó là loại đề nghị nào: bản mồ côi không có tệp đã lưu, nên câu trấn an thông thường — <em>&quot;dự án đã lưu của bạn không bị thay đổi&quot;</em> — sẽ là đang mô tả một tệp không tồn tại.","changelog.7a6d58e08394":"⛔ <strong>Một nhật ký không có ảnh chụp riêng sẽ không bao giờ được đề nghị</strong>, vì không có dự án đã lưu nào để phát lại nó lên và kết quả sẽ là một dự án chưa từng tồn tại. Một đề nghị đã được chấp nhận hoặc bỏ đi sẽ không quay lại.","changelog.e51b2a693d90":"Giới hạn đã biết — một phiên dài tạo ra tệp dự án lớn","changelog.7b7551a966b9":"⚠ <strong>Nhật ký thao tác nằm bên trong tệp <code>.oscillate</code>, có chủ đích</strong>: nó là thứ giúp hoàn tác sống sót qua một lần lưu và nạp lại, và cả Tua lại phiên lẫn Bản tua nhanh phiên đều được suy ra từ nó. Không có gì cắt bớt nó, nên tệp lớn dần theo phiên — đo được <strong>29 MB sau 100,000 thao tác và 58 MB sau 200,000</strong>, khoảng một phiên tám giờ, ghi trong 67 ms.","changelog.2d5d351a5323":"▶ Mức tăng là <strong>tuyến tính</strong>, không phải luỹ tiến, và mức trần được ghi rõ thay vì bị chặn: cắt bớt nhật ký sẽ cùng lúc xoá mất hoàn tác-sau-khi-nạp-lại, Tua lại phiên và Bản tua nhanh. ⛔ Quyết định của chủ dự án, 2026-09-15.","changelog.1bd930b6d7dc":"Thay đổi — trình duyệt lọc ngay từ nguồn","changelog.ad56b31dd7dc":"⚠ <strong>Mở một kệ trong trình duyệt không còn dựng toàn bộ danh sách trước.</strong> Mỗi kệ trong năm kệ — Nhạc cụ và bốn Factory Expansion — được liệt kê bằng cách nhân bản toàn bộ 1,648 nhạc cụ rồi bỏ đi bốn phần năm thuộc về các kệ khác, ở mỗi lần liệt kê. Giờ nó chỉ đi qua kệ được yêu cầu: <strong>0.140 ms → 0.001 ms</strong> đo trong bản release với Nhạc cụ, và ít nhất 1,298 lần cấp phát chuỗi không còn xảy ra mỗi lần.","changelog.f69b8488a31f":"⛔ Đây cũng là lỗi mà <code>Freally MIDI Master</code> đã sửa ở nguồn gốc cùng ngày, và lập luận của nó đi theo bản nhập: một danh sách được lọc sau khi đã dựng là được dựng toàn bộ trên <em>&quot;luồng mà DAW dùng để vẽ cửa sổ của nó&quot;</em>.","changelog.46a40063d923":"Sửa lỗi — những gì các đợt rà soát Giai đoạn 11 tìm ra","changelog.92c5375cd4da":"⛔ <strong>Màn hình chờ trên macOS giữ ứng dụng lại bảy giây ở mỗi lần khởi động.</strong> Cửa sổ native không có trang nào bên trong, nên không có gì gọi <code>splash_finished</code> — và bộ canh 4 giây viết cho <em>&quot;một trang bị ném lỗi&quot;</em> đã lặng lẽ trở thành đường đi bình thường của macOS. Giờ màn hình chờ native tự bàn giao theo độ dài hoạt ảnh của chính nó, và một cổng kiểm tra đọc nhánh macOS để chắc chắn bộ canh trang không bao giờ quay lại đó.","changelog.fcfe9625c96b":"⛔ <strong>Và nó còn đang chạy một cú nhảy khác với Windows và Linux.</strong> Bản Rust có một parabol đối xứng trong khi stylesheet có <code>51 − 17u − 78·sin(πu)</code>, không co giãn chút nào, dấu của độ lệch dọc bị đảo, và một cửa sổ bằng 62 % màn hình thay vì toàn bộ — nên hình nhân chúi xuống thay vì nhảy lên, không bao giờ tiến về phía bạn, và bị cắt xén theo một khung vô hình giữa màn hình. Cả bốn đều được sửa, và <code>splash_macos.rs</code> giờ <strong>phân tích chính các key frame của <code>window.css</code></strong> và thất bại nếu hai cách cài đặt lệch nhau ở bất kỳ mẫu nào trong hai mươi mốt mẫu.","changelog.9e463e8ee449":"⛔ <strong>Trang tài liệu vẫn ở ngôn ngữ trước khi bạn chọn lại tiếng Anh.</strong> Mọi nút có thể dịch đều mang sẵn tiếng Anh trong mã đánh dấu, và bộ chuyển ngôn ngữ hiểu điều đó là &quot;không có gì phải làm cho tiếng Anh&quot; — nên chọn Français rồi chọn English để lại một trang tiếng Pháp dưới <code>lang=&quot;en&quot;</code>. Từ tiếng Ả Rập, bố cục thôi lật gương trong khi chữ vẫn là tiếng Ả Rập. Giờ tiếng Anh là một bảng dịch như mọi ngôn ngữ khác, được đọc ra từ trang một lần trước khi có gì ghi đè lên.","changelog.704583748781":"⛔ <strong>Một lần tải bản cập nhật thất bại vứt bỏ đề nghị bạn vừa xem xét</strong>, nên thử lại nghĩa là thêm một yêu cầu mạng. ⚠ Bảng <em>Cập nhật</em> còn thông báo <em>&quot;Không liên hệ gì cả.&quot;</em> như một kết quả thật ở mọi bản cài mới, ngay bên dưới một công tắc đã ghi <em>&quot;Tắt.&quot;</em> — một câu nói về việc chẳng ai làm.","changelog.058de0de8dea":"⚠ Ngoài ra: <code>--verify</code> không kèm <code>--assets</code> báo thảm hoạ § F-32 cho một manifest âm thanh hợp lệ; một ngoại lệ trong <code>deny.toml</code> có thể lặng lẽ miễn trừ lệnh cấm GPL; một dấu <code>|</code> bên trong span mã làm thêm một cột vào bảng được công bố; và ba cổng kiểm tra đọc <code>main.rs</code> bằng một phép tìm mà một lời chú thích cũng trả lời được, một phương thức thụt lề cũng thoả mãn được, và — trong một trường hợp — một phép kiểm chống-rỗng không bao giờ tới được nhánh mà nó canh.","changelog.16ca0f9a8fbd":"⛔ Đóng băng tính năng — 11 tháng 9 năm 2026","changelog.ca13a48bad9c":"<strong>Danh sách tính năng đã đóng cho tới bản ổn định <code>v1.0.0</code>.</strong> Từ đây chỉ có sửa lỗi, gia cố, tối ưu, tài liệu và bản địa hoá được đưa vào. Một ý tưởng tới trong giai đoạn beta sẽ nhận số phiên bản <em>sau</em> 1.0 thay vì một chỗ trong đó — một bản beta có bộ tính năng thay đổi không phải là beta, và các báo cáo lỗi của nó sẽ mất ý nghĩa.","changelog.73951f911f5c":"⚠ <strong>Ba thứ đã được đặc tả trước vạch đóng băng vẫn đang được hoàn thiện</strong> và được mang theo chứ không bị cắt: Bản tua nhanh phiên, việc giao stem của MixSir, và báo cáo người cùng phòng đã mất kết nối. Mang theo một tính năng dang dở không giống với thêm một tính năng mới.","changelog.6293a41b4e75":"Thêm mới — nó có thể tự cập nhật, và đã có sách hướng dẫn","changelog.ac19bec2400d":"<strong>Oscillate có thể tự cập nhật, và nó hỏi trước.</strong> <em>Cài đặt ▸ Cập nhật</em> hiện phiên bản bạn đang chạy, một nút <em>Kiểm tra cập nhật</em>, chính xác địa chỉ sẽ được liên hệ, và lần cuối địa chỉ đó thật sự được liên hệ. ⛔ <strong>Không có gì xảy ra cho tới khi bạn nhấn nút.</strong> Kiểm tra lúc khởi động là một công tắc và nó đang <strong>tắt</strong>; khi tắt thì không liên hệ gì, bảng không hiện kết quả nào, và <em>Kiểm tra lần cuối</em> vẫn là <em>Chưa bao giờ</em>. ⛔ Nó không bao giờ hiện <em>&quot;bạn đang dùng bản mới nhất&quot;</em> cho một lần kiểm tra chưa hề diễn ra — đó là hai sự thật khác nhau và chỉ một trong hai là đúng.","changelog.2d43b4efba6d":"⚠ <strong>Lần kiểm tra gửi đi những gì: không gì cả.</strong> Nó xin một tệp tĩnh và không mang thông tin nào về bạn, máy này hay các dự án của bạn. Khi tìm thấy bản cập nhật, bạn được xem phiên bản, ngày, nhật ký thay đổi và dung lượng, rồi bạn quyết định. ⛔ <strong>Mọi bản cập nhật đều có chữ ký</strong>, và bản nào có chữ ký không xác minh được sẽ bị từ chối kèm thông báo lỗi thay vì được cài — không có đường nào đi vòng qua bước kiểm tra đó.","changelog.fc410aff2057":"⛔ <strong>Hai câu đã được sửa vì nó, và cả hai đều đã nằm trong bản phát hành.</strong> Cài đặt nói <em>&quot;không tài khoản, không đo từ xa, không kết nối tự động dưới bất kỳ hình thức nào&quot;</em> bằng mười tám ngôn ngữ, và bản thoả thuận cũng nói vậy. Một lần kiểm tra lúc khởi động mà bạn đã bật <strong>chính là</strong> một kết nối tự động, nên giờ cả hai đều nói Oscillate <em>không tạo kết nối nào mà bạn không yêu cầu</em> và kể ra ba trường hợp nó dùng tới mạng.","changelog.459ef05e4504":"<strong>Một trang tài liệu, bằng mười tám ngôn ngữ.</strong> Trang chủ, sách hướng dẫn đầy đủ, nhật ký thay đổi và chiếc thang phiên bản — không CDN, không phân tích, không trình theo dõi, không phông chữ nhúng và không script bên thứ ba nào ở bất cứ đâu, cũng chính là lời hứa mà ứng dụng đưa ra và được một cổng kiểm tra khi dựng bảo đảm thay vì để như một lời tuyên bố. ⛔ <strong>Trên đó không có bản tải về, và sẽ không có cho tới <code>v1.0.0</code>.</strong> Trang tải về đã được dựng, nói thẳng rằng chưa có gì ở đó, và không được liên kết tới.","changelog.51a624b39021":"<strong>Mọi quy trình trong tài liệu đều được minh hoạ bằng ảnh chụp màn hình thật của bản dựng thật</strong>, với thứ bạn được bảo phải nhấn được đóng khung đỏ và đánh số — chụp bởi một lượt chạy không giao diện trên front end đã dựng, không bao giờ vẽ tay, và được kiểm tra ở mỗi lần chạy để ảnh của một bản dựng không còn tồn tại không thể sống sót.","changelog.84b4b10ce168":"<strong>Màn hình chờ native trên macOS.</strong> Vẫn là hình nhân đó và cú nhảy đó, được AppKit vẽ thay vì một web view thứ hai — nhờ vậy bỏ được API riêng tư duy nhất của Apple mà sản phẩm này dùng. ⚠ Một lời gọi riêng tư là lời gọi Apple có thể gỡ bỏ trong một bản cập nhật nhỏ; nếu điều đó xảy ra trong giai đoạn beta, mọi máy Mac sẽ vẽ một hình chữ nhật đục đè lên màn hình. Windows và Linux không thay đổi.","changelog.4c1daaca8982":"⛔ **Nút <em>Mở báo cáo GitHub đã điền sẵn</em> trong ứng dụng chẳng dẫn tới đâu.** Nó trỏ tới chủ cũ của kho mã, nên mọi nhà sản xuất dùng nó — con đường duy nhất mà cả trình báo cáo sự cố tồn tại để dẫn tới — đều nhận lỗi 404, sau khi đã viết xong báo cáo. Trình chạy plugin cũng tự giới thiệu với plugin CLAP bằng chính địa chỉ chết đó.","changelog.fdc84a95e8eb":"⚠ <strong><code>v0.4.5</code> bị thiếu trong chiếc thang phiên bản được công bố</strong>, và cả trong chiếc thang nội bộ, dù giai đoạn đằng sau nó đã được dựng từ 2026-09-04. Giờ hai chiếc thang được sinh ra từ một tệp và được so sánh ở mỗi lần dựng.","changelog.70e390902fc1":"Thêm mới — bạn có thể nhìn thấy họ, nghe thấy họ, trao cho họ một track, và in ra ai viết gì","changelog.0ff6295aa3e0":"⛔⛔ <strong>Giọng nói, camera và chia sẻ màn hình, trong bảng phòng.</strong> Nhấn <em>Nói</em> và những người khác nghe thấy bạn; nhấn <em>Camera</em> và họ nhìn thấy bạn. Mỗi lúc chỉ một người được chia sẻ màn hình. ⚠ <strong>Micrô và camera của bạn tắt cho tới khi bạn nhấn nút, và mặc định Oscillate từ chối chúng</strong> — ứng dụng tự giữ sự đồng ý của nó và webview chỉ hỏi hệ điều hành sau khi bạn đã đồng ý. Đóng phòng hoặc tắt một nút điều khiển sẽ dừng luồng, và đó là điều làm tắt đèn báo của phần cứng.","changelog.58fe9d7d8f57":"⚠ <strong>Không có gì từ camera hay micrô được ghi lại, đệm xuống đĩa, hoặc gửi tới đâu ngoài những người cùng phòng của bạn.</strong> Không có máy chủ nào trên đường đi. ⚠ Màn hình được chia sẻ <strong>chỉ mang hình ảnh</strong> — bất cứ thứ gì đang phát trên máy bạn, kể cả nhạc không phải do bạn viết, đều ở lại trên máy bạn.","changelog.3b3fa07d1428":"⛔ <strong>Chia sẻ màn hình có trên Windows và Linux.</strong> macOS không có đường ghi hình màn hình nào ra khỏi một webview nhúng mà không cần API riêng tư trong một tệp nhị phân đã được công chứng, nên nút đó vắng mặt ở đây và nói lý do thay vì thất bại khi được nhấn.","changelog.8b18ea1e7eeb":"⛔⛔ <strong>Bàn giao — trao một track cho ai đó và lấy lại bằng một phím.</strong> Khi họ đang giữ nó, họ là người <strong>duy nhất</strong> được ghi lên track đó, <em>kể cả bạn cũng không</em>, mọi chỉnh sửa của bạn trên track đó đều bị từ chối cho tới khi bạn lấy lại. ⚠ Và việc giữ vừa <strong>giới hạn</strong> vừa độc quyền: họ được ghi lên track đó và không gì khác. Trao một dòng bass không phải là trao cả phiên.","changelog.52c632003a26":"⚠ <strong>Lấy lại là một con dấu, không phải một công tắc.</strong> Một chỉnh sửa họ làm trước khi họ có thể biết vẫn là của họ và vẫn được ghi nhận; chỉnh sửa làm sau đó thì không. Từ chối mọi thứ đang trên đường đi sẽ là trừng phạt ai đó vì tốc độ ánh sáng.","changelog.d460b43b1bf3":"⛔ <strong>Quyền giữ chỉ ràng buộc máy đã trao nó</strong>, và kéo dài đúng bằng thời gian kết nối. Ai ngắt kết nối thì không giữ gì cả — nếu không thì rời phòng sẽ khoá bạn khỏi chính track của mình cho tới hết phiên.","changelog.8d5007a0052a":"⛔⛔ <strong>Kumite — một trận đấu beat trong đó mỗi lượt sở hữu các ô nhịp của riêng mình.</strong> Mỗi lượt nhận một đoạn rời nhau trên dòng thời gian, cố định từ khi trận đấu bắt đầu, nên <em>tới lượt ai</em> và <em>trong phạm vi của họ</em> là cùng một câu hỏi. ⚠ <strong>Đồng hồ đếm ngược trên màn hình không chặn gì cả, và đó là chủ ý</strong>: một phép kiểm tra dựa vào đồng hồ thật sẽ để hai máy tính đi tới hai câu trả lời ngược nhau cho cùng một chỉnh sửa và để hai dự án lặng lẽ trôi xa nhau. Trì hoãn đồng hồ chẳng được lợi gì, và không có lượt nào để giành hay để không chịu nhường.","changelog.884f0b382cfc":"⚠ <strong>Cửa sổ ô nhịp bao phủ việc đặt clip.</strong> Pattern, track, tự động hoá, làn CC và làn trống vốn trải dài cả dòng thời gian theo cấu trúc và vẫn theo quy tắc người-ghi-sau-thắng; bảng nói rõ điều đó thay vì để bạn tự phát hiện.","changelog.a7e65a956e7d":"⛔⛔ <strong>Bảng chia phần được suy ra, và phần việc bạn đã lấy lại không được tính.</strong> Hoàn tác là một thao tác bình thường trong nhật ký, nên một cách đếm ngây thơ sẽ ghi công cho nhà sản xuất tám nốt mà họ đã hoàn tác — và ghi công hai lần, một lần cho phần việc và một lần cho lệnh hoàn tác. Làm lại cũng được giải quyết: phần việc bị hoàn tác rồi được làm lại sẽ được ghi công lại. ⚠ Theo từng tác giả: số thao tác, nốt, clip, thiết bị và các track họ đã chạm vào, với các phần chia cộng lại đúng bằng tổng mà chúng là phân số.","changelog.2b918a7903cf":"⚠ <strong>Một sự thật được suy ra thì không thể gõ vào.</strong> <code>Contribution</code> không mang chút văn bản nào — chỉ id, số nguyên và dấu thời gian — và nó không có bộ giải tuần tự, nên nó không bao giờ có thể tới từ một tệp, một người cùng phòng hay từ trang. Nó chỉ có thể được tính ra. Tên được phân giải ở rìa, từ id, và một tác giả mà máy này không có kênh nào sẽ giữ id của họ thay vì mượn biệt danh của người khác.","changelog.a0d3d98f71d7":"⚠ <strong>Xuất ra Markdown, CSV và PDF chưa được dựng</strong>, và cột phần trăm có thể chỉnh sửa cũng chưa. Thứ được phát hành là phần suy ra, trên màn hình.","changelog.f4799f613685":"Thay đổi — người cùng phòng không thể nói dưới danh nghĩa người khác","changelog.d169d798cfa7":"⛔⛔ <strong>Danh tính là kết nối, không phải một trường trong thông điệp.</strong> Cho tới bản phát hành này, tác giả của một thao tác là một chuỗi do người gửi tự chọn: phép kiểm tra cũ chỉ từ chối một thao tác tự nhận là <em>bạn</em>, và không làm gì với một người cùng phòng đóng dấu danh tính của <strong>bên thứ ba</strong> lên một thao tác. Điều đó sẽ khiến một track được bàn giao, một lượt đấu và một dòng ghi công đều làm giả được, mỗi thứ chỉ bằng một dòng.","changelog.e345cf9eb7ad":"▶ Phòng không có tài khoản và không có gì có thể ký một thông điệp, nên Oscillate dùng thứ duy nhất nó biết chắc: kết nối mà các byte thực sự đi tới. Thông điệp đầu tiên trên một kết nối giới thiệu ai đang nói, và sau đó <strong>không nửa nào của cặp đó được đổi</strong> — một kết nối không thể tự đổi tên, và một kết nối mới không thể tự nhận là người mà Oscillate đang nghe từ một kết nối khác. ⚠ Một danh tính chưa từng thấy được tin ở lần đầu nó lên tiếng; không có tài khoản thì không có cách nào tốt hơn, và giả vờ khác đi sẽ tệ hơn cả giới hạn này.","changelog.e4feb5900f76":"⛔ <strong>Một lần bị từ chối không còn là một lỗi vi phạm.</strong> Ba lỗi vi phạm sẽ ngắt kết nối một người cùng phòng, và trước đây mọi lần bị từ chối vì quyền đều bị tính — nên ai đó có đồng hồ đếm ngược nói chuông chưa reo, hoặc có quyền vừa bị thu hồi một khoảnh khắc trước, bị tính lỗi vi phạm vì hành xử đúng như thiết kế. Giờ chỉ thông điệp sai dạng hoặc giả mạo mới bị tính, và sự phân biệt đó là một lỗi biên dịch chứ không phải một lời chú thích.","changelog.bdb9d0d768f8":"Sửa lỗi — năm ngõ cụt trong bảng phòng","changelog.c26c74c2acfa":"⛔⛔ <strong>Một vùng đã thu gọn có thể mở lại.</strong> Bảng phòng tự ẩn khi hẹp hơn 1180 pixel CSS và nút trên thanh tiêu đề của nó bị <strong>vô hiệu hoá</strong> — nhưng một laptop 1280 pixel ở mức co giãn màn hình mặc định của Windows báo khoảng 853, nên trên một máy bình thường <strong>không có cách nào mở phòng cả</strong>. Giờ thu gọn là một mặc định mà bạn có thể ghi đè. Chật chội mà dùng được còn hơn đúng mà không với tới được.","changelog.68ce629f09b9":"⛔ <strong>Đã có đường lui từ một phòng tạo dở.</strong> Một nhà sản xuất đã nhấn <em>Tạo</em> rồi lại muốn vào phòng của một người bạn thì bị mắc kẹt: không có ô tham gia, không có <em>Rời</em>, và không có gì đưa bảng về điểm đầu. Khởi động lại ứng dụng là cách khôi phục duy nhất.","changelog.9a716d44d5e3":"⛔ <strong>Một lỗi có tên giờ có một nút bấm bên dưới.</strong> Khi một kết nối thu thập ổn thoả nhưng rồi không bao giờ mở, bảng vẽ ra một lời giải thích chính xác cho một lỗi vĩnh viễn mà không có gì để nhấn — <em>một vòng xoay chờ với thêm vài bước</em>.","changelog.e95b50b168e7":"⛔ <strong>Một mã rỗng là một lời từ chối, không phải một mã.</strong> Khi không có backend, bảng vẽ một ô trống với nút <em>Sao chép</em> vẫn hoạt động và lời cảnh báo <em>hãy coi nó như mật khẩu</em> ngay bên cạnh.","changelog.2efd7314519c":"⚠ <em>&quot;Đang nhận dự án…&quot;</em> không còn nằm đè lên một bảng đang rảnh, và người tham gia thứ hai và thứ ba nhận một ô dán trống thay vì văn bản của người trước.","changelog.0294d79bbe62":"Thêm mới — một phím biến phiên thành thứ bạn có thể đăng lên","changelog.2b19ee32f945":"⛔⛔ <strong>Thẻ phiên.</strong> Nhấn <code>Ctrl/Cmd+Shift+C</code>, hoặc Tệp ▸ <em>Thẻ phiên…</em>, và Oscillate vẽ một ảnh 1200×630 của phiên — nhịp độ, giọng, bao nhiêu track và clip, dài bao lâu, hình dáng của bản phối và dấu hiệu Oscillate. Lưu hoặc sao chép nó rồi đăng lên.","changelog.789fdbc637f7":"⛔ <strong>Mã phòng mặc định là tắt</strong>, và công tắc của nó mang lời cảnh báo ngay bên cạnh chứ không giấu trong chú giải: <strong>hãy coi nó như mật khẩu — ai nhìn thấy nó cũng có thể vào phòng.</strong> Khi không có phòng nào đang mở, công tắc nói rõ điều đó thay vì nằm xám ở đó mà không giải thích gì.","changelog.70bf28ecdf8d":"⛔ <strong>Một tấm thẻ không thể làm lộ máy của bạn, và đó là tính chất của thiết kế chứ không phải một bộ lọc.</strong> Các dữ kiện dùng để dựng thẻ <strong>không có chỗ nào để chứa văn bản</strong> — không tên dự án, không tên track, không tên sample, không đường dẫn. Không có bộ làm sạch nào để làm sai vì không có gì để làm sạch.","changelog.2ffea8d2ddec":"⚠ <strong>Lưu là nút luôn hoạt động.</strong> Việc nền tảng này có cho Oscillate đặt ảnh vào khay nhớ tạm hay không là điều chúng tôi không thể hứa, nên <em>Sao chép</em> nói thẳng khi nó không làm được thay vì trông như đã thành công.","changelog.49b5e00378e0":"⚠ Hình dáng được vẽ từ toàn bộ bản phối, không phải phần đang trên màn hình — nên cùng một phiên tạo ra cùng một tấm thẻ ở cả hai lần.","changelog.5eabaf9d3bff":"Thêm mới — phiên của bạn mở được mà không cần Oscillate","changelog.85583a70d607":"⛔⛔ <strong>Tệp ▸ Xuất thư mục đi kèm…</strong> biến phiên thành một thư mục các tệp thông thường: một stem dài trọn bài cho mỗi track, một tệp MIDI cho mỗi phần, tất cả các phần trong một <code>.mid</code> type-1, một bản đồ nhịp độ và một README giải thích tất cả. <strong>Ở mọi nơi khác, tệp dự án là con tin.</strong> Một cộng sự không có Oscillate thả các stem vào ô nhịp 1 và chúng thẳng hàng.","changelog.b3048638cc00":"▶ <strong>Mọi stem đều dài bằng cả bài</strong>, nên không có gì phải xê dịch cho vào chỗ.","changelog.353e48b03b6b":"⛔ <strong>Một phần bị tắt tiếng vẫn được kết xuất và đặt tên, không bao giờ bị lặng lẽ bỏ đi.</strong> Trao cho ai đó một tệp im lặng có tên đúng, độ dài đúng là cách tệ nhất để bỏ sót một track, vì nó trông như đúng — nên Oscillate vẫn kết xuất nó và liệt kê nó dưới <em>MUTED PARTS</em> trong README, để bạn tắt tiếng lại nếu muốn đúng những gì đã phát.","changelog.a9bc3aab7e27":"⛔ <strong>README cũng nói rõ những gì KHÔNG có trong thư mục.</strong> Oscillate kết xuất các stem này mà không có bất kỳ VST 3 hay CLAP nào có trong phiên — các thiết bị riêng của Oscillate thì có, plugin thì không — và một cộng sự nhận được một phần nghe không đúng xứng đáng được biết lý do thay vì bị để đoán mò. Giới hạn đó được ghi vào tệp mà mọi bản xuất tạo ra.","changelog.83bc1a94a3b0":"⚠ <strong>Một phiên dài hơn mười phút chưa thể xuất theo cách này</strong>, và nó nói rõ điều đó thay vì tạo ra một thứ bị cắt cụt.","changelog.76f000611d9c":"Thêm mới — bản master cho bạn biết mỗi dịch vụ sẽ làm gì với nó","changelog.c8f1227e67e3":"⛔⛔ <strong>Đo master trung thực.</strong> Nhấn <strong>Độ lớn</strong> trong bàn trộn và Oscillate hiện LUFS tích hợp, ngắn hạn và tức thời của master, dải độ lớn của nó, và <strong>đỉnh thực tính bằng dBTP</strong> — rồi, bên cạnh mục tiêu được công bố của mỗi dịch vụ, dịch vụ đó thực sự sẽ làm gì với bản master này. Một bản master ở −9.16 LUFS so với −14 của Spotify sẽ bị <strong>giảm 4.84 dB</strong>, và bảng nói đúng bằng những lời đó.","changelog.fdb6d3d5fb12":"▶ <strong>Ai cũng có LUFS. Không ai cho bạn biết nó có nghĩa gì với nơi bản thu sắp tới.</strong> Bảng đó chính là ý nghĩa của tính năng.","changelog.e3f75c74b59a":"⛔ <strong>Đỉnh thực không phải đỉnh mẫu, và cho tới giờ Oscillate chỉ có cái thứ hai.</strong> Bộ chuyển đổi dựng lại dạng sóng <em>đi qua</em> các mẫu, và dạng sóng đó có thể vọt cao hơn mẫu cao nhất — nên một limiter đặt theo đỉnh mẫu sẽ bị clip khi phát trong khi đồng hồ đo hiện −0.1. Giờ Oscillate đo ở mức oversampling 4×, đúng như ITU-R BS.1770-4 yêu cầu, và báo bằng dBTP để chính đơn vị cho bạn biết bạn đang nhìn con số nào.","changelog.db653ea0e802":"⛔ <strong>Mục tiêu không phải là quy tắc, và mỗi hàng đều nói rõ nó là loại nào.</strong> Phần lớn trong số này là chuẩn hoá khi phát mà người nghe có thể tắt; hai cái — EBU R 128 và ATSC A/85 — là đặc tả giao nộp thật sự. Ghi chú là một phần của hàng, không phải một chú giải bạn phải đi tìm. ⚠ Bảng nằm trong <code>data/loudness-targets.json</code> kèm ngày kiểm tra lần cuối, vì những con số này thay đổi.","changelog.721221e316a5":"⛔ <strong>Luôn luôn hai chữ số thập phân, và một số liệu chưa ai đo là một dấu gạch chứ không phải một con số.</strong> Một đồng hồ đo làm tròn theo cách tâng bốc là một đồng hồ đo nói dối lịch sự, và &quot;−200.00 LUFS&quot; không phải là phép đo của bất cứ thứ gì.","changelog.b4bf7c9e9637":"⚠ <strong>Mặc định tắt, vì nó tốn thời gian xử lý</strong>, và nút bấm nói rõ điều đó.","changelog.b0bc2e5d54c5":"Thêm mới — bàn trộn có thể cho bạn biết hai track nào đang tranh nhau","changelog.92a06653ecc1":"⛔⛔ <strong>Ra-đa che lấp.</strong> Nhấn <strong>Ra-đa</strong> trong bàn trộn và Oscillate liệt kê các cặp track chiếm cùng một phần của phổ tần, cặp tệ nhất trước, gọi tên dải tần nơi chúng gặp nhau. Nhấp vào một hàng và nó đưa bạn tới một trong hai track.","changelog.2e33bd64d89d":"▶ <strong>Đó là số học, và bảng nói đúng như vậy.</strong> Âm thanh của mỗi track được rút gọn thành năng lượng của ba mươi mốt dải một-phần-ba quãng tám; hai track ghi điểm cao ở một dải khi năng lượng của chúng <em>giống nhau</em> và cả hai đều <em>thực sự có mặt</em>, và một va chạm là một cặp giữ trạng thái đó suốt một giây rưỡi. iZotope tính tiền cho một đồng hồ đo che lấp và dựa vào học máy; đây là một phép tính chồng lấn có sẵn trong hộp, và chú giải nói cho bạn điều đó thay vì ngụ ý điều khác.","changelog.e7e45a4d31f7":"⛔ <strong>Mặc định tắt, vì nó tốn thời gian xử lý</strong>, và nút bấm nói rõ điều đó trước khi bạn nhấn. Tắt nó sẽ giải phóng các bộ phân tích và dừng luồng âm thanh ghi lại — tắt là tắt thật.","changelog.0acfd6d0ea4c":"⛔ **Một cặp mà Oscillate chưa nghe được vẽ là <em>chưa nghe thấy</em>, không bao giờ là sạch.** Hai track chưa tạo ra âm thanh nào không phải là hai track được xác nhận sạch, và một bảng báo điều thứ hai khi ý nó là điều thứ nhất sẽ là đưa ra một khẳng định mà chưa ai đo.","changelog.dd554854708c":"⚠ <strong>Những gì chưa có, nói thẳng.</strong> Không có <em>Gợi ý</em>: ra-đa cho bạn biết chồng lấn ở đâu nhưng không đề xuất một động thái EQ, và nhấp vào một hàng chọn một trong hai track thay vì mở cả hai. Và một phiên có hơn ba mươi hai track chỉ được theo dõi tới đó — bảng nói rõ điều này thay vì vẽ phần còn lại là sạch.","changelog.766ccc081745":"Thêm mới — bản dựng giờ từ chối một tính năng mà ứng dụng không với tới được","changelog.d340e8a8a795":"⛔⛔ <strong><code>check-commands.mjs</code>: mọi <code>#[tauri::command]</code> phải nằm trong <code>generate_handler!</code>.</strong> Đây là một cổng chặn <strong>lỗi mà dự án này đã phát hành nhiều hơn bất kỳ lỗi nào khác</strong> — một cơ chế sống lâu hơn nơi gọi duy nhất của nó, mười bảy lần được ghi nhận. Một lệnh thiếu trong danh sách đó vẫn <strong>biên dịch được, qua được clippy, qua được <code>cargo test</code>, và không tồn tại đối với trang</strong>: không lỗi, không cảnh báo, không bài kiểm thử nào thất bại, chỉ là một tính năng lặng lẽ vắng mặt trong ứng dụng phát hành. Từng có cả một giai đoạn không với tới được theo cách này.","changelog.6a242e5b8d08":"▸ <strong>Nó thất bại theo cả hai chiều</strong> — một lệnh không ai đăng ký, và một cái tên còn sót trong danh sách sau khi hàm của nó đã bị đổi tên. ▸ <strong>Nó không thể khớp với chính văn bản của nó.</strong> Phiên bản hiển nhiên của phép kiểm tra này grep tên lệnh và vì thế khớp với chính khai báo <code>fn</code>, bỏ qua đúng thứ nó được viết ra để bắt; phép này so sánh hai <em>tập hợp</em>, nên không có phép tìm chuỗi con nào để đánh lừa. ▸ <strong>Và nó từ chối báo một lượt quét sạch trên hư không</strong>: nếu một trong hai bên phân tích ra ít hơn một trăm mục thì việc phân tích đã hỏng, và cổng thất bại thay vì báo &quot;sạch&quot;. Một cổng đạt khi chẳng tìm thấy gì còn tệ hơn không có cổng, vì người ta tin nó.","changelog.368c3ca85aec":"⚠ Nó chạy trong <code>npm run ci:local</code> và trong job chuỗi cung ứng của CI. Nó đã được nhìn chuyển đỏ theo cả hai chiều trước khi được commit, và cây mã nó canh hiện đang sạch ở mức <strong>163 khai báo, 163 đăng ký</strong>.","changelog.c791e210b65a":"Thêm mới — lời của bạn nằm trên dòng thời gian, và take nhớ những lời nào","changelog.f5e9ebab3d41":"⛔⛔ <strong>Làn lời bài hát.</strong> Nhấn nút lời bài hát trên thanh công cụ bản phối và một dải mở ra bên dưới thước với lời của bạn trải dọc theo bài. Dòng bạn đang ở được vẽ bằng màu nhấn và âm tiết dưới đầu phát sáng lên khi nó đi qua — đọc từ <strong>chính tick dùng để vẽ đầu phát</strong>, sáu mươi lần mỗi giây, không bao giờ từ một bộ hẹn giờ. Một máy nhắc chữ chậm hơn transport là điều duy nhất tính năng này không bao giờ được phép làm.","changelog.47d04dae6e96":"▸ <strong>Nhập <code>.txt</code> hoặc <code>.lrc</code>.</strong> Một tệp <code>.lrc</code> có thời gian sẽ rơi đúng vào các ô nhịp nó được hát — các dấu <code>[mm:ss.xx]</code> của nó được chuyển đổi qua bản đồ nhịp độ của dự án, nên một bài chậm lại ở ô nhịp chín vẫn thẳng hàng. Văn bản không có thời gian được trải ra khắp đoạn và bạn xê dịch từng dòng vào chỗ, mỗi lần một ô nhịp, mỗi lần một bước hoàn tác. ⚠ Lời trong tệp được sao chép vào dự án; chính tệp thì không bao giờ được tham chiếu lại, nên một bản lời bạn kéo ra từ thư mục tải về sẽ không tự trống trơn vào tuần sau.","changelog.9ed712d8b53f":"▸ <strong>Take nhớ những lời mà nó được hát theo.</strong> Khi một bản thu được ghi xong, nó ghi lại bản lời nào đang trên màn hình, nên một bản comp dựng từ bốn take mang đúng đoạn verse trong mọi vùng. ⛔ <strong>Và viết lại một dòng không viết lại lịch sử</strong>: chỉnh sửa đầu tiên sau khi một take được ghi giữ lại lời cũ cho take đó và cho bạn một bản lời mới để làm việc. Xoá một bản lời mà các take đang trỏ tới sẽ hỏi hai lần và cho bạn biết có bao nhiêu take.","changelog.c7fbbc8b0881":"⚠ <strong>Chưa được dựng</strong>: kéo một dòng bằng con trỏ (hiện tại các nút xê dịch là thứ di chuyển dòng) và tách một dòng thành âm tiết bằng tay.","changelog.eda939abbe78":"Thêm mới — một máy nhắc chữ bạn đọc được từ bên kia căn phòng","changelog.9c8a4a093ca5":"⛔⛔ <strong>Ba cách để nhìn lời, và không cách nào cần màn hình thứ hai.</strong> Biểu tượng lời bài hát trên thanh công cụ bản phối vẫn mở chúng <strong>ngay trong</strong> làn. Cạnh nút Thu âm giờ có thêm hai cách: <strong>Máy nhắc chữ</strong>, mở một máy nhắc chữ nổi cỡ lớn đè lên phiên, và <strong>⇱</strong>, chuyển nó vào <strong>một cửa sổ riêng</strong> cho màn hình thứ hai. Cả ba vẽ cùng những lời từ cùng một tick — tick dùng để vẽ đầu phát — nên làn và máy nhắc chữ không bao giờ bất đồng về dòng bạn đang ở.","changelog.162980882b3e":"▸ <strong>Cỡ chữ dành cho giá micrô, không phải cho bàn làm việc.</strong> Cỡ nhỏ nhất của máy nhắc chữ lớn hơn ba lần cỡ chữ thân của ứng dụng, và thanh trượt chỉ đi lên từ đó. Mức sàn đó được bảo đảm hai lần, trong mã và trong stylesheet, và được <em>đo</em> trong một trình duyệt thật thay vì chỉ khai báo — vì một cỡ chữ được ghi ra mà không bao giờ được áp dụng trông y hệt một cỡ chữ đang hoạt động.","changelog.bc3bce45fb64":"▸ <strong>Lật gương, cho kính máy nhắc chữ.</strong> Chữ hiện ngược trên màn hình để tấm kính lật lại đúng chiều cho ca sĩ. ⚠ Các nút điều khiển không bao giờ bị lật: một thanh trượt bạn không ngắm được còn tệ hơn không có thanh trượt.","changelog.b5cab03de549":"▸ <strong>Tương phản cao</strong> — trắng trên đen ở cả hai giao diện, 21:1, vượt xa tiêu chuẩn trợ năng khắt khe nhất hiện có. Âm tiết bạn đang ở giữ màu nhấn và gạch chân của nó.","changelog.09c361712c76":"▸ <strong>Tốc độ cuộn</strong>, và nó trung thực về việc nó làm: transport quyết định <em>khi nào</em> một dòng trở thành dòng hiện tại, nên nút điều khiển chỉ thay đổi tốc độ cột chữ di chuyển tới đó — từ cắt tức thì tới trượt chậm. Không có gì ở đây được điều khiển bởi đồng hồ.","changelog.03410a1b5d7b":"<code>Esc</code> cất máy nhắc chữ nổi đi. Nút ⇲ của cửa sổ tách rời ẩn nó đi, nên nó trở lại đúng chỗ và đúng trạng thái bạn đã để.","changelog.18c67528e236":"Thay đổi — trang ghi công thôi phóng đại những gì được phát hành","changelog.509f0435939b":"⛔⛔ <strong>Nó ghi &quot;926 thành phần&quot;. 360 trong số đó là công cụ dựng hoàn toàn không có trong Oscillate</strong> — các trình biên dịch và trình chạy kiểm thử dùng để dựng dự án, không bao giờ tới máy của bạn. Cài đặt → Ghi công giờ nói thẳng hai con số: <strong>567 thành phần được phát hành bên trong Freally Oscillate</strong>, và 360 thành phần khác chỉ từng chạy trên máy đã dựng nó. Đây là trang tồn tại để bạn tự kiểm chứng lời khẳng định &quot;miễn phí, và không AI&quot;, nên một con số tâng bốc chúng tôi là thứ tệ nhất nó có thể mang.","changelog.5814ad801a5b":"▸ <strong>Danh sách được phân nhóm, và bạn thấy được mỗi thứ là gì.</strong> SDK plugin, codec âm thanh, crate Rust, bộ biểu tượng, gói npm, và tác phẩm minh hoạ do chủ sở hữu Oscillate vẽ — sáu tiêu đề, vì câu hỏi &quot;cái nào trong số này là codec?&quot; không trả lời được từ một danh sách phẳng chín trăm hàng.","changelog.f9de56f9441e":"▸ <strong>Mọi thành phần có ghi tên tác giả giờ đều hiện tên đó</strong>, và đó là ý nghĩa thật sự của lời hứa mà một trang ghi công đưa ra. ⚠ Gói npm không ghi tên tác giả ở bất cứ chỗ nào Oscillate đọc được mà không phải hỏi máy chủ, và Oscillate không hỏi máy chủ, nên các hàng đó không hiện tác giả thay vì một phỏng đoán.","changelog.3d0eb391f040":"▸ <strong>VST 3 Plug-In SDK được liệt kê, kèm thông báo bản quyền của nó</strong> — nó không nằm trong lockfile nào, nên chưa từng có gì đặt nó vào đó, và giấy phép đòi đúng một điều đó.","changelog.7377a939c0c4":"Thêm mới — take bạn vừa thu tới được nhà sản xuất kia","changelog.7fb3fbc8f280":"⛔⛔ <strong>Bản thu thì được gửi đi; gói sample thì không.</strong> Take là thứ duy nhất bạn sở hữu một cách không thể tranh cãi, nên khi ai đó vào phòng của bạn, các take bạn đã thu đi theo dự án và clip của họ phát được. Mọi thứ bạn đã mua thì ở nguyên chỗ cũ, và danh sách những thứ cần đi kiếm không thay đổi.","changelog.0e125500e568":"▶ <strong>Oscillate biết một take là của bạn vì chính nó đã ghi tệp đó</strong>, ngay lúc ghi — không phải đoán từ đường dẫn. Và nó chỉ bao giờ gửi một tệp thực sự nằm trong thư mục Takes của chính nó, nên một dự án ai đó gửi email cho bạn không thể biến máy bạn thành con đường chuyển tiếp tệp của <em>họ</em>.","changelog.52dc23d22b34":"▸ <strong>Một take tới nơi không phải của bạn để chuyển tiếp.</strong> Mỗi máy chỉ bảo đảm cho những gì chính nó đã thu. ⚠ Điều này được viết ra như một quy tắc trước khi nó đúng: mã lẽ ra phải xoá dấu đánh dấu không hề tồn tại, nên take của một cộng sự lẽ ra đã được đưa tiếp cho người thứ ba như thể bạn đã thu nó. Giờ nó được thực thi, theo cả hai chiều, với một cổng kiểm tra canh chừng.","changelog.4976afdf942b":"▸ <strong>Bảng cho biết bao nhiêu take đã tới</strong>, bên cạnh danh sách những sample chưa tới. Một clip bắt đầu phát vài giây sau khi bạn vào phòng là tính năng đang hoạt động, và trước đây không có gì trên màn hình nói điều đó.","changelog.91203a1b805c":"Sửa lỗi — một sample được nhập bị đánh dấu là bản thu của chính bạn","changelog.bf40e3fa098c":"⛔⛔ <strong>Mọi tệp âm thanh bạn nhập qua bản phối đều được ghi vào dự án như một take do Oscillate tạo ra.</strong> Nó dùng chung một đường mã với trình thu âm và đường đó đặt dấu đánh dấu vô điều kiện, kèm lời chú thích khẳng định chỉ có trình thu âm tới được nó. Hai hệ quả kéo theo: một cộng sự không bao giờ được báo một sample bạn nhập đến từ gói nào, nên họ không thể đi mua nó; và một khi take bắt đầu được gửi đi, một sample đã mua lẽ ra cũng đi theo. Giờ nhập và thu được phân biệt bằng hệ thống kiểu thay vì bằng một lời chú thích.","changelog.8d484c32c666":"Thêm mới — gói sample của bạn vẫn là của bạn","changelog.8f6475f914ce":"⛔⛔ <strong>Oscillate không phải là cách để chuyển gói sample giữa các máy tính, và giờ nó thực thi điều đó thay vì chỉ hứa.</strong> Khi bạn làm việc với ai đó, thứ đi qua là <em>tham chiếu</em> của dự án tới một âm thanh — không bao giờ là âm thanh, và không bao giờ là đường dẫn nơi nó nằm trên đĩa của bạn.","changelog.f988bbb09929":"▶ <strong>Nếu cả hai bạn đều sở hữu gói, nó cứ thế phát.</strong> Oscillate nhận ra âm thanh của cộng sự trong thư viện của chính bạn theo nội dung của nó, nên cùng một gói hoạt động bất kể bạn để nó ở đâu hay đã đổi tên thư mục thành gì. Bạn không phải định vị thứ gì cả.","changelog.c8bdf1531d58":"▸ <strong>Nếu bạn không sở hữu nó, Oscillate cho bạn biết nó là gì</strong> — gói nào và tệp nào — và clip im lặng cho tới khi bạn có nó, từ cộng sự qua Discord hoặc bằng cách mua, như bạn vốn vẫn làm. ⚠ Một sample của bạn có cùng tên nhưng âm thanh khác được báo là khác thay vì bị lặng lẽ đặt vào chỗ, vì làm vậy sẽ thay đổi bản thu mà không cho bạn biết.","changelog.4649fcb81559":"⚠ <strong>Điều này đúng trong suốt lúc bạn làm việc, không chỉ khi bạn vào phòng.</strong> Một sample được kéo vào track giữa phiên được gửi đi với đường dẫn đã bị gỡ, như mọi thứ khác.","changelog.57f9f9dbb430":"Thêm mới — một dấu trên các gói mà cả hai bạn cùng sở hữu","changelog.1c9cfe9ae3ee":"▸ <strong>Giờ Oscillate có thể cho bạn biết gói sample nào của bạn mà những người bạn đang làm cùng cũng có</strong> — từng byte một, không phải theo tên. Một thư mục cả hai bạn đều có sẽ có một dấu bên cạnh trong trình duyệt, để bạn biết ngay một âm thanh mình định dùng là thứ họ thực sự nghe được.","changelog.3f47892c9684":"⚠ Nó so sánh theo hai bước để luôn nhanh: tên tệp và kích thước trước, không đọc gì từ đĩa của bạn, và phép kiểm tra đầy đủ từng byte chỉ trên những gói mà hoá ra người khác cũng có. Một gói cả hai bạn đều có dưới tên thư mục khác nhau vẫn khớp.","changelog.7bec1b129e12":"⛔ <strong>Nó đánh dấu, và chỉ làm vậy thôi.</strong> Không có gì được gửi đi — một kết quả khớp cho bạn biết âm thanh giống hệt nhau, và nó không bao giờ có thể cho ai biết mỗi bạn đã có nó bằng cách nào.","changelog.bb2db2d36be7":"Sửa lỗi — bảng phòng hoàn toàn không có trên màn hình","changelog.55a9091211cb":"⛔⛔ <strong>Vùng phòng chỉ vẽ tiêu đề, nút tách rời và không gì khác.</strong> Mọi thứ phía sau đã được dựng mà không thứ nào với tới được: không nút để nhấn, không mã để sao chép. ⚠ Được tìm ra bởi một bài kiểm thử nhìn vào trang <em>đã dựng</em> thay vì vào một thành phần.","changelog.1ec729130651":"▸ ⚠ <strong>Và dải hiện/ẩn của bàn phím ảo quá nhỏ để là một mục tiêu dễ nhấn</strong> — cao 21 pixel trong khi mọi thứ nhấn được nên cao ít nhất 24. Nó chỉ hiện ra ở mọi nơi từ bản phát hành trước, và đó là lúc nó bắt đầu có ý nghĩa.","changelog.57877c1f100c":"Sửa lỗi — hoàn tác không làm gì sau khi mở một dự án đã lưu","changelog.5243b35620d0":"⛔⛔ <strong>MỞ MỘT DỰ ÁN, THAY ĐỔI MỘT CHỖ, NHẤN <code>Ctrl+Z</code> — VÀ CHẲNG CÓ GÌ XẢY RA.</strong> Mỗi lần khởi động cấp cho máy tính này một danh tính mới, trong khi dự án đã lưu nhớ người đã viết ra nó, nên sau khi mở một tệp, thay đổi của bạn bị xếp dưới tên người khác và lệnh hoàn tác của bạn không tìm thấy chúng. ⚠ Không có lỗi nào: mục menu đơn giản là xám và phím tắt không làm gì.","changelog.c356d2d80bd1":"▸ Giờ máy tính này giữ một danh tính duy nhất, nên mở lại dự án hôm qua cũng mang về lịch sử hoàn tác bạn để lại trong đó — đúng thứ mà tệp dự án vốn được thiết kế để mang.","changelog.f0d11ed91957":"Thêm mới — biến một bản thu thành nốt, và một pattern thành bản thu","changelog.a7701541a706":"⛔⛔ <strong>NHẤP CHUỘT PHẢI VÀO MỘT CLIP VÀ NÓ TRỞ THÀNH LOẠI KIA.</strong> Một clip âm thanh trở thành một pattern nằm bên cạnh; một pattern trở thành âm thanh nằm bên cạnh. ⚠ <strong>Clip bạn bắt đầu không bao giờ bị thay thế</strong> — bạn yêu cầu loại kia, chứ không yêu cầu cái đầu tiên biến mất — và toàn bộ lần chuyển đổi là <strong>một lần nhấn hoàn tác</strong>, kể cả track nó tạo ra để đặt kết quả lên.","changelog.2a5ddf2c998c":"▸ <strong>Một bản thu trở thành nốt</strong> bằng cách lắng nghe xem mỗi nốt bắt đầu ở đâu và cao độ là gì. ⚠ <strong>Nó sẽ không hoàn hảo và nó nói rõ điều đó.</strong> Một vòng lặp trống chuyển ra <strong>chẳng được gì cả</strong>, và cho bạn biết có bao nhiêu nhát đánh nó không đọc ra được cao độ — một giai điệu mà bản thu của bạn không hề chứa còn tệ hơn một lời từ chối thành thật.","changelog.59ed1e55e7ad":"▸ <strong>Một pattern trở thành âm thanh qua bất cứ thứ gì có trên track đó</strong>: nhạc cụ trong khe của nó, rồi mọi hiệu ứng âm thanh phía sau, theo thứ tự, mỗi thứ được gọi tên trong dòng hiện ra khi xong. ⚠ Một thiết bị bạn đã tắt bằng chấm tím của nó, hoặc cả một nhóm bạn đã tắt, <strong>không</strong> có trong bản kết xuất. ⚠ Fader và pan của track cố ý <em>không</em> được in vào — clip mới phát qua chúng, nên in chúng vào sẽ áp dụng hai lần.","changelog.083ef45f5391":"▸ <strong>Nếu khe nhạc cụ trống, nó nói rõ đã dùng âm thanh nào thay thế</strong>, và một sampler chưa nạp gì sẽ <strong>bị từ chối kèm tên gọi</strong> thay vì trả về hai giây im lặng.","changelog.79e200253532":"▸ <strong>Tiến độ là một con số, không phải một vòng xoay chờ.</strong>","changelog.85981714a333":"Thêm mới — phòng mở ra, và không ai phải chạy máy chủ","changelog.4749e8ae03da":"⛔⛔ <strong>BỐN NHÀ SẢN XUẤT, MỘT PHIÊN, KHÔNG MÁY CHỦ.</strong> Nhấn <em>Tạo mã phòng</em>, gửi mã cho ai đó, dán mã họ gửi lại, và các bạn đã kết nối. <strong>Không tài khoản, không đăng nhập, không có gì phải duy trì chạy và không có gì ai đó có thể tắt đi.</strong>","changelog.40cbdaae0aa4":"▸ <strong>Giờ đã có nửa của người tham gia.</strong> Dán mã vào bảng phòng và Oscillate trả lời bằng một mã của riêng nó để gửi lại — mảnh còn thiếu khi phiên bản trước tạo được phòng mà không ai vào được.","changelog.5417dcda779c":"▸ ⛔ <strong>Người thứ ba và thứ tư chỉ tốn mỗi người một lượt trao đổi, không phải sáu.</strong> Khi hai người đã kết nối, kết nối đó mang lời giới thiệu cho tất cả những người khác: một phòng bốn người là <strong>ba</strong> lượt trao đổi thay vì sáu như một mạng lưới đầy đủ lẽ ra cần, và người thứ ba và thứ tư không bao giờ phải dán gì cho nhau.","changelog.e32d5d96e2d3":"▸ <strong>Bạn thấy được ai đang ở đây.</strong> Một danh sách thành viên với mỗi người một màu — cùng một màu ở mọi nơi người đó xuất hiện — và <strong>con trỏ của họ di chuyển trên bản phối của bạn</strong> khi họ làm việc. ⚠ Tên do chính người dùng tự gõ và danh sách nói rõ điều đó: không có tài khoản, nên không có gì kiểm tra được tên.","changelog.309b2d70f417":"▸ <strong>Trò chuyện, chừng nào phòng còn.</strong> ⛔ Nó không được ghi ở đâu cả — không xuống đĩa, không vào dự án, không vào cài đặt của bạn.","changelog.63c63c2cdd7b":"▸ ⛔ <strong>Lệnh hoàn tác của bạn là của bạn.</strong> <code>Ctrl+Z</code> lấy lại thay đổi gần nhất <strong>của bạn</strong> và không bao giờ của người khác, kể cả khi chỉnh sửa của họ đang rơi xen giữa chỉnh sửa của bạn. Hai người sửa cùng một thứ vào cùng một lúc cuối cùng sẽ thấy cùng một kết quả, mà không máy nào phải hỏi gì.","changelog.f28f76dbdb7c":"▸ ⚠ <strong>Khi không kết nối được, nó cho bạn biết vì sao.</strong> Khoảng một cặp trong mười không thể kết nối trực tiếp với nhau, và Oscillate gọi tên nguyên nhân thật — kể cả <strong>đo</strong> được trường hợp mạng của bạn cấp cho mỗi máy chủ một địa chỉ khác nhau, trường hợp mà ngoài relay ra không gì giúp được. ⛔ Không có vòng xoay chờ nào quay mãi mãi.","changelog.17298de48df2":"▸ ⛔ <strong>Bạn được cho biết nó sẽ liên hệ với gì, và nó đã liên hệ với gì.</strong> Mở phòng sẽ hỏi một máy chủ STUN công khai về địa chỉ của bạn — các máy chủ nó sẽ thử được liệt kê trên bảng trước khi bạn nhấn gì, những máy chủ thực sự trả lời nằm trong Cài đặt ▸ Cộng tác sau đó, danh sách là của bạn để thay thế, và <strong>Không liên hệ máy chủ nào</strong> tắt hẳn việc này.","changelog.63cb58714c59":"▸ ⛔⛔ <strong>Mã phòng chứa địa chỉ công khai của máy bạn</strong>, và đó là điều khiến một phòng không máy chủ khả thi. <em>&quot;Hãy coi đây như một mật khẩu&quot;</em> nằm bên cạnh <strong>mọi</strong> nút sao chép mã.","changelog.9191285a6277":"⚠ <strong>Không có gì được khởi chạy cho tới khi cần</strong> — không phòng, không tiến trình, và không có hộp hỏi tường lửa nào trên một máy chưa từng có ai mở phòng.","changelog.e3b418ec5f75":"⚠ <strong>Những gì chưa có:</strong> người vào phòng <strong>không</strong> nhận được dự án của bạn. Cho tới khi tính năng đó có mặt, cả hai máy phải mở cùng một tệp <code>.oscillate</code> thì các chỉnh sửa mới mang cùng một ý nghĩa.","changelog.e9c85ff00dfa":"Sửa lỗi — chưa từng có gì đọc dạng sóng của một thư mục","changelog.d7b3c5728d91":"⛔⛔ <strong>THÊM MỘT THƯ MỤC GIỜ SẼ ĐỌC DẠNG SÓNG CỦA NÓ.</strong> Lẽ ra nó đã làm vậy từ trước: có một lượt quét, một thanh tiến độ và một bộ nhớ đệm, và <strong>không có gì trong chương trình từng khởi động nó</strong>. Mọi dạng sóng đều được vẽ lần đầu khi bạn tình cờ nhấp vào tệp đó, đúng lúc bạn ít muốn chờ nhất. ⚠ Thanh bên cạnh danh sách thư mục giờ đã chạy, kèm số tệp.","changelog.c5045ae52aa6":"Thêm mới — tệp nằm đúng chỗ bạn thả, và mỗi thiết bị có mặt hiển thị riêng","changelog.8aa7963ebacf":"⛔⛔ <strong>KÉO MỘT SAMPLE TỪ EXPLORER VÀ THẢ VÀO BẢN PHỐI.</strong> Âm thanh vào làn âm thanh còn MIDI vào làn MIDI; loại sai sẽ <strong>bị từ chối thay vì lặng lẽ được cấp một track mới</strong>, và đích thả nói rõ điều đó trước khi bạn buông tay. Khoảng trống bên dưới track cuối cùng tạo ra một làn đúng loại, đặt tên theo tệp. ⚠ Nhiều tệp cùng lúc sẽ nằm nối đuôi nhau và tính là <strong>một</strong> lần nhấn hoàn tác, và một tệp <code>.mid</code> tới nơi dưới dạng nốt trên chính lưới của dự án thay vì theo nhịp độ nó được viết.","changelog.e2a8868bca4e":"▶ <strong>Việc này không cần quyền mới nào.</strong> Thao tác kéo đi trên cùng kênh mà đồng hồ đo dùng; đường dẫn tệp hoàn toàn không bao giờ tới được trang.","changelog.c170e8e66577":"⛔⛔ <strong>LIMITER KHÔNG CÒN TRÔNG NHƯ EQ.</strong> Mỗi thiết bị trong bảy mươi lăm thiết bị tự khai báo mặt hiển thị của nó — nó vẽ gì phía trên các nút điều khiển, nó muốn rộng bao nhiêu, và nút nào trong số đó là những nút bạn hay với tới trước. Equaliser vẽ đáp tuyến của nó; compressor vẽ lượng nó đang cắt bớt, với con số bên cạnh thanh. ⚠ Một mặt hiển thị mà bản dựng này chưa đo được thì <strong>không vẽ gì</strong> thay vì một hình bịa ra.","changelog.9913ddb063ed":"⛔⛔ <strong>NHÓM CÁC THIẾT BỊ, VÀ TẮT CẢ MỘT NHÓM BẰNG MỘT CHẤM.</strong> Đánh dấu hai thẻ trở lên trong giá, nhấn <em>Nhóm</em>, và chúng cùng chuyển vào dưới một tiêu đề có tên, một mũi tên gập và một chấm tím duy nhất — đặc khi nhóm bật, rỗng khi nhóm tắt. ⚠ Tắt rồi bật lại một nhóm trả lại đúng những gì bạn đã có, kể cả thiết bị bên trong mà bạn đã cố ý bỏ qua. ⛔ Một dự án có nhóm vẫn mở được trên bản dựng chưa từng biết tới nhóm.","changelog.7742cde966eb":"▸ <strong>Mọi thẻ thiết bị cũng có chấm đó</strong>, trên thiết bị riêng của Oscillate lẫn trên plugin VST 3 và CLAP.","changelog.70451f4cd15b":"▸ <strong>Có thể kéo thiết bị từ trình duyệt vào giá</strong>, thả vào đúng khe bạn chọn — những khe không nhận nó sẽ nói lý do trước khi bạn thả.","changelog.e5e7c82e5751":"▸ <strong>Âm thanh độc quyền trên Windows, theo sự kiện.</strong> Thiết bị chỉ thuộc về Oscillate và đường trộn của hệ thống bị bỏ qua; màn hình cài đặt báo những gì thực sự đã mở chứ không phải những gì được yêu cầu. ⚠ Bất cứ điều gì máy từ chối đều lùi về một luồng dùng chung hoạt động được thay vì im lặng.","changelog.9cc28e987ea4":"Sửa lỗi — nốt của chính plugin không có chỗ nào để đi","changelog.e38c38ecdf91":"⛔ <strong>Nốt do plugin phát ra giờ có một cổng kiểm tra ở mọi chặng.</strong> Chúng được rút ra từ plugin, chở qua đường ống và đẩy vào khối — và bài kiểm thử duy nhất trên đường truyền đó gửi đi gửi về một danh sách sự kiện <strong>rỗng</strong>, nên hai mươi byte mà một sự kiện chiếm chưa từng được thứ gì kiểm tra.","changelog.14fc2e72aca1":"Thêm mới — trình chỉnh sửa plugin mở được, và trình duyệt biết bạn đang ở làn nào","changelog.3a086a46c809":"⛔⛔ <strong>CỬA SỔ RIÊNG CỦA PLUGIN ĐÃ MỞ ĐƯỢC.</strong> Hộp cát sở hữu một cửa sổ cấp cao thật với vòng bơm thông điệp, nên trình chỉnh sửa VST 3 hay CLAP hiện ra, di chuyển, đóng lại và <strong>mở lại</strong> được — đóng trình chỉnh sửa không còn có nghĩa là phải xoá thẻ để lấy nó lại. ⚠ Một plugin từ chối hiện trình chỉnh sửa giờ được phân biệt với một plugin bị sập: một lời từ chối không làm xám thứ gì.","changelog.1aed8953980f":"▸ <strong>Mục Plugin liệt kê những gì trình quét tìm thấy</strong>, và plugin xuất hiện <strong>ngay khi được tìm thấy</strong> thay vì tất cả ở cuối. ⚠ Việc quét không còn mở một cửa sổ console cho mỗi plugin — lần quét đầu một thư viện thật từng nháy ra hàng chục cửa sổ như vậy.","changelog.84b095c699d5":"▸ <strong>Đầu track nói nó là MIDI hay Âm thanh, bằng một từ.</strong> Huy hiệu trước đây là một ký hiệu nhỏ nằm sau <code>aria-hidden</code>, chẳng nói gì với trình đọc màn hình và nói rất ít với nhà sản xuất mới; câu hỏi nó phải trả lời là <em>tôi có thể đặt hiệu ứng nào ở đây</em>.","changelog.dc9fc03cc83d":"▸ <strong>Trình duyệt đi theo làn đang chọn.</strong> Một làn âm thanh không liệt kê plugin nhạc cụ hay hiệu ứng nốt, vì nó không có nốt nào để đưa cho chúng; một danh mục có sẵn không phù hợp sẽ nói rõ thay vì trống trơn. Các hiệu ứng âm thanh riêng của Oscillate không bao giờ bị ẩn — chúng thuộc về cả hai loại làn.","changelog.899b576b1610":"▸ <strong>Nhạc cụ thứ hai thay thế nhạc cụ thứ nhất</strong>, như mọi DAW khác vẫn làm, trong một thao tác nên một lần nhấn hoàn tác đưa nhạc cụ cũ trở lại cùng thiết lập của nó.","changelog.ece91873bdd3":"Sửa lỗi — plugin đồng bộ nhịp độ bị báo sai thời gian","changelog.940e26b06d02":"⛔⛔ <strong>ĐẦU PHÁT THÌ KHỚP; DÒNG THỜI GIAN XUNG QUANH NÓ THÌ KHÔNG.</strong> Mỗi khối, plugin được trao một transport. Vị trí phách của nó luôn là thật — năm trường bên cạnh là hằng số, và <strong>cả hai định dạng plugin đều khai báo các trường đó là hợp lệ</strong>:","changelog.f753d55e9822":"⛔ <strong>Vị trí mẫu của VST 3 là một bộ đếm chạy tự do</strong>, không phải đầu phát. Nó khớp cho tới lần định vị lại đầu tiên rồi lệch vĩnh viễn, đúng bằng khoảng đã nhảy — nên một plugin tin vào đồng hồ chính xác từng mẫu sẽ trôi khỏi lưới ngay khi bạn lặp.","changelog.f49a399d635c":"⛔ Dòng thời gian tính bằng giây là <code>0</code>, trong khi CLAP được báo nó hợp lệ.","changelog.f6279218ddd3":"⛔ Vòng lặp dài bằng không, trong khi VST 3 khai báo các trường chu kỳ là đáng tin.","changelog.17084eb56c2d":"⛔ Loại nhịp luôn là bốn-bốn, nên mọi thứ đồng bộ theo ô nhịp đều sai ở 3/4 hay 7/8; ô nhịp luôn nhận là bắt đầu ở đầu bài; và cờ thu âm luôn là false.","changelog.9cdee9cc734d":"▸ Giờ cả năm đều lấy từ chính transport, và vị trí mẫu được <strong>suy ra</strong> từ đầu phát thay vì đếm riêng — hai đồng hồ sẽ lệch nhau, một đồng hồ thì không thể.","changelog.77ad99f84eb0":"Thêm mới — Windows mở được luồng độ trễ thấp, và bảng thôi phỏng đoán","changelog.a602943c1b8b":"⛔⛔ <strong>CHIẾC THANG CÓ THỂ CẤP MỘT BẬC MÀ KHÔNG GÌ MỞ ĐƯỢC.</strong> Oscillate đã hỏi Windows engine âm thanh của nó chạy ở chu kỳ nào từ Giai đoạn 7; điều nó không làm được là mở một luồng ở chu kỳ đó. <code>cpal</code> không thực hiện lời gọi <code>IAudioClient3::InitializeSharedAudioStream</code> và không thể được yêu cầu làm vậy, nên <code>ModeReason::LowLatencyNotBuilt</code> tồn tại để nói thật điều đó thay vì hứa một độ trễ mà sản phẩm không mang lại được.","changelog.e7258ea8357b":"▸ <strong>Giờ đã có backend âm thanh thứ hai.</strong> <code>MMDeviceEnumerator</code> ▸ <code>IAudioClient3</code> ▸ <code>GetSharedModeEnginePeriod</code> ▸ <code>InitializeSharedAudioStream</code>, theo sự kiện, với luồng kết xuất riêng. Trên máy phát triển, cả hai đầu cuối đều trả lời <strong>480 khung ở 48 kHz</strong>. ⚠ Mọi thất bại đều lùi về luồng dùng chung thông thường và vẫn phát ra tiếng: một bản Windows cũ hơn, một trình điều khiển không nhận chu kỳ đó, một định dạng trộn không phải float 32-bit.","changelog.861accbc382a":"⛔ <strong>Chuỗi lý do đã đổi nghĩa, nên nó đổi câu chữ trong cả 18 ngôn ngữ.</strong> <code>lowLatencyNotBuilt</code> trước đây nghĩa là <em>Oscillate không làm được việc này</em>. Giờ nó nghĩa là <em>máy này không chịu</em>, và đó mới là chỗ đáng đổ lỗi.","changelog.6e9efa7f4ed8":"Sửa lỗi — bảng âm thanh báo một dự đoán thay vì một sự thật","changelog.ea32534bf5d0":"⛔⛔ <strong>CÀI ĐẶT ▸ ÂM THANH GỌI THIẾT BỊ LÀ “DÙNG CHUNG” TRONG KHI MỘT LUỒNG ĐỘ TRỄ THẤP ĐANG PHÁT QUA NÓ.</strong> Chiếc thang quyết định dựa trên những gì trình điều khiển <em>quảng cáo</em>: một chu kỳ tối thiểu từ 128 khung trở xuống ở 48 kHz. Các đầu cuối của máy phát triển quảng cáo 480 — vậy mà <code>InitializeSharedAudioStream</code> vẫn mở được chúng.","changelog.b78ee47f67e4":"▶ <strong>Bảng không còn dự đoán về một thiết bị đang mở.</strong> Engine ghi lại bậc nó thực sự lấy và điều đó thắng tuyệt đối; chiếc thang giữ một công việc trung thực, đó là nói một thiết bị <strong>chưa</strong> mở có lẽ sẽ cho được gì. ⚠ Một bản sửa trước đó đã chỉnh dự đoán dựa trên engine, và một lần chỉnh chỉ có thể <em>trừ bớt</em> khỏi một dự đoán mà nó không đưa ra — nên nó bắt được một chiều và mù với chiều kia.","changelog.8870524415ec":"⛔ <strong>Và chu kỳ trên màn hình giờ là chu kỳ đo được.</strong> Trước đây là <code>min_period_frames</code>, tức điều trình điều khiển tuyên bố, hiện bên cạnh một luồng đang chạy ở bất cứ mức nào <code>InitializeSharedAudioStream</code> đã cấp. Với một thiết bị chưa mở thì số quảng cáo vẫn được giữ, ở đó nó là một dự đoán chứ không phải lời khẳng định về một thứ đang chạy.","changelog.e255b62cecd9":"⛔ <strong>Một lời từ chối giữ lại lý do của nó.</strong> Một trình điều khiển không chạy nhanh tới vậy, một bản Windows quá cũ cho <code>IAudioClient3</code> và một thiết bị đã biến mất từng bị gộp vào một câu trả lời trống, và bảng gắn nhãn cả ba là <em>&quot;máy này không mở được luồng độ trễ thấp&quot;</em> — thứ khiến người ta đi cập nhật Windows vì một thiết lập trình điều khiển.","changelog.5b21975b68bb":"Sửa lỗi — bảng âm thanh báo một quyết định thay vì một sự thật","changelog.2718cbe5591b":"⛔⛔ <strong>Dựng backend lại mở ra đúng lời nói dối đó ở tầng trên.</strong> Khi luồng độ trễ thấp đã là thật, chiếc thang cấp bậc đó cho mọi trình điều khiển đủ nhanh — và khi việc mở sau đó thất bại, engine lặng lẽ lùi về trong khi bảng vẫn ghi <em>&quot;Độ trễ thấp, dùng chung&quot;</em>. ▸ Cài đặt ▸ Âm thanh giờ báo những gì engine đang chạy thực sự đã lấy, không phải những gì được quyết định cho nó.","changelog.795cdd276d4e":"Sửa lỗi — một khối 10 ms được lập lịch như một trình soạn thảo văn bản","changelog.ebec07e8645f":"⛔ <strong>Luồng kết xuất chưa được đăng ký với MMCSS.</strong> Xin trình điều khiển 480 khung chẳng được gì nếu luồng lấp đầy chúng có thể bị một thao tác kéo cửa sổ chen ngang. Giờ nó tham gia tác vụ <strong>Pro Audio</strong>, và một cổng kiểm tra đọc mức ưu tiên của chính luồng kết xuất từ bên trong callback — <strong>0 → 15</strong> — thay vì tin suông.","changelog.c73668bfb50e":"Thêm mới — plugin phát ra tiếng, lần đầu tiên","changelog.73ae63bbe1c7":"⛔⛔ <strong>CHƯA TỪNG CÓ VST 3 HAY CLAP NÀO XỬ LÝ MỘT KHỐI ÂM THANH TRONG SẢN PHẨM NÀY.</strong> Suốt Giai đoạn 6 và Giai đoạn 7, plugin được quét, nạp, kích hoạt, báo độ trễ, ghi độ trễ đó trở lại dự án và mở cửa sổ trình chỉnh sửa riêng — mọi bước đều có cổng kiểm tra và đều xanh — trong khi tín hiệu đi <strong>thẳng qua bên cạnh nó</strong>. Thứ nhà sản xuất nghe thấy là track không có plugin của họ, trong khi cửa sổ plugin đang mở ngay trước mặt.","changelog.732aab71cf12":"▶ <strong>Bốn điều phải cùng đúng một lúc</strong>: <code>DeviceRack</code> giữ <code>Vec&lt;Box&lt;dyn StockDevice&gt;&gt;</code>; cửa duy nhất của <code>GraphBuilder</code> là <code>registry::build</code>; <code>Channel::chain</code> được đánh khoá theo một <code>type_id</code> của registry mà plugin không có; và <code>oscillate_app::mixer</code> mở vòng lặp chiếu của nó bằng <code>let DeviceKind::Stock { .. } else { continue }</code>. ⚠ <strong>Lần thứ tám dự án này tìm thấy một cơ chế hoàn chỉnh mà không có gì gọi tới.</strong>","changelog.4d8fc1027169":"⚠ <strong><code>oscillate-audio</code> vẫn không phụ thuộc vào <code>oscillate-host</code>, và không được phép.</strong> Engine khai báo một <em>hình dạng</em> — <code>rack::ForeignDevice</code> — và <code>src-tauri</code>, vốn đã phụ thuộc vào cả hai, cung cấp một cái. Engine vẫn không thể mở thư viện dùng chung, và giờ nó chạy được thứ mà một bên khác đã mở.","changelog.f8700736d0be":"Thêm mới — một track có thể phát đầu ra plugin của track khác","changelog.3e316a37dda0":"Thứ mà Live gọi là <strong>&quot;MIDI From → track → Plug-in Output&quot;</strong>, và <code>InputRouting</code> có thêm <code>notes_from</code>. ⛔ <strong>Đây là lỗi đặc trưng ở dạng thuần khiết nhất:</strong> đầu ra của một plugin phát nốt được CLAP rút ra, được VST 3 rút ra, được <code>AudioMessage::events</code> chở ngược qua đường ống và đẩy vào danh sách của bên gọi — năm chặng đều đúng — rồi bị <strong>bỏ đi</strong>, vì trong engine không có chỗ nào để đặt nó.","changelog.bcc00e454522":"⚠ Một tuyến là một <strong>cạnh thứ tự</strong> trong cùng lượt sắp xếp tô-pô dùng để sắp thứ tự định tuyến âm thanh, nên nốt thuộc về khối này chứ không phải khối trước, và hai track trỏ vào nhau sẽ bị từ chối thay vì bị kết xuất trễ một khối mãi mãi.","changelog.2447de6a9358":"Thêm mới — thu MIDI, việc Oscillate chưa từng làm","changelog.0bba2bd8bed7":"<code>capture::NoteCapture</code> — không khoá, không cấp phát, mười sáu nghìn nốt, và <strong>mỗi nốt mang theo vị trí của nó tính bằng subtick</strong>, vì một vòng đệm chỉ chứa thông điệp trần sẽ đặt mọi nốt của take vào phách một. ⛔ Được ghi lại <strong>sau</strong> khi các nốt được định tuyến nhập vào và <strong>trước</strong> chuỗi nốt của chính track, đúng thứ mà mọi DAW đều thu: đầu vào, không phải kết quả sau hiệu ứng. Ghi sau chuỗi sẽ nướng luôn arpeggiator vào, và phát clip trở lại qua nó sẽ rải hợp âm lên chính phần đã được rải.","changelog.71aaaf954cef":"⚠ Một take được ghi thành <strong>một</strong> <code>Operation</code> mang hai chỉnh sửa — pattern và clip đặt nó — nên hoàn tác không để lại một pattern mà không có gì phát nó.","changelog.44edd735e062":"Thêm mới — Cài đặt ▸ Âm thanh, và chiếc thang quyết định dựa trên sự thật","changelog.26faed29b702":"⛔ <strong>Tab đó vẽ ra phần thân trống suốt tám giai đoạn</strong>, trong khi <code>device::enumerate</code>, <code>device::resolve</code>, <code>negotiate</code>, <code>Granted</code> và <code>ModeReason</code> nằm trong engine mà <strong>không có nơi gọi nào bên ngoài <code>device.rs</code></strong> — lần thứ chín của cùng một lỗi. Bảng liệt kê các đầu ra, chọn một đầu ra, chọn chiếm bao nhiêu thiết bị, và <strong>gọi tên thứ đã được cấp kèm lý do</strong>, vì sự đánh đổi giữa độ trễ và việc dùng chung thiết bị là quyết định của nhà sản xuất.","changelog.3eff9d3dc578":"<code>engineperiod::smallest_period</code> hỏi <code>IAudioClient3::GetSharedModeEnginePeriod</code> qua <code>windows-rs</code>, nên chiếc thang quyết định dựa trên chu kỳ engine thật thay vì mức sàn bộ đệm mà trình điều khiển quảng cáo. ⛔ <strong>Việc đó tìm ra hai lỗi thật</strong>: card âm thanh tích hợp của máy này quảng cáo mức sàn bằng <strong>không</strong>, mà <code>negotiate</code> đọc thành <code>0 &lt;= 128</code> và cấp bậc độ trễ thấp; và bảng lẽ ra đã báo <em>&quot;Độ trễ thấp, dùng chung&quot;</em> cho một luồng dùng chung bình thường, vì <code>InitializeSharedAudioStream</code> chưa được dựng. Cả hai đều được sửa, và lỗi thứ hai giờ là <code>ModeReason::LowLatencyNotBuilt</code> — một câu trả lời trung thực thay vì một lời nói dối ngay trên màn hình cài đặt của nhà sản xuất.","changelog.db88097b77e2":"Thêm mới — trình duyệt tệp, năm định dạng xuất, và phần nghe thử của trình duyệt","changelog.409208576c1a":"Trình duyệt tệp với transport nghe thử, nghe thử clip MIDI, thẻ nhạc cụ theo hai trục, bộ nhớ đệm và lập chỉ mục dạng sóng; xuất ra WAV, AIFF, FLAC, Ogg và MP3, master, stem và MIDI, với một bảng Cài đặt và tiến độ trung thực.","changelog.a7939e4436cb":"Đã đo — quyết định làm hay không làm ứng dụng web, sớm bốn bậc","changelog.93f8bbf3e20c":"⛔ <strong>Được dời lên từ <code>v2.0.0</code> theo lập luận của chủ dự án</strong>, và lập luận đó đúng: tìm ra ở <code>v2.0.0</code> nghĩa là tìm ra sau khi mọi tính năng đã được thiết kế hai lần. Cả hai câu hỏi đều được trả lời trong <code>web/spike/</code>.","changelog.799111b932af":"✅ <strong>DSP biên dịch ra <code>wasm32-unknown-unknown</code> ngay lần đầu</strong>, không phải sửa mã nguồn — kể cả <code>oscillate-synth</code> và kho 248 nhạc cụ có sẵn — và một cây đại dương cầm mô phỏng ở đa âm tối đa tốn khoảng <strong>11% của một khối 128 khung</strong>.","changelog.7ead2fc63ed7":"✅ <strong>Một VST 3 có thể tới được tab trình duyệt qua cầu nối native</strong>: một vòng đi-về loopback là <strong>p99 0.049 ms</strong>, khoảng 2% của một khối.","changelog.1f8fdb6a96c2":"⛔ <strong>Nhưng nó không nghe giống nhau.</strong> WASM và native lệch nhau ở khối đầu tiên 2.4e-5 rồi ổn định quanh <strong>−60 dBFS</strong>, vì 551 lời gọi hàm siêu việt mỗi khối được tính bởi bản port <code>libm</code> riêng của Rust trên wasm và bởi MSVC CRT trên native. ▶ Cách khắc phục có giới hạn — crate <code>libm</code> ở cả hai phía — và nó cũng làm dịch đầu ra của bản desktop, nên đó là một quyết định chứ không phải một bản vá.","changelog.09954837c4f4":"⚠ <strong>Giai đoạn 6 và 7 cùng được đưa vào <code>main</code> ngày 2026-08-29</strong>, dưới dạng merge commit <code>43785ad</code> và <code>7bb1ea1</code>. Cùng nhau chúng là bậc <code>v0.3.0</code> — một DAW chạy được plugin của bạn <em>và</em> có plugin riêng — và bậc này <strong>chưa được gắn tag</strong>: nó cần <code>REL-0.3.0</code>, bản dựng phát hành đầu-cuối, trước đã. <code>v0.2.0</code> và <code>v0.2.5</code> vẫn chưa được gắn tag phía sau nó.","changelog.9b1dcbd5fbd5":"Thêm mới — cả 248 nhạc cụ, các gói trống, và Freally MixSir","changelog.52be750b9006":"⛔⛔ <strong>DANH SÁCH TỪNG LÀ 197 VÀ LÝ DO ĐÁNG ĐỂ BIẾT.</strong> Nó <strong>duyệt</strong> <code>Kind::ALL</code> riêng của mỗi engine, nên nó chỉ có thể thấy những nhạc cụ mà một engine mô phỏng <em>gọi tên</em>. <code>SubBass</code>, <code>SawLead</code>, <code>WarmPad</code>, <code>Riser</code>, <code>VoxChop</code> và bốn mươi sáu nhạc cụ khác được định nghĩa bằng một <strong>patch</strong> thay vì một chỉ số kind — không lượt duyệt nào tới được chúng. Đó là toàn bộ khoảng cách giữa 197 và 248.","changelog.40218bb7cac0":"⛔ <strong>Và một chỉ số kind không phải là một âm thanh.</strong> Ghim <code>(Bowed, 2)</code> cho ra patch <em>mặc định</em> của engine kéo vĩ với <code>Cello</code> được chọn — không phải tiếng Cello mà nhà sản xuất nghe trong Freally MIDI Master, vốn là <code>generator::generate</code> → <code>articulation::apply</code> → <code>tone::apply</code>. Hai sản phẩm, cùng một cái tên, âm thanh khác nhau, và không có gì thất bại.","changelog.5e270075e2b0":"Vì vậy <code>factory/</code> là danh mục, <strong>được nhập vào</strong>: bảy tệp lấy nguyên từng byte từ module preset riêng của plugin, cộng một <code>preset.rs</code> suy ra từ phần của <code>mod.rs</code> không chứa khai báo module nào. Một cổng chống rẽ nhánh suy ra lại phần đó và thất bại kèm tên dòng. <code>style_sound</code>, <code>palette</code> và <code>user</code> được để lại — nửa dành cho nghệ sĩ/nhà sản xuất — và một bài kiểm thử thứ tư sẽ thất bại nếu một trong số đó xuất hiện.","changelog.3de65c2ec7b1":"⚠ <strong>Hai bản trùng cục bộ bị xoá thay vì giữ cạnh bản nhập.</strong> <code>natural_note</code> và <code>shape</code> theo từng họ của bộ nướng one-shot đều là bản sao thô hơn của <code>audition_note()</code> và <code>render_time()</code>, vốn đã được hệ phân loại mang <strong>theo từng nhạc cụ</strong>.","changelog.3a4683be12b7":"<strong>Điều chế cao độ, bàn phím và giá âm sắc.</strong> 91 trong 248 nhạc cụ có thể điều chế cao độ và 157 thì không, và đường chia cắt ngang qua các họ — riêng Bộ gõ đã có 11 có và 82 không — nên trình duyệt <strong>lọc</strong> bằng một nút viên thuốc chứ không bao giờ chia thư mục. Cả hai nửa của câu hỏi đều được trả lời: nút lọc để săn tìm, một dấu SVG nội tuyến trên mỗi hàng để duyệt. (Không phải <code>∿</code>, U+223F, ký tự không có trong Noto Sans và bị vẽ thành ô trống.)","changelog.542c14231314":"Phím của bàn phím ảo được ghi nhãn theo độ tương phản của một cây piano thật — phím trắng mang nhãn tối, phím đen mang nhãn sáng — qua <code>--color-text</code> thay vì một giá trị cố định, và đó là điều giúp nó sống sót ở cả hai giao diện. Nó được lưu lại và mặc định mở.","changelog.327f4ea52638":"Giá âm sắc phía trên nó mang chính những từ của plugin — <strong>Room, Heat, Echo, Gain, Pan, Pitch Mod</strong> — lấy ra từ danh mục của plugin trong cả mười tám ngôn ngữ, vì <em>&quot;một DAW gọi nó là 'Drive' trong khi plugin gọi nó là 'Heat' là hai cái tên cho một nút điều khiển&quot;</em>. ⛔ Nó hoàn toàn không được vẽ trên nhạc cụ không điều chế được cao độ. ⚠ Gain và Pan là của <strong>track</strong>, không phải một cặp thứ hai.","changelog.9fde2df9f578":"<strong>Các gói trống.</strong> Mười một bộ trống và 407 one-shot CC0, đi kèm và duyệt được. ⛔ Âm thanh được sao chép còn bộ sinh thì không: <code>kitgen</code> lấy mọi mẫu từ một luồng <strong>ChaCha8</strong> còn <code>rng</code> của Oscillate là <strong>SplitMix64</strong>, nên một bộ sinh được port sang sẽ phát hành một thư viện trống khác dưới cùng mười một cái tên.","changelog.36f9d92b4cee":"<strong>Freally MixSir</strong> — ghép đôi điện thoại bằng mã QR, gửi cho nó dự án đã phối dưới dạng stem, cân bằng bằng các núm vẽ ra, và tải về bản mix hoặc bất kỳ track nào dưới dạng WAV hoặc MP3. ⛔ Mọi thứ sau khi stem tới nơi đều diễn ra tại chỗ: bàn trộn và phần xuất hoạt động khi đã tắt mạng, và đó là toàn bộ ý nghĩa — <em>&quot;nhà một người bạn là một mạng khác. Một luồng trực tiếp chết ngay ở cửa trước. Một tệp thì không.&quot;</em>","changelog.94365ba1d670":"⛔ <strong>Mã bí mật của phiên không phải là tuỳ chọn.</strong> Mỗi lần ghép đôi một mã, không lưu gì lại, năm lần thất bại là lần ghép đôi chết, và chỉ một lời từ chối duy nhất không nói phần nào sai — vì một thông điệp phân biệt &quot;không có mã bí mật&quot; với &quot;sai mã bí mật&quot; sẽ cho kẻ tấn công biết họ đã đạt được điều nào trong hai.","changelog.083b2dd09b8a":"⛔ <strong>Mọi thẻ thiết bị đi kèm đều được ghi nhãn bằng ID của nó.</strong> Giá thiết bị hiện <code>whetstone</code>, <code>vise</code>, <code>factory.cello</code> — một định danh nội bộ ngay ở chỗ duy nhất nhà sản xuất nhìn vào để xem trên track của mình có gì.","changelog.6d162dd890d4":"⛔ <strong>248 nhạc cụ lẽ ra đã không có núm nào trên thẻ.</strong> Chúng không phải mục trong <code>registry::ALL</code> và được phân giải qua một lần tra cứu thứ hai mà đường dẫn của thẻ không thực hiện.","changelog.8ac445d35eda":"⛔ <strong>Một núm trên thẻ dịch nhầm tham số.</strong> Núm trên thẻ bỏ qua các lựa chọn, nên vị trí của núm trên thẻ không phải chỉ số của nó trong danh sách của thiết bị — và trên mọi thiết bị có bảng mở đầu bằng một bộ chọn chế độ, mỗi núm trên thẻ đều dịch nút điều khiển nằm phía trên nút mà nó được ghi nhãn. Một cách lặng lẽ.","changelog.a56a71232f82":"⛔ <strong>Công thức &quot;dự án → bàn trộn kết xuất được&quot; bị chia đôi.</strong> Vòng lặp nối mỗi kênh vào khe luồng của nó nằm bên trong một lệnh Tauri và không ở đâu khác, nên bất cứ thứ gì dựng bàn trộn mà không đi qua lệnh đó đều kết xuất ra <strong>im lặng</strong>.","changelog.7dfa8f74186b":"<strong>Khung nhìn bản phối tách ra thành cửa sổ riêng.</strong> ⚠ Tách rời và ẩn là hai việc khác nhau: ẩn nó sẽ để lại một DAW không có chỗ nào đặt clip, nên nó vẫn không có nút trên thanh tiêu đề — nhưng một nhà sản xuất có hai màn hình muốn dòng thời gian nằm trên màn hình lớn.","changelog.acbb6415e329":"<strong><code>cargo test --workspace</code> giảm từ 417 s xuống 166 s</strong>, và việc nướng one-shot từ 168 s xuống 15 s, không bỏ qua gì và không chia mảnh.","changelog.27f0c63ca33a":"Thêm mới — bạn có thể nghe một thiết bị trước khi dùng","changelog.9e4c221fc50d":"⛔⛔ <strong>KHÔNG CÓ GÌ TRONG OSCILLATE PHÁT ĐƯỢC TIẾNG CỦA MỘT THIẾT BỊ CHƯA NẰM TRÊN TRACK.</strong> Trình duyệt liệt kê bảy mươi lăm thiết bị bằng một cái tên gợi hình và một dòng tiếng Anh dễ hiểu, và để chọn giữa <code>Crucible</code> và <code>Muster</code> thì phải thêm một cái vào track, vẽ một nốt, nhấn phát, lắng nghe, xoá nó đi, rồi làm lại y như vậy với cái kia.","changelog.5804f25b08c9":"▶ <strong>Một trình phát nghe thử, bên dưới Trình duyệt tệp.</strong> Nhấp vào một thiết bị riêng của Oscillate và nó phát phần trình diễn của chính nó; chọn một thư mục rồi nhấp vào một sample và nó phát sample đó. Một trình phát thay vì mỗi hàng một transport: mỗi lúc chỉ một âm thanh được nghe thử, và dạng sóng có chỗ để nằm.","changelog.40cbef0ecde9":"<strong>Dạng sóng, cho cả nhạc cụ lẫn sample</strong> — giá trị nhỏ nhất và lớn nhất mỗi cột thay vì cứ N mẫu lấy một, nên transient của một nhát trống sống sót khi được vẽ. <strong>Nền phía sau phần đã phát đổi màu khi chạy</strong>, kèm đầu phát và số đọc <strong>giây đã chạy / tổng số giây</strong>.","changelog.f3f0517ac936":"<strong>Phát và dừng, một vòng lặp có thể tắt đi lại, và ← / → để chạy lùi và chạy tới.</strong> Đảo ngược là chiều mà chỉ số nguồn đi, không phải một bộ đệm thứ hai và không phải một đường mã thứ hai.","changelog.884d06fa9f2c":"<strong>Nốt, velocity và độ dài theo từng nhạc cụ</strong>, được đo chứ không đoán: <code>Crucible</code> và <code>Muster</code> giữ một nốt C3 hơn hai giây vì một patch wavetable và một bè mười hai nhạc công vẫn còn đang chuyển động ở giây thứ nhất; <code>Skin</code> được giữ 40 ms vì một tiếng kick toàn là đuôi; <code>Sideband</code> được đánh, nhả và để ngân.","changelog.8d682a63aee9":"⚠ <strong>Năm trong mười một nhạc cụ nói rõ vì sao chúng không phát được.</strong> <code>Flint</code>, <code>Armory</code>, <code>Bench</code>, <code>Hammer</code> và <code>Filings</code> là sampler và im lặng cho tới khi được nạp một tệp, nên chúng hiện câu đó thay vì một nút bấm chẳng phát ra gì. ⛔ Một cổng kiểm tra giữ vững ranh giới: mọi nhạc cụ đã dựng đều hoặc khai báo phần nghe thử, hoặc khai báo các khe sample.","changelog.151407842cb1":"⚠ <strong>Trình phát là một giọng được trộn SAU đồ thị</strong>, theo cách của <code>click.rs</code>. Nó phát được khi transport đang dừng, không cần dựng lại đồ thị, và không bao giờ cấp phát — bộ đệm được kết xuất ở tầng ứng dụng rồi trao xuống, và bộ đệm bị thay thế được <strong>gửi lại cho luồng ứng dụng thay vì bị giải phóng</strong>, vì giải phóng là anh em sinh đôi của cấp phát. Cổng kiểm tra luồng âm thanh bao phủ nó, và đã được nhìn thất bại với <code>deallocations: 1</code>.","changelog.e7fc9384962d":"Thêm mới — các nhạc cụ của Freally Secretarium, và nghe thử chỉ là đọc tệp","changelog.356af9b34f95":"⛔⛔ <strong>TRÌNH DUYỆT LIỆT KÊ MƯỜI MỘT NHẠC CỤ BỊA RA VÀ KHÔNG NHẠC CỤ THẬT NÀO.</strong> Chỉ dẫn của chủ dự án, nói bốn lần: <em>&quot;lẽ ra tôi phải có tất cả các nhạc cụ giống Freally MIDI Master&quot;</em>, <em>&quot;và Freally Secretarium&quot;</em>, <em>&quot;đúng những nhạc cụ đó, không phải mấy cái bịa ra&quot;</em>.","changelog.88620eb11d8a":"▶ **<code>synth/</code> trong workspace này <em>chính là</em> <code>havoc_dsp</code> của Secretarium<strong> — từng module một — và cả </strong>197<strong> nhạc cụ của nó đã được biên dịch sẵn vào Oscillate. Không có gì liệt kê chúng. <code>Quiver</code>, <code>Muster</code> và <code>Crucible</code> hiện ra ở chỗ lẽ ra phải là <code>Violin</code>, <code>Tuba</code>, <code>Grand Piano</code>, <code>Rhodes EP</code>, <code>Accordion</code> và các bộ trống 808/909/707/606. ⚠ </strong>Lần thứ sáu trong dự án này có một cơ chế đúng mà không có gì gọi tới**, và lớn nhất cho tới nay.","changelog.9d0068c6cd97":"⚠ <strong>Danh mục không cố định cái tên nào.</strong> <code>oscillate_dsp::secretarium</code> duyệt <code>Kind::ALL</code> riêng của mỗi engine và hỏi <code>name()</code> của nó, nên theo cấu trúc nó <em>chính là</em> danh sách của Secretarium và không thể trôi lệch.","changelog.527bd770093f":"Sửa lỗi — nhấp ▶ làm đứng ứng dụng chín giây","changelog.7cfc5be2b1d8":"⛔⛔ <strong>ĐO TRONG BẢN RELEASE, Ở 48 kHz:</strong>","changelog.00ab2993d58b":"▶ <strong>Mọi <code>#[tauri::command]</code> trong ứng dụng này đều đồng bộ, và một lệnh đồng bộ chạy trên luồng giao diện.</strong> <code>preview_device</code> dựng cả một nhạc cụ mô phỏng và kết xuất vài giây âm thanh ngay ở đó, mỗi lần nhấp — nên nhấp vào <code>Muster</code> làm đứng ứng dụng chín giây và nhấp lần nữa xếp hàng thêm chín giây. Đó là một nguyên nhân cho hai báo cáo của chủ dự án: <em>&quot;các nhạc cụ nạp rất chậm&quot;</em> và <em>&quot;tôi cứ nhấp nút để phát và cuối cùng nó sập&quot;</em>.","changelog.f75de40a46cd":"⛔ <strong>Bản sửa chính là thiết kế của chủ dự án</strong>: <em>&quot;nó chỉ nên nạp một clip âm thanh cho one shot, không phải cả nhạc cụ trừ khi nó được thêm vào khung nhìn bản phối&quot;</em>. <code>bake-oneshots</code> kết xuất cả 197 lúc dựng — <strong>mỗi cái ở đúng nốt mà nhạc cụ đó thực sự vang</strong>, theo âm vực thật của nó: <code>Tuba</code> ở C2, <code>Piccolo</code> ở C6, <code>Violin</code> ở G4, <code>Double Bass</code> ở E2. Bộ gõ không định âm được đánh dấu đúng như vậy thay vì được gán một nốt giả.","changelog.8d6da56f85ca":"<strong>197 clip, 22.6 MB, nướng trong 110 s</strong> — mono 16-bit, cân mức về −1 dBFS để so hai nhạc cụ là so âm thanh chứ không phải so gain, và được cắt ở chỗ âm thanh thực sự dừng thay vì ở một ngân sách đoán chừng.","changelog.94c1bdbaa43a":"<strong>Nghe thử giờ chỉ là đọc tệp: trung bình 0.19 ms, tệ nhất 0.5 ms.</strong> Trong tệp nhị phân phát hành qua CDP: danh sách 197 nhạc cụ hiện ra trong <strong>134 ms</strong>, và <code>Violin</code>, <code>Tuba</code> và <code>Grand Piano</code> nghe thử trong <strong>75 / 45 / 51 ms</strong>.","changelog.2dc07d5f1557":"⚠ Hai cổng kiểm tra giữ điều đó: mọi nhạc cụ đều có clip và không clip nào im lặng, và đọc một clip luôn dưới 50 ms.","changelog.c5ee9fe2006c":"⛔ <strong>Và các clip suýt nữa đã phát hành trong tình trạng không với tới được.</strong> Khai báo chúng là <code>../assets/oneshots</code> đặt một thư mục <strong><code>_up_</code></strong> theo đúng nghĩa đen vào cây đã cài đặt — <code>Freally Oscillate\\_up_\\assets\\oneshots\\</code> — trong khi ứng dụng phân giải <code>assets/oneshots</code>. Mọi lần chạy dev đều ổn, vì có một đường dự phòng của workspace trả lời; bản dựng <em>đã cài</em> lẽ ra đã chẳng tìm thấy gì và phát im lặng cho cả 197. ⚠ <strong>Được tìm ra bằng cách giải nén MSI và chạy bố cục đã giải nén với bản sao mã nguồn bị giấu đi</strong>, cách sắp đặt duy nhất mà đường dự phòng không thể cứu lỗi. Bộ nướng giờ ghi bên trong <code>src-tauri/</code>, nên không còn <code>../</code> nào dính vào.","changelog.f4ddb6130986":"Sửa lỗi — bấm liên tục <em>Thêm</em> sinh ra mỗi lần nhấp một tiến trình plugin","changelog.a8ec7142d4cc":"⛔ Báo cáo của chủ dự án: <em>&quot;nếu tôi thêm một plugin lặp đi lặp lại thật nhanh thì ứng dụng sập, nó không nên cố nạp nó 15 lần thật nhanh vào cùng một track audio/midi rồi sập&quot;</em>. Mỗi lần thêm khởi chạy một hộp cát <code>oscillate-hostproc</code> và chờ nó; mười lăm cú nhấp là mười lăm tiến trình được sinh ra tranh nhau trên luồng giao diện. ⚠ <strong>Bỏ đi, không xếp hàng</strong> — nhà sản xuất tì tay lên nút muốn thêm một thiết bị, không phải mười lăm.","changelog.7dda4841cc1a":"Thêm mới — chọn một nhạc cụ và chơi nó bằng ← và →","changelog.82c24a2d7b61":"⚠ Danh sách là một listbox: nhấp vào một cái tên để chọn nó, <strong>→ phát xuôi và ← phát ngược</strong>. ⛔ Chiều phát được đặt <em>trước</em> khi clip nạp — thứ tự ngược lại sẽ phát lần nhấn đầu xuôi chiều và chỉ đảo ngược ở lần thứ hai, trông như một lần nhấn phím bị rớt hơn là một lỗi.","changelog.fafc2a09973e":"Thêm mới — Trình duyệt tệp giờ là một trình duyệt thực thụ, bố trí theo cách của Ableton","changelog.edb9f6a2c94a":"⛔⛔ <strong>NÓ TỪNG LÀ MỘT DANH SÁCH PHẲNG, VÀ MỘT DANH SÁCH PHẲNG BẢY MƯƠI LĂM THIẾT BỊ LÀ MỘT BỨC TƯỜNG.</strong> Chỉ dẫn của chủ dự án: <em>&quot;nó nên có một danh sách như Plugins, Instruments, rồi một nút Add Folder … giống hệt cách bố trí trình duyệt của Ableton&quot;</em>.","changelog.5e9e61c53217":"▶ <strong>Một màn hình chính gồm các địa điểm</strong>, mỗi cái có một <code>›</code>: <strong>Nhạc cụ</strong>, <strong>Hiệu ứng âm thanh</strong>, <strong>Hiệu ứng MIDI</strong>, <strong>Plugin</strong>. Nhấp vào một mục và nó liệt kê những gì bên trong. Bên dưới là <strong>Chọn thư mục</strong>, và dưới đó là các thư mục bạn đã thêm, <strong>chỉ hiện tên</strong> — nhấp vào một tên và bạn có cây của thư mục đó: gốc, thư mục con, sample và MIDI.","changelog.099ce0f7d765":"<strong>← và → phía trên danh sách là ĐIỀU HƯỚNG</strong>, không phải phát. Lùi trở về các danh mục từng bước một; tiến đi lại theo vết cũ, hoặc — khi không còn gì phía trước — mở thư mục bạn ở lần cuối. ⚠ <strong>Một lịch sử, không phải một cờ chế độ</strong>: một biến boolean <code>showingCategories</code> không thể trả lời <em>&quot;tiến vào thư mục bạn ở lần cuối&quot;</em>, mà đó là toàn bộ ý nghĩa của mũi tên.","changelog.79957fde35e2":"<strong>Bộ lọc tìm trong bất cứ thứ gì bạn đang xem</strong>, và tìm theo việc một thiết bị <em>là gì</em> lẫn tên gọi của nó — <code>compressor</code> tìm ra <code>Vise</code>, cái tên chẳng nói gì về nó.","changelog.e8b3a1a389e9":"<strong><code>Plugins</code> nghĩa là plugin của người khác</strong>, như trong Ableton. Bảy mươi lăm thiết bị riêng của Oscillate nằm trong chỉ mục quét — chính điều đó mới làm danh sách với tới được — và được lọc ra lại ở đây, nếu không thì mỗi thiết bị sẽ xuất hiện hai lần và <em>Plugin</em> sẽ là chỗ duy nhất ai đó cần tới.","changelog.0047f4f33bdc":"<strong>Trình phát nghe thử được ghim cố định bên dưới trình duyệt</strong>, đúng như yêu cầu.","changelog.4f2676f1a739":"Sửa lỗi — ba lỗi mà việc viết lại trình duyệt gây ra, tất cả đều tìm ra nhờ chạy thử bản dựng","changelog.f49547b29542":"⛔ <strong>Một sampler bị báo là không có giọng.</strong> <code>previewDevice</code> chọn lời từ chối của nó từ một danh sách mà bảng cũ tải về khi gắn kết; bảng viết lại không tải nó, nên danh sách cứ trống và mọi sampler đều rơi xuống câu <em>&quot;thiết bị này không có giọng riêng&quot;</em>. ▶ <strong>Lần thứ tư trong dự án này có một cơ chế sống lâu hơn nơi gọi duy nhất của nó</strong>, và lần thứ ba ngay trong tính năng này. Hàng vốn đã mang câu trả lời, nên giờ lời từ chối lấy từ hàng và không còn danh sách thứ hai nào để lệch nhịp.","changelog.662d079a371c":"⛔ <strong>Phần hướng dẫn từng bước chụp ảnh một lời từ chối bên dưới chú thích hứa hẹn một dạng sóng.</strong> Nó nhấp vào nút ▶ đầu tiên trong danh sách, đó là <code>Armory</code> — một sampler. Sáu trong bảy mươi lăm thiết bị tự phát tiếng được; nút ▶ giờ nói nó thuộc loại nào trong <code>data-can-hear</code>, và phần hướng dẫn chọn một thiết bị phát được.","changelog.6d5cf6780d7a":"⛔ <strong>Không có gì canh quy tắc về độ dài của chính chủ dự án.</strong> <em>&quot;Không phải kiểu one shot 1 giây, mà kiểu one shot 2-4 giây để bạn nghe được cả dàn hay tiếng violin đang chơi&quot;</em> — và phép kiểm tra duy nhất là một khoảng <code>400..=6_000</code> trên một con số trong registry, vui vẻ cho qua một tiếng violin bị chặt ở 400 ms, vì một độ dài được khai báo không nói gì về việc <strong>âm thanh</strong> đã kết thúc hay chưa. Giờ có hai cổng kiểm tra lắng nghe thay vào đó:","changelog.67673c6c454c":"<code>no_instrument_is_cut_off_while_it_is_still_sounding</code> kết xuất từng phần nghe thử và đo một phần mười cuối cùng so với đỉnh của chính nó — một tỉ số, vì ba trong sáu thiết bị này cách nhau nhiều bậc về mức tuyệt đối và một ngưỡng tuyệt đối sẽ chỉ đo lại <em>chính</em> lỗi đó. Còn trong vòng 30 dB của đỉnh ở cuối nghĩa là bộ đệm kết thúc giữa chừng một nốt.","changelog.9dba8e1945f1":"<code>an_instrument_that_holds_a_note_demonstrates_for_at_least_two_seconds</code> đòi hai tới bốn giây với mọi thiết bị giữ nốt của nó trong một giây — trường hợp violin-và-kèn đồng mà chủ dự án đã nêu — trong khi để một tiếng hi-hat được đánh vẫn ngắn. Cả hai đều đã được nhìn thất bại: <code>crucible</code> bị cắt còn 1.5 s báo <em>&quot;vẫn còn vang ở mức −27.9 dB dưới đỉnh&quot;</em>.","changelog.3ac136922655":"Sửa lỗi — một đường dẫn từ trang tới được đĩa, và cổng kiểm tra không nhìn thấy","changelog.d83b8e757dd9":"⛔⛔ <strong><code>preview_file</code> NHẬN MỘT ĐƯỜNG DẪN TỪ WEBVIEW VÀ MỞ NÓ</strong>, và <code>no_command_opens_a_path_from_the_page</code> vẫn <strong>xanh</strong> trên nó. <code>Source::open(</code> có trong danh sách dấu hiệu của cổng đó; phần nghe thử giải mã ở tần số của phiên nên gọi <strong><code>Source::open_at</code></strong>, thứ mà mục đó không khớp.","changelog.f6e0367699b1":"▶ <strong>Đó chính xác là điều mà lời chú thích của chính danh sách dự đoán</strong> sẽ xảy ra khi một lời gọi có tên mới mà danh sách không được báo — và nó xảy ra hai lần trong một thay đổi, vì <code>preview_browse</code> tới <code>read_dir</code> qua một <code>listing_for</code> riêng tư và cũng không chứa dấu hiệu nào. Cùng một hình dạng với <code>place_recording</code> trước đó.","changelog.81f850dd8839":"⚠ Cổng giờ đã biết <code>Source::open_at(</code>, <code>read_dir(</code> và <code>listing_for(</code>, và khẳng định nó chọn ra <strong>năm</strong> lệnh nhận đường dẫn thay vì ba. Đã được nhìn thất bại: gỡ phép kiểm tra đi khiến nó nói <em>&quot;danh sách không phải là cổng; lời gọi mới là cổng.&quot;</em>","changelog.2d054f75b71a":"⛔ <strong>Chính phép kiểm tra là <code>oscillate_app::preview::Roots</code></strong> — các thư mục nhà sản xuất đã chọn trong một <strong>hộp thoại native</strong>, thứ mà trang không thể mở cũng không thể chọn thay ai. Cũng là lập luận mà <code>Session::knows</code> đưa ra về một dự án. Nó chuẩn hoá đường dẫn trước khi so sánh, nên <code>../</code> thoát ra khỏi cây, một liên kết tượng trưng thoát ra khỏi cây, và một thư mục anh em có chung tiền tố tên đều bị từ chối, mỗi trường hợp một bài kiểm thử.","changelog.eab49295e87c":"⚠ Tìm ra, chưa sửa — các giọng bộ gõ mô phỏng chưa được hiệu chỉnh mức","changelog.1db39a57f0b2":"⛔ <strong>Kết xuất một phần trình diễn là lần đầu tiên trong dự án này có thứ gì đó đo MỨC đầu ra của một nhạc cụ</strong>, và ba thiết bị lệch nặng. Ở thiết lập mặc định, ở 48 kHz:","changelog.8dbc3e72e325":"⚠ <strong>Các nút chỉnh <code>Level</code> được áp dụng và đang hoạt động</strong> — <code>Skin</code> mặc định ở −6 dB và <code>Bronze</code> ở −9. Chỉ là các giọng mô phỏng bên dưới chúng chưa được hiệu chỉnh, so với toàn thang hay so với nhau. Trên một track, <code>Skin</code> clip nặng còn <code>Sideband</code> thì không nghe thấy bên cạnh nó.","changelog.01769f9570bb":"⛔ <strong>Cố ý không sửa ở đây.</strong> Chỉnh lại ba thiết bị đã phát hành sẽ thay đổi mọi dự án đang dùng chúng, nên đó là quyết định của chủ dự án chứ không phải một thay đổi lặng lẽ khi đang thêm một tính năng trình duyệt. Phần nghe thử được cân mức — điều vốn đúng cho việc so sánh, và là điều mọi thư viện sample đều làm — và <code>Rendered::raw_peak</code> giữ con số thật để lỗi vẫn đo được. <code>the_percussion_voices_are_not_level_calibrated_and_this_says_so</code> khẳng định trạng thái hiện tại và sẽ thất bại vào ngày ai đó hiệu chỉnh chúng, và đó là lời nhắc để cập nhật bảng này.","changelog.d14d01c626ec":"Thay đổi — các bộ sinh là của Freally MIDI Master, không phải của Oscillate (Giai đoạn 8)","changelog.dc81dfbc9b4f":"⛔ <strong>Oscillate không mang mã sinh nội dung nào, và crate <code>engine</code> đã bị gỡ.</strong> Nó vốn là một chỗ giữ trống trong workspace từ commit đầu tiên, chờ được lấp đầy bằng một lần nhập giờ sẽ không bao giờ diễn ra.","changelog.e3f68ceb379a":"▶ Thay vào đó, Freally MIDI Master được phát hành như một <strong>plugin đi kèm chạy trong host</strong>, nên các bộ sinh của nó tới qua ranh giới plugin mà Giai đoạn 6 đã dựng — VST 3 và CLAP, ngoài tiến trình.","changelog.7fc1c070e5b4":"⚠ <strong>Vì sao một nguồn sự thật duy nhất tốt hơn một bản dựng khép kín ở đây.</strong> Nhúng engine vào sẽ có nghĩa là một bản sao từng byte được giữ nguyên bởi một cổng chống rẽ nhánh, một lần đồng bộ lại mỗi khi nguồn gốc thay đổi, và mã nguồn của một sản phẩm khác sống trong hai kho mã. Hai sản phẩm phải khớp nhau — cùng seed và cùng phong cách phải cho ra cùng một bản phối ở cả hai — và một bản sao chính là thứ đến lúc nào đó sẽ thôi khớp.","changelog.2048fc009c6c":"Thêm mới — các thiết bị riêng của Oscillate (Giai đoạn 7)","changelog.f5822af61c3c":"⛔⛔ <strong>SÁU MƯƠI CHÍN TRONG BẢY MƯƠI LĂM ĐÃ ĐƯỢC DỰNG</strong>, gồm cả hai mươi tám hiệu ứng cốt lõi, toàn bộ mười sáu thiết bị nốt, và chín nhạc cụ. ⚠ Sáu cái vẫn chỉ được khai báo, và mỗi cái bị chặn ở một đường nối chứ không phải ở DSP — chúng được liệt kê theo tên dưới mục <em>Những gì chưa được dựng</em> bên dưới, kèm thứ mỗi cái đang chờ.","changelog.668c497ed943":"⛔ <strong>Các thiết bị được dựng kể từ lần danh sách còn ghi năm mươi tư</strong>, và đường nối mà mỗi cái buộc phải có:","changelog.8e557db4dbd0":"<strong><code>Filings</code></strong> — một đám mây grain từ một clip, sáu mươi tư grain lấy từ một kho cấp phát trước. Chính các cổng kiểm tra của nó tìm ra hai lỗi trước khi phát hành: tổng các đường bao grain to bằng <code>Density × Grain Size</code>, nên làm dày một đám mây từ bốn mươi grain mỗi giây lên hai trăm làm tăng 14 dB; và một grain bị phun quá cuối nguồn thì im bặt khi đường bao đang ở mức đầy, đo được thấp hơn 23 dB.","changelog.50a4eea3576b":"<strong><code>Armory</code></strong> — tám vùng, mỗi vùng tám round-robin, trên một bảng phẳng 128×128 theo phím-và-velocity dựng ngoài luồng âm thanh, nên một nốt chỉ tốn một lần tra chỉ số và không phép tính nào. Công suất bằng nhau ở các mối nối, vì hai vùng của một multisample là hai bản thu khác nhau và crossfade tuyến tính giữa hai nguồn không tương quan sẽ hụt 3 dB. Kho giọng có thêm một đường bao bộ lọc thật cho nó.","changelog.25ae013f0dd8":"<strong><code>Sift</code></strong> — khử nhiễu phổ ở 4096/1024, nghĩa là <code>Stft</code> phải nhận độ dài khung lúc khởi tạo thay vì từ một hằng số của crate. Trừ theo miền công suất thay vì biên độ: một âm cao hơn nền 53 dB mất 0.12 dB theo cách này và chưa tới một phần nghìn decibel theo cách kia.","changelog.99e2902c99af":"<strong><code>Yield</code></strong> — giữ một phần tránh khỏi âm vực của track khác. Cần một đường nối chiếm dụng cao độ giữa các track: <code>Context</code> giờ mang một <code>&amp;[PitchSet]</code>, chỉ đọc và không khoá <em>theo kiểu dữ liệu</em> thay vì theo lời hứa, cộng ba tầm đọc trước để nút <code>Lookahead</code> của nó có ý nghĩa ở 0, 1 và 2 phách.","changelog.cc6fff187e87":"<strong><code>Press</code></strong> — bộ tạo hình MPE, cần <code>NoteMessage</code> mang <code>Pressure</code>, <code>Timbre</code> và <code>Bend</code>. Đánh khoá theo nốt thay vì theo kênh, vì kênh thành viên là một chi tiết truyền tải của MIDI 1.0. Nốt đồng thời thứ mười sáu bị từ chối và được đếm, không bao giờ bị cướp.","changelog.267f52bbec0d":"<strong><code>Ply</code></strong> — một bộ hoà âm đi theo hợp âm mà bản phối thực sự có. Các cổng kiểm tra của nó lòi ra ba lỗi: bộ dò cao độ đầu vào đọc bin to nhất, mà với một nguyên âm được hát thì đó là bất cứ hoạ âm nào được formant ưu ái — một giọng hát ở C giữa bị nhận là cao hơn một quãng tám và một quãng năm; làm tròn theo bin để lại khoảng trống khi dịch lên; và đường khô không được làm trễ cho khớp với đường ướt, nên ở mức mix mặc định nó là một bộ lọc răng lược mà đồ thị lẽ ra sẽ bù độ trễ đã khai báo bằng cách kéo đường khô lên sớm.","changelog.aadbc3dce93b":"<strong><code>Rein</code></strong> — một hiệu ứng được trình diễn bởi một clip MIDI thay vì một LFO. Cần velocity và mật độ nốt theo từng track trong chỉ mục bản phối.","changelog.f7bd53ba1079":"<strong><code>Muster</code></strong> — một phần được chơi bởi một bè tới mười hai nhạc công, thời điểm, cao độ, mức âm và attack của mỗi người được rút ra một lần từ seed của dự án và giữ cố định.","changelog.e4a1a80427f8":"<strong><code>Quiver</code></strong> — tám chuỗi dưới một bàn phím, các vùng nửa mở với fade công suất bằng nhau.","changelog.abefe55690b3":"⛔⛔ <strong>VÀ BỐN VI PHẠM LUỒNG ÂM THANH MÀ CỔNG CẤP PHÁT KHÔNG NHÌN THẤY.</strong> Nó duyệt mọi thiết bị đã dựng khi <strong>chưa nạp sample nào và không có nốt nào đang vang</strong>, nên đường đọc của mọi sampler và vòng lặp giọng của mọi nhạc cụ chưa từng một lần nằm dưới bộ cấp phát có đếm. Giờ nó nạp một clip vào mọi khe và đánh một hợp âm tám nốt hai lần, và nó tìm ra bốn:","changelog.dd412aa63e27":"<code>Skin</code>, <code>Bronze</code> và <code>Sideband</code> mỗi cái đều đọc <code>block.notes.to_owned()</code> — một <code>Vec</code> được cấp phát trong callback kết xuất ở mỗi khối có mang nốt.","changelog.1fe564b767bd":"<code>Crucible</code> nạp engine của nó từ <code>process</code>, và synth được nhập dựng trạng thái mô phỏng của một giọng ở lần đầu giọng đó được dùng — nên nốt đồng thời thứ chín cấp phát trong callback.","changelog.1743b0d8b2c4":"▶ <strong>Trước đây:</strong> cả hai mươi tám hiệu ứng cốt lõi, mười một trong mười sáu thiết bị nốt, bốn nhạc cụ và mười một trong mười bảy thiết bị đặc trưng — năm mươi tư trên bảy mươi lăm. ▶ 28 hiệu ứng cốt lõi là toàn bộ thứ mà đặc tả gọi là &quot;mọi thứ một nhà sản xuất cần để hoàn thành một bản thu mà không phải với tới plugin của người khác&quot;. Danh sách là 75 và con số trung thực là thứ <code>oscillate_dsp::registry::implemented_count()</code> trả lời; cả hai con số đều được khẳng định trong mã nên không con số nào trôi lệch khỏi tài liệu. Hai mươi mốt thiết bị còn lại xuất hiện trong trình duyệt có tên và bị làm xám, không có nút điều khiển nào — một danh sách nút điều khiển thiếu DSP làm cho các con số có nghĩa sẽ là những khoảng giá trị bịa ra mà trông có vẻ chính xác.","changelog.afcfa380d255":"<strong>Bộ cân bằng:</strong> <code>Whetstone</code>, <code>Hilt</code>, <code>Temper</code>. <strong>Động lực:</strong> <code>Vise</code>, <code>Weld</code>, <code>Strata</code>, <code>Parry</code>, <code>Ceiling</code>, <code>Peen</code>, <code>Quench</code>. <strong>Drive và bộ khuếch đại:</strong> <code>Shear</code>, <code>Triode</code>, <code>Rasp</code>, <code>Fold</code>, <code>Oxide</code>, <code>Furnace</code>, <code>Baffle</code>. <strong>Delay:</strong> <code>Relay</code>, <code>Spool</code>, <code>Sparks</code>. <strong>Reverb:</strong> <code>Chamber</code>, <code>Foil</code>, <code>Coil</code>. <strong>Điều chế và bộ lọc:</strong> <code>Shoal</code>, <code>Veer</code>, <code>Comb</code>, <code>Edge</code>. <strong>Tiện ích:</strong> <code>Stance</code>. <strong>Nhạc cụ:</strong> <code>Crucible</code>. <strong>Thiết bị nốt:</strong> <code>Runner</code>, <code>Stack</code>, <code>Hone</code>, <code>Weight</code>, <code>Hold</code>, <code>Scatter</code>, <code>Trail</code>, <code>Hand</code>, <code>Approach</code>, <code>Rake</code>, <code>Turn</code>. <strong>Bộ gõ:</strong> <code>Skin</code>, <code>Bronze</code>, <code>Sideband</code>. <strong>Đặc trưng:</strong> <code>Waypoint</code>, <code>Guard</code>, <code>Lantern</code>, <code>Feint</code>, <code>Wear</code>, <code>Gild</code>, <code>Skywave</code>, <code>Toll</code>, <code>Vault</code>, <code>Cleave</code>, <code>Strand</code>.","changelog.5140cf1f25dd":"Sửa lỗi — ba thứ chỉ ứng dụng phát hành mới cho thấy được","changelog.c5dfcf91c9c3":"⛔⛔ <strong><code>oscillate-hostproc.exe</code> KHÔNG CÓ TRONG TRÌNH CÀI ĐẶT NÀO, NÊN KHÔNG PLUGIN NÀO NẠP ĐƯỢC.</strong> <code>tauri.conf.json</code> không khai báo <code>externalBin</code> cũng không có mục <code>bundle.resources</code>, và <code>target/release/</code> cũng không bao giờ chứa tệp nhị phân đó — nên mọi VST 3 và mọi CLAP đều thất bại trong ứng dụng <em>release</em> với","changelog.07ff7d609df0":"▶ <strong>Đây là câu trả lời cho &quot;chưa có plugin nào từng được nó nạp&quot;: không plugin nào nạp được.</strong> Toàn bộ thành quả của Giai đoạn 6 đã chết trong mọi thứ dựng bằng <code>tauri build</code>, và lẽ ra cũng chết trong trình cài đặt mà một người thử nghiệm chạy. Nó đạt ở mọi nơi khác vì <code>cargo test</code>, <code>cargo run</code> và <code>scripts/host-conformance.mjs</code> đều chạy từ <code>target/debug/</code>, nơi cargo đã đặt sẵn tệp nhị phân bên cạnh. ⚠ Được sửa bằng <code>scripts/build-hostproc.mjs</code>, một khai báo <code>externalBin</code>, và <code>src-tauri/tests/the_bundle_carries_the_sandbox.rs</code> — bài kiểm thử thất bại nếu khai báo, đường dẫn hay bước dựng tạo ra tệp đó bị tách rời nhau. Cả hai trình cài đặt đều được dựng lại và đều lớn thêm đúng bằng kích thước nén của tệp nhị phân.","changelog.006a47556b9e":"⛔⛔ <strong>SÁU MƯƠI CHÍN THIẾT BỊ ĐI KÈM VẪN KHÔNG VỚI TỚI ĐƯỢC TỪ TRÌNH DUYỆT</strong>, và đây là lần thứ sáu của cùng một hình dạng. <code>PluginScan::index()</code> đặt danh sách lên đầu một cách đúng đắn; <code>PluginScan::state()</code> lại nhân bản kết quả quét thô <strong>ở tầng nằm dưới bản sửa đó</strong> — và <code>plugins_state</code> là lệnh duy nhất mà bảng trình duyệt gọi. Nên <code>device_rack</code>, <code>device_add</code> và <code>locate_for_load</code> đều thấy danh sách, năm cổng kiểm tra gọi <code>index()</code> và đều đạt, còn nhà sản xuất gõ <code>vise</code> vào bộ lọc thì chẳng được gì. ⚠ Một bài kiểm thử có sẵn khẳng định <code>state().index.plugins.len() == 1</code>, thứ đã khoá chặt lỗi lại. Cổng mới cố ý đi qua <code>state()</code>: <strong>đó là hàm có người dùng ở đầu bên kia.</strong>","changelog.0cc1ca49a0e2":"⛔ <strong>Nhãn của một nút điều khiển và gợi ý trên thanh trạng thái của nó bị tráo nhau trong cả mười tám bảng dịch.</strong> <code>arrangement.metre</code> chứa câu còn <code>hints.metre</code> chứa từ, nên thanh công cụ bản phối vẽ ra một đoạn văn bị ngắt dòng ở chỗ lẽ ra là một nhãn một từ. Cả hai chuỗi đều tồn tại và đều đã được dịch, nên cổng kiểm tra tương đương — vốn so các bảng dịch với nhau — xanh trên mười tám lỗi giống hệt nhau. Giờ có một cổng kiểm tra <em>hình dạng</em>: mọi nhãn thanh công cụ phải ngắn hơn gợi ý giải thích nó.","changelog.033773d6f964":"Sửa lỗi — <code>Rein</code> đặt <code>Off</code> ở chỉ số ba","changelog.3dbe0f12826c":"⚠ <code>Params::on</code> trả lời <code>index &gt;= 1</code>, nên một nút điều khiển đặt <code>Off</code> ở bất cứ đâu ngoài vị trí đầu sẽ bị mọi thiết bị hỏi tới đọc thành <em>bật</em>. <code>Target A</code> và <code>Target B</code> của <code>Rein</code> liệt kê nó ở cuối. ⛔ Bị bắt bởi <code>every_switch_in_the_crate_reads_off_then_on</code>, một bất biến trên toàn crate chứ không phải sở thích đặt tên — và đúng là loại quy tắc chỉ đáng giá khi ai đó thêm thiết bị thứ bảy mươi lúc bốn giờ sáng.","changelog.176683ba65e2":"Thay đổi — ba cổng kiểm tra dựng lại thiết bị cho mỗi thiết lập, và một trong số đó tốn mười chín phút","changelog.7f6ca671bb48":"⚠ <strong>Sáu mươi chín thiết bị tốn hơn năm mươi tư, và hai trong số thiết bị mới tốn hơn rất nhiều.</strong> <code>Sift</code> và <code>Ply</code> mỗi cái chạy một phép biến đổi 4 096 điểm cho mỗi kênh mỗi bước nhảy; <code>Muster</code> chứa tới mười hai engine synth và <code>Quiver</code> tám, và <code>SynthEngine::new</code> mất khoảng một giây. Bộ cổng kiểm tra từ ba phút lên <strong>hơn hai mươi lăm phút, và bị buộc dừng thay vì chạy xong</strong> — và hai lần đầu cố làm nó vừa túi tiền đều nhắm sai chỗ.","changelog.c76554d4e4d6":"⛔⛔ <strong>NGUYÊN NHÂN THẬT LÀ MỘT HÌNH DẠNG, Ở BA CHỖ: MỘT CỔNG KIỂM TRA DỰNG MỘT THIẾT BỊ MỚI CHO MỖI THIẾT LẬP NÓ THỬ.</strong> Không tính chất nào trong ba tính chất đó liên quan gì tới việc khởi tạo — <code>set_param</code> tới được mọi thiết lập, và <code>set_param</code>, <code>prepare</code> và <code>load_sample</code> đều chạy <strong>ngoài</strong> luồng âm thanh. Các lần khởi tạo là chi phí thừa thuần tuý, và khi danh sách có các nhạc cụ mang engine, chúng trở thành toàn bộ thời gian chạy:","changelog.8a13018ad9f4":"⛔ <strong>Riêng <code>silence_in_silence_out</code> đã chiếm mười chín phút trong số đó</strong>, và nó là bài kiểm thử cuối cùng còn đang chạy khi bộ kiểm thử bị buộc dừng — đó là lý do hai bản sửa trước đó bên dưới trông như chẳng đạt được gì.","changelog.6f7962d980c6":"⚠ <strong>Không khẳng định nào bị nới lỏng.</strong> Mọi thiết lập vẫn được duyệt qua, theo cùng thứ tự, ở mọi cỡ khối; mỗi thiết lập được <code>reset</code> trước khi kết xuất; và mỗi nút điều khiển được đưa về mặc định trước khi nút kế tiếp dịch chuyển, nên mỗi lượt vẫn chỉ cách mặc định đúng một nút điều khiển — đúng thứ mà việc dựng thiết bị mới từng mang lại. ⚠ Nếu có khác thì cổng im lặng giờ còn kiểm tra <em>gắt hơn</em>: các engine được dựng trễ bởi một thiết lập trước vẫn được giữ, nên phần thiết bị đang chạy trên hư không còn nhiều hơn trước.","changelog.a633f2f1182e":"⚠ <strong>Hai thay đổi với chính các thiết bị, vốn đáng làm dù thế nào và tự chúng hầu như chẳng tiết kiệm được gì:</strong>","changelog.26dabe8bffb3":"<strong><code>Muster</code> chỉ dựng những nhạc công sẽ phát tiếng.</strong> Một bè bốn người từng phải trả cho mười hai, trong sản phẩm lẫn trong bộ kiểm thử; những người còn lại được dựng khi <code>Players</code> tăng lên, trong <code>set_param</code>, vốn không bao giờ chạy trên luồng âm thanh.","changelog.51e5d2b28182":"<strong><code>Quiver</code> chỉ dựng những chuỗi có thể phát tiếng.</strong> Bảy trong tám chuỗi của nó mở ra im lặng với một vùng trống, và một chuỗi không thể phát tiếng thì không cần engine.","changelog.df19439598d0":"⚠ <strong>Một cổng kiểm tra không ai đủ sức chạy là một cổng bị bỏ qua</strong>, tức là cũng như không có — và dự án này có bảy lỗi được ghi nhận mà chỉ một cổng thực sự được ai đó chạy mới bắt được.","changelog.6e1b1bcf02c1":"Sửa lỗi — khai báo sidecar làm hỏng mọi bản dựng <code>cargo</code>, và <code>ci:local</code> vẫn xanh trên nó","changelog.99a217744ea0":"⛔⛔ <strong>MỘT KHAI BÁO <code>externalBin</code> LÀ ĐẦU VÀO CỦA BẢN DỰNG, KHÔNG CHỈ LÀ ĐẦU VÀO CỦA GÓI.</strong> Build script của Tauri từ chối dựng <code>src-tauri</code> <strong>hoàn toàn</strong> trừ khi sidecar tồn tại cho bộ ba của host — một lệnh <code>cargo clippy</code> hay <code>cargo test</code> thông thường, không chỉ <code>tauri build</code>. Nên bản sửa cho <em>&quot;không trình cài đặt nào mang hộp cát&quot;</em> ngay lập tức làm hỏng cả ba job <code>quality</code> với","changelog.c5df1463b340":"⛔ <strong>Và <code>npm run ci:local -- --slow</code> đạt 18/18 trong khi điều đó đang đúng.</strong> Cái máy thêm khai báo có một sidecar đã được đặt sẵn bởi một lần chạy tay build script trước đó, nên mọi lần chạy cục bộ từ đó đều lặng lẽ phụ thuộc vào một tệp mà một lệnh <em>khác</em> để lại. ⚠ Một trình chạy như vậy không chạy môi trường của CI, mà đó là việc duy nhất nó tồn tại để làm — và đây là lần thứ hai trong dự án này một bộ kiểm thử cục bộ xanh nằm trên một cây mã hỏng.","changelog.18fb4b406b6c":"⚠ Quy trình giờ đặt sidecar <strong>trước</strong> các cổng Rust thay vì sau; <code>ci-local.mjs</code> tự đặt một sidecar như cổng đầu tiên của nó; và <code>ci_stages_the_sandbox_before_anything_that_builds_this_crate</code> khẳng định <strong>thứ tự</strong>, vì một bước đặt sẵn chạy sau các cổng chính là thứ đã có từ trước và chính là thứ đã thất bại. ⚠ <code>--debug</code>, vì job đó không đóng gói gì và build script chỉ kiểm tra đường dẫn có tồn tại hay không.","changelog.4773f02d6a28":"⚠ <strong>Các job <code>release</code> vẫn đạt suốt thời gian đó</strong>, vì <code>npm run tauri:build</code> chạy script đặt sẵn trước. Chỉ những job dựng crate mà không đóng gói nó bị ảnh hưởng — đó là lý do không có gì cục bộ bắt được.","changelog.6014a99b778f":"Thêm mới — chưa từng có gì trong bộ kiểm thử trao cho một thiết bị một khối cuối ngắn","changelog.0565b063c7c7":"⛔⛔ <strong>MỌI SỐ KHUNG TRONG BỘ CỔNG KIỂM TRA ĐỀU LÀ BỘI SỐ CHÍNH XÁC CỦA CỠ KHỐI.</strong> 1 024 khung ở khối 64, 4 096 ở 2 048, 8 192 ở 64 trong cổng im lặng — nên qua <strong>bảy mươi lăm thiết bị và bốn cỡ khối, chưa thiết bị nào từng được yêu cầu xử lý một khối dở dang.</strong> Một thiết bị đọc <code>block</code> ở chỗ lẽ ra phải đọc <code>frames.min(block)</code> sẽ xanh ở mọi nơi tại đây.","changelog.9fb238124783":"⚠ <strong>Engine thật tạo ra khối ngắn liên tục</strong>: cuối một khoảng, một ranh giới vòng lặp, phần bù độ trễ của chính một thiết bị. Điều này được tìm ra trong lúc cắt giảm thời gian chạy của bộ kiểm thử, không phải nhờ một lần thất bại — đó là phần khó chịu, vì nếu không thì chẳng có gì sẽ tìm ra nó.","changelog.1ee0368d2be0":"⚠ <code>frames_for</code> giờ trừ đi nửa khối, nên <strong>mọi cỡ khối đều kết thúc bằng một khối dở dang</strong>, và <code>every_block_size_ends_on_a_short_block</code> khẳng định tính chất đó của hàm trợ giúp thay vì tin vào một lời chú thích — một cỡ khối được thêm vào <code>BLOCKS</code> mà tình cờ chia hết sẽ lặng lẽ đưa bộ kiểm thử về lại chỗ cũ. ⚠ Nó còn <em>rẻ hơn</em> khoảng một phần năm, một chiều hiếm thấy với một bản sửa độ phủ.","changelog.b032786ec60c":"⚠ <strong>Cổng cấp phát là hàng thứ ba của bảng đó</strong>, và chính nó làm hình dạng lộ ra: dạy nó nạp sample và đánh hợp âm đã đẩy nó từ hai mươi giây lên hơn hai mươi phút chỉ trong một commit. Giờ nó được dựng một lần cho mỗi thiết bị, mọi thiết lập vẫn được duyệt theo cùng thứ tự và mọi khối làm nóng vẫn giữ nguyên — <strong>64 giây, và vẫn đỏ khi một <code>Vec</code> bị đặt trở lại vào <code>process</code>.</strong>","changelog.e90a16ca644f":"Thêm mới — seed có thể gieo lại, và sáu thiết bị thức dậy","changelog.3f0ff3b92998":"⛔⛔ <strong><code>ops::reroll_seed</code> KHÔNG CÓ NƠI GỌI NÀO, VÀ ĐÓ LÀ LẦN THỨ BẢY.</strong> Seed của dự án đã nằm trong mô hình từ Giai đoạn 3; nó đi cùng chỉ mục bản phối và tới được <code>Context::seed</code>; sáu thiết bị rút mọi quyết định ngẫu nhiên từ nó. <strong>Không có gì trong giao diện thay đổi được nó</strong>, nên mỗi thiết bị trong sáu cái đó chỉ có đúng một hành vi suốt đời một dự án — và mọi cổng kiểm tra tự tạo một <code>Context</code> đều xanh trên đó, vì một context tự tạo có thể mang bất cứ seed nào nó thích.","changelog.96d0a4ae4376":"⚠ Giờ có một <strong>nút ⚄ trên thanh công cụ bản phối</strong>, cạnh nhịp độ, vì seed là thuộc tính của bài hát chứ không phải của máy. Con số mới được bên gọi tạo ra và truyền vào thao tác, nên một dự án mở lại nghe giống dự án đã lưu: một thao tác tự gieo ngẫu nhiên sẽ không phát lại được.","changelog.aaf264952da8":"Thay đổi — hộp thoại làm mờ phiên phía sau nó","changelog.109a1280400d":"⚠ Chỉ dẫn của chủ dự án: <em>&quot;khi bất kỳ hộp thoại nào hiện lên trên DAW, các phần nền của DAW phải bị làm mờ và chỉ hộp thoại đó được nhìn thấy.&quot;</em> Chỉ một lớp phủ thì mọi fader và clip phía sau vẫn đọc được. <code>backdrop-filter</code> trên lớp phủ thay vì một filter trên gốc ứng dụng — filter áp dụng cho cả cây con và sẽ làm mờ luôn hộp thoại. ⚠ Đo trên tệp nhị phân phát hành: năng lượng tần cao của Trình duyệt tệp giảm từ 7.18 xuống 3.94 khi hộp thoại mở.","changelog.b509ead0e07f":"Thêm mới — mọi nút điều khiển, bằng mọi ngôn ngữ (Giai đoạn 7)","changelog.3fdf63211c68":"⛔⛔ <strong>Các bảng điều khiển nói cả mười tám ngôn ngữ.</strong> 482 nhãn nút điều khiển khác nhau trên 69 thiết bị đã dựng, được dịch vào mọi bảng dịch mà Oscillate phát hành — thứ cuối cùng trong Giai đoạn 7 vẫn còn là tiếng Anh ở mọi nơi.","changelog.9b5cef558932":"⚠ <strong>Một nhãn và gợi ý trên thanh trạng thái của nó bị tráo nhau trong cả mười tám bảng dịch.</strong> <code>arrangement.metre</code> chứa câu <em>&quot;Loại nhịp của dự án — một ô nhịp có bao nhiêu phách, và một phách có giá trị bao nhiêu.&quot;</em> còn <code>hints.metre</code> chứa từ <em>&quot;Nhịp&quot;</em>, nên thanh công cụ bản phối vẽ ra một đoạn văn bị ngắt dòng ở chỗ lẽ ra là một nhãn một từ. Không gì có thể bắt được nó: cả hai chuỗi đều tồn tại, đều đã được dịch, và cổng kiểm tra tương đương so các bảng dịch với nhau — mà bảng nào cũng sai theo cùng một kiểu. Giờ có một cổng kiểm tra <em>hình dạng</em>: nhãn là một từ, gợi ý là một câu.","changelog.e4e709b8830c":"▶ <strong>Quy ước của ngành, vốn không giống với việc dịch mọi thứ.</strong> <code>Gain</code>, <code>Attack</code>, <code>Release</code>, <code>Threshold</code>, <code>Ratio</code>, <code>Low Cut</code> được giữ nguyên trong tiếng Đức, Pháp, Tây Ban Nha, Ý, Hà Lan và các ngôn ngữ khác, vì đó là thứ nhà sản xuất đọc thấy trên mọi DAW khác họ từng mở — Cubase và Studio One phát hành bảng điều khiển tiếng Đức ghi đúng những từ đó. Dịch chúng thành <code>Verstärkung</code>, <code>Ansprechzeit</code> và <code>Schwellwert</code> là tiếng Đức đúng nhưng <strong>xa lạ hơn</strong>, chứ không bớt xa lạ. ⚠ Từ vựng mô tả thông thường — <code>Frequency</code>, <code>Level</code>, <code>Width</code>, <code>Length</code>, <code>Size</code>, <code>Noise</code>, <code>Material</code> — được dịch ở mọi nơi.","changelog.7983ad8fb373":"⚠ <strong>Tiếng Nhật, Hàn, Trung, Nga, Ukraina, Ả Rập và Hindi không giữ lại chữ Latinh nào</strong>, vì chính các DAW của họ cũng không: katakana <code>アタック</code>, hangul <code>어택</code>, <code>起音</code>, <code>Атака</code>. Vẫn là quy ước đó nhưng cho ra câu trả lời khác, và <strong>không ngôn ngữ nào trong bảy ngôn ngữ đó xuất hiện trong danh sách giữ nguyên tiếng Anh</strong> — cả 319 từ đều được kiểm tra trong cả bảy.","changelog.b7c89628b394":"⛔ <strong>Khoá được tính trong Rust, từ nhãn.</strong> <code>Gain</code> là <strong>một</strong> chuỗi cho toàn bộ danh sách thay vì mười một chuỗi nếu đánh khoá theo từng thiết bị, và một nút điều khiển bị đổi tên sẽ sinh ra một khoá mà cổng kiểm tra ngôn ngữ báo là thiếu, thay vì một bảng lặng lẽ lùi về tiếng Anh trong khi mọi bài kiểm thử vẫn xanh.","changelog.15e32938dfa3":"⚠ <strong>Lưới được ghép từ một mẫu theo từng ngôn ngữ, không phải viết ra sáu mươi lần.</strong> <code>Band 1 Frequency</code> … <code>Band 4 Shape</code> và lưới động lực bốn dải chỉ khác nhau ở một chữ số hay một dải, nên mỗi ngôn ngữ chỉ nêu trật tự từ của nó một lần. ⛔ Lần thử đầu dùng một dạng duy nhất cho mỗi dải và sinh ra <code>Hoch Ratio Up</code>, <code>Высокие Соотношение вверх</code> và <code>Tief Decay</code> — tất cả đều sai ngữ pháp. Một từ chỉ dải đứng một mình trên nút chỉnh âm sắc không phải là từ dùng để bổ nghĩa cho một danh từ khác: tiếng Đức cần <code>Höhen-</code> và một dấu gạch nối, tiếng Nga và Ukraina cần <strong>sở hữu cách</strong> và đứng <em>sau</em> thuật ngữ. Giờ hai dạng được cho riêng.","changelog.94784bd56e51":"⚠ <strong><code>Look Ahead</code> và <code>Lookahead</code> là cùng một nút điều khiển được viết theo hai cách</strong> — ba thiết bị viết kiểu này, hai thiết bị viết kiểu kia. Được thống nhất thành <code>Lookahead</code>, cách mà số đông dùng và cách các limiter hiện đại in ra. Vậy là bớt đi một bản dịch trùng trong mười tám ngôn ngữ, và một cổng kiểm tra giờ từ chối hai nhãn chỉ khác nhau ở khoảng trắng hay chữ hoa.","changelog.99966156003c":"Thêm mới — bốn cơ chế đúng đắn mà không có gì gọi tới (Giai đoạn 7)","changelog.f9e8e0604480":"⛔⛔ <strong>Oscillate không phát được một nốt nào.</strong> Không từ bàn phím ảo, không từ bàn phím phần cứng. Module <code>midi</code> của <code>oscillate-audio</code> — <code>ports()</code>, <code>Input::open()</code>, <code>EventQueue</code>, <code>Filter</code>, <code>decode()</code> — đã được dựng, kiểm thử, và <strong>không crate nào ngoài chính nó tham chiếu tới</strong>; <code>NoteBank</code> chỉ được worker phát lại lấp đầy, từ các clip. Nên mọi nhạc cụ trong danh sách đều thêm được vào track mà không cái nào chơi được. <code>live.rs</code> là đường còn thiếu, và nó là <strong>một</strong> hàng đợi vì bàn phím ảo và cổng MIDI là cùng một sự kiện đi vào qua hai cửa khác nhau — hai đường sẽ là hai câu trả lời cho việc velocity nghĩa là gì, hai quy tắc tắt-mọi-nốt và hai quyết định về chuyện gì xảy ra khi transport đang chạy, và đường ít được dùng hơn sẽ là đường sai.","changelog.dccd39d3b268":"⛔⛔ <strong><code>Waypoint</code>, <code>Guard</code> và <code>Lantern</code> đọc <code>next_section_ticks: None</code> ở mọi khối, mãi mãi.</strong> Khả năng đọc trước là tuyên bố chủ đạo của giai đoạn này — <em>plugin được biết đầu phát đang ở đâu và không bao giờ được biết phía trước có gì</em> — vậy mà <code>graph.rs</code> dựng <code>Context</code> của nó bằng <code>..Context::default()</code>. Ba thiết bị đặc trưng chỉ là một compressor, gate và delay bình thường với một nút Lookahead chết. ⚠ <strong>Mọi cổng kiểm tra đều xanh vì mỗi cổng tự dựng <code>Lookahead</code> riêng rồi truyền vào.</strong> Tất cả đều hỏi xem thiết bị có <em>phản hồi</em> với nó không; không cổng nào hỏi xem nó có bao giờ <em>nhận được</em> nó không. Cùng hình dạng với việc danh sách không với tới được từ trình duyệt, và cùng một câu hỏi tìm ra nó: <em>nhà sản xuất thực sự sẽ nhấn gì?</em> Giờ cấu trúc của bản phối được tính ngoài luồng âm thanh và trao xuống dưới dạng tick tương đối.","changelog.022bbad0846a":"⛔ <strong>Đường nối sample, và một giọng phía sau mọi thiết bị phát tệp.</strong> Bảy nhạc cụ ở trạng thái <code>Declared</code> chỉ vì thiếu thứ này. Một thiết bị được dựng từ một <code>type_id</code> và một danh sách <code>f64</code>, còn đường dẫn thì không phải thứ nào trong hai — <code>ParamSpec</code> mang số vì luồng âm thanh không được thấy <code>String</code> — nên sample không thể tới dưới dạng một nút điều khiển. Thay vào đó nó tới dưới dạng hoán đổi <code>Arc&lt;SampleData&gt;</code>, được giải mã trên một worker. ⚠ <strong>Cái bẫy là lúc giải phóng</strong>: nhả <code>Arc</code> cuối cùng sẽ giải phóng bộ nhớ trên bất cứ luồng nào đã nhả nó, nên luồng âm thanh trả cái cũ lại thay vì giải phóng nó. ⚠ Đầu đọc đã nằm trong <code>delay::sinc_read</code> từ AM-A1, được ghi chú là <em>&quot;của sampler&quot;</em> — đã viết, đã kiểm thử, và không sampler nào với tới được, vì không sampler nào viết được. Một giọng phục vụ tất cả: được gom lại ở <code>prepare</code>, không bao giờ cấp phát sau đó, bị cướp theo thứ tự nhỏ-nhất-rồi-cũ-nhất và <strong>được fade thay vì cắt</strong>, vì cắt cứng ở một mẫu bất kỳ là một tiếng lách cách ở mức đầy và nó rơi đúng lúc nhà sản xuất đang chơi.","changelog.47a37733c964":"▶ <strong>Danh sách là 63 trên 75, tăng từ 54.</strong> Chín thiết bị rời khỏi danh sách bị chặn: <code>Sift</code>; các thiết bị nốt <code>Weave</code>, <code>Tread</code> và <code>Revoice</code>; và các sampler <code>Flint</code>, <code>Armory</code>, <code>Bench</code>, <code>Hammer</code> và <code>Filings</code>. ⚠ <strong>Cả 28 hiệu ứng cốt lõi đều đã được dựng từ trước</strong> — mỗi cái trong số này đều bị chặn ở một đường nối chứ không phải vì thiếu thời gian của ai, đó là lý do đóng ba đường nối đã giải phóng chín thiết bị.","changelog.5a6a1d227692":"Thêm mới — chia sẻ những gì bạn đã làm (Giai đoạn 7)","changelog.dbcd3e927b1f":"⛔⛔ <strong>Thiết lập của một thiết bị nằm gọn trong một dòng bạn có thể dán vào khung chat.</strong> Không tệp, không tải lên, không tài khoản — đó là cách một cộng đồng thực sự trao đổi âm thanh.","changelog.f0988a917537":"▶ <strong>Mọi dòng tới nơi đều bị coi là thù địch</strong>, vì nó đến từ một người lạ qua một cửa sổ chat. Độ dài được kiểm tra <strong>trước khi cấp phát bất cứ thứ gì</strong>; một thiết bị lạ bị từ chối kèm tên thay vì bị đoán mò; mọi giá trị đều được kiểm tra với khoảng giá trị của chính nút điều khiển của nó và một dòng nằm ngoài khoảng sẽ bị <strong>từ chối thay vì kẹp lại</strong> — kẹp lại biến một dòng hỏng thành một thiết bị trông đúng mà nghe sai, đúng kiểu lỗi mà nhà sản xuất không chẩn đoán được. Một <code>NaN</code> được phân tích như một con số và cũng bị từ chối: một giá trị như vậy lọt vào trạng thái của bộ lọc sẽ làm câm track cho tới hết phiên mà không có gì trên bảng nói lý do.","changelog.94eaa1442544":"⛔ <strong>Không có gì được áp dụng cho tới khi bạn đã đọc những gì sẽ thay đổi.</strong> Bảng liệt kê các nút điều khiển sẽ dịch chuyển, từ giá trị nào sang giá trị nào, bằng chính bộ định dạng của DSP — để bản xem trước không thể nói một con số mà núm vặn sau đó lại mâu thuẫn — và chỉ khi đó mới đề nghị áp dụng, dưới dạng <strong>một bước hoàn tác</strong>. ⚠ Ô dán là một trường văn bản thay vì đọc khay nhớ tạm: <code>readText()</code> hỏi hệ điều hành về bất cứ thứ gì bạn sao chép lần cuối, còn một trường văn bản thì chẳng hỏi gì.","changelog.ac55cb626b91":"⚠ <strong>Dòng này không dùng deflate</strong>, như bản phác thảo § F-18 từng gợi ý. Mục tiêu là dưới 200 ký tự và cả danh sách đo được chưa tới một nửa con số đó khi chưa nén, nên nén sẽ đổi được vài ký tự chẳng ai đếm với cái giá là hai phụ thuộc trên một cây mã có cổng kiểm tra giấy phép làm hỏng bản dựng. Byte phiên bản có mặt để một thiết bị tương lai cần tới thì có.","changelog.504a5ab9a3c1":"⛔⛔ <strong>VÀ CẢ MỘT GIÁ THIẾT BỊ ĐƯỢC LƯU THÀNH TỆP.</strong> <em>&quot;Chúng ta có thể lưu các nhóm VST3 cùng thiết lập của chúng làm preset không — hay các nhóm plugin đi kèm?&quot;</em> — có, cả hai, theo thứ tự, với nút điều khiển của mọi thiết bị, trạng thái bỏ qua của nó và trạng thái mờ riêng của plugin. Đó là <em>Audio Effect Rack</em> của Ableton và <em>mixer state</em> của FL, và chưa có gì bao phủ nó: một chuỗi công thức là <strong>một</strong> thiết bị, và một chuỗi vocal bốn thiết bị không có cách nào lưu lại cả.","changelog.f81450b45e4f":"<strong>Một tệp, không phải một dòng, và sự phân biệt này gánh trọng trách.</strong> Trạng thái của một thiết bị đi kèm là một nắm số. Trạng thái của một plugin là một khối dữ liệu mờ của nhà sản xuất và thường lên tới hàng megabyte; một bộ tuần tự hoá cố làm cho nó dán được sẽ hoặc cắt cụt nó, hoặc tạo ra thứ không ai gửi nổi.","changelog.a3f286b4c94a":"⛔ <strong>Một preset ghi tên một plugin bạn không có VẪN NẠP ĐƯỢC</strong> — giữ thiết lập, trạng thái và vị trí của nó trong chuỗi, được vẽ thành ô giữ chỗ có đề nghị <em>Tìm…</em>. Từ chối cả preset chỉ vì thiếu một thiết bị là cách một preset được chia sẻ trở nên vô dụng.","changelog.9acecd496795":"⚠ <strong>Nó ghi lại những gì nó không thể hứa.</strong> Một preset mang theo phiên bản plugin lúc được lưu, và gọi lại nó với một phiên bản khác sẽ khôi phục trạng thái và <strong>nói rõ điều đó</strong> — nhà sản xuất plugin có quyền thay đổi ý nghĩa của trạng thái giữa các bản phát hành, và lặng lẽ nạp một trạng thái bị xáo trộn còn tệ hơn một lời cảnh báo.","changelog.359fe5e52aef":"⛔ <strong>Một preset không bao giờ mang số liệu độ trễ.</strong> Độ trễ là thứ một thiết bị <em>báo</em> khi nó nạp; một tệp có thể đặt được nó sẽ để preset của người lạ làm lệch mọi track trong dự án của bạn, và bạn sẽ nghe điều đó như thể chính thời điểm chơi của mình đang trục trặc.","changelog.c7548c290126":"Nó cố ý là <strong>cùng một vỏ chứa với <code>.oscillate</code></strong> — số magic, việc từ chối phiên bản, số khúc được kiểm tra trước khi đặt chỗ cho thư mục và phép tính có kiểm tra trên mọi offset đều đã đúng sẵn ở đó, và bản sao thứ hai của tất cả những thứ đó mới là thứ sẽ bị làm sai.","changelog.12b0585e2328":"Thêm mới — bộ cổng kiểm tra, trên toàn bộ danh sách (Giai đoạn 7)","changelog.27da05681148":"⛔⛔ <strong>Không thiết bị đi kèm nào cấp phát trong lúc đang xử lý, được đo chứ không phải giả định.</strong> Mọi thiết bị đã dựng, ở mọi giá trị cực trị của tham số và với mọi nút điều khiển cùng ở mức tối đa, được chạy qua một <strong>bộ cấp phát toàn cục có đếm</strong> — nằm trong bộ kiểm thử luồng âm thanh của <code>oscillate-audio</code> vì mỗi tiến trình chỉ có đúng một bộ và bộ đó đã có sẵn ở đó. ⚠ Đã được nhìn thất bại với một thiết bị bị phá cho cấp phát tám số float. ▶ Mục 3 của triết lý dựng nói không cấp phát trên luồng âm thanh; cho tới lúc này, đó là một quy tắc có rà soát đằng sau chứ không phải một phép đo.","changelog.c1dd75c564d7":"⛔⛔ <strong>Một bộ kiểm thử, và nó duyệt registry thay vì một danh sách do ai đó duy trì</strong> — nên một thiết bị thêm vào ngày mai có mặt trong mọi cổng mà không ai phải nhớ thêm nó. Mười bốn cổng: không cấp phát ở bốn cỡ khối và mọi cực trị tham số, độ trễ khai báo so với đo được, im lặng vào im lặng ra, tính tất định theo seed, thiết bị nốt báo tràn thay vì bỏ rơi một hợp âm, không nốt bị kẹt sau lệnh tắt-tất-cả, đường cong vẽ ra so với âm thanh, lợi thế cấu trúc, và không có đáp ứng xung thu sẵn nào ở bất cứ đâu trong cây mã.","changelog.ef1f383d949f":"▶ <strong>Bốn cổng khẳng định một SỰ VẮNG MẶT, và mỗi cổng được ghép với một khẳng định có mặt</strong> — vì một cổng khẳng định sự vắng mặt sẽ đạt dễ dàng với một thiết bị chẳng làm gì. Trước hết bộ kiểm thử phải được chứng minh là đã chạy trên một danh sách thật, đã thay đổi một tín hiệu thật, đã lấp đầy một bộ đệm nốt thật.","changelog.a1f70e07df67":"<strong>Ba lỗi thật, tìm ra nhờ viết nó:</strong>","changelog.9c3286495065":"⛔ <strong><code>Furnace</code> vẽ tone stack của nó mà bỏ sót hai tầng trong chính đường âm thanh của nó</strong> — tụ sáng bắc qua nút gain và độ suy giảm của biến áp đầu ra — và lệch <strong>2.9 dB ở 4 kHz</strong> so với những gì nó thực sự làm. Một đường cong thiếu một tầng là đồ trang trí cho thiết bị chứ không phải phép đo của nó. Đã sửa, và đường cong giờ bám theo âm thanh tới một phần mười decibel.","changelog.fc2768b6fb8d":"⛔ <strong><code>Lantern</code> trông như bỏ qua bản phối</strong> nhưng không phải vậy: bản kết xuất của cổng dài 8 192 mẫu trong khi delay của nó là 12 000, nên chưa có gì quay lại cả. Một cổng đo phần đuôi phải chạy quá phần đuôi đó.","changelog.44daac3f8f13":"⛔ <strong>&quot;Độ trễ khai báo là chỗ xung đạt đỉnh&quot; là sai</strong>, và hai thiết bị chứng minh điều đó theo hai chiều ngược nhau. <code>Toll</code> khai báo không và đạt đỉnh ở 1 332 — nó là bộ cộng hưởng, và tiếng ngân của nó tích tụ sau một xung đã đi thẳng qua. Cửa sổ của <code>Strand</code> ngân 517 mẫu <em>trước</em> đỉnh của nó. Cả hai khai báo đều trung thực; phép đo thì không. Giờ cổng đo chỗ đáp ứng <strong>bắt đầu</strong> và chỗ nó <strong>đạt đỉnh</strong>, và khẳng định đúng những gì mỗi điều chứng minh được: không gì được tới muộn hơn khai báo, và không gì được đạt đỉnh sớm hơn.","changelog.9e568642d580":"⚠ <strong>Đáp ứng tần số là một đại lượng tín hiệu nhỏ, và hai thiết bị cần điều đó được nói ra thành lời.</strong> <code>Furnace</code> trả lời −7.97 dB ở 80 Hz với một âm −20 dBFS và −0.01 dB với một âm nhỏ, vì âm đầu đang bị nén. Wow và flutter của <code>Oxide</code> dịch vị trí đọc, tức là điều chế tần số — một âm 4 kHz đều đặn mất 3 dB vào các dải biên mà không đường cong biên độ nào vẽ ra được. Cổng giữ yên điều chế và đo ở mức nhỏ, và nói lý do ở cả hai chỗ.","changelog.ae6713aae737":"Thêm mới — những thiết bị không plugin nào làm được (Giai đoạn 7, AM-C)","changelog.ccec0b2bb36e":"⛔⛔ <strong>Ba trong số đó đọc bản phối, và đó không phải là một bộ đệm dài hơn.</strong>","changelog.525a54a16b01":"▶ Đọc trước hai ô nhịp <em>âm thanh</em> là độ trễ, và mọi nhà sản xuất trong phiên đều phải trả giá. Đọc trước hai ô nhịp <em>cấu trúc</em> của bản phối thì <strong>không tốn gì</strong> — điệp khúc vẫn ở ô nhịp 33 dù đã có ai phát tới đó hay chưa. Không định dạng plugin nào để lộ bản phối của host, đó là lý do những thiết bị này chỉ có thể tồn tại bên trong một DAW đồng thời đã viết ra chúng. Cả ba khai báo <strong>độ trễ bằng không</strong>, và cổng kiểm tra của chúng là: thay đổi cấu trúc mà không đổi một mẫu nào cũng làm thay đổi những gì chúng làm.","changelog.2d95b40d737e":"<strong><code>Waypoint</code> đã sẵn sàng đè đoạn điệp khúc ngay khi nó tới</strong>, thay vì phản ứng với nó trễ vài mili giây.","changelog.61058866fd1f":"<strong><code>Guard</code> mở ra cho một nhát đánh chưa xảy ra.</strong> Một ngưỡng thì không làm được: tới lúc mức âm vượt ngưỡng thì transient đã qua.","changelog.0a518a9dfc80":"<strong><code>Lantern</code> xả một delay VÀO vạch ô nhịp</strong>, để phần đuôi tự tắt thay vì bị cắt. Một nhát cắt là một tiếng lách cách, và thiết bị này tồn tại để tránh mớ lộn xộn mà việc xả bằng tay gây ra.","changelog.3adaa073b4e9":"⛔ <strong>Ba thiết bị nữa gieo lại y hệt từ seed của dự án</strong>, nên một đoạn stutter nghe đúng ở lượt thứ ba vẫn còn đó ở lượt thứ bốn mươi — và gieo lại là một thao tác hoàn tác được chứ không phải một canh bạc. <code>Feint</code>, <code>Wear</code> và <code>Skywave</code>.","changelog.faf2b04e72fd":"<strong><code>Gild</code> cho bạn chọn hoạ âm.</strong> Một bộ tạo dạng sóng cho ra bất cứ hỗn hợp nào rơi ra từ đường cong của nó; một cơ sở Chebyshev trả lời đúng hoạ âm được yêu cầu, nên hoạ âm thứ hai và thứ năm là hai nút điều khiển riêng làm hai việc riêng.","changelog.388e74d46c0c":"<strong><code>Toll</code> khiến mọi âm thanh ngân lên như một vật bị gõ</strong>, được kích bởi chính các transient của đầu vào — nên một tiếng snare đi qua một ống ngân như một cái ống bị snare gõ vào, còn một nốt ngân dài thì hầu như không làm nó ngân chút nào.","changelog.72e4b3c8680a":"<strong><code>Vault</code> tính reverb từ một căn phòng đo bằng mét.</strong> Kích thước quyết định thời điểm tới của các phản xạ và độ dài các đường trễ trong bể: phản xạ đầu tiên của một căn phòng bốn mươi mét thật sự tới muộn hơn bốn lần so với một căn phòng ba mét.","changelog.3ab7f011c6f7":"<strong><code>Cleave</code> tách nhát đánh khỏi âm sắc</strong>, bằng cách hỏi ở mọi điểm trên phổ xem nó to <em>lúc này</em> và nhỏ ngay trước và sau đó — một nhát đánh — hay to <em>ở đây</em> và nhỏ ở bin hai bên — một nốt. Nó không cần ngưỡng và không cần học gì: đó là một nhận định về hình dạng của âm thanh.","changelog.34f872d520d1":"<strong><code>Strand</code> dựng lại một âm thanh từ các hoạ âm thành phần mà nó tìm thấy trong đó</strong>, nên tiếng thở và tiếng vĩ kéo có thể được giảm riêng khỏi các nốt.","changelog.7af3df17572e":"⚠ <strong>Tuyên bố &quot;không plugin nào làm được điều này&quot;, được kiểm tra lại dựa trên những gì đã phát hành chứ không phải những gì được đặc tả</strong> — Cổng Giai đoạn 7 đòi đúng điều đó, vì một lời phóng đại trong đặc tả sẽ thành lời phóng đại trong tiếp thị. ▶ <strong>Sáu</strong> trong mười một thiết bị xứng đáng: ba cái đọc cấu trúc của bản phối (<code>Waypoint</code>, <code>Guard</code>, <code>Lantern</code>) và ba cái tất định từ seed của dự án (<code>Feint</code>, <code>Wear</code>, <code>Skywave</code>), hai thứ mà không định dạng plugin nào để lộ ra. Năm cái còn lại — <code>Gild</code>, <code>Toll</code>, <code>Vault</code>, <code>Cleave</code>, <code>Strand</code> — là DSP đặc sắc và được mô tả ở trên dựa trên giá trị riêng của chúng, không kèm tuyên bố rằng chúng không thể được viết thành plugin. README từng ghi mười một và giờ ghi sáu.","changelog.a8c23b6590a7":"Thêm mới — ba giọng trống được mô phỏng, không phải lấy mẫu (Giai đoạn 7, SP-02)","changelog.b45e2a05e0f9":"<strong><code>Skin</code> là một màng bị gõ, không phải một sample.</strong> Các hoạ âm thành phần của nó là các nghiệm Bessel — thành phần thứ hai gấp 1.59 lần thành phần thứ nhất, không phải gấp đôi, và đó là toàn bộ khác biệt giữa một cái trống và một nốt có cao độ. Chỗ dùi rơi xuống quyết định mode nào được kích, dùi cứng tới đâu quyết định nó tiếp xúc bao lâu, và dây snare chỉ rè lên khi mặt trống dịch chuyển đủ để hất chúng ra. <strong>Một tiếng kick giữ cao độ chính xác tới một cent suốt bốn giây tắt dần.</strong>","changelog.e1820ecc0952":"<strong><code>Bronze</code> là một tấm phẳng tán sắc.</strong> Sáu mươi tư hoạ âm thành phần tách xa nhau khi lên cao, đó là lý do một cái cymbal là một mảng âm còn một sợi dây là một hợp âm. Pedal của hi-hat thật sự kẹp nó lại: khi đóng, phần đuôi ngắn hơn hơn hai mươi decibel, và chuyển động đó mất đúng khoảng thời gian mà nút Closure quy định.","changelog.da5d0b60ebad":"<strong><code>Sideband</code> là FM bốn operator</strong> qua tám thuật toán, có oversampling, với operator feedback được giữ dưới mức đơn vị trong DSP cũng như trên bảng — một operator tự điều chế ở mức một là một bộ tạo nhiễu không bao giờ quay lại được.","changelog.d99f1f1c0dab":"⛔ <strong>Cùng tham số kết xuất ra cùng một nhát đánh</strong>, mọi lần, trên mọi máy. Mọi bộ sinh đều được gieo lại seed khi giọng được đặt lại thay vì tiếp tục từ bất cứ đâu nó tình cờ đang ở, nên bản bounce nghe đúng như những gì đã nghe.","changelog.87dbbf51c469":"Thêm mới — những gì xảy ra với một đoạn trước khi nó được chơi (Giai đoạn 7, AM-D1)","changelog.66e2e630602a":"⛔⛔ <strong>Giờ thiết bị nốt đã có chỗ để chạy</strong>, và cho tới lúc này thì chưa có.","changelog.0b00d82af6a6":"▶ <strong>Mười sáu thiết bị có trong danh sách mà không có đường nối nào để chạy.</strong> Một thiết bị đi kèm chỉ ghi được âm thanh, nên arpeggiator không có cách nào phát ra một nốt; và phần mã dựng dải kênh bỏ mọi thiết bị nốt ra khỏi chuỗi, kèm một lời chú thích nói rằng nó làm vậy. Thứ còn thiếu là cơ chế chứ không phải các thiết bị chưa được viết — đây là lần thứ năm dự án này gặp hình dạng đó.","changelog.06268f644505":"<strong>Rải hợp âm, hoà âm, nhân tính hoá, lặp tiếng vọng, chỉnh sửa và biến đổi một đoạn</strong>, trong một chuỗi, trước khi nhạc cụ nghe thấy nó. Mười một trong mười sáu đã được dựng.","changelog.2308ba050970":"⛔ <strong>Không có gì ở đây có thể để một nốt bị kẹt.</strong> Mọi thiết bị đều bị ràng buộc với điều đó: bộ chỉnh dời note-off đúng như cách nó đã dời note-on, bộ dựng hợp âm nhả mọi giọng nó đã phát, và các nốt riêng của arpeggiator dừng khi transport dừng.","changelog.f94d5f02304a":"⛔ <strong>Mọi thiết bị ngẫu nhiên hoá đều gieo lại y hệt từ seed của dự án</strong>, nên bản bounce nghe đúng như những gì đã nghe. <code>Scatter</code> rút cao độ, velocity và thời điểm từ ba luồng riêng, nên gieo lại một luồng sẽ để các luồng kia giống hệt từng byte — nhà sản xuất có thể sửa thời điểm của một đoạn mà không mất những nốt họ thích.","changelog.b7a88dfc6644":"<strong>Một chuỗi nốt hết chỗ sẽ nói rõ</strong>, và số lượng được ghi lại. Một arpeggiator lặng lẽ đánh mất một hợp âm sẽ là một lỗi được tìm ra một tuần sau.","changelog.acc86def0061":"<strong><code>Temper</code> tăng và cắt cùng một tần số mà không triệt tiêu nhau.</strong> Đó là toàn bộ ý nghĩa của một equaliser chương trình thụ động và là phần mà mọi bản bắt chước dựng từ EQ tham số đều làm sai: phần tăng và phần cắt dùng chung cuộn cảm, nên 6 dB mỗi bên ở 100 Hz để lại <strong>+2.0 dB</strong> bên dưới và một chỗ trũng <strong>−1.4 dB</strong> ở 180 Hz thay vì một đường phẳng.","changelog.b3d85a912eee":"<strong><code>Strata</code> chia bốn dải cộng lại đúng bằng thứ đã đi vào.</strong> Sai lệch dưới <strong>0.01 dB</strong> trên mọi vùng crossover, điều đòi hỏi hiệu chỉnh all-pass trên các dải đã bỏ qua một crossover — thiếu chúng, một bộ xử lý đa dải sẽ bị lọc răng lược đúng ở những chỗ nó tồn tại để xử lý. Mỗi dải nén xuống và nâng lên từ <strong>một</strong> bộ phát hiện, nên hai nửa không thể bất đồng.","changelog.33d3cfb69d0c":"<strong><code>Stance</code> giống hệt từng bit khi bạn chưa yêu cầu nó làm gì.</strong> Không phải &quot;gần đủ&quot; — ra đúng những con số đã vào. Mọi tầng đều được bỏ qua thay vì chạy ở mức đơn vị, vì bộ xoay pha và crossover là các mạng all-pass, và một mạng all-pass cứ chạy sẽ làm nhoè mọi transient trên track chỉ vì một nút điều khiển chẳng ai chạm vào.","changelog.85c6c680dbe0":"<strong>Ba reverb, một bể, và &quot;hai giây&quot; nghĩa là hai giây ở cả ba.</strong> <code>Chamber</code>, <code>Foil</code> và <code>Coil</code> dùng chung một mạng delay phản hồi mười sáu đường với ma trận trộn trực giao, nên thời gian decay được quyết định bởi nút decay và không gì khác: RT60 đo được nằm <strong>trong vòng 5 %</strong> so với con số trên bảng từ 0.2 giây tới 12.","changelog.790ef72775e3":"<strong><code>Coil</code> nhỏ giọt, và tiếng nhỏ giọt là chính cơ chế chứ không phải một sự mô phỏng nó.</strong> Một lò xo truyền tần số thấp chậm hơn tần số cao, nên một xung quay lại thành một tiếng chirp đi xuống; mỗi lò xo là 120 tầng all-pass tán sắc, tạo 38 ms trễ ở 500 Hz so với 7.6 ms ở 4 kHz. Bể có một bộ lò xo và hai pickup, đó là nguồn gốc của stereo — không phải từ việc chạy cả bể hai lần.","changelog.13fe8240a909":"<strong>Phần bass của <code>Foil</code> không ngân lâu hơn phần cao</strong>, điều duy nhất phân biệt một plate với một hội trường nhỏ và là điều mà mọi bản mô phỏng plate đều làm sai.","changelog.cbb8261f8b1b":"<strong>Các lần lặp của <code>Spool</code> mỗi vòng lại đục hơn và bẩn hơn</strong>, vì độ bão hoà và suy hao khe của đầu từ nằm bên trong vòng phản hồi thay vì ở đường ra. Băng từ hay bucket brigade: băng thông của đường bucket đi xuống theo clock của nó, nên delay dài là delay tối — đúng như một linh kiện bucket-brigade thật sự, chứ không phải một delay có bộ lọc đặt phía sau.","changelog.3ed31dd895e1":"<strong><code>Comb</code> là một flanger qua-không thực thụ.</strong> Đường khô cũng được làm trễ, nên đường được điều chế quét qua nó và sang phía bên kia; ở điểm giao, hai đường mang cùng các mẫu tới mức tốt hơn <strong>60 dB</strong>, một điểm triệt tiêu mà flanger chỉ tiến gần tới không được thì không đạt tới. ⚠ Phần trễ của đường khô là độ trễ thật và được khai báo, nên gạt công tắc không làm track bị sớm.","changelog.bd48e1488259":"<strong><code>Sparks</code> dịch giọng mà không trôi</strong>, chính xác tới hơn một phần nghìn cent trên ±24 nửa cung, và các cửa sổ grain của nó cộng lại bằng đơn vị ở mọi mật độ thay vì chỉ ở đúng một mức chồng lấn mà cửa sổ Hann tình cờ làm được.","changelog.f57ce8edbf1a":"<strong><code>Shoal</code> giữ được độ rộng khi gập về mono.</strong> Mở rộng không làm dịch tổng mono chút nào, ở mọi độ rộng và mọi tần số, vì tổng và độ rộng được dựng riêng thay vì độ rộng là một mẹo đảo cực tính sẽ triệt tiêu khi gập lại.","changelog.cee1b6a54d95":"<strong>Băng của <code>Oxide</code> đục hơn ở 7½ ips so với 15</strong>, và còn đục hơn nữa khi đầu từ mòn — vì đầu phát không thể phân giải bước sóng ngắn hơn khe của chính nó, tức là <code>|sin(x)/x|</code> và một dòng mã chứ không phải một đường cong ai đó vẽ ra. Head bump của nó dịch theo tốc độ băng vì cùng lý do đó, và nó làm méo sườn lên khác với sườn xuống, đúng như một vòng từ trễ làm và một bộ tạo dạng sóng thì không làm được.","changelog.1910ed335a88":"<strong><code>Furnace</code> chùng xuống thay vì chỉ vuông vức hơn.</strong> Nguồn cấp của nó sụt dưới dòng mà các đèn công suất kéo, nên một hợp âm kéo điện áp xuống và nốt kế tiếp nhỏ hơn cho tới khi điện áp hồi lại: <strong>nén 4 dB khi vượt ngưỡng clip 6 dB</strong>, và nút Sag có quyền thực sự với con số đó.","changelog.e79ee3f59a10":"<strong><code>Baffle</code> không có đáp ứng xung nào bên trong, theo đúng nghĩa đen.</strong> Một loa cộng hưởng, một đỉnh vỡ màng loa, một cấu hình thùng có cổng, một bậc mép vách, một micrô có khoảng cách và trục, và một căn phòng ngắn — mỗi thứ là một hệ số chứ không phải một tệp. Loa mười hai inch cộng hưởng ở 75 Hz, loa mười lăm inch thấp hơn, loa tám inch cao hơn.","changelog.79387b24db13":"<strong>Chúng phát ra tiếng trong ứng dụng, không chỉ trong bài kiểm thử.</strong> Một thiết bị trên track được dựng khi kế hoạch kết xuất được dựng, chạy giữa phần cộng của dải kênh và fader của nó — chỗ của một insert — và độ trễ nó khai báo là mốc để mọi track khác được căn theo. ⛔ Chỉ có đúng một chỗ một thiết bị đi kèm có thể được khởi tạo, và nó trả về độ trễ trong cùng lời gọi đó, nên hai thứ không thể tách rời nhau.","changelog.3a625cdcb34b":"<strong>Một bảng điều khiển bạn thực sự vặn được.</strong> Một khung vỏ cho mọi thiết bị để chúng trông như cùng một gia đình, và một bảng được vẽ từ chính mô tả của thiết bị. ⛔ Bảng không bao giờ tự định dạng một con số: nó được trao chuỗi mà bộ định dạng riêng của DSP tạo ra, nên số đọc không thể bất đồng với những gì bạn sẽ nghe.","changelog.7e1fc34d1868":"<strong>Nút điều khiển hoạt động đúng như nút điều khiển.</strong> Hành trình 270°, tỉ lệ kéo vừa với bàn tay, <code>Shift</code> để chỉnh tinh — kèm hiện số thập phân mà nó mang lại — một vùng nắm mịn gần tâm và thô ở rìa, các nấc <strong>cản lại chứ không bật vào</strong> để một nút hai cực vẫn đặt được ở +0.3 dB, nhấp kèm <code>Alt</code> và nhấp đúp để đặt lại, con lăn chuột, điều khiển đầy đủ bằng bàn phím, và một lần kéo vẫn tiếp tục bám khi ra khỏi bảng.","changelog.5c54fb29c894":"<strong>Mọi thiết bị đều nói nó tốn của bạn bao nhiêu.</strong> Một thiết bị có độ trễ sẽ hiện nó, tính bằng mẫu và mili giây, ngay trên bảng của mình.","changelog.8e0f56dd7bcb":"<strong>Một clip MIDI phát ra tiếng.</strong> Nhạc cụ trên một track nhận các nốt mà bản phối chứa, chính xác từng mẫu trong khối, và đầu ra của nó là thứ mà chuỗi và fader của dải kênh xử lý. ⚠ Trước đây các nốt tới được đồ thị rồi dừng ở đó.","changelog.2e43c657f195":"Thêm mới — Oscillate là stereo, từ đầu tới cuối (Giai đoạn 7)","changelog.587ea2844a2a":"⛔ <strong>Giờ mọi đường âm thanh trong Oscillate đều mang hai kênh.</strong> Trước đây nó mang một, và đó không phải là một giới hạn trong lời chú thích:","changelog.be58cc9d5843":"<strong>Một tệp stereo phát ra stereo.</strong> Một tệp stereo được nhập bị worker phát lại lấy trung bình về một kênh trước khi kịp tới đồ thị kết xuất. Nhà sản xuất có thể nhập một bản bounce stereo, nhìn một dạng sóng stereo, mà đang nghe một tổng ở giữa — không có gì ở đâu nói ra điều đó.","changelog.ddf594435dd8":"<strong>Mọi dải kênh đều có pan hoạt động.</strong> Trước đây sản phẩm hoàn toàn không có pan theo từng kênh: luật pan chỉ được áp dụng một lần, ở master.","changelog.8ac7863b5f5d":"⛔ <strong>Pan và balance là hai luật khác nhau, và Oscillate dùng cả hai.</strong> Một nguồn mono được <em>đặt vị trí</em> với công suất không đổi, nên pan nó qua lại không làm thay đổi độ lớn. Một tín hiệu vốn đã là stereo được <em>nghiêng</em> ở mức đơn vị, nên một bus chuyển tiếp nó không làm suy giảm nó. Áp dụng luật đặt vị trí ở mọi điểm cộng là cách một bản mix lặng lẽ mất 3 dB mỗi bus — điều đã từng xảy ra một lần, và giờ có hai bài kiểm thử nói như vậy.","changelog.d0c94d7d1062":"<strong>Bù trễ được thực hiện theo từng kênh.</strong> Một đường trễ là bộ nhớ; một đường dùng chung cho hai kênh sẽ đặt lịch sử của kênh này vào đầu ra của kênh kia, tức là một tổng mono với thêm vài bước.","changelog.1ff0289da7b2":"<strong>Một tệp có nhiều kênh hơn Oscillate có sẽ được gập lại một cách trung thực.</strong> Kênh 1 và 2 là cặp chính; mọi kênh sau đó nhập vào cả hai bên với công suất bằng nhau. Một stem sáu kênh sẽ mất gì đó trong một sản phẩm hai kênh, và mất đều nhau là câu trả lời không bịa ra một bản mix chưa ai làm.","changelog.430445e78834":"⚠ <strong>Những gì chưa được dựng, nói thẳng.</strong>","changelog.ed4cf4e242f9":"<strong>Sáu thiết bị</strong>: bốn hiệu ứng âm thanh, một nhạc cụ và một thiết bị chơi phần cứng. ⚠ <strong>Mọi hiệu ứng cốt lõi và mọi thiết bị nốt đều đã được dựng.</strong> Con số từng là hai mươi mốt trước khi đường nối sample, luồng nốt, khả năng đọc trước, đường nối chiếm dụng giữa các track và đường nối MPE được đóng lại; những gì còn lại bị chặn ở thứ mà một thiết bị thực sự không nhìn thấy được, và mỗi cái nói rõ đó là gì.","changelog.38a8ee71a0b3":"<strong><code>Frequency Carve</code></strong> so các dải của track này với <strong>âm thanh của mọi track khác</strong>. Đường nối chiếm dụng mang những gì các track khác đang <em>chơi</em> — các nốt của chúng — chứ không phải chúng <em>nghe ra sao</em>: công bố năng lượng dải theo từng track là chuyện khác, và nó phải được lấp đầy sau khi mỗi track kết xuất chứ không phải trước khi bất kỳ track nào kết xuất.","changelog.9d4c0bb1c873":"<strong><code>Reverse Reverb</code></strong> dựng phần đuôi đảo ngược từ <strong>âm thanh chưa được phát</strong>, nghĩa là cần một luồng worker kết xuất bốn ô nhịp tiếp theo trong bản phối của track này vào một vòng đệm. Không có gì trong đồ thị kết xuất đi trước đầu phát; khả năng đọc trước mang cấu trúc, không mang âm thanh.","changelog.a1bd3c93ef36":"<strong><code>Chain Morph</code></strong> biến đổi giữa <strong>hai chuỗi hiệu ứng đầy đủ</strong> ở cấp hệ số. Giờ một thiết bị có thể chứa <em>engine</em> của thiết bị khác — <code>Quiver</code> chứa tám và <code>Muster</code> mười hai — nhưng một chuỗi gồm các thiết bị bất kỳ không có chỗ để giữ nút điều khiển của chúng: tham số của một thiết bị là một <code>Vec&lt;f64&gt;</code> phẳng, và tham số của một chuỗi lồng sẽ phải sống bên trong nó.","changelog.a8f92d184a0a":"<strong><code>Ember</code></strong> <em>&quot;phát lại những gì track này vừa chơi&quot;</em>, nên nó cần <strong>đầu ra sau fader</strong> của chính track được ghi vào một vòng đệm. Đường nối sample trao cho thiết bị một tệp; cái này cần một điểm rẽ trên đồ thị, vốn là hình dạng của đường thu âm chứ không phải của đường sample.","changelog.84b441e09a4b":"<strong><code>Salvage</code></strong> <em>&quot;dựng một bộ trống từ chính các thư mục của bạn&quot;</em>, nên nó cần thư viện của nhà sản xuất: nó bị chặn ở Trình duyệt tệp, và Giai đoạn 8 là lúc nó rời khỏi danh sách này.","changelog.21f63c13e3b3":"<strong><code>Outpost</code> chơi phần cứng ngoài</strong> qua một cổng MIDI với đường âm thanh trả về được đo. ⛔ <strong>Oscillate hoàn toàn không có I/O cổng MIDI</strong> — <code>oscillate_audio::midi</code> tồn tại mà không có gì gọi tới — nên cái này bị chặn ở một tầng chứ không phải ở một thiết bị.","changelog.55b1e9f4ac42":"<strong><code>Rein</code> không có nút <code>Pressure Depth</code></strong>, trong khi § 2 có liệt kê. Nốt được lưu của <code>oscillate_project</code> mang cao độ, velocity, velocity nhả và kênh; poly pressure không được ghi lại, nên nút đó sẽ là một núm vặn không có gì phía sau. ⚠ <code>NoteMessage::Pressure</code> đã tồn tại kể từ <code>Press</code>, nên đường nối DSP đã có — thứ còn thiếu là nốt được lưu.","changelog.3b6bba40e92d":"<strong><code>Strand</code> dịch giọng bằng cách dời bin thay vì dùng phase vocoder</strong>, trong khi đặc tả của nó yêu cầu bộ dao động liên tục về pha — nên một hoạ âm thành phần bị dịch rơi vào tâm bin gần nhất và bị nhoè thay vì sạch. ⚠ Nó chạy ở 1024 điểm trong khi đặc tả yêu cầu 4096. <code>Stft</code> giờ nhận độ dài khung lúc khởi tạo — <code>Sift</code> và <code>Ply</code> đều chạy ở 4096 — nên đây là việc đo lại chứ không phải một giới hạn, và việc đó chưa được làm.","changelog.00463fd5e001":"<strong>Quãng tám thấp nhất của <code>Sift</code> giảm 8.4 dB trên mức đặt 12</strong>, trong khi mọi dải từ 63 Hz tới 16 kHz đều nằm trong vòng nửa decibel. Ở khung 4096 điểm, quãng tám từ 22 tới 45 Hz chỉ có ba bin, và mức trung bình 64 khung của chính § 2 là 1.4 giây — quá ngắn để phần đáy của một nền nhiễu thật lặp lại. Cổng kiểm tra khẳng định đúng những gì nó thực sự làm và nói lý do.","changelog.14f6fe586263":"<strong><code>Hone</code> và <code>Stack</code> lấy giọng từ chính bảng của chúng</strong>, trong khi đặc tả còn đưa ra giọng của dự án và track hợp âm làm nguồn. Cả hai đều cần tới dự án, nên không nguồn nào được đưa ra thay vì đưa ra mà chẳng có tác dụng.","changelog.57af5d8acf67":"<strong><code>Approach</code> dựng đoạn fill từ những gì đang được giữ</strong>, trong khi đặc tả yêu cầu hợp âm của đoạn sắp tới. Bản thân ranh giới đoạn là thật — nó đến từ khả năng đọc trước mà engine đã tính sẵn — nên đoạn fill tới đúng chỗ với đúng hình dạng.","changelog.cabbe8817e21":"<strong>Tiếng rít của <code>Spool</code> và tiếng rên clock của <code>Shoal</code> chỉ phát ra khi có thứ gì đó đang đi qua.</strong> Một cỗ máy thật rít dù có gì đang phát hay không; một plugin rít trên một track im lặng là thứ nhà sản xuất sẽ gỡ đi ngay lần đầu solo một đoạn yên tĩnh.","changelog.9fc40d6ef00e":"<strong><code>Foil</code> và <code>Coil</code> hành xử như plate và spring; chúng không phải lời giải của vật lý.</strong> Đặc tả yêu cầu vài nghìn bộ cộng hưởng từ phương trình tấm mỏng tán sắc và ba bể gồm các tầng mô phỏng. Thứ được dựng là bể reverb dùng chung được tạo hình để hành xử như từng loại, trong đó độ tán sắc của <code>Coil</code> là cơ chế thật còn khoảng cách mode của <code>Foil</code> không tuyên bố tuân theo định luật của tấm.","changelog.fd6445143eaf":"<strong><code>Strata</code> không có chế độ crossover pha tuyến tính</strong>, trong khi đặc tả của nó yêu cầu một chế độ ở 4096 tap và độ trễ 2048 mẫu. Nên trên bảng cũng không có bộ chọn Filter Mode — một bộ chọn chỉ có một vị trí hoạt động còn tệ hơn không có. Tiêu chí biên độ đạt được trên đường LR4; tiêu chí pha ±0.5° thuộc về chế độ không có ở đây, và một cây LR4 không thể đạt được nó.","changelog.8fb3c0f5fe51":"<strong>Độ trễ từ của <code>Oxide</code> không phải là lời giải Jiles-Atherton</strong>, và tone stack của <code>Furnace</code> không phải lời giải mạch theo nút mà đặc tả của nó yêu cầu — nên tiêu chí ±0.3 dB của stack không được tuyên bố. Mỗi cái thực sự <em>là</em> gì được ghi trong header module của nó, bên cạnh những gì là thật: suy hao khe và hành vi theo tốc độ của <code>Oxide</code> là vật lý, và độ tán sắc của <code>Coil</code> là cơ chế.","changelog.65207b679973":"<strong><code>Temper</code> mô phỏng hành vi của mạch thụ động thay vì giải nó.</strong> Sự tương tác mà nhà sản xuất tìm tới được đo theo chính các con số của đặc tả; không gian trạng thái theo nút bậc bốn bên dưới không phải là mạch điện, và tầng drive của nó là một phi tuyến có oversampling chứ không phải một tầng đèn với nguồn cấp riêng.","changelog.9e9b24e99407":"<strong><code>Whetstone</code> có bốn dải và không có đường pha tuyến tính</strong>, trong khi đặc tả của nó yêu cầu mười hai dải và cả hai chế độ pha.","changelog.1f3f9ed46a23":"<strong>Bộ phân tích và đường vết giảm gain chưa chạy TRỰC TIẾP.</strong> Đường cong mà thiết bị áp dụng được vẽ, đã hiệu chỉnh, trên một lưới tần số và decibel thật, và bộ cổng kiểm tra giữ nó trong vòng một phần mười decibel so với âm thanh. Những thứ bên cạnh — mức giảm gain và độ tương quan — là các giá trị <strong>nghỉ</strong> của thiết bị, đọc từ một thiết bị được dựng ra để trả lời câu hỏi rồi bỏ đi. Một đường vết chuyển động cần một điểm rẽ trên chính phiên bản của engine đẩy dữ liệu vào một vòng đệm không khoá, và cái đó chưa được dựng. ⚠ Điều này được nói trong header module của <code>panel.rs</code> thay vì để ai đó thắc mắc vì sao kim không bao giờ nhúc nhích.","changelog.076bf92bab94":"<strong>Đường cong là HÌNH DẠNG, không phải cấu trúc gain.</strong> Chỗ một thiết bị trũng xuống và nâng lên được vẽ và có cổng kiểm tra; tổng thể nó to bao nhiêu thì không, vì mức tín hiệu nhỏ của một bộ khuếch đại đèn là độ dốc của ba triode và một vòng hồi tiếp, và đưa điều đó vào đường cong vẽ ra sẽ là viết mô hình phi tuyến lần thứ hai ở một chỗ không có gì ràng buộc nó với lần thứ nhất.","changelog.a830ff8ce227":"<strong>Các thiết bị stereo từng bị chặn giờ không còn bị chặn nữa.</strong> <code>Stance</code>, <code>Chamber</code>, <code>Foil</code>, <code>Coil</code>, <code>Shoal</code> và <code>Vault</code> chờ một đồ thị kết xuất hai kênh chứ không phải chờ thời gian của ai. Đồ thị đó đã có và <code>Stance</code> đã được dựng; năm cái kia giờ chỉ đơn giản là chưa được viết, như những cái còn lại.","changelog.e173fc848dc8":"<strong>Không thể thả một preset chuỗi lên track từ trình quản lý tệp</strong>, và thư viện giá thiết bị mà định dạng này phục vụ (200 giá của chính hãng) chưa được viết. Thứ được dựng là định dạng, việc lưu, việc gọi lại và các cảnh báo — menu xin một tệp qua hộp thoại native, con đường duy nhất mà ứng dụng này sẽ tin tưởng.","changelog.0e86c6b10e81":"<strong>Chuỗi công thức là một thiết bị.</strong> Dán một chuỗi vào một <em>track</em> để tạo thiết bị là nửa sau của § F-18 và chưa được nối: bản xem trước nói dòng đó dành cho thiết bị nào và không đề nghị gì, thay vì thêm thứ mà nhà sản xuất không yêu cầu.","changelog.6070503f26bb":"Thêm mới — chạy plugin (Giai đoạn 6)","changelog.4cdb78939a18":"<strong>Oscillate nạp các plugin VST 3 và CLAP bạn đã sở hữu</strong>, mỗi cái trong <strong>một tiến trình riêng</strong>. ⛔ Plugin nào sập thì chỉ một thiết bị bị làm xám, vẫn giữ tên và có nút <em>Nạp lại</em> bên cạnh; transport vẫn chạy và dự án không bị đụng tới.","changelog.f1ceb07e2c76":"⛔ <strong>Tệp nhị phân của ứng dụng hoàn toàn không nạp được plugin.</strong> Các bộ nạp nằm sau một tính năng Cargo mà chỉ tệp nhị phân hộp cát bật lên — nên tiến trình bạn chạy không liên kết <code>dlopen</code> cho <code>.vst3</code> hay <code>.clap</code> và không thể mở một plugin nào dù được yêu cầu. Đó là tính chất của bản dựng, không phải một quy tắc ai đó phải tuân theo.","changelog.2cc3956eefdc":"⚠ Plugin chạy <strong>chậm một khối</strong>, đó là cách mọi host ngoài tiến trình hoạt động — và khối đó được <strong>cộng vào độ trễ mà thiết bị báo</strong>, nên phần bù là cho độ trễ thật sự tồn tại chứ không phải cho con số plugin tự nhận.","changelog.d17de61edfa2":"<strong>Một lần quét plugin không bao giờ bắt bạn chờ.</strong> Mỗi plugin được mở trong một tiến trình dùng-một-lần có giới hạn thời gian, bảng nói nó đang xem tệp nào <strong>theo tên</strong>, và bạn vẫn tiếp tục làm việc trong lúc đó. Thứ gì làm sập trình quét hai lần sẽ được để riêng ra — <strong>một cách công khai</strong>, kèm chuyện đã xảy ra và nút <em>Thử lại</em> — thay vì lặng lẽ biến mất khỏi bộ sưu tập của bạn.","changelog.6b08669472c3":"<strong>Oscillate tìm ở đâu là do bạn quyết định.</strong> Các thư mục chuẩn của từng định dạng được liệt kê đúng như chúng là, có thể tắt nhưng không sửa được, và bạn thêm tối đa <strong>năm thư mục của riêng mình</strong> qua chính hộp chọn của hệ điều hành. ⛔ Giới hạn này được nói ra kèm lý do — một lần quét khởi động một tiến trình cho mỗi plugin nó tìm thấy. Một thư mục trên ổ đĩa bạn đã rút ra được hiện là thiếu và <strong>được giữ lại</strong>.","changelog.cc7e387cb175":"<strong>Giá thiết bị.</strong> Mỗi thiết bị một thẻ, theo thứ tự chuỗi, cho biết nó là gì (<code>STOCK</code>, <code>CLAP</code> hoặc <code>VST3</code>), preset của nó, và <strong>nó tốn của bạn bao nhiêu độ trễ — tính bằng mẫu và mili giây</strong>. Không host nào hiện điều đó rõ ràng, và một nhà sản xuất đang thu giọng cần biết thiết bị nào đang làm họ tốn 40 ms.","changelog.3d1bb7f3c970":"<strong>Bỏ qua vẫn giữ thiết bị được nạp và vẫn bù độ trễ của nó</strong>, nên tắt một thiết bị không làm dịch mọi track khác so với nó. Đó là khác biệt giữa bỏ qua và gỡ bỏ, và là điều người ta nhận ra.","changelog.cccfa4d11c12":"<strong>Gỡ bỏ là một lần nhấn hoàn tác, và nó quay lại với mọi thứ bạn đã đặt.</strong> Mất một giờ tinh chỉnh vì một cú nhấp nhầm là không chấp nhận được.","changelog.5d696b3bddc6":"<strong>Sắp xếp lại bằng cách kéo</strong>, và một chuỗi mà thiết bị không được vào sẽ nói <em>vì sao</em> — &quot;thiết bị nốt phải đứng trước nhạc cụ&quot; — thay vì từ chối trong im lặng.","changelog.00a58d0258aa":"<strong>Bù trễ plugin, trên toàn đồ thị.</strong> Mọi điểm cộng đều căn bằng những gì tới nó, nên một track có EQ pha tuyến tính và một track không có gì tới cùng lúc. ⛔ Được chứng minh bằng <strong>phép thử triệt tiêu</strong>: cùng một tín hiệu đi qua một thiết bị có báo độ trễ và đi vòng qua nó, triệt tiêu thành im lặng <strong>tuyệt đối</strong> — và cùng phép thử đó khi gỡ bỏ phần bù, chứng minh nó đang đo một thứ có thật.","changelog.97dfa8211a1f":"<strong>Một plugin không có trên máy này trở thành một ô giữ chỗ có tên</strong>, giữ trạng thái và tự động hoá của nó và đề nghị <em>Tìm…</em> — và <em>Tìm…</em> <strong>xác minh</strong> tệp bạn trỏ tới trước khi gắn, thay vì lặng lẽ gắn thiết lập của bạn vào một plugin khác.","changelog.32a11990f9cc":"<strong>Đóng băng và bounce tại chỗ</strong>, cố ý là hai thao tác khác nhau: đóng băng giải phóng các tiến trình plugin của track và có thể đảo ngược chính xác; bounce thay thế các clip và gỡ các thiết bị. ⛔ Một bản đóng băng không còn khớp với những gì trên track sẽ được <strong>rã băng</strong>, không bao giờ được phát — nghe âm thanh của hôm qua còn tệ hơn chẳng nghe gì.","changelog.b470dbf6260c":"<strong>Một bộ kiểm thử tuân thủ.</strong> Tệp nhị phân hộp cát được phát hành được điều khiển qua một đường ống thật ở mỗi lần chạy CI — nó phải trả lời, từ chối một khối thù địch mà không chết, và gọi tên một plugin không tồn tại — và các plugin miễn phí được ghim bằng SHA256 sẽ được nạp và mô tả khi có mặt.","changelog.4e46ad2f60cf":"Pháp lý — giấy phép VST 3, được đọc chứ không phải giả định (Giai đoạn 6)","changelog.f37a3bfa9028":"⛔ <strong>VST 3 SDK của Steinberg là MIT</strong>, từ bản 3.8 trở đi, và <a href=\"https://freallyproducts.com/freally-oscillate/legal/vst3-sdk.md\"><code>docs/legal/vst3-sdk.md</code></a> ghi lại văn bản giấy phép từ bên trong bản sửa đổi đã ghim — không phải từ một bài báo. Miễn phí, dùng được trong sản phẩm độc quyền, không cần đăng ký, và điều kiện duy nhất là thông báo bản quyền.","changelog.744c22d64e93":"⛔ <strong>Nhãn hiệu được ghi nhận riêng và bị từ chối.</strong> Logo VST là tuỳ chọn theo MIT; Oscillate không đi kèm nó, và &quot;VST&quot; không xuất hiện trong tên sản phẩm nào.","changelog.0bc06d4d7aba":"⛔ <strong>Vì vậy không có C++ trong kho mã này.</strong> Cầu nối mà lộ trình từng cho phép không được dựng: các binding Rust được phát hành đã sinh sẵn, nên không SDK nào được nhúng vào, không bộ công cụ C++ nào được thêm vào bản dựng, và không cái nào được thêm vào bất kỳ runner nào trong ba runner CI.","changelog.5a58a9104716":"Thêm mới — các trình chỉnh sửa (Giai đoạn 5)","changelog.ed12a161eacd":"<strong>Bản phối phát được.</strong> Kế hoạch kết xuất đọc các clip của dự án: một clip âm thanh được truyền từ tệp của nó tại vị trí của nó trên dòng thời gian, tôn trọng độ lệch nội dung, cả hai fade và gain của nó, được cộng vào track của nó. ⛔ Các mẫu được lấy từ đĩa qua một vòng đệm do một worker lấp đầy — không bao giờ đọc tệp trên luồng âm thanh.","changelog.34bc614e709e":"<strong>Piano roll.</strong> Nốt được vẽ, di chuyển, đổi kích thước, dịch giọng và xoá bằng chính những thao tác mà bản phối dùng; một làn velocity; các làn bộ điều khiển để bạn vẽ một đường cong ngang qua, nơi <strong>một lần quét là một lần nhấn hoàn tác</strong>; và một âm giai của dự án để gập các hàng lạc giọng lại.","changelog.fe21807f67ce":"<strong>Trình chỉnh sửa clip âm thanh.</strong> Nhấp đúp vào một clip âm thanh và cuối cùng nó cũng mở ra — dạng sóng riêng ở mức thu phóng riêng, <strong>xuống tới từng mẫu</strong>: dưới độ phân giải của bộ nhớ đệm đỉnh của bản phối, các mẫu được đọc từ tệp cho đúng khung đang trên màn hình.","changelog.63b986567a23":"Một <strong>đường bao gain của clip</strong> được vẽ đè lên dạng sóng. ⛔ Một nút điều khiển thứ ba, tách riêng khỏi gain cố định của clip và khỏi tự động hoá của track — ba thứ mà phần lớn DAW gộp ít nhất hai làm một — để bạn có thể hạ một chữ trong phần vocal mà không chạm vào gì khác.","changelog.b554f646f97e":"<strong>Tay cầm fade và cả hai mép</strong>, chính là các thao tác của bản phối chứ không phải một bộ thứ hai có thể bất đồng với chúng.","changelog.0c638649fa35":"<strong>Đảo ngược, chuẩn hoá, làm im một vùng chọn, và khử độ lệch DC.</strong> ⛔ Mọi thao tác đều <strong>không phá huỷ</strong>: chúng là các trường trên clip, trong nhật ký hoàn tác, không bao giờ là việc ghi lại tệp. Thư viện sample của bạn không phải của chúng tôi để chỉnh sửa.","changelog.abbe7944b38f":"Đầu phát chạy trên dạng sóng khi đang phát, và một khoảng bạn kéo ra để làm im.","changelog.c377ccf80966":"<strong>Bảy phép biến đổi nốt</strong>, mỗi phép một lần nhấn và một lần nhấn hoàn tác: đảo, đảo ngược, kéo giãn, legato, lượng tử hoá, nhân tính hoá và đưa-về-âm-giai.","changelog.4baac0375406":"⛔ <strong>Lượng tử hoá có độ mạnh, không phải một công tắc.</strong> Ở nửa độ mạnh, một nốt dịch nửa đường về phía lưới — cách siết một take mà không làm phẳng đi phần trình diễn khiến nó đáng giữ. Swing chỉ đẩy các phách nghịch.","changelog.b6bb8b6037c9":"⛔ <strong>Nhân tính hoá có thể tái lập.</strong> Tính ngẫu nhiên được gieo seed và seed là một phần của thao tác, nên cùng một phiên mở trên máy khác — hoặc phát lại từ chính nhật ký của nó — cho ra cùng một bản nhạc.","changelog.1eb70df10591":"⚠ Năm phép có phím tắt. Đảo và kéo giãn thì không: chúng cần một con số, và một phím tự đoán con số đó sẽ làm sai một cách nhanh chóng.","changelog.8c457c75ee5d":"<strong>Một quy tắc quyết định trình chỉnh sửa nào mở ra</strong>, ở một chỗ: clip MIDI mở piano roll, clip âm thanh mở trình chỉnh sửa dạng sóng, và clip MIDI trên một track trống mở lưới trống.","changelog.b620599ca4c1":"<strong>Lưới trống.</strong> Một clip trên track bạn đã đánh dấu là bộ trống mở ra thành một lưới các làn thay vì piano roll — mỗi âm một làn, có tên, velocity thể hiện qua độ đậm, tắt tiếng theo làn và <strong>nhóm choke</strong> để hi-hat đóng chặn hi-hat mở. ⛔ Là bộ trống là thuộc tính của TRACK, đúng như ý bạn khi nói <em>&quot;track trống của tôi&quot;</em>.","changelog.8f31cc77fb13":"<strong>Làn tự động hoá cho mọi tham số.</strong> Các công cụ vẽ, bút chì, đường thẳng và đường cong; các chế độ đọc, ghi, latch và touch; một tay cầm cong trên mỗi điểm. ⛔ Nó <strong>chính xác từng mẫu</strong>: engine được biết mỗi khoảng của một khối nằm ở đâu trên dòng thời gian, nên một đường cong được quét đúng kể cả qua một điểm vòng lặp rơi vào giữa bộ đệm.","changelog.cf94d06807a3":"<strong>Kata — một đường cong bạn có thể đặt tên và dùng lại.</strong> Đóng dấu một hình ở bất cứ đâu, với lượng, độ lệch và độ biến thiên riêng; sửa hình đó và <strong>mọi con dấu đều theo</strong>, vì con dấu là một tham chiếu chứ không phải một bản sao. ⚠ Độ biến thiên được gieo seed, nên một phiên ngày mai vẫn nghe y như vậy.","changelog.06c1460a5f20":"<strong>Ghép take với các làn take.</strong> Thu đè lên một đoạn bao nhiêu lần tuỳ thích: mỗi take giữ làn riêng của nó và không có gì bị ghi đè. Quét ngang các làn để chọn take nào phát ở đâu, và các mối nối là <strong>crossfade thật</strong> — cả hai take đều được đọc và trộn, với công suất bằng nhau, nên mức âm không bị hụt ở giữa mỗi mối nối.","changelog.aee6a60fece3":"<strong>Bản thu ẩn.</strong> Một take bạn không chọn sẽ không bao giờ bị xoá. Nó thu gọn vào một làn bóng mờ và nằm lại trong tệp cho tới khi bạn chủ động xoá take đó.","changelog.b74811a88c81":"<strong>Nhát cắt.</strong> Vẽ một nét lưỡi dao ngang bản phối và mọi clip mà nét đi qua đều bị tách tại chỗ nó đi qua — và <strong>góc của nét chính là crossfade</strong>: dốc là một nhát cắt gọn, thoai thoải là một lần hoà dài, kèm độ dài tính bằng mili giây hiện ra trong lúc bạn vẽ. ⛔ Cả nét là một lần nhấn hoàn tác.","changelog.ff38926dc74b":"<strong>Tua lại phiên.</strong> Một dòng thời gian thứ hai — không phải của bài hát, mà của phiên làm việc. Kéo nó và nhìn bản phối tự dựng lại ngược thời gian. ⛔ <strong>Tua là một khung nhìn</strong>: không có gì thay đổi cho tới khi bạn chọn một trong ba thứ được đề nghị khi buông tay — trở về hiện tại, hoàn tác đến đây, hoặc <strong>Rẽ nhánh</strong>, tách dự án từ thời điểm đó và giữ cả hai.","changelog.23b8f03491d7":"<strong>Các bảng bạn có thể kéo ra màn hình thứ hai.</strong> Trình duyệt tệp, Bộ sinh, Trình chỉnh sửa, Bàn trộn và Phòng đều mở được trong cửa sổ riêng, với thanh tiêu đề và thanh trạng thái riêng. ⛔ Mọi cửa sổ đều hiện cùng một phiên: chỉnh sửa ở một cửa sổ xuất hiện ở tất cả, track bạn chọn trong bàn trộn tách rời là track được chọn trong bản phối, và nhấp đúp vào một clip sẽ mở nó ở bất cứ cửa sổ nào đang chứa trình chỉnh sửa. ⚠ Đóng một bảng tách rời sẽ đặt nó về chỗ cũ thay vì huỷ nó, và các bảng luôn quay về bên trong ứng dụng khi bạn khởi động lại — một cửa sổ được khôi phục lên một màn hình bạn đã rút ra là cửa sổ bạn không với tới được.","changelog.8076f4c7a582":"<strong>Một clip có thể lặp lại để lấp đầy độ dài của chính nó.</strong> Trường này đã có trong tệp từ Giai đoạn 3 và bản phối đã vẽ dấu lặp từ Giai đoạn 4; giờ có một nút bấm, trong cả hai trình chỉnh sửa, và chất liệu thực sự lặp lại.","changelog.01bd16d5c3eb":"<strong>Tìm các nhát đánh trong một take.</strong> Một lần nhấn đánh dấu mọi transient trên dạng sóng — chỗ nhà sản xuất cắt, căn theo lưới, hoặc cắt gọt tới nốt đầu tiên.","changelog.939938b1052f":"<strong>Clip MIDI được lên lịch.</strong> Nốt của một pattern tới được luồng âm thanh, đúng phách, được dịch giọng theo vị trí đặt chứa chúng. ⚠ Ở cuối luồng chưa có gì để phát chúng thành tiếng — nhạc cụ là Giai đoạn 7 — nhưng bộ lập lịch đã có và đã được chứng minh, và đó là điều giúp giai đoạn kia không phải tới lúc đó mới phát hiện ra mình cần một bộ.","changelog.e12f1a9c473b":"<strong>Một tệp được thu ở tần số lấy mẫu khác với phiên giờ phát đúng tốc độ.</strong> Một sample 44.1 kHz trong một phiên 48 kHz từng phát ra cao hơn khoảng một nửa cung rưỡi và ngắn hơn 9 %, mà không có gì nói lý do. ⛔ Phép chuyển đổi là một bộ nội suy sinc có cửa sổ, lọc về tần số Nyquist thấp hơn trong hai tần số trước khi hạ mẫu, nên không có gì bị gập ngược vào dải bạn nghe được. ⚠ Trình chỉnh sửa vẫn cho bạn biết cả hai con số: một tệp được lấy mẫu lại không phải là tệp gốc, và nếu bạn đang săn nửa decibel cuối cùng của một bản master thì bạn có quyền biết nguồn nào của mình đang bị chuyển đổi.","changelog.f8e6e5b55387":"Sửa lỗi — ⛔⛔ TOÀN BỘ DANH SÁCH KHÔNG VỚI TỚI ĐƯỢC (Giai đoạn 7)","changelog.7645fca08728":"<strong>Năm mươi tư thiết bị, bảng điều khiển, đường cong, chuỗi công thức của chúng — tất cả đã dựng, tất cả đã kiểm thử, và không cái nào có trong trình duyệt.</strong> Nhà sản xuất không thể thêm một thiết bị riêng nào của Oscillate vào track.","changelog.1599669c8454":"▶ Trình duyệt plugin liệt kê những gì <strong>trình quét</strong> tìm thấy trên đĩa, còn thiết bị đi kèm được biên dịch vào tệp nhị phân chứ không được quét — <code>scan::describe_one</code> từ chối nó kèm tên. Không có gì từng đưa danh sách vào chỉ mục đó, nên <code>device_add</code> trả lời <em>&quot;không plugin đã quét nào có id hilt&quot;</em> cho cả bảy mươi lăm thiết bị, và danh sách không hiện cái nào. ⚠ <strong>Mọi cổng kiểm tra khác đều xanh</strong>, vì mọi cổng khác đều hỏi xem thiết bị có <em>hoạt động</em> không. Không cổng nào hỏi xem có ai với tới được nó không.","changelog.268e4269f385":"⛔ <strong>Đây là lần thứ năm dự án này phát hành cả một cơ chế mà không có gì gọi tới</strong>, và lần thứ năm câu hỏi tìm ra nó vẫn là câu đó: <em>nhà sản xuất thực sự sẽ nhấn gì?</em> Các cổng mới trong <code>plugins::browser</code> hỏi đúng câu đó — mọi thiết bị trong danh sách đều có trong trình duyệt, một thiết bị đi kèm thực sự thêm được vào track, danh sách đứng trước và kết quả quét không bị mất — và cả ba đều đã được nhìn thất bại với đúng lỗi này.","changelog.54f680c853bb":"⚠ <strong>Một nửa thứ hai, trong giao diện.</strong> Huy hiệu định dạng là <code>format === 'vst3' ? 'VST3' : 'CLAP'</code> — một biểu thức hai nhánh trên một kiểu ba biến thể, nên mọi thiết bị riêng của Oscillate lẽ ra đã bị gắn nhãn <strong>CLAP</strong> ngay khi chúng có mặt trong danh sách. Giờ nó là một phép tra bảng, nên định dạng thứ tư sẽ là một lỗi biên dịch thay vì rơi vào nhánh nào thua.","changelog.73c54b400c47":"⚠ <strong>Và một lỗi khả năng với tới thứ hai bên dưới: trình duyệt không TÌM được chúng.</strong> § 1 nói rõ — <em>&quot;chỉ mục tìm kiếm trên cột đó không phải là tuỳ chọn; nó là thứ duy nhất làm cho một cái tên gợi hình dùng được, và phát hành các cái tên mà không có nó khiến cả bộ còn tệ hơn tên chung chung&quot;</em> — vậy mà bộ lọc chỉ đọc tên và nhà sản xuất. <code>Vise</code> là một compressor và chẳng có gì trong từ đó nói vậy. Giờ thiết bị mang theo việc nó là gì qua đường nối và phép tìm nhìn vào đó, nên gõ &quot;compressor&quot; sẽ tìm ra nó.","changelog.9df0131b255e":"⚠ <strong>Bộ nhớ đệm không bao giờ mang danh sách.</strong> Danh sách là thuộc tính của bản dựng, không phải của máy: một bộ nhớ đệm do phiên bản này ghi và phiên bản khác đọc sẽ hồi sinh những thiết bị không còn tồn tại, và trình duyệt sẽ đề nghị một thiết bị mà registry trả lời là <code>None</code>.","changelog.51ab50580236":"Sửa lỗi — ba cổng kiểm tra đang canh nhầm thứ (Giai đoạn 7)","changelog.3b4ddbdf23f0":"⛔⛔ <strong>Hai kiểu Rust cùng ghi một tệp TypeScript, và cổng kiểm tra binding không nhìn thấy.</strong> <code>oscillate_dsp::device::Domain</code> và <code>oscillate_project::track::Domain</code> đều sinh ra <code>src/bindings/Domain.ts</code>, nên <strong>crate nào chạy kiểm thử sau cùng thì thắng</strong> — cây làm việc chập chờn, và phép kiểm tra báo trôi lệch trên một cây chẳng ai đụng tới. ⚠ <strong>Bản sửa đầu tiên gỡ <code>export</code> của một crate và trông như đã thành công</strong>, vì thứ tự chạy tình cờ có lợi cho project; nó quay lại vào lần tiếp theo một bài kiểm thử <code>oscillate-dsp</code> chạy sau cùng. ts-rs ghi ra một kiểu bất cứ khi nào có thứ được export với tới được nó, và một <code>DeviceSpec</code> được export mang một <code>domain</code>. ▶ Kiểu của DSP giờ là <code>DeviceDomain</code> trong TypeScript, và <strong><code>check-bindings</code> từ chối mọi cặp kiểu được export sẽ rơi vào cùng một đường dẫn</strong> — đã được nhìn thất bại với đúng lỗi này. Thứ mà cổng đó cuối cùng sẽ báo là <em>không</em> trôi lệch trên một cây thực sự đã thay đổi.","changelog.88e9c9b494b0":"⛔ <strong>Một preset chuỗi được ghi bằng <code>fs::write</code>.</strong> <code>SECURITY.md</code> nói rằng Oscillate ghi bên cạnh đích với <code>O_EXCL</code> rồi đổi tên đè lên — để một liên kết tượng trưng cài vào chỗ một tệp sẽ nằm bị từ chối thay vì bị ghi xuyên qua — và điều đó chỉ có đúng một cách cài đặt, bên trong phần lưu dự án. Bên ghi thứ hai chẳng có gì trong số đó. ▶ <code>io::write_atomic</code> giờ là cách cài đặt đó, và cả hai nơi gọi đều đi qua nó.","changelog.786d25e6f7a0":"⚠ <strong>Cổng kiểm tra ngôn ngữ gọi một dạng số nhiều được khai báo đúng là một khoá bị thiếu.</strong> i18next phân giải <code>t('a.b', { count })</code> qua <code>a.b_one</code> và <code>a.b_other</code> và không bao giờ qua <code>a.b</code>. Giờ cổng đã hiểu điều đó và <strong>đòi cả hai dạng</strong> — một khoá chỉ có <code>_other</code> sẽ hiện ra chính cái khoá khi số đếm là một, đúng kiểu lỗi mà cổng tồn tại để bắt, chỉ khó thấy hơn.","changelog.36ca4917ed10":"Sửa lỗi — trước khi bất cứ điều gì ở trên được phát hành","changelog.c7dcd3ccbb44":"⚠ Mỗi lỗi dưới đây đều được tìm ra bởi đợt rà soát Cổng Giai đoạn 5 hoặc bằng cách chạy thử ứng dụng đã dựng, và mỗi lỗi đều xanh trong bộ kiểm thử trước đó.","changelog.4c94ae2428be":"<strong>Bản phối im bặt ngay khi bạn nhấn Phát.</strong> Một lượt cập nhật tự động hoá trong khi transport chạy đã thay kế hoạch kết xuất năm mươi lần mỗi giây bằng một kế hoạch không gắn clip nào.","changelog.151aee7757e6":"<strong>Các bảng tách ra màn hình thứ hai không nhìn thấy phiên.</strong> Mỗi cửa sổ là một trình duyệt nhỏ riêng với bản sao riêng của mọi thứ, và không có gì báo cho các cửa sổ khác khi có thay đổi.","changelog.58bfb47479c3":"<strong>Tách rời một bảng có thể làm treo ứng dụng</strong>, và một dự án mới mở ra một cửa sổ đầy các bảng trống.","changelog.87b86fb5cfb4":"<strong>Một tệp có hơn hai kênh bị giật</strong>, và có thể dừng toàn bộ việc phát cho tới hết phiên nếu clip được đặt để lặp lại.","changelog.665dfeb7d79e":"<strong>Tự động hoá vẽ muộn trong phiên phát ở sai mức</strong> và nhảy bậc thay vì quét mượt — đúng ở đầu bài, sai ở mọi chỗ khác.","changelog.fe41509c874e":"<strong>Một Kata được đóng dấu không phát ra tiếng cũng không được vẽ</strong>, dù nó đã được lưu và được đếm.","changelog.f0c60af56408":"<strong>Các nốt sau một nốt dài không phát.</strong> Một nốt ngân ở đầu ô nhịp chặn mọi thứ phía sau cho tới khi nó kết thúc.","changelog.313751e2faad":"<strong>Phần lớn mối nối comp là nhát cắt gọn</strong> thay vì crossfade bạn đã đặt.","changelog.e084958ed56f":"<strong>Dấu transient trên một clip đã cắt gọt</strong> lẽ ra sẽ nằm sai chỗ.","changelog.14f8ce6b8a19":"Thêm mới — bản phối (Giai đoạn 4)","changelog.b6922d007ca3":"<strong>Khung nhìn bản phối.</strong> Một dòng thời gian bạn làm việc được: thước có ô nhịp và phách, lưới đi theo mức thu phóng, clip được vẽ từ chính nội dung của chúng, và đầu track dọc bên cạnh. Thu phóng theo thang logarit và neo dưới con trỏ, nên ô nhịp bạn đang nhìn vẫn nằm đúng chỗ bạn đang nhìn.","changelog.7cae614909e8":"<strong>Clip được vẽ từ đúng bản chất của chúng.</strong> Một clip âm thanh vẽ dạng sóng thật từ tệp đỉnh đã lưu đệm; một clip MIDI vẽ các nốt của nó, ở đúng cao độ có trong đó. ⛔ Một clip có nội dung chưa tới chỉ vẽ phần thân và không gì khác — một dạng sóng giữ chỗ là lời nói dối về âm thanh.","changelog.b6e510719661":"<strong>Di chuyển, sao chép, cắt gọt, tách, fade, tắt tiếng, lặp, đổi tên và đổi màu</strong>, và <strong>mỗi thao tác là một lần nhấn hoàn tác</strong> dù chạm vào bao nhiêu clip. Kéo kèm <code>Alt</code> để sao chép. Cắt gọt từ mép nào cũng được; chất liệu đi theo mép thay vì trượt bên dưới nó. Lưỡi dao cắt mọi clip đã chọn trong một nét.","changelog.a21fb8951d11":"<strong>Đầu phát.</strong> Một đường màu xanh lơ — màu duy nhất dành riêng cho <em>hiện tại</em> — được vẽ từ vị trí mà luồng âm thanh <strong>thực sự đã tới</strong>, sáu mươi lần mỗi giây. ⛔ Không bao giờ nội suy đi trước engine: một đầu phát dự đoán sẽ sai mỗi khi một bộ đệm trễ, và trông như âm thanh đang giật trong khi không phải. Nhấp vào thước để định vị, kéo để tua.","changelog.0132a0a5cc57":"<strong>Một dòng thời gian tự dài ra.</strong> Thước kéo dài khi bạn đặt nội dung gần cuối nó, và bạn có thể kéo dấu kết thúc ra xa hơn bằng tay. ⛔ Mức trần là <strong>hai giờ</strong>, được nói rõ trên thanh công cụ và được báo khi bạn chạm tới — không bao giờ là một lần thả lặng lẽ chẳng làm gì.","changelog.261a9999d38c":"<strong>Nhóm track.</strong> Kéo một đầu track vào một nhóm và nó gập vào trong. ⛔ Nhóm là một bus thật với fader và chuỗi riêng, nên tắt tiếng nhóm sẽ làm im mọi thứ bên trong — không phải một tiện ích chỉ để vẽ.","changelog.e3f13607ab34":"<strong>Đánh dấu, ngoặc vòng lặp, nhịp độ và loại nhịp</strong>, tất cả trên dòng thời gian thay vì trong một hộp thoại. Kéo thước kèm <code>Alt</code> để vẽ một vòng lặp.","changelog.67e7decaa422":"<strong>Bám lưới</strong>, kể cả <em>thích ứng</em> — lưới đi theo mức thu phóng, nên nó luôn là mức chia nhỏ nhất bạn thực sự nhìn thấy được.","changelog.7bdf979c3936":"<strong>200 track × 2 000 clip.</strong> Được đo, không phải tuyên bố: một màn hình của một dự án 400 000 clip được trả lời trong <strong>2.4 ms</strong> so với một khung hình 16 ms.","changelog.a04b02adb5a0":"Thêm mới — bàn trộn trở thành một phần của dự án","changelog.aa23b1e78aec":"<strong>Giờ mọi nút điều khiển trên bàn trộn đều là thay đổi hoàn tác được.</strong> Một lần kéo fader, tắt tiếng, solo, bật sẵn sàng thu, chọn đầu vào và đổi tên đều đi vào nhật ký thao tác, vào tệp và vào nhật ký sự cố — vì track là một thực thể của <strong>dự án</strong> và bàn trộn là một hình chiếu của nó. ⛔ Trước đây, không có gì trong giao diện ghi nhận một thao tác nào cả: Hoàn tác và Làm lại bị xám vĩnh viễn và đề nghị khôi phục không bao giờ xuất hiện được.","changelog.5800eedeca12":"<strong>Chọn một dải kênh và nhấn <code>Delete</code></strong> để gỡ track đó cùng mọi thứ trên nó, trong một lần nhấn hoàn tác. Vùng chọn chuyển sang track kế tiếp. ⛔ Không thể xoá master.","changelog.092073003d57":"<strong>Kéo các dải kênh để sắp xếp lại</strong>, trong một lần nhấn hoàn tác. Thứ tự là của dự án, nên bàn trộn, bản phối và tệp đã lưu luôn khớp nhau.","changelog.c53e20e0fcf2":"<strong>Fader master được lưu.</strong> Nó từng là nút điều khiển duy nhất trên bàn trộn vừa không hoàn tác được vừa không được ghi vào tệp — một phiên được mix ở −3 dB sáng hôm sau mở ra ở mức đơn vị.","changelog.f754a89b56d9":"<strong>Nhấp đúp vào tên một dải kênh để đổi tên track.</strong>","changelog.71651e6922dd":"Thêm mới — transport","changelog.151c030e6fd3":"<strong>Thu âm bắt đầu khi nhấn và dừng khi nhấn</strong>, và nhấn Thu âm lần nữa sẽ tắt nó. ⛔ <strong>Không có đếm vào trừ khi bạn bật</strong> trong Cài đặt → Ghi âm, nơi có lựa chọn 3–5 giây hoặc 1–4 ô nhịp.","changelog.13a415817735":"<strong>Phát, Dừng, Thu âm, Sẵn sàng thu, Đầu vào, Tắt tiếng và Solo đều phản hồi ngay lập tức.</strong> Mỗi lần nhấn là một vòng đi-về thay vì hai, và nút bấm xác nhận lần nhấn trong khi câu trả lời của engine đang trên đường tới. ⛔ Thứ nó <em>vẽ</em> vẫn là thứ engine đã công bố — lời xác nhận là cho lần nhấn, không bao giờ là một tuyên bố về âm thanh.","changelog.4aa204616e75":"<strong>Transport đã rời khỏi bàn trộn</strong> để nằm phía trên bản phối, nên ẩn bảng bàn trộn không còn ẩn luôn nút Phát.","changelog.6e24c576ac39":"<strong>Nhấp đúp vào một tệp <code>.oscillate</code> sẽ mở nó</strong>, dù Oscillate đã đang chạy hay chưa.","changelog.174b3ab19a0f":"**Thanh trạng thái chỉ nói một bảng <em>dùng để làm gì</em> khi chuột ở trên thanh tiêu đề của nó.** Thấp hơn tiêu đề một pixel là nó lùi về câu nghỉ. Giờ nó hiện như nhau ở bất cứ đâu bên trong một vùng.","changelog.4b361ad48ca4":"<strong>Fader của bàn trộn trông như một hình vuông.</strong> Núm của nó cùng màu với dải kênh phía sau, nên nút điều khiển không có viền suốt nửa dưới. Giờ nó có rãnh, một núm có chỗ bám và một thang chia — và độ tương phản được <strong>đo</strong> trên mọi nền ở cả hai giao diện thay vì ước bằng mắt.","changelog.3fe647a29dfd":"<strong>Một con chuột nằm yên làm câm bàn phím.</strong> Khi gợi ý được gắn cho cả bảng, một con chuột để ở bất cứ đâu trong cửa sổ được ưu tiên hơn bàn phím cho tới hết phiên — trống trơn đúng với những người cần thanh trạng thái nhất. Giờ thao tác nào chuyển động <em>sau cùng</em> thì nó trả lời.","changelog.d4042456dc28":"Thêm mới — thu âm, đúng như cách nhà sản xuất thực sự làm việc (2026-08-26 và 27)","changelog.27cea337b5fa":"<strong>Một take xong trở thành một clip trên track đang sẵn sàng thu.</strong> Trước đây nó ghi ra một tệp <code>.wav</code>, báo tệp nằm ở đâu, và để dòng thời gian trống trơn.","changelog.a05ec14dab99":"<strong>Mỗi take là một clip riêng</strong>, và hai take liền nhau đều được ghi — nên chất liệu để ghép take có sẵn đó thay vì một take lặng lẽ thay thế take khác trên đĩa.","changelog.063bae2b2031":"<strong>Một take mới thay thế những gì nó phủ lên.</strong> Punch in đè lên một take có sẵn và âm thanh cũ dừng hẳn ngay chỗ take mới bắt đầu. ⛔ <strong>Không có gì bị phá huỷ</strong>: các clip bị đẩy ra được cắt gọt và tách, mọi mẫu vẫn nằm trong tệp nguồn của nó, và một lần nhấn Hoàn tác đưa tất cả trở lại.","changelog.e3c8ed4616e6":"<strong>Dạng sóng được vẽ ngay khi bạn hát</strong>, lớn dần dưới đầu phát — từ đỉnh đo được của chính engine, nên thứ bạn nhìn và mức âm trên dải kênh của bạn không thể bất đồng. Một take im lặng vẫn vẽ clip của nó, đúng độ dài thật.","changelog.f76d7ffb3369":"<strong>Máy đếm nhịp phát ra tiếng.</strong> Nó có một thiết lập dự án, một thao tác và một cờ trong engine, mà không có đường nào nối chúng lại — tiếng tích tắc được tính mỗi khối mà không có gì đọc. Giờ có một giọng, một công tắc trên dải điều khiển phát, và một phần đếm vào bạn nghe được.","changelog.f3d9577ce851":"<strong>Phần đếm vào bạn nhìn thấy được.</strong> Số giây còn lại trước khi bắt đầu thu được hiện ở chỗ bạn liếc thấy bằng khoé mắt, được đếm bởi luồng âm thanh chứ không phải một bộ hẹn giờ trên trang.","changelog.517bce56ac3a":"<strong>Bản phối cho biết đầu phát đang ở đâu</strong> — ô nhịp và phách, thời gian, nơi track kết thúc, và mức trần hai giờ. Trước đây nó chỉ cho biết dự án dài bao lâu.","changelog.12429092771c":"<strong>Một vùng chọn track chung cho bàn trộn và bản phối</strong>, nên Thu âm không thể ghi vào một track bạn không nhìn tới.","changelog.7a13f6667cf5":"<strong>Nhấn Dừng hai lần đưa đầu phát về đầu.</strong>","changelog.a74f61c309b9":"<strong>Các fade không thể chéo nhau.</strong> Kéo fade-in quá fade-out sẽ bị kẹp lại ở phần chỗ mà fade kia để lại.","changelog.5635048c1c6c":"<strong>Tên track được giới hạn độ dài và dễ đọc.</strong> Đầu track trong bản phối cho tên một dòng riêng — sáu nút 24 px trong một đầu track 196 px chỉ để lại cho nó khoảng mười.","changelog.ae173857b667":"Thêm mới — các nút điều khiển phát mà nhà sản xuất hay với tới (2026-08-27)","changelog.6434635375f9":"<strong>Một máy đếm nhịp bạn nhìn được.</strong> Một chữ <code>M</code> <strong>giữa</strong> hai chấm, phần tô đổi từ chấm này sang chấm kia ở mỗi phách, nên cặp chấm trông như bàn tay nhạc trưởng chứ không như một bóng đèn nhấp nháy. ⚠ Các chấm to bằng chấm của nút Thu âm và chúng bật tức thì thay vì mờ dần — một phách là một khoảnh khắc, và một máy đếm nhịp chuyển mượt vào phách sẽ trông như trễ kể cả khi tiếng tích tắc đúng giờ tuyệt đối. ⚠ Được vẽ từ phách mà luồng âm thanh thực sự đã tới — một bộ hẹn giờ theo nhịp độ sẽ trôi lệch so với engine chỉ trong vài giây, và một máy đếm nhịp bất đồng với những gì bạn nghe còn tệ hơn không có.","changelog.a2c66155342b":"<strong>Một ngoặc vòng lặp bạn thao tác được.</strong> Một ngoặc đã có sẵn khi dự án mở — từ ô nhịp 1 tới ô nhịp 5, đang tắt — nên bạn không bao giờ phải tự tìm cách tạo. Kéo thanh nối và cả vòng lặp trượt theo, giữ nguyên độ dài; kéo một trong hai tay cầm và chỉ đầu đó di chuyển. ⛔ <strong>Chúng không bao giờ chéo nhau được</strong>: mỗi đầu bị kẹp ở một ô nhịp <em>theo loại nhịp đang có hiệu lực tại chỗ nó nằm</em>. Nhấp kèm <code>Ctrl</code>/<code>Cmd</code> để bật tắt vòng lặp, và mỗi thao tác như vậy là một lần nhấn hoàn tác.","changelog.8f16d426462b":"<strong>Nhấp vào bất cứ đâu trong bản phối để đặt đầu phát ở đó</strong>, không chỉ trên thước cao 24 pixel. ⚠ Kéo vẫn là khoanh vùng chọn — hai thao tác được phân biệt bằng việc con trỏ có di chuyển hay không.","changelog.ae32226c7f3d":"<strong>Loại nhịp sửa được</strong>, cạnh nhịp độ, đúng chỗ của nó. Nó đã có trong mô hình từ Giai đoạn 3, <code>bars.ts</code> đã đọc nó và thước đã vẽ nó, vậy mà không có gì trong giao diện thay đổi được nó.","changelog.22ad9b3d722f":"Sửa lỗi — những đường nối mà ba đợt rà soát tìm ra (2026-08-27)","changelog.fa4907a02da4":"<strong>Các chỉnh sửa sau của một thao tác được kiểm tra hợp lệ dựa trên dự án như trước khi có các chỉnh sửa trước đó.</strong> Và khi đã sửa điều đó, việc cắt gọt mép trái của một clip kết thúc ở mức trần hai giờ lại bị từ chối: trạng thái trung gian chạy quá điểm cuối dù trạng thái cuối cùng thì không.","changelog.1bba613b10b9":"<strong>Lưới bám bỏ qua mọi lần đổi loại nhịp sau lần đầu tiên.</strong> Một phiên chuyển sang 6/8 ở ô nhịp 33 vẫn bám phần còn lại của bản phối theo ô nhịp 4/4 — và ngay cả lưới đúng cũng được đếm từ tick không thay vì từ chỗ loại nhịp đổi, nên clip rơi vào giữa các vạch ô nhịp bạn nhìn thấy.","changelog.3a0c33b3e6b3":"<strong>Cuộn nhanh có thể để dòng thời gian hiện các ô nhịp bạn đã cuộn qua</strong>, và khẳng định đã nạp những ô nhịp mà nó chưa từng nạp.","changelog.8597dcaebff6":"<strong>Các dải hàng bị đảo ngược khi bạn cuộn</strong>, trong khi chúng tồn tại chính là để giúp dõi theo hàng.","changelog.3bb4cc884f29":"<strong>Một lần kéo chiều cao track bị huỷ để đầu track sai kích thước</strong> cho tới hết phiên.","changelog.0673ae95a689":"<strong>Nhật ký khôi phục có thể lặng lẽ bỏ mọi thứ sau một bản ghi quá cỡ</strong> và báo tệp như một lần cụt đuôi bình thường do sự cố.","changelog.c2949c578495":"<strong>Một tệp <code>.wav</code> mang khúc <code>LIST</code>, <code>fact</code> hay <code>PAD </code> trống trước <code>fmt </code> bị từ chối như thể bị cụt</strong> — không có dạng sóng, và clip phát ra im lặng.","changelog.6e0584e53a87":"<strong>Một câu trả lời sai hình dạng làm sập cửa sổ</strong> thay vì bị từ chối.","changelog.3b546441830b":"<strong>Đích thả tệp của bản phối</strong>, thứ không bao giờ có thể hoạt động. Webview không bao giờ thấy một thao tác kéo tệp — Tauri sở hữu việc thả — và kể cả nếu thấy, một đường dẫn do trang cung cấp chính là thứ sản phẩm này từ chối chấp nhận. ⚠ Việc nhập âm thanh không bị ảnh hưởng: nó vẫn với tới được qua hộp chọn tệp. Một lần thả thật phải được xử lý trong Rust, và đó là một quyết định thiết kế chứ không phải một bản sửa lỗi.","changelog.ae0e37ba6be2":"Sửa lỗi — những gì cổng giai đoạn tìm ra khi chạy thử ứng dụng đã dựng","changelog.bbbc9059eb60":"⚠ Mỗi lỗi dưới đây đều qua được toàn bộ bộ kiểm thử và thất bại trong tay nhà sản xuất. Chúng được tìm ra khi chạy thử <strong>tệp nhị phân release</strong> thay vì một bản dựng xem trước, đó chính là mục đích của lượt kiểm tra thực tế của cổng.","changelog.84a878dc90df":"⛔ <strong>Một chỉnh sửa trên bàn trộn vô hình với Hoàn tác, và với dấu báo thay đổi chưa lưu.</strong> Thêm một track đặt một dải kênh vào giá và không tới được gì khác — <code>File ▸ Undo</code> vẫn xám, chấm báo chưa lưu không bao giờ sáng, và đầu track trong bản phối vẫn hiện các track như trước. <strong>Một nhà sản xuất dành cả phiên trong bàn trộn rồi thoát ra không bao giờ được báo là mình có phần việc chưa lưu.</strong> Giờ mọi lệnh thay đổi dự án đều trả lời bằng toàn bộ đường nối.","changelog.b91883d78df0":"⛔ <strong>Hoàn tác ném lỗi, và không làm gì.</strong> <code>project_undo</code>, <code>project_open</code>, <code>project_new</code> và <code>project_save</code> trả lời bằng một bản tóm tắt trơn trong khi front end chờ toàn bộ đường nối, nên hoàn tác thất bại lặng lẽ bên trong chính phần mã đã thực hiện nó. Mở một dự án cũng không bao giờ đọc lại bàn trộn từ các track của dự án mới.","changelog.ebd08c2bb97b":"⛔ <strong><code>File ▸ Undo</code> hiện <code>Undo {{gesture}}</code>.</strong> Khi không có gì để hoàn tác, menu vẽ ra chính khuôn mẫu của nó. Giờ có một nhãn riêng trong cả mười tám ngôn ngữ — một phép nội suy rỗng là không đủ, và để lại một dấu hai chấm lơ lửng trong tiếng Nga và một trợ từ trơ trọi trong tiếng Nhật.","changelog.b0798ca992b8":"⛔ <strong>Mọi fader trên bàn trộn đều vẽ thang chia mà không có vạch mức đơn vị.</strong> Mức đơn vị được so khớp với một vị trí thang cố định bằng phép so sánh bằng trên số thực dấu phẩy động, trong khi bàn trộn tự tính vị trí của nó từ hành trình, nên chẳng bao giờ khớp. Giờ vạch được vẽ <strong>đúng tại</strong> mức đơn vị thay vì ở nấc gần nhất, điều này cũng sửa các fader có mức đơn vị nằm cách xa mọi nấc.","changelog.bca525a074d9":"<strong>Phần đếm vào chỉ tới được engine nếu bạn mở Cài đặt.</strong> Nó được đẩy đi bởi chính bảng vẽ bộ chọn, nên ở mỗi lần khởi động, engine đếm vào bằng không cho tới khi màn hình đó được ghé qua.","changelog.5ce1635ae9eb":"<strong>Bản phối vẽ lại sáu mươi lần mỗi giây khi đang dừng</strong>, dựng lại mọi hàng track, chỉ vì một vị trí đầu phát mà chỉ hai nút đọc tới.","changelog.f3c36b3ce60a":"Sửa lỗi — mô hình, và những gì một tệp thù địch có thể làm","changelog.793366e43f5d":"⛔ <strong>Một đường dẫn <code>.wav</code> bên trong tệp dự án được mở mà không được kiểm tra.</strong> Một tệp <code>.oscillate</code> tới qua tải về hoặc từ một cộng sự, và một tệp được sửa tay có thể chỉ định một đường dẫn trên <strong>máy khác</strong> — mà Windows sẽ tự động xác thực tới, làm lộ thông tin đăng nhập của nhà sản xuất, chỉ vì mở tệp. Giờ Oscillate từ chối mọi đường dẫn không phải là một tệp cục bộ thuần tuý trước khi mở nó.","changelog.772fa7975871":"⛔ <strong>Một lệnh nhập chấp nhận đường dẫn tệp từ giao diện.</strong> Giờ nó chỉ lấy từ hộp chọn native, như mọi đường dẫn khác trong sản phẩm — và một bài kiểm thử đọc mã nguồn để giữ nó như vậy.","changelog.62b162f4459b":"⛔ <strong>Gỡ một track có thể làm mất clip của nó vĩnh viễn.</strong> Một lần gỡ được dựng ngoài thao tác bình thường không ghi lại đường lui nào cho các clip nó đã xoá, nên hoàn tác khôi phục một track trống. Giờ việc đó bị từ chối.","changelog.ac5b9eebbbf8":"<strong>Xoá một nhóm để lại các track bên trong vẫn trỏ vào nó.</strong> Bàn trộn và bản phối đều vẽ một nhóm không còn tồn tại. Thay vào đó, các track con được nhấc lên nhóm phía trên.","changelog.4ced12bd8446":"<strong>Một bản thu bị cắt ngang vì sự cố được nhập vào mà không có danh tính nội dung</strong> và với độ dài lấy từ header thay vì từ những gì thực sự có ở đó. Giờ nó bị từ chối, kèm một câu nói rõ chuyện gì đã xảy ra.","changelog.82c6f3242320":"<strong>Một dự án có thể tự tắt giới hạn hai giờ của nó</strong> chỉ bằng một trường bị sửa.","changelog.6a9f69980c92":"<strong>Trình đọc đỉnh định cỡ bộ đệm theo một con số trong tệp.</strong>","changelog.1e1652d0b1fc":"Thêm mới — dự án (Giai đoạn 3)","changelog.000b52ad8bce":"<strong>Một phiên bản Oscillate duy nhất, không phải nhiều.</strong> Khởi chạy Oscillate khi nó đã đang chạy sẽ đưa cửa sổ hiện có lên trước thay vì khởi động tiến trình thứ hai. ⛔ Hai Oscillate sẽ tranh nhau thiết bị âm thanh, <code>preferences.json</code> và thư mục take — và cái đầu tiên trong số đó hiện ra như một biểu ngữ trông giống phần cứng bị hỏng.","changelog.8289318a37f6":"<strong>Nhật ký thao tác.</strong> Mỗi thay đổi nhà sản xuất thực hiện là một <code>Operation</code>, và hoàn tác, làm lại, cộng tác, Tua lại phiên và sổ ghi tác quyền là bốn cách đọc của cùng một nhật ký đó. Một thao tác phức hợp là <strong>một</strong> thao tác — kéo bốn mươi nốt chỉ tốn một lần nhấn hoàn tác, không phải bốn mươi.","changelog.4eb96d6377e1":"<strong>Hoàn tác và làm lại không giới hạn, theo từng tác giả.</strong> <code>Ctrl</code>/<code>⌘</code>+<code>Z</code> hoàn tác thay đổi gần nhất <em>của bạn</em> và không bao giờ của người khác, ngay từ commit đầu tiên, trước khi có ai để cùng chia sẻ phiên. 10,000 thao tác đo được <strong>5.8 MB</strong> và lần hoàn tác đơn lẻ chậm nhất là <strong>7 µs</strong> — so với ngân sách 200 MB và 16 ms.","changelog.bdc94205dc9c":"<strong>Pattern.</strong> Một clip <em>tham chiếu</em> nội dung của nó và không bao giờ sở hữu nó — với MIDI cũng như với âm thanh. Đặt một phần trống bốn ô nhịp ba mươi hai lần và bạn có ba mươi hai clip và <strong>một</strong> pattern: sửa một lần và mọi vị trí đặt đều thay đổi. <em>Tách riêng</em> là một hành động rõ ràng để rẽ nhánh nó.","changelog.388422931fa2":"<strong>Tệp <code>.oscillate</code>.</strong> Một vỏ chứa có phiên bản: một manifest JSON cộng các khúc nhị phân. ⛔ Mọi độ dài đều được kiểm tra giới hạn trước khi tới bộ cấp phát, nên một tệp hỏng hoặc thù địch sẽ <strong>báo lỗi kèm lý do</strong> và không bao giờ làm sập tiến trình. Mọi tiền tố của một tệp hợp lệ và mọi biến đổi một byte trên nó đều được kiểm thử.","changelog.d522a5cbcc8e":"<strong>Lưu, Lưu thành, Mở, và một lịch sử phiên bạn thao tác được.</strong> Các dự án gần đây có thể mở, <strong>hiện trong trình quản lý tệp</strong>, quên từng cái một hoặc xoá hết — danh sách là bản ghi những gì bạn đã làm, nên nó là của bạn để xoá. Một dự án có tệp đã bị dời đi sẽ bị làm xám và <strong>giữ nguyên hàng của nó</strong>, nên cắm lại ổ đĩa sẽ khôi phục nó.","changelog.260ee88cb364":"<strong>Một phiên mặc định.</strong> Lưu bản phối bạn luôn bắt đầu từ đó — track, tên, màu, định tuyến, chuỗi thiết bị, nhịp độ và loại nhịp — và <code>New Project</code> sẽ mở nó. ⛔ Không bao giờ có clip của bạn và không bao giờ có âm thanh của bạn. <em>Đặt lại về mặc định gốc</em> đưa bản của chính Oscillate trở lại.","changelog.b5e407459915":"<strong>Khôi phục sau sự cố tới đúng thời điểm sự cố.</strong> Mọi thao tác đều được ghi nhật ký vào một tệp đi kèm ngay khi xảy ra, nên lúc sập không còn gì phải làm — phần việc đã nằm trên đĩa. ⛔ Khôi phục được <strong>đề nghị</strong>, không bao giờ tự áp dụng: dự án đã lưu của bạn không bị ghi cho tới khi bạn đồng ý. Khoảng thời gian một lần mất điện có thể làm mất được nêu rõ trong menu Tệp thay vì chỉ ngụ ý.","changelog.b31ad4e4a0db":"<strong>Một tệp từ bản Oscillate mới hơn sẽ từ chối mở, gọi tên cả hai phiên bản</strong>, và đề nghị chế độ chỉ đọc. ⛔ Và một trường mà bản dựng này không hiểu sẽ được mang qua khi lưu thay vì bị lặng lẽ bỏ đi.","changelog.4f94248b72da":"<strong><code>Ctrl</code>/<code>⌘</code> + <code>N</code>, <code>O</code>, <code>S</code>, <code>Shift+S</code>, <code>Z</code> và <code>Shift+Z</code></strong>, đều gán lại được, và đều bị bỏ qua khi bạn đang gõ trong một ô nhập.","changelog.ee8c3606ce09":"Một lần lưu không bao giờ cắt cụt tệp mà nó đang thay thế. Dự án mới được ghi bên cạnh dự án cũ, đồng bộ xuống đĩa, và chỉ sau đó mới được đổi tên đè lên — nên không có khoảnh khắc nào đường dẫn chứa một nửa dự án.","changelog.6ceed1e0814b":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-08-25\">2026-08-25</time></span>","changelog.f67bfa325008":"<strong>Lớp vỏ, và một âm thanh.</strong> Giai đoạn 1 và 2 gộp lại — bậc đầu tiên mà Oscillate trông giống chính nó <strong>và</strong> mở được thiết bị, giữ nhịp, trộn, đo và thu. ⚠ Đã dựng và xác minh, <strong>không công bố</strong> (quy tắc điều lệ 5).","changelog.5796e58a5bdd":"<strong>Một cửa sổ không viền với thanh tiêu đề riêng</strong> và − □/❐ ✕. Vùng kéo loại trừ các nút điều khiển, nhấp đúp để phóng to, và aero-snap vẫn hoạt động vì thao tác kéo được trao cho chính vòng di chuyển của hệ điều hành. Vị trí và kích thước cửa sổ được ghi nhớ theo từng máy — và <strong>không bao giờ được khôi phục lên một màn hình không còn kết nối</strong>.","changelog.f9b314697ae1":"<strong>Hệ thống bảng</strong>: Trình duyệt tệp, Bộ sinh, Trình chỉnh sửa, Bàn trộn và Phòng, mỗi bảng được hiện và ẩn bằng một nút hình ảnh <em>chính là</em> trạng thái của vùng đó, trên <code>Ctrl/⌘+1…5</code>.","changelog.a9109db1e242":"<strong>Mười hai biểu tượng bảng</strong>, tự vẽ trên lưới 24 × 24 bằng <code>currentColor</code>, và một cổng kiểm tra kết xuất từng cái ở 16 px và thất bại nếu có hai cái trùng hình bóng.","changelog.69e7b7c3ab85":"<strong>Khung bố cục</strong> — lưới theo thiết kế, thanh chia điều khiển được bằng bàn phím, và các vùng thu gọn theo một thứ tự được ghi rõ khi cửa sổ hẹp lại, với nút của vùng không vừa bị vô hiệu hoá và nói lý do.","changelog.147bb006862f":"<strong>Co giãn tỉ lệ</strong>: một hệ số tỉ lệ, tính ở một chỗ, với chữ co giãn chậm hơn hình khối, được quét ở tám độ rộng từ 1280 tới 3840 để tìm rãnh chết và vùng nhấp quá nhỏ.","changelog.ac2529873765":"<strong>Ba trạng thái giao diện — hệ thống, sáng và tối — được ghi nhớ theo từng máy</strong>, và việc chuyển đổi đi theo nhát cắt.","changelog.015a610ef72a":"<strong>Nhát cắt</strong>: một lần quét chéo, trên một trục, dùng cho mọi hộp thoại, mọi bảng và việc chuyển giao diện. Dưới <code>prefers-reduced-motion</code> nó là một đường khác chứ không phải một đường ngắn hơn, và lớp quét không bao giờ được gắn vào.","changelog.d1b1a8561adc":"<strong>Hộp thoại Cài đặt</strong> với cả mười mục, <code>Esc</code>, bẫy tiêu điểm, áp dụng tức thì và lưu riêng theo từng máy. Các mục chưa có hệ thống con nào phía sau nói rõ điều đó thay vì vẽ ra các nút điều khiển chẳng thay đổi gì.","changelog.9b7d9224e453":"<strong>Một bảng phím tắt gán lại được</strong> — một bảng, được các trình xử lý đọc và được kết xuất vào Cài đặt, với xung đột bị từ chối kèm tên.","changelog.01315f761e95":"<strong>Sáu nút điều khiển cốt lõi</strong> — Knob, Fader, Meter, Toggle, Selector và NumberField — dùng chung một thao tác, với động học đồng hồ đo thuần tuý và được kiểm thử từng khung hình.","changelog.297b0ff97ebe":"<strong>Màn hình chờ</strong>: hình nhân Oscillate nhảy lên, lưỡi dao chém xuống, và nhát cắt quét nó đi để lộ ra bản phối. Phím hoặc cú nhấp nào cũng bỏ qua được nó, nó không bao giờ kéo dài thời gian khởi động nguội, và tác phẩm minh hoạ 2 MB được thu nhỏ lúc dựng.","changelog.1aac2bdb22c4":"<strong>Bản thoả thuận lần chạy đầu</strong>, được kết xuất từ chính <code>EULA.md</code> và được ghi nhận theo mã băm của văn bản đó, nên một bản thoả thuận thay đổi đáng kể sẽ hỏi lại. Không có gì hoạt động trước khi chấp nhận — kể cả mọi phím tắt.","changelog.4413c389097a":"<strong>Báo lỗi và báo sự cố.</strong> Một lần panic của Rust ghi ra báo cáo trước khi tiến trình kết thúc; một lỗi kết xuất ghi ra một báo cáo và <strong>để việc phát tiếp tục chạy</strong>. Báo cáo nằm tại máy, được hiện đầy đủ, giữ tối đa hai mươi báo cáo mới nhất, và được che mọi đường dẫn tuyệt đối và địa chỉ. ⛔ Không có gì được tự động truyền đi, và <em>mở báo cáo đã điền sẵn</em> trao một URL cho trình duyệt của bạn thay vì tự gửi yêu cầu.","changelog.ed49327ae78a":"Cổng <code>bindings</code> là một cổng trôi lệch thật thay vì một bài kiểm thử ghi đè lên chính thứ nó kiểm tra: nó chụp lại, sinh lại và so sánh, và thất bại khi bước export không tạo ra gì cả.","changelog.38d32c539046":"Các cổng Playwright chọn theo <strong>project</strong> thay vì liệt kê tên tệp spec — trước đây một spec mới chạy được ở máy cục bộ mà không bao giờ chạy trên CI.","changelog.3f0c0f6da683":"Hoạt ảnh mặt nạ của nhát cắt chạy ngược chiều, nên mọi hộp thoại, mọi vùng và màn hình chờ đều mờ dần tới <strong>hoàn toàn vô hình</strong> khoảng 260 ms sau khi xuất hiện, trong khi vẫn nhấp được. Phát hiện bằng mắt; giờ được ghim bằng một khẳng định keyframe và bằng các bài kiểm thử so sánh pixel thật.","changelog.666c4c2ea362":"Một tuỳ chọn được đổi trong vòng 250 ms trước khi thoát bị mất, vì lần ghi được trì hoãn gộp và không có gì xả nó ra khi thoát.","changelog.034ca2037612":"Thay đổi — màn hình chờ và biểu tượng, theo quyết định của chủ dự án (2026-08-25)","changelog.7f6a52a11899":"⛔ <strong>Màn hình chờ giờ là một cửa sổ trong suốt riêng.</strong> Trước đây nó là một lớp phủ bên trong ứng dụng, nghĩa là có hai điều nó không bao giờ thoát được: nó không thể lớn hơn cửa sổ ứng dụng — 960×600 logic trên màn hình 2560×1600 ở mức co giãn 150 % — và luôn có <em>thứ gì đó</em> được vẽ phía sau hình nhân đã cắt. Giờ nó là <code>splash.html</code>, một trang riêng trong một cửa sổ toàn màn hình riêng <strong>không có nền màu nào</strong>, được dựng và định cỡ trong Rust theo màn hình nó mở trên đó. Thứ bao quanh hình nhân Oscillate chính là màn hình máy tính của bạn.","changelog.eccd1dd3e489":"Gói màn hình chờ là <strong>0.7 kB JavaScript và 1 kB CSS</strong>, hoàn toàn tách biệt khỏi 189 kB của ứng dụng. Đó là thứ đầu tiên được giải mã khi khởi động nguội.","changelog.405302c0a35a":"<strong>Cú nhảy là một cú nhảy thật.</strong> Nó vào từ dưới mép đáy, vọt lên tới đỉnh, rồi rơi xuống — lao về phía bạn liên tục qua cả hai nửa, tỉ lệ 0.13 → 2.0, kết thúc vượt xa mép màn hình. Các keyframe là mẫu lấy từ hai đường cong trơn chứ không phải các tư thế đặt bằng tay.","changelog.c8138b18399e":"⚠ <strong>Cửa sổ ứng dụng vẫn ẩn cho tới khi màn hình chờ bàn giao</strong>, và Rust đặt một bộ canh để một trang không bao giờ gọi lại không thể để lại một tiến trình đang chạy mà không có cửa sổ nào.","changelog.c72349087278":"⛔ <strong>Biểu tượng ứng dụng được vẽ lại, không phải chụp ảnh.</strong> Trong một ngày, biểu tượng phát hành là hình nhân của màn hình chờ cắt ra từ chính lớp mặt nạ của nó; ở 16 px, một bức ảnh toàn thân chỉ là một đống nhoè. Giờ nó là <strong>một thanh katana xuyên qua một chiếc vòng bị chém đứt</strong>, sinh ra từ các design token bằng phép tính — chiếc vòng cho <em>bốn nhà sản xuất, một phiên</em>, thanh kiếm cho Oscillate, trên trục −22° của chính sản phẩm.","changelog.480ac8d3405f":"Thay đổi — thời lượng và hành vi của màn hình chờ","changelog.2ef806b69680":"⛔ <strong>Nó là bắt buộc và không bỏ qua được, như của FL Studio.</strong> Không có nút bỏ qua, không bắt sự kiện phím bất kỳ. Nó phát trọn cú nhảy, nhát chém và nhát cắt ở mỗi lần khởi động cho tới khi bạn tắt nó trong <strong>Cài đặt → Giao diện</strong>, và công tắc đó chỉ được tôn trọng khi màn hình chờ đã chạy hết ít nhất một lần trên máy này — nên một tệp tuỳ chọn sao chép từ máy khác không thể bỏ qua một màn hình tiêu đề mà máy này chưa từng hiện.","changelog.ddddf34a2c57":"⚠ <strong>Điều này đảo ngược hai quy tắc của § F-21</strong>, một cách có chủ đích: <em>&quot;bỏ qua được bất cứ lúc nào&quot;</em> và <em>&quot;không bao giờ kéo dài thời gian khởi động nguội&quot;</em>. Giờ nó tốn khoảng hai giây. Thứ còn giữ lại là một <strong>mức trần</strong> — bắt buộc không có nghĩa là vô hạn, và một bài kiểm thử vẫn khẳng định nó kết thúc.","changelog.40d388966a63":"⚠ <strong>Hành vi cũ tệ hơn vẻ ngoài của nó.</strong> Chuỗi hoạt ảnh nhảy thẳng tới nhát chém ngay khi ứng dụng sẵn sàng, mà ứng dụng sẵn sàng gần như tức thì — nên trên mọi máy thật, cú nhảy chỉ phát được khoảng một phần năm và thanh kiếm không bao giờ chém xuống.","changelog.b3f010a5d099":"<strong>Hình nhân lớn hơn nhiều và thực sự lao về phía bạn</strong> — căn giữa tuyệt đối thay vì là một phần tử flex giành cột với chữ logo, lớn lên 2.7× qua cú nhảy và kết thúc gần bằng chiều cao màn hình.","changelog.5e796ac2c528":"<strong>Màn hình chờ tối ở cả hai giao diện.</strong> Trên một máy dùng giao diện sáng, nó là một hình nhân nhỏ giữa một khoảng trắng; câu định danh của chính sản phẩm là <em>một phòng thu tối với một lưỡi sáng bên trong</em>. Đó là bề mặt duy nhất không đi theo giao diện, và <code>splash.contrast.test.ts</code> kiểm tra màu riêng của nó thay vào đó.","changelog.be115dfca1d9":"<strong>Tác phẩm minh hoạ được sinh ra ở độ phân giải đầy đủ</strong> (cao 1531 px ở 2×), vì giờ nó được hiển thị đủ lớn để tài nguyên 1280 px cũ bị nhoè.","changelog.4806942da19f":"⛔ <strong>Màn hình chờ không còn quét VÀO, chỉ quét ra.</strong> Nó là bề mặt đầu tiên trên màn hình mà phía sau không có gì để lộ ra từ đó, và che nó vào nghĩa là khung ứng dụng hiện <em>xuyên qua</em> nó suốt thời gian nhát cắt — một cái chớp của đúng giao diện mà nó tồn tại để giới thiệu, ở mỗi lần khởi động.","changelog.917a1f65a62b":"<strong>Được tìm ra bởi chính các đợt rà soát của cổng giai đoạn, và được sửa ở đây:</strong>","changelog.f3f677980569":"⛔ <strong>Một báo cáo sự cố rời máy mà chưa được che thông tin.</strong> Phía Rust che khi ghi xuống đĩa, nhưng hộp thoại tự ghép lại lỗi thô — nên bản sao mà người dùng có thể đưa vào khay nhớ tạm, tải về, hoặc dán vào một <strong>issue GitHub công khai</strong> lại là bản chưa được che gì cả, dưới một biểu ngữ hứa rằng nó không chứa đường dẫn tệp nào. Giờ chỉ có một báo cáo: được soạn và che một lần, trong Rust, và đó là văn bản được hiện và là văn bản duy nhất có thể gửi đi. Khi không có backend để che, các nút gửi hoàn toàn không được đưa ra.","changelog.7ddebee8ab10":"⛔ <strong>Thoát khi đang phóng to phá huỷ kích thước thật của cửa sổ.</strong> Hình chữ nhật được lưu là hình đã phóng to, nên bỏ phóng to ở lần khởi động sau khôi phục về đúng kích thước nó đang có, và kích thước đã sắp xếp mất vĩnh viễn.","changelog.b22c92d59e1d":"⛔ <strong>Hai tiến trình cùng ghi <code>preferences.json</code> có thể xoá mất nửa của nhau.</strong> Khi đóng, lần xả của front end và lần lưu hình học của Rust kích hoạt cùng lúc; lần nào tới sau thắng cả tệp, làm mất hoặc vị trí cửa sổ hoặc một phần tư giây cuối của giao diện, bố cục và việc chấp nhận. Giờ cả hai lần ghi đều được gộp, nên thứ tự không còn quan trọng.","changelog.9355bc11339a":"⛔ <strong>Kích thước tối thiểu của cửa sổ được khai báo bằng pixel logic</strong> trong khi mọi chỗ khác dùng cùng các hằng số đó đều là pixel vật lý. Ở mức co giãn 150 %, cửa sổ đầu tiên mở ra to bằng màn hình và lòi ra ngoài mép thay vì căn giữa, và các điểm ngắt thu gọn dưới 1280 không bao giờ kích hoạt được.","changelog.a0e64e3152ba":"⛔ <strong>Địa chỉ của một người cùng phòng ở cuối câu, hoặc kèm cổng, không được che</strong> — token mang theo dấu chấm câu, nên nó bị tách thành năm phần thay vì bốn và phép kiểm tra thất bại theo hướng cho qua. IPv6 thì chưa bao giờ được che.","changelog.73fe3e54392a":"⛔ <strong>Hai báo cáo sự cố trong cùng một giây ghi đè lên nhau</strong>, trên một tính năng có quy tắc là không bao giờ bắt người dùng tái hiện lỗi trước khi thu thập tệp.","changelog.fd305290022c":"⛔ <strong>Khoá dàn trang lại là một cờ thay vì một bộ đếm</strong>, nên con trỏ đầu tiên được nhả ra đã xoá một lần giữ mà một thao tác kéo khác vẫn đang sở hữu — cửa sổ dàn trang lại ngay dưới một bàn tay vẫn đang kéo, đúng kiểu lỗi mà § F-35 cấm.","changelog.f97e1805f598":"Một phím tắt được gán lại thành <code>+</code> không bao giờ kích hoạt được: dấu phân cách của tổ hợp và phím của nó là cùng một ký tự, nên phím bị phân tích thành rỗng. Nó được lưu, được hiển thị và chẳng làm gì.","changelog.1818dd50dc97":"Thẻ thoả thuận khi bị từ chối không có bẫy tiêu điểm, nên người dùng bàn phím có thể Tab ra xuyên qua lớp phủ đục và nhấn các nút trên thanh tiêu đề.","changelog.affbfc927387":"Quy tắc ngôn ngữ đã lưu của <code>initialLocale</code> là mã không thể tới được; quyết định thật bỏ qua bước kiểm tra hợp lệ của nó, trao thẳng cho i18next một ngôn ngữ mà Oscillate không phát hành. Bộ chọn ngôn ngữ ở chân trang cũng không bao giờ lưu lại lựa chọn.","changelog.9e060fae8ad3":"Tiêu điểm chỉ được trả lại khi một hộp thoại vẫn còn được gắn, trong khi hai trong ba hộp thoại lại bị gỡ ra.","changelog.c3a66b9ba90c":"⛔ <strong>Một cửa sổ phóng to không bao giờ mở lại ở trạng thái phóng to.</strong> Windows cấp cho cửa sổ phóng to một khung đổi kích thước vô hình lòi ra ~11 px khỏi mỗi mép, nên <code>y</code> được lưu của nó là <code>-11</code> — và lớp bảo vệ khi khôi phục đòi <em>toàn bộ</em> dải tiêu đề 64 px phải nằm trên màn hình. Vì vậy mọi cửa sổ phóng to từng được lưu đều bị đánh giá là không dùng được và lặng lẽ bị thay bằng một mặc định căn giữa. Tìm ra bằng cách dựng tệp nhị phân release rồi chạy nó.","changelog.303430e5157f":"<strong>Những cổng kiểm tra không thể thất bại, giờ đã được làm thật:</strong>","changelog.b0bcf47ad11e":"Cổng trôi lệch <code>bindings</code> không bao giờ làm trống thư mục trước khi sinh lại, và ts-rs chỉ ghi thêm — nên các nhánh &quot;binding cũ&quot; và &quot;không sinh ra gì cả&quot; của nó đều không thể tới được. Đã xác minh bằng cách cài một binding mồ côi và nhìn cổng chuyển đỏ.","changelog.80822e6bc052":"Bốn khẳng định e2e được giải quyết dựa trên trạng thái vốn đã đúng trước cả lần nhấn phím mà chúng kiểm thử, và <code>dismissSplash</code> lấy mẫu một màn hình chờ chưa được gắn — để lớp phủ nuốt mất cú nhấp kế tiếp trong mọi bài kiểm thử có mở ứng dụng.","changelog.977117c0a2a3":"Thêm mới — engine âm thanh (Giai đoạn 2)","changelog.e7b90e4f7a6c":"<strong>Một engine âm thanh thời gian thực</strong> mở thiết bị và kết xuất các khối <strong>không cấp phát, không khoá và không lời gọi hệ thống nào trong callback</strong> — được thực thi bằng một bộ cấp phát toàn cục có đếm bao quanh callback, không phải bằng cách xem xét.","changelog.e61632d46641":"<strong>Một đồ thị kết xuất không khoá</strong> được trao cho luồng âm thanh bằng phép hoán đổi con trỏ nguyên tử, với kế hoạch cũ được giải phóng trên luồng giao diện. Luồng âm thanh không bao giờ giải phóng gì và không bao giờ chờ.","changelog.ad0918e4e397":"<strong>Transport</strong>: phát, dừng, thu, định vị, lặp, bản đồ nhịp độ, bản đồ loại nhịp, máy đếm nhịp và đếm vào — tất cả bằng subtick dấu phẩy tĩnh (960 PPQ × 65 536) để một phiên dài một giờ không bị trôi.","changelog.c3381e2b7634":"<strong>Bàn trộn</strong>: kênh, fader, pan công suất không đổi (giữa −3.01 dB), tắt tiếng, solo, send, nhóm và master, được sắp thứ tự bằng sắp xếp tô-pô trên cả quan hệ cha và quan hệ send.","changelog.3c007269b511":"<strong>Đo mức vào một vùng nhớ dùng chung</strong>, đọc qua một lược đồ URI tuỳ biến thay vì IPC JSON — một bố cục nhị phân cố định, nên sáu mươi lần đọc mỗi giây không tốn công phân tích.","changelog.b0b53fddf264":"<strong>Thu âm</strong>: sẵn sàng thu, chọn đầu vào, giám sát (<strong>mặc định tắt</strong>), đếm vào và punch, ghi thẳng xuống đĩa qua một vòng đệm không khoá bởi một luồng ghi. Header WAV được ghi <strong>trước</strong> mẫu đầu tiên, và một take có header chưa kịp được vá vẫn khôi phục được từ kích thước tệp.","changelog.57a6593bdb89":"<strong>Đầu vào MIDI</strong> với đóng gói/giải nén không mất mát qua một hàng đợi không khoá.","changelog.ae5e6e02af07":"<strong>Xử lý cắm nóng thiết bị và thay đổi tần số lấy mẫu</strong> — rút một giao diện âm thanh ra và transport dừng, dải kênh gọi tên thiết bị và dự án không bị đụng tới; <em>Tiếp tục</em> mở lại nó.","changelog.e435ef5b747d":"Sửa lỗi — những gì đợt rà soát Cổng Giai đoạn 2 tìm ra","changelog.54faffc42107":"⛔ <strong>Ba trong số này đã được dựng đầy đủ và kiểm thử đơn vị đầy đủ, mà hoàn toàn không hoạt động trong ứng dụng phát hành.</strong> Chúng được liệt kê theo tinh thần đó: các bài kiểm thử phủ từng mảnh mà không bao giờ phủ đường nối giữa chúng.","changelog.5bba3d0973a6":"⛔ <strong>Thu âm chưa bao giờ chạy ngoài bài kiểm thử.</strong> Callback thật không truyền điểm rẽ thu âm nào — mọi phần của đường đi đều tồn tại mà không có gì gọi tới.","changelog.bf141689a01d":"⛔ <strong>Mọi đồng hồ đo của track đều chết.</strong> Khe đồng hồ đo của dải kênh chỉ được cấp cho master, và vùng nhớ được định cỡ cho hai kênh bất kể có bao nhiêu track.","changelog.d4e9a63a6aad":"⛔ <strong>Không đồng hồ đo nào nhúc nhích được trong bản dựng đóng gói.</strong> Ảnh chụp được phục vụ từ một origin khác với trang và không mang <code>Access-Control-Allow-Origin</code>. CSP đã cho phép lược đồ đó — <strong>CSP không phải CORS</strong>, và máy chủ dev không bao giờ cho thấy điều này.","changelog.e27afc804d21":"⛔ <strong>Mọi vòng lặp không bắt đầu ở ô nhịp 1 đều nhảy về đầu dự án.</strong> Phép quay vòng lấy một vị trí <em>subtick</em> trừ đi một giá trị <em>tick</em>. ⚠ Mọi bài kiểm thử vòng lặp có sẵn đều dùng ô nhịp 1, nơi phép tính sai tình cờ lại đúng.","changelog.afe43c0d4e2a":"<strong>Một lần quay vòng giữa khối phát lại phần đầu của đầu vào</strong>, vì mỗi khoảng đẩy lát cắt đầu ra lên mà không đẩy lát cắt đầu vào — một tiếng giật ở mỗi lần lặp khi đang giám sát.","changelog.ea0d9ab4ca81":"<strong>Một lần định vị tới cùng lúc với lệnh thu đã nuốt mất phần đếm vào.</strong> Một nút bấm bình thường (&quot;thu từ đầu vùng chọn&quot;) gửi cả hai trong cùng một khoảng hở giữa hai khối.","changelog.212a1425d0de":"⛔ **Nhấn <em>Dừng</em> có thể làm đứng cửa sổ.** Take được đóng trên luồng giao diện, chờ nhập vào một luồng ghi có thể đang bị chặn vì đĩa bị nghẽn — và Oscillate tự vẽ thanh tiêu đề của mình, nên không có khung cửa sổ của hệ điều hành nào để dựa vào.","changelog.5601b4005190":"<strong>Một thiết bị thất bại ở khối đầu tiên bị mở lại trong một vòng lặp chặt</strong>, không nghỉ và không giới hạn; và một lỗi phát sinh trong lúc luồng đang mở có thể bị nuốt mất, để lại một ứng dụng im lặng báo một thiết bị khoẻ mạnh.","changelog.6ce4996c40aa":"<strong>Chỉnh sửa bàn trộn thực hiện trong lúc thiết bị đang mở bị bỏ khỏi đường âm thanh</strong>, nên một fader được kéo trong lúc kết nối lại hiện một giá trị mà phát ra một giá trị khác.","changelog.8008bbcdc222":"<strong>Máy đếm nhịp có thể tràn số và panic bên trong callback âm thanh</strong> khi định vị gần cuối phạm vi.","changelog.12e2665533c9":"Sửa lỗi — những gì một đợt rà soát các bản sửa tìm ra","changelog.108a22259133":"⛔ <strong>Một đợt rà soát thứ hai, giới hạn trong commit sửa lỗi thay vì trong các lỗi.</strong> Nó tìm ra thêm sáu lỗi, <strong>hai lỗi nghiêm trọng, và một trong số đó do chính một bản sửa tạo ra.</strong> Được ghi lại vì đó là lập luận cho việc lượt rà soát này tồn tại.","changelog.198888ba7d98":"⛔ <strong>Một vòng lặp vô hạn trong callback âm thanh.</strong> Khi cho <code>span_end</code> và <code>first</code> của máy đếm nhịp phép toán bão hoà, bước nhảy của chính vòng lặp đã bị bỏ sót. Trong bản dựng release nó quay vòng số và chạy qua khoảng ~10¹¹ vòng — <strong>tệ hơn cả lần panic mà nó thay thế.</strong>","changelog.3805b261f86a":"⛔ **Một lần nhấn <em>Tiếp tục</em> tốn bằng hai, và có thể treo luồng thiết bị mãi mãi.** Hai vòng lặp cùng tiêu thụ một cờ mở lại, nên một lần nhấn trong khoảng nửa giây tới hai giây khi thiết bị đang mở đã dỡ bỏ chính thiết bị vừa mở.","changelog.7e57ef4b8c08":"<strong>Một take có thể không bao giờ kết thúc</strong> nếu transport vẫn đang chạy: luồng ghi chỉ đọc cờ dừng khi lượt xả trống, trong khi luồng âm thanh cứ tiếp tục lấp đầy vòng đệm. Giờ phần đuôi xả đã có giới hạn.","changelog.2c2d115a8222":"<strong>Một dải kênh vượt quá vùng nhớ đồng hồ đo được cấp một khe không tồn tại</strong> — lỗi đồng hồ đo chết quay lại ở số kênh cao hơn. Giờ nó không được cấp đồng hồ đo nào, như vậy là trung thực, thay vì một đồng hồ đứng im ở −∞.","changelog.1b65e543046f":"<strong>Ảnh chụp đồng hồ đo mang cả 1 024 khe sáu mươi lần mỗi giây</strong> — 16 KB mỗi khung hình cho một phiên có hai dải kênh. Giờ nó chỉ mang các kênh đã thực sự mang một mẫu nào đó.","changelog.cab3bd8a9f1a":"<strong>Số mẫu bị rớt được đọc trước lượt xả</strong>, nên nó bỏ sót đúng những lần rớt mà một ổ đĩa chậm gây ra.","changelog.fb88cf8c59c9":"⚠ <strong>Hai bài kiểm thử không thể thất bại</strong>, còn tệ hơn không có — cả hai đều được viết ở cổng này, và giờ đều đã được sửa: một bài kiểm thử máy đếm nhịp có đầu vào không bao giờ đi vào vòng lặp nó đang kiểm thử, và một bài kiểm thử đồng hồ đo theo dải kênh chỉ có một track, nơi master rò vào khe qua luật pan và đạt đúng với hành vi mà bài kiểm thử được viết ra để bác bỏ.","changelog.6c6912c7b7c5":"Sửa lỗi — những gì đợt rà soát bảo mật vô tình gặp phải","changelog.3bc132875a67":"⚠ <strong><code>/security-review</code> không tìm thấy lỗ hổng mức HIGH hay MEDIUM nào.</strong> Nó xác nhận riêng header CORS của lược đồ đồng hồ đo là ổn: <code>register_uri_scheme_protocol</code> là một cơ chế chặn của webview chứ không phải socket, nên địa chỉ đó không thể truy cập từ ngoài máy. Những gì nó tìm thấy trên đường đi qua còn tệ hơn thứ nó đi tìm.","changelog.e6bf7c677991":"⛔ <strong>Một take có thể bị cắt cụt lặng lẽ.</strong> Tệp take được đặt tên theo đồng hồ thật, dưới một lời chú thích khẳng định đó là bộ đếm đơn điệu, và luồng ghi dùng <code>File::create</code>, vốn cắt cụt tệp. ⚠ Lỗi ẩn cho tới khi việc đóng take được dời khỏi luồng giao diện — sau đó một take mới có thể ghi đè lên take vẫn đang được ghi. Giờ là <code>create_new</code>, một dãy số thực sự theo từng phiên, và một lớp bảo vệ từ chối bắt đầu trong khi take trước vẫn đang đóng.","changelog.b135c10bd85f":"<strong><code>Access-Control-Allow-Origin</code> là một danh sách cho phép thay vì <code>*</code></strong> — coi như gia cố, không phải vì nó khai thác được.","changelog.c8f633bba310":"Thay đổi — âm thanh trên Windows, theo quyết định của chủ dự án (2026-08-25)","changelog.a2460f3b52b6":"⛔ <strong>ASIO bị loại khỏi sản phẩm.</strong> Steinberg cấp phép kép cho SDK vào tháng 10 năm 2025 (GPLv3 trở lên, <strong>hoặc</strong> một thoả thuận độc quyền miễn phí). ⛔ <strong>Lựa chọn GPLv3 bị bác bỏ</strong>: nó sẽ đặt mã nguồn của chính Oscillate dưới copyleft, và GPL <strong>cho phép rõ ràng người khác bán</strong> những gì họ nhận được. Lựa chọn độc quyền — miễn phí, một chữ ký, cho phép mã nguồn đóng — bị từ chối thay vì ký một hợp đồng cho một khả năng mà WASAPI đã mang lại. ⚠ <strong>Nó vẫn còn đó và có thể đảo ngược; không có gì trong mã phụ thuộc vào lựa chọn này.</strong>","changelog.9b112e158a81":"<strong>Độ trễ thấp trên Windows là WASAPI độc quyền + <code>IAudioClient3</code></strong>, nhắm tới <code>v0.4.0</code>. ⚠ <strong>Không có con đường MIT/Apache nào tới ASIO</strong> — mọi wrapper đều có giấy phép dễ dãi nhưng biên dịch dựa trên header của Steinberg, và giấy phép của một wrapper không thể trao quyền đối với header của Steinberg.","changelog.894975a8d218":"<strong>Mức hỗ trợ tối thiểu là Windows 10 1607+</strong>, mức mà <code>IAudioClient3</code> và WebView2 vốn đã yêu cầu. ⛔ <strong>Windows 11 không bắt buộc và không được phép trở thành bắt buộc.</strong>","changelog.f376443b92b4":"<span class=\"release__meta\"><span class=\"release__ver\">v0.0.1</span><time class=\"release__date\" datetime=\"2026-08-24\">2026-08-24</time></span>","changelog.9f343f82939c":"<strong>Nền móng, kho mã, và xương sống CI.</strong> Một cửa sổ trống dựng được, chạy được, và được bảo vệ bởi mọi cổng kiểm tra mà dự án này sẽ dựa vào — được viết trước khi có bất cứ thứ gì đáng bảo vệ, vì một cổng thêm vào sau là một cổng phải được lắp ngược vào mọi thứ đã dựng mà không có nó.","changelog.b9f3e0e185fd":"⚠ <strong>Một tag, không phải một bản phát hành. Không có bản tải về nào và sẽ không có cho tới <code>v1.0.0</code>.</strong> Các trình cài đặt cho bậc này đã được dựng, cài, khởi chạy và tính mã băm, rồi <strong>được giữ lại thay vì công bố</strong>.","changelog.1c8b846c2976":"Kho mã, giấy phép Bảo lưu mọi quyền, EULA, và một <code>.gitignore</code> giữ các tài liệu kế hoạch nội bộ ở ngoài <strong>ngay từ commit đầu tiên</strong>.","changelog.26c9317c192c":"Một Cargo workspace gồm mười ba thành viên — mọi crate mà kiến trúc yêu cầu, mỗi crate là một khung biên dịch được — và lớp vỏ Tauri 2.","changelog.0ad7dd57c2b3":"Front end React 19 / Vite / TypeScript / Tailwind 4, và các design token của Oscillate: cả hai giao diện, với bảng màu sáng được đặt tên đúng một lần.","changelog.b58ef9a54add":"Cả 18 bảng dịch ngôn ngữ, đóng gói sẵn thay vì tải về, tiếng Anh đứng đầu trong bộ chọn và 17 ngôn ngữ còn lại theo thứ tự chữ cái.","changelog.de27cfddc011":"<strong>Mười lăm cổng kiểm tra</strong>, và <code>npm run ci:local</code> để chạy chúng theo cách CI chạy: định dạng mã, lint, kiểu, kiểm thử đơn vị, clippy dưới <code>-D warnings</code>, danh sách giấy phép cho phép, phần ghi công được sinh ra, kiểm tra tên sản phẩm, kiểm tra không-AI/không-đo-từ-xa/không-HTTP, Playwright, và một lượt quét 18 × 2 giao diện và ngôn ngữ.","changelog.014c5ad1e881":"GitHub Actions trên Windows, macOS và Linux, với mọi action được ghim vào một SHA commit và mọi tệp thực thi tải về được kiểm tra theo SHA256.","changelog.6b279b513071":"<code>THIRD-PARTY-NOTICES.md</code> và dữ liệu ghi công trong ứng dụng, đều được sinh ra từ đồ thị phụ thuộc thật nên không cái nào có thể trôi lệch khỏi những gì thực sự được liên kết."};
